window.__Q=window.__Q||{};window.__Q["prev/8/A2"]=[{"q":"患者，女，18岁。双下肢对称性出血点1周，高出皮面，发痒，伴关节肿痛。血小板计数、出凝血时间及血块退缩试验均正常，凝血酶原消耗试验正常。尿蛋白（＋＋）。最可能的诊断是","o":["原发免疫性血小板减少症","过敏性紫癜","血管性血友病","单纯性紫癜","血小板功能异常"],"a":1,"e":"过敏性紫癜属血管壁功能异常，四肢对称性高出皮面的紫癜伴痒感、关节痛，累及肾脏出现血尿、蛋白尿，而血小板计数及各项凝血试验均正常，符合血管性紫癜。原发免疫性血小板减少症有血小板减少；血管性血友病与血小板功能异常多表现为出血时间延长或手术出血不止，且无对称性皮疹与关节痛；单纯性紫癜仅为四肢偶发瘀斑，无系统症状"},{"q":"患者，男，30岁。眩晕、恶心3天。查体：眼球震颤阳性。患者最可能的诊断是","o":["晕动病","梅尼埃病","高血压病","眼肌麻痹","链霉素中毒"],"a":1,"e":"梅尼埃病为突发旋转性眩晕，伴恶心呕吐、耳鸣、听力减退及眼球震颤，发作短暂，周围性眩晕体征与此相符。晕动病须有乘船乘车等运动诱因；高血压病以血压升高为主，无明显眼震；眼肌麻痹多有复视与眼球运动障碍；链霉素中毒有明确用药史且伴听力损害，均非本例"},{"q":"患者，男，48岁。突发阴囊疼痛4小时，向腹股沟区放射明显。查体：右侧阴囊明显红肿，皮温增高，触及睾丸附睾肿大呈一肿块，不易区分，触痛明显。该患者最可能的诊断是","o":["急性膀胱炎","急性前列腺炎","阴囊疝","急性附睾炎","附睾结核"],"a":3,"e":"急性附睾炎表现为阴囊红肿热痛，附睾肿痛明显且与睾丸分界不清，可向腹股沟放射，符合急性炎症。急性前列腺炎以尿频尿急、会阴不适为主；阴囊疝为可复性肿物，无红肿热痛；附睾结核质地硬、有结节感、无明显压痛且伴输精管串珠样改变；急性膀胱炎以膀胱刺激征为主，均不符"},{"q":"患者，男，65岁。进行性排尿困难5年，不能自行排尿8小时，膀胱膨隆伴轻压痛。首选的治疗方法应该是","o":["药物治疗","针灸","耻骨上膀胱穿刺","导尿并保留导尿管","耻骨上膀胱造瘘"],"a":3,"e":"慢性尿潴留致膀胱过度充盈、不能排尿，首选导尿并保留导尿管以引流尿液、解除梗阻。耻骨上膀胱穿刺或造瘘仅在导尿失败时采用；针灸与药物对急性尿潴留起效慢，不能迅速减压；本例已有8小时无尿，需立即引流，不宜观望"},{"q":"患者，男，38岁。1天前感冒、发热，自服对乙酰氨基酚1片，1小时前出现呕血，量约50ml，平素身体健康，无腹痛。查体：肝脾不大。引起呕血最可能的病因是","o":["消化性溃疡","急性胃黏膜病变","食管-胃底静脉曲张","食管贲门黏膜撕裂综合征","食管炎"],"a":1,"e":"急性胃黏膜病变由非甾体抗炎药等损伤胃黏膜屏障引起，服用解热镇痛药后突发呕血、无腹痛及肝脾肿大，最符合此诊断。消化性溃疡多有慢性节律性上腹痛；食管胃底静脉曲张破裂出血量大、有肝硬化背景；食管贲门黏膜撕裂综合征常先有剧烈呕吐；食管炎出血量少且伴烧灼感"},{"q":"75岁男性脑梗死患者，进行溶栓治疗，治疗初期，会出现","o":["纤维蛋白/纤维蛋白原降解产物阴性，D-二聚体阴性","纤维蛋白/纤维蛋白原降解产物阳性，D-二聚体阴性","纤维蛋白/纤维蛋白原降解产物阴性，D-二聚体阳性","纤维蛋白/纤维蛋白原降解产物阳性，D-二聚体阳性","纤维蛋白/纤维蛋白原降解产物阴性，D-二聚体可能阳性或者阴性"],"a":3,"e":"溶栓治疗使纤维蛋白和纤维蛋白原同时被降解，继发性纤溶亢进，故纤维蛋白/纤维蛋白原降解产物与D-二聚体均阳性。FDP阳性而D-二聚体阴性提示原发性纤溶或假阳性；FDP阴性而D-二聚体阳性多见于DIC、静脉血栓等继发性纤溶早期或FDP假阴性；二者均阴性可排除明显纤溶激活"},{"q":"图为一NHL患者的骨髓涂片，按恶性淋巴瘤的分期该患者应为","o":["Ⅰ期","Ⅱ期","Ⅲ期","Ⅳ期","Ⅱ期或Ⅲ期"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。恶性淋巴瘤分期中，骨髓受侵即为Ⅳ期，故骨髓涂片见淋巴瘤细胞支持Ⅳ期。Ⅰ期限于单个淋巴结区，Ⅱ期累及同侧多个淋巴结区，Ⅲ期侵犯横膈两侧淋巴结，均可无骨髓浸润；Ⅱ期或Ⅲ期说法不符合Ann Arbor分期标准\n\n官方题库中缺失图片"},{"q":"青年男性，无明显诱因突发胸痛，呼吸困难。查体：瘦长体型，右侧胸廓饱满，呼吸运动减弱，气管向左侧偏移，叩诊鼓音。最可能的诊断为","o":["支气管哮喘","肺气肿","胸腔积液","气胸","支气管扩张"],"a":3,"e":"自发性气胸典型表现为瘦长体型者突发胸痛与呼吸困难，患侧胸廓饱满、呼吸运动减弱、叩诊鼓音，气管向健侧移位。支气管哮喘为双肺弥漫性哮鸣音，无单侧体征；肺气肿呈双侧过清音、桶状胸；胸腔积液叩诊浊音且气管移向健侧但无鼓音；支气管扩张以长期咳脓痰、咯血为主"},{"q":"患者，女，30岁。乏力、恶心、食欲缺乏2周。查体：T 38℃，皮肤黄染，巩膜黄染，肝肋下1cm，质软，轻触痛。实验室检查：ALT 3000U/L，MAO 15U/L，HBsAg阳性。患者最可能的诊断是","o":["溶血性黄疸","慢性活动性肝炎","急性重型肝炎","肝硬化","梗阻性黄疸"],"a":2,"e":"急性重型肝炎在HBsAg阳性基础上出现黄疸、发热与极度升高的ALT，肝细胞广泛坏死使MAO从坏死细胞逸出而升高，病情凶险。溶血性黄疸以间接胆红素升高为主、无肝细胞损伤；慢性活动性肝炎病程长、起病缓；肝硬化有门脉高压表现且ALT升高不明显；梗阻性黄疸以ALP、GGT升高为主"},{"q":"23岁女性，游走性关节痛10年，胸闷、气短2年，心脏彩超提示风湿性心脏病。关节痛应属于","o":["主诉","现病史","既往史","系统回顾","个人史"],"a":2,"e":"既往史记录病人过去疾病及与现病相关的病史，风湿性心瓣膜病需追问既往反复咽痛、游走性关节痛，且关节痛已缓解10年，故归入既往史。主诉为本次就诊主要症状；现病史为本次疾病发生发展全过程，10年前关节痛非本次风湿性心脏病表现；系统回顾与各系统症状筛查有关；个人史涉及起居嗜好等"},{"q":"患者，女，30岁，常感乏力、心悸、胸痛。查体：颈动脉搏动明显，心尖部可闻及柔和递减型舒张中晚期杂音，无震颤，胸骨右缘第2肋间可闻及舒张期叹息样杂音。X线心影呈靴形心，左室增大。可能的诊断是","o":["二尖瓣狭窄","主动脉瓣狭窄","主动脉瓣关闭不全","肥厚性心肌病","高血压心脏病"],"a":2,"e":"主动脉瓣关闭不全时主动脉瓣区舒张期叹气样杂音，重度反流致相对性二尖瓣狭窄，心尖出现柔和递减型舒张中晚期AustinFlint杂音、无震颤，左室增大呈靴形心，伴周围血管征。二尖瓣狭窄为心尖隆隆样递增型杂音伴震颤；主动脉瓣狭窄为收缩期喷射性杂音；肥厚性心肌病杂音随动作变化；高血压心脏病以长期高血压为基础"},{"q":"患者，男，54岁。肝硬化出现腹水入院5天。今起出现发热、腹痛、腹胀明显。诊断为自发性细菌性腹膜炎。该患者腹水检验的特点是","o":["漏出性腹水","细胞总数小于200/μl","蛋白质含量为20g/L","乳酸脱氢酶含量为100U/L","分类时，中性粒细胞为75%"],"a":4,"e":"自发性细菌性腹膜炎为渗出性腹水，白细胞及中性粒细胞显著增多，分类中性粒细胞达75%最具诊断价值。漏出性腹水蛋白低、细胞数少，见于单纯肝硬化；细胞总数小于200/μl不支持感染；蛋白质20g/L与LDH100U/L均偏低，属漏出液特征，与细菌感染不符"},{"q":"患者，男，58岁。乏力、上腹痛2个月。查体：心肺无异常，肝肋下2cm，触痛，脾不大。化验检查ALT、ALP、GGT和MAO均增高，A/G比值减低，AFP阳性。患者最可能的诊断是","o":["急性肝炎","慢性肝炎","肝硬化","原发性肝癌","化脓性梗阻性胆管炎"],"a":3,"e":"原发性肝癌时AFP阳性具特异诊断价值，肝内局限性胆道阻塞使ALP、GGT明显升高，A/G比值下降反映肝功能受损。急性肝炎ALT显著升高而AFP阴性、病程短；慢性肝炎AFP多阴性；肝硬化AFP可轻度升高但少持续阳性；化脓性梗阻性胆管炎以发热、腹痛、黄疸三联征为主，无AFP阳性"},{"q":"一患者主要因震颤入院。查体发现患者静止时震颤明显，运动时减轻，睡眠后消失，多有肌张力增高。属于以下哪种神经体征","o":["运动性震颤","静止性震颤","意向性震颤","手足徐动","舞蹈样运动"],"a":1,"e":"静止性震颤在静止时明显、运动时减轻、睡眠时消失，伴肌张力增高，见于帕金森病，与本例完全吻合。运动性震颤与意向性震颤均在动作时出现，后者接近目标时加重；手足徐动为手足缓慢不规则扭曲动作；舞蹈样运动为快速不规则无目的动作，均不符合静止时明显的特点"},{"q":"患者，女，38岁。患风湿性心脏病二尖瓣狭窄3年。近1个月出现咳嗽及咳痰，伴夜间阵发性呼吸困难。查体：BP 120/80mmHg，P 90次/min，双肺底少许水泡音，心尖部闻及舒张中、晚期隆隆样杂音伴第一心音亢进及舒张期开瓣音。下一步处理首选","o":["二尖瓣置检术","经皮二尖瓣球囊扩张术","二尖瓣分裂术","冠状动脉造影术","继续观察"],"a":1,"e":"风湿性二尖瓣狭窄出现夜间阵发性呼吸困难及肺底湿啰音，提示肺淤血，心尖隆隆样杂音伴开瓣音说明瓣膜活动度好，首选经皮二尖瓣球囊扩张术解除狭窄。二尖瓣置换术创伤大，非首选；二尖瓣分裂术已少用；冠状动脉造影用于排查冠心病，不解决瓣膜狭窄；继续观察会延误心功能恶化"},{"q":"患者，男，42岁。节律性中上腹痛13年。每于餐后半小时发作，下次进餐前缓解；服硫糖铝症状可缓解。近3个月疼痛规律消失，服上药无效，且食欲减退。为明确诊断，应首选的检查是","o":["胃肠钡餐检查","血清促胃液素测定","胃液分析","癌胚抗原（CEA）测定","纤维胃镜检查加胃黏膜组织活检"],"a":4,"e":"胃溃疡节律性上腹痛多年，近期疼痛规律消失、药物无效伴食欲减退，须警惕癌变，纤维胃镜加活检可直接观察并取组织确诊。胃肠钡餐对早期癌变敏感性低；血清促胃液素测定用于胃泌素瘤；胃液分析诊断价值有限；CEA特异性不高，均不能替代病理活检"},{"q":"患儿，男，1岁，出生1个月时儿保发现心脏杂音。查体：于胸骨左缘2肋间及3/6级粗糙收缩期杂音，伴P2增强，S2固定分裂。患儿可伴有","o":["发绀、杵状指","心尖冲动向左移位","双侧心界扩大","强迫蹲踞位","梨形心"],"a":1,"e":"胸骨左缘第2肋间收缩期杂音、P2亢进及S2固定分裂提示房间隔缺损，左向右分流致右心室容量负荷增加，心尖冲动向左移位。发绀与杵状指见于法洛四联症等右向左分流先心；强迫蹲踞位为法洛四联症特征；双侧心界扩大提示扩张型心肌病；梨形心见于二尖瓣狭窄"},{"q":"患者因呼吸困难1周入院，查X线示右侧中等量胸腔积液，最不可能出现的体征是","o":["右侧呼吸运动受限","气管移向健侧","右侧语音震颤增强","叩诊右肺呈浊音","右侧肋间隙丰满"],"a":2,"e":"中等量胸腔积液时液体使肺与胸壁隔开，语音震颤减弱或消失，故右侧语音震颤增强最不可能出现。右侧呼吸运动受限、肋间隙丰满、气管移向健侧及叩诊浊音均为胸腔积液典型体征；语音震颤增强见于肺实变，因实变肺组织传导良好，与积液物理性质相反"},{"q":"患者，男，36岁。发作性胸痛1年，M型超声心动图检查，可见室间隔与左室后壁之比为1.6∶1，左室流出道28mm，SAM现象阳性。下列哪项体征具有诊断意义","o":["心尖区舒张中晚期隆隆样杂音，左侧卧位时增强","主动脉瓣第二听诊区舒张期叹气样杂音，呼气末增强","肺动脉瓣舒张期吹风样递减型杂音，卧位时增强","胸骨左缘第3、4肋间收缩期杂音，VALSALVA动作时增强","胸骨左缘第4、5肋间舒张期隆隆样杂音，吸气时增强"],"a":3,"e":"室间隔与左室后壁之比增大、左室流出道狭窄及SAM现象阳性提示肥厚型梗阻性心肌病，胸骨左缘第3、4肋间收缩期杂音在Valsalva动作时增强，因回心血量减少使梗阻加重。心尖舒张中晚期隆隆样杂音为二尖瓣狭窄；主动脉瓣第二听诊区叹气样杂音为主动脉瓣关闭不全；肺动脉瓣舒张期杂音或三尖瓣区吸气增强杂音提示其他瓣膜病变"},{"q":"患者，男，40岁。突发性上腹部疼痛2小时来院急诊。查体：腹部平坦，全腹均有压痛，腹部触诊呈板状，肠鸣音消失，肝浊音界缩小。该患者肠鸣音消失的主要原因是","o":["肠坏死","机械性肠梗阻","肠运动障碍","剧痛而不敢腹式呼吸","炎症刺激而致肠麻痹"],"a":4,"e":"板状腹、全腹压痛、肝浊音界缩小提示急性弥漫性腹膜炎，炎症刺激肠管致麻痹性肠梗阻，肠鸣音减弱或消失。肠坏死多见于绞窄性肠梗阻，伴剧烈持续腹痛；机械性肠梗阻早期肠鸣音亢进呈金属音；肠运动障碍与剧痛不敢深呼吸均非本例肠鸣音消失的主要机制"},{"q":"患者，女，66岁，间断低热、盗汗、咳嗽3月，需排除肺结核。若结核菌素皮试是检测哪一型超敏反应","o":["Ⅰ","Ⅱ","Ⅲ","Ⅳ","Ⅵ"],"a":3,"e":"结核菌素皮试通过致敏T细胞介导的迟发型反应判断结核感染，属Ⅳ型超敏反应，皮肤试验为其典型检测方法。Ⅰ型为速发型过敏反应；Ⅱ型由抗体介导细胞毒；Ⅲ型为免疫复合物沉积致病；Ⅵ型并非经典超敏反应分型，均与结核菌素试验机制不符"},{"q":"神经系统查体时，发现患者肢体在被动伸曲时起始阻力明显增加，终末时阻力突发减弱。考虑损伤以下哪个部位","o":["锥体束","锥体外系","小脑","周围神经","脊髓前角"],"a":0,"e":"被动伸屈肢体时起始阻力大、终末阻力突然减弱为折刀现象，是痉挛性肌张力增高的特征，由锥体束损害所致。锥体外系损害表现为铅管样或齿轮样强直，各方向阻力均匀一致；小脑病变致肌张力减低与共济失调；周围神经及脊髓前角损害亦表现为肌张力减低"},{"q":"患者，男，28岁。3年来反复上腹部疼痛伴反酸未治疗，2小时前突然上腹剧痛，深呼吸时腹痛加重，出冷汗，来诊。此时最应注意的体征是","o":["肠鸣音是否亢进","肝浊音界是否消失","腹壁有否柔韧感","胃泡鼓音区是否扩大","前倾位腹痛是否减轻"],"a":1,"e":"溃疡病史者突发上腹剧痛、深呼吸加重，提示急性胃肠穿孔，游离气体积聚膈下使肝浊音界缩小或消失，是最具决定性的体征。肠鸣音亢进见于机械性肠梗阻；腹壁柔韧感见于结核性腹膜炎；胃泡鼓音区扩大无特异诊断意义；前倾位减轻见于胰腺癌，均非穿孔的直接征象"},{"q":"患者，男，25岁。全身反复皮疹3年，冬天加剧，夏日缓解，自觉瘙痒。查体发现头皮及躯干、四肢伸侧散在圆形胡豆至胡桃大小的红色斑丘疹，上附白色小片鳞屑，刮去鳞屑，基底潮红，少许出血点，无渗出。诊断考虑","o":["季节性皮炎","银屑病","神经性皮炎","头癣","湿疹"],"a":1,"e":"银屑病典型表现为红色斑丘疹上覆银白色鳞屑，刮去鳞屑见薄膜现象与点状出血，好伸侧、冬重夏轻，与本例相符。季节性皮炎与湿疹多无银白色鳞屑及点状出血；神经性皮炎为苔藓样变、剧痒；头癣为真菌感染，鳞屑不呈银白色且可累及发干，均不支持"},{"q":"患者，女，50岁，发现血脂升高、大量蛋白尿、水肿1年，诊断为肾病综合征，该患者尿中不可见的是","o":["透明管型","白细胞管型","肾小管上皮细胞管型","蜡样管型","脂肪管型"],"a":1,"e":"白细胞管型提示肾脏感染性病变或免疫性反应，如肾盂肾炎、间质性肾炎，肾病综合征无此管型。透明管型健康人偶见；肾小管上皮细胞管型见于肾小管损伤；蜡样管型提示肾单位长期阻塞、预后差；脂肪管型为肾小管上皮脂肪变性，是肾病综合征特征之一"},{"q":"患者，男，32岁，因咽痛伴吞咽困难3天入院。查体：咽红，双侧扁桃体肿大超过咽腭弓，扁桃体隐窝内可见少许黄白色分泌物。该患者扁桃体为","o":["无明显肿大","Ⅰ度肿大","Ⅰ度与Ⅱ度之间","Ⅱ度肿大","Ⅲ度肿大"],"a":3,"e":"扁桃体肿大超过腭咽弓但未达咽后壁中线为Ⅱ度，隐窝内黄白色分泌物为急性化脓性扁桃体炎表现。Ⅰ度不超过腭咽弓；Ⅲ度达到或超过咽后壁中线；无明显肿大与Ⅰ度、Ⅱ度之间均不符合本例超过咽腭弓的描述"},{"q":"患者，男，32岁，因高楼跌下致多发伤就诊。查体：神志清楚，下腹部压痛，下肢肌力肌张力正常。观察2小时后，患者诉上厕所尿不出，查体在耻骨上触及肿胀的膀胱，尿道口出现轻微血渍。首先应采取的处理措施是","o":["试插导尿管","膀胱造瘘","逆行性尿道造影","急查膀胱镜","急诊手术"],"a":0,"e":"外伤后尿潴留、膀胱充盈且尿道口有血渍，首先试插导尿管，既可解除尿潴留，又能根据能否插入判断尿道损伤程度。膀胱造瘘用于导尿失败或尿道断裂；逆行性尿道造影多在导尿失败后行；膀胱镜与急诊手术创伤大，不作为首选处理"},{"q":"患者，男，73岁，基础风湿性心脏病、二尖瓣狭窄，间断活动后气短数年来诊，入室心电图如下所示，进一步需完善","o":["B型脑钠肽","冠状动脉CTA","超声心动图","动态心电图","胸部正侧位"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。超声心动图是诊断二尖瓣狭窄等瓣膜病的首选无创方法，可明确瓣口面积、左房大小及肺动脉压力。B型脑钠肽仅反映心功能；冠脉CTA评估冠脉；动态心电图查心律失常；胸片不能直接显示瓣膜病变，均不能替代超声\n\n官方题库中缺失图片"},{"q":"患者，男，60岁，出现进行性排尿困难，最常见的原因是","o":["前列腺癌","前列腺增生","膀胱颈纤维性增生","膀胱结石","尿道结石"],"a":1,"e":"老年男性进行性排尿困难最常见于前列腺增生，增生的前列腺压迫尿道致尿线变细、排尿费力。前列腺癌也可致排尿困难但发病率低于增生且多伴硬结；膀胱颈纤维性增生少见；膀胱结石表现为排尿突然中断；尿道结石有排尿困难与尿流中断但无多年进行性加重过程，均非最常见原因"},{"q":"患者，男，36岁。水肿，尿少1周，血压120/80mmHg。尿常规：蛋白（＋＋＋＋），血浆白蛋白25g/L，24小时尿蛋白定量为9g。最可能的诊断是","o":["右心衰竭","肝硬化","肾病综合征","重度营养不良","急性肾炎综合征"],"a":2,"e":"大量蛋白尿超过3.5g/d、血浆白蛋白低于30g/L、明显水肿与高脂血症构成肾病综合征，本例24小时尿蛋白9g、白蛋白25g/L完全符合。右心衰竭以颈静脉怒张、肝大、下肢水肿为主；肝硬化有门脉高压；重度营养不良白蛋白低但无大量蛋白尿；急性肾炎综合征以血尿、高血压为主"},{"q":"患者，男，18岁。身高183cm，体重75kg。实验室检查：空腹血糖6.9mmol/L，2次餐后2小时血糖15.3mmol/L，血胰岛素增高。该患者最可能的诊断是","o":["1型糖尿病","胰岛素分泌不足为主的2型糖尿病","胰岛素抵抗为主的2型糖尿病","糖耐量减低","空腹血糖减损"],"a":2,"e":"两次餐后2小时血糖超过11.1mmol/L已达糖尿病标准，空腹血糖6.9mmol/L未达7.0，血胰岛素增高提示胰岛素抵抗，符合以胰岛素抵抗为主的2型糖尿病。1型糖尿病胰岛素明显降低；胰岛素分泌不足为主的2型以分泌缺陷为主；糖耐量减低与空腹血糖减损均未达糖尿病切点"},{"q":"患者，男，60岁，2型糖尿病病史10年。自行停用胰岛素后出现流涕，呕吐，腹泻，血气分析可见酸中毒。该患者最可能出现的呼吸节律改变是","o":["潮式呼吸","叹气样呼吸","抑制性呼吸","端坐呼吸","Kussmaul呼吸"],"a":4,"e":"停用胰岛素后酮症酸中毒，严重代谢性酸中毒通过深快呼吸排出CO2代偿，形成Kussmaul呼吸。潮式呼吸见于中枢神经系统疾病与心力衰竭；叹气样呼吸多为功能性；抑制性呼吸因胸痛致吸气突然停止；端坐呼吸为左心衰竭体位，均非酸中毒特征"},{"q":"患者，男，48岁，10年少量饮酒史。近1个月上腹疼痛，饥饿时加重，呈现疼痛－进食－缓解的规律。最可能的诊断是","o":["食管炎","十二指肠球炎","胆囊炎","慢性胃炎","十二指肠溃疡"],"a":4,"e":"十二指肠溃疡疼痛呈疼痛—进食—缓解规律，饥饿时加重，进食或服抑酸药后缓解，中上腹痛为其特征。食管炎为胸骨后烧灼痛；十二指肠球炎症状无典型节律；胆囊炎疼痛与进食油腻相关、向右肩放射；慢性胃炎疼痛节律不明显，均不符"},{"q":"患儿，男，1岁。额、顶、颞及枕部突出膨大呈圆形，颈静脉充盈，对比之下颜面很小，双目下视，巩膜外露。该患儿的诊断为","o":["小儿佝偻病","变形性骨炎","脑积水","肢端肥大症","马方综合征"],"a":2,"e":"巨颅伴额顶颞枕部膨大、颈静脉充盈、颜面相对狭小及落日现象为脑积水特征，因颅内压增高压迫眼球致双目下视、巩膜外露。小儿佝偻病为方颅；变形性骨炎少见且头颅增大伴骨痛；肢端肥大症为成人生长激素过多；马方综合征以细长体型、晶状体脱位为主"},{"q":"患者，女，24岁，发热10天，右侧胸痛，胸片示右胸腔中等量积液，则胸部叩诊可发现的阳性体征不包括","o":["Damoiseau线","Garland三角区","Traube区增大","Skoda浊鼓音区","Grocco三角区"],"a":2,"e":"Traube区为胃泡鼓音区，位于左前胸下部，右侧胸腔积液不会使其增大，反可因积液压迫膈肌下移而改变。Damoiseau线为积液上界弓形线；Garland三角区与Skoda浊鼓音区为积液区邻近叩诊改变；Grocco三角区为对侧脊柱旁浊音区，均可见于胸腔积液"},{"q":"患者，男，70岁，进行性吞咽困难2个月入院。胃镜提示食管中下段不规则充盈缺损，管壁僵硬，病变段长约5.5cm。查见哪种浅表淋巴结肿大对诊断意义最大","o":["颈前后淋巴结","耳前后淋巴结","Virchow淋巴结","右锁骨上淋巴结","腋窝淋巴结"],"a":2,"e":"Virchow淋巴结为左侧锁骨上淋巴结，是胸导管汇入颈静脉处，食管癌、胃癌转移常在此触及，对食管中下段癌诊断意义最大。颈前后淋巴结多见于头颈炎症；耳前后淋巴结引流头面部；右锁骨上淋巴结多为肺癌转移；腋窝淋巴结引流上肢与乳腺"},{"q":"患者，男，24岁。数日前去公共泳池游泳，后出现尿急、尿频、尿痛等症状，医生疑为细菌性尿道炎。采集清洁中段尿进行细菌检查，常规培养条件为","o":["需氧培养","厌氧培养","微需氧培养","二氧化碳培养","含高浓度氢气的空气"],"a":0,"e":"细菌性尿道炎尿液培养常规采用需氧培养，多数尿路致病菌为需氧菌，清洁中段尿可避免污染。厌氧培养用于厌氧菌感染，非尿路常规；微需氧培养用于弯曲菌等；二氧化碳培养用于脑膜炎奈瑟菌等苛养菌；含高浓度氢气空气非标准培养条件"},{"q":"老年患者，有糖尿病史12年，糖尿病视网膜病变1年，查尿常规正常。为尽早发现患者糖尿病肾脏损害，应选择下列哪项检查协助诊断","o":["尿微量清蛋白","24h尿蛋白定量","尿液浓缩稀释功能","尿渗透压","尿比重"],"a":0,"e":"尿微量清蛋白是早期糖尿病肾损害的敏感指标，在尿常规蛋白阴性时即可升高，适合早期筛查。24小时尿蛋白定量用于显性蛋白尿；尿液浓缩稀释功能、尿渗透压与尿比重反映肾小管浓缩功能，敏感性不足，不能早期发现肾小球滤过屏障损伤"},{"q":"患者，男，3年前因高热、咳痰、咳嗽、胸痛，诊断为肺炎。10天前出现高热，咳嗽、咳痰，门诊诊断为肺炎。病历书写时，你认为3年前的肺炎应写入","o":["主诉","现病史","既往史","个人史","一般项目"],"a":2,"e":"已治愈的疾病写入既往史，3年前肺炎已痊愈，与本次肺炎无直接延续关系，故归既往史。主诉为本次就诊主要症状；现病史记录本次疾病的发生发展，10天前肺炎属现病史；个人史涉及生活习惯；一般项目为姓名、年龄等基本信息，均不接纳陈旧已愈疾病"},{"q":"患者，男，65岁。着凉后出现发热、咳嗽、咳痰、呼吸困难。既往慢性阻塞性肺疾病病史15年。该患者不可能出现的体征是","o":["桶状胸","听诊可闻及湿啰音","叩诊呈过清音","气管居中","管性呼吸音"],"a":4,"e":"慢性阻塞性肺疾病及肺气肿表现为桶状胸、叩诊过清音、呼吸运动减弱、气管居中，可闻及湿啰音，但不会出现管性呼吸音。管性呼吸音为肺实变时空气传导增强所致，见于大叶性肺炎实变期，与肺过度充气、含气量增多的病理基础相反"},{"q":"24岁男性，发热、咳嗽1周来诊。下述问诊问题不恰当的是","o":["发烧有几天了","有没有咯血","咳嗽什么情况下重","体温最高多少","咳嗽有没有时间规律"],"a":1,"e":"问诊应使用通俗易懂语言，咯血为医学术语，患者可能不理解而误解，应解释为痰中带血或咳血后再询问。发热天数、最高体温、咳嗽诱因与时间规律均为咳嗽伴发热问诊的必要内容，有助于判断病程、病因及病情变化，问法恰当"},{"q":"患者，男，40岁，腹痛、发热、皮肤黄染入院。既往胆道疾病病史多年。查体有少量腹腔积液。诊断为急性化脓性梗阻性胆管炎。那么该患者腹腔积液LDH含量可能为","o":["＜100U/L","＜150U/L","＜200U/L","＞200U/L","＞300U/L"],"a":3,"e":"急性化脓性梗阻性胆管炎并发腹膜炎时腹腔积液为渗出液，LDH增高超过200U/L，积液LDH与血清LDH比值大于0.6。小于100、150、200U/L均为漏出液范围；大于300U/L虽亦升高，但渗出液诊断界值为200U/L，故＞200U/L最准确"},{"q":"患者，32岁，女。消瘦、怕热、多汗半年余，突眼1个月就诊。查体：T 36.5℃，P 98次/min，R 22次/min，BP 120/62mmHg。甲状腺检查发现甲状腺肿大，但未超过胸锁乳突肌外缘。下列说法错误的是","o":["该患者最可能诊断是甲亢","该患者甲状腺Ⅱ度肿大","该患者甲状腺Ⅲ度肿大","该患者甲状腺上可能听到收缩期动脉杂音","该患者甲状腺可能触及震颤"],"a":2,"e":"甲状腺肿大未超过胸锁乳突肌外缘为Ⅱ度，本例伴消瘦、怕热、突眼及血管杂音符合甲亢，故Ⅲ度肿大说法错误。Ⅰ度为不能看出但能触及；超过胸锁乳突肌外缘方为Ⅲ度；甲亢甲状腺可闻收缩期动脉杂音、触及震颤，均为正确描述"},{"q":"患者，女，48岁。反复心悸，持续时间不等。体格检查示心率150次/min，心律不齐，第一心音强弱不等。下列哪种情况患者不能使用胺碘酮","o":["P波等电位线消失","RR间期不等","QTc 560ms","QRS波时限130ms","心动过速时可见“R-ON-T”现象"],"a":2,"e":"胺碘酮延长QT间期，QTc 560ms已显著超过440ms正常上限，使用可诱发尖端扭转型室速，属禁忌。心房颤动本身可见P波等电位线消失、RR间期不等；QRS增宽提示室内传导差异；R-on-T现象易致恶性心律失常，但胺碘酮使用的直接禁忌是QT延长"},{"q":"一患儿郊游后出现鼻痒、流涕，第2天出现呼吸困难、不能平卧。查体：胸廓饱满，两肺满布大量干鸣音，可能出现","o":["触觉语颤增强","两肺叩诊浊音","触觉语颤减弱","两肺叩诊实音","两肺听觉语颤增强"],"a":2,"e":"支气管哮喘发作时肺过度充气，胸廓饱满呈吸气位，呼吸动度变小，触觉语颤减弱，叩诊过清音，两肺满布干啰音。触觉语颤增强与听觉语颤增强见于肺实变；两肺叩诊浊音或实音提示胸腔积液或肺实变，均与哮喘含气量增多的体征相反"},{"q":"患者，男，22岁，头痛伴畏寒、发热5天入院。查体：胸腹部可见散在数十个鲜红色圆形斑疹，压之皮疹可消退。该患者的诊断可能是","o":["流行性脑脊髓膜炎","伤寒","猩红热","风疹","丹毒"],"a":1,"e":"玫瑰疹为鲜红色圆形斑疹，直径2～3mm，压之褪色、松开复现，多见于胸腹部，是伤寒与副伤寒的特征性皮疹，本例符合。流行性脑脊髓膜炎为瘀点瘀斑、压之不褪色；猩红热为弥漫性皮疹；风疹皮疹稀疏；丹毒为局部红肿热痛的片状红斑"},{"q":"32岁男性患者，腹痛来诊，下列问诊不恰当的是","o":["您哪儿不舒服","您腹痛有多久","您什么时间开始起病的","您大便是黑色的吗","您曾经有过类似的腹痛吗"],"a":3,"e":"问诊避免暗示性提问，您大便是黑色的吗带有诱导，应改为大便什么颜色。您哪儿不舒服为开放式提问；腹痛多久、何时起病为病程问诊；既往类似腹痛为既往史内容，均属恰当问诊，不会引导患者作出特定回答"},{"q":"患者，男，38岁，急性白血病。化疗后全血细胞减少，出现发热，血浆降钙素原水平200ng/ml，血压90/50mmHg，考虑感染性休克可能。以下哪种检查结果不会出现","o":["血浆组织型纤溶酶原激活剂测定减低","ATPP延长","纤维蛋白原下降","3P试验阴性","D-二聚体增高"],"a":0,"e":"感染性休克易并发DIC，继发性纤溶亢进使组织型纤溶酶原激活剂释放增多而非减低，同时FDP与D-二聚体增高、纤维蛋白原消耗下降、APTT延长。3P试验早期阳性、晚期可因纤维蛋白降解产物进一步分解而转阴，故阴性不能作为排除依据；t-PA减低与本例机制相反"},{"q":"患者，男，30岁。骨折后进行手术，术后出现大片皮肤瘀斑、血肿、关节出血，可能原因是","o":["血管舒缩功能紊乱","血小板质的异常","血小板量的减少","凝血因子缺乏","弥散性血管内凝血"],"a":4,"e":"骨折与手术为强促凝刺激，术后出现大片瘀斑、血肿及关节出血等多部位出血，符合弥散性血管内凝血消耗性凝血障碍。血管舒缩功能紊乱与血小板质的异常多表现为皮肤黏膜出血；血小板量的减少以瘀点为主；单纯凝血因子缺乏常有自幼出血史，均不如DIC贴合术后急性广泛出血"},{"q":"患者，女，45岁，体检发现尿糖（＋＋＋），为区别该患者肾性糖尿和糖尿病性糖尿，应加做","o":["尿定性实验","空腹血糖及糖耐量实验","尿沉渣镜检","尿蛋白分析","超声检查"],"a":1,"e":"肾性糖尿血糖正常而肾糖阈降低，糖尿病性糖尿血糖升高，空腹血糖及糖耐量试验可明确血糖水平以鉴别。尿定性实验已提示尿糖阳性，无鉴别价值；尿沉渣镜检查有形成分；尿蛋白分析评估肾脏损伤；超声检查看结构，均不能区分两类糖尿"},{"q":"患儿，男，1岁，出生1个月时发现心脏杂音。查体：于胸骨左缘2肋间及3/6级粗糙收缩期杂音，伴P2增强，S2固定分裂。患儿最可能是","o":["生理性杂音","肺动脉瓣狭窄","肺动脉瓣关闭不全","房间隔缺损","室间隔缺损"],"a":3,"e":"S2固定分裂不受呼吸影响，是房间隔缺损的典型体征，胸骨左缘第2肋间收缩期杂音为肺动脉瓣区血流增多所致相对狭窄，P2亢进提示肺血增多。生理性杂音无固定分裂；肺动脉瓣狭窄P2减弱；肺动脉瓣关闭不全为舒张期杂音；室间隔缺损杂音在胸骨左缘第3、4肋间"},{"q":"患者，男，60岁。面黄、消瘦2个月。查体：皮肤巩膜黄染，腹软，肝脾不大。腹部B超见胰腺头部占位性病变，胆管扩张。该患者尿中主要的胆红素是","o":["游离胆红素","胆红素-Y蛋白","葡萄糖醛酸胆红素","胆红素-清蛋白复合物","胆红素-Z蛋白"],"a":2,"e":"胰头占位压迫胆总管致梗阻性黄疸，结合胆红素即葡萄糖醛酸胆红素为水溶性，可经肾小球滤过从尿中排出，成为尿中主要胆红素。游离胆红素与胆红素-清蛋白复合物不溶于水不能滤过；胆红素-Y蛋白、Z蛋白为肝细胞内转运形式，不出现在尿中"},{"q":"患者，男，35岁。上腹部规律性疼痛5年，多于秋季出现。1周以来每晚12点左右出现上腹痛。3小时前，患者进食后突然出现持续性剧烈腹痛，以上腹正中为重，不敢呼吸。腹部查体：板状腹，全腹压痛（＋），反跳痛（＋），肝浊音界消失，肠鸣音减弱。该患者可能的诊断为","o":["急性胰腺炎","肠梗阻","十二指肠球部溃疡急性穿孔","幽门梗阻","急性胆囊炎"],"a":2,"e":"十二指肠球部溃疡穿透前壁致急性穿孔，突发上腹剧痛、板状腹、全腹压痛反跳痛、肝浊音界消失、肠鸣音减弱，符合急性弥漫性腹膜炎。急性胰腺炎淀粉酶显著升高、无肝浊音界消失；肠梗阻为阵发性绞痛伴肠鸣音亢进；幽门梗阻以呕吐宿食为主；急性胆囊炎疼痛向右肩放射"},{"q":"中年女性，咳嗽、右侧胸痛3天。查体：右侧可闻及胸膜摩擦音。该患者首先应考虑下列哪种疾病","o":["右侧自发性气胸","右侧少量胸腔积液","右下肺不张","右侧大量胸前积液腔","慢性支气管炎"],"a":1,"e":"胸膜摩擦音由纤维素性胸膜炎致脏壁两层胸膜粗糙引起，少量积液时两层尚未完全分开仍可闻及，积液增多则摩擦音消失。气胸叩诊鼓音、呼吸音消失；大量胸腔积液叩诊实音、摩擦音消失；肺不张气管移向患侧；慢性支气管炎无胸膜摩擦音"},{"q":"患者，男，17岁。受凉后咽痛、发热，10天后出现颜面及双下肢水肿，查尿蛋白（＋＋），尿红细胞满视野，红细胞异形率达80%。最可能的诊断是","o":["紫癜性肾炎","急性肾小球肾炎","感染性间质性肾炎","败血症","狼疮性肾炎"],"a":1,"e":"急性肾小球肾炎常在咽部感染后1～3周发病，出现血尿、蛋白尿、水肿，尿红细胞异形率高提示肾小球源性。紫癜性肾炎有对称性紫癜；感染性间质性肾炎以发热、白细胞尿为主；败血症有全身中毒症状；狼疮性肾炎多发于女性并伴多系统损害"},{"q":"患者，男，70岁。因头晕胸痛半月来诊，既往有10年高血压病史。查体血压160/75mmhg，心率102次/min，S1增强，心界左侧扩大，伴抬举样搏动。该患者叩诊心界可见","o":["梨形心","普大心","烧瓶心","心界随体位呈动态变化","靴型心"],"a":4,"e":"长期高血压致左心室肥厚扩大，心尖搏动向左下移位呈抬举样，心浊音界向左下增大、心腰加深呈靴形心。梨形心见于二尖瓣狭窄；普大心为扩张型心肌病；烧瓶心为心包积液且随体位变化；心界随体位动态变化亦为心包积液特征，均不符"},{"q":"患者，女，66岁，既往冠状动脉粥样硬化性心脏病史30年。今晨练后出现胸痛，疼痛后3小时入院，心电图如图，最可能的诊断为","o":["急性前壁心肌梗死，陈旧性下壁心肌梗死","急性前间壁、前壁心肌梗死","变异性心绞痛","急性下壁心肌梗死，陈旧性前壁心肌梗死","陈旧性前壁、下壁心肌梗死伴前壁室壁瘤形成"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。心电图定位中V1～V3导联对应前间壁、V3～V5对应前壁，急性心肌梗死表现为相应导联ST段抬高与病理性Q波。前间壁或前壁梗死多由上前降支闭塞引起；下壁梗死看Ⅱ、Ⅲ、aVF；陈旧性梗死仅有Q波而无急性ST段抬高\n\n官方题库中缺失图片"},{"q":"面部不适患者入院进行神经系统查体，发现右侧面部痛觉减退，右侧咀嚼肌无力。考虑损伤以下哪条神经","o":["右侧面神经","右侧舌咽神经","右侧三叉神经","右侧动眼神经","右侧副神经"],"a":2,"e":"三叉神经为混合神经，眼支与上颌支司面部感觉，下颌支支配咀嚼肌，右侧面部痛觉减退伴咀嚼肌无力提示右侧三叉神经损害。面神经支配表情肌而非咀嚼肌；舌咽神经主司吞咽与舌后味觉；动眼神经管眼球运动；副神经支配胸锁乳突肌与斜方肌"},{"q":"患者，男，47岁，发热1周，查见颈部多处淋巴结无痛性肿大，检查方法错误的是","o":["可站在被检查者前面，手指紧贴检查部位","由浅入深滑动触诊","触诊时让被检查者头稍高，或偏向检查侧的对侧","检查时注意淋巴结的部位、大小、硬度、压痛、活动度等","颈部检查完后，还要检查其他部位"],"a":2,"e":"颈部淋巴结触诊应嘱被检查者头稍低或偏向检查侧，使皮肤肌肉松弛便于触诊，头稍高或偏向对侧的说法错误。检查者可站于前方或背后、手指紧贴滑动触诊；由浅入深多方向滑动；注意部位、大小、硬度、压痛与活动度；颈部检查后须查其他部位，均为正确方法"},{"q":"患者，男，42岁，上腹烧灼样痛，进食后可缓解，反酸。最可能的诊断是","o":["胆囊炎","急性胰腺炎","慢性痢疾","肠梗阻","消化性溃疡"],"a":4,"e":"上腹烧灼样痛、进食后缓解、反酸为消化性溃疡尤其是十二指肠溃疡的典型节律。胆囊炎疼痛与油腻饮食相关、向右肩放射；急性胰腺炎为持续性剧痛向背部放射；慢性痢疾以腹泻黏液便为主；肠梗阻为阵发性绞痛伴停止排气排便，均不符"},{"q":"A患者由于肾小球肾炎引起的血尿，B患者由于溶血引起的血红蛋白尿，二者尿液颜色接近，用下列哪个实验可以加以区分","o":["尿液颜色观察","尿胆原测试实验","尿沉渣镜检","尿三杯实验","尿潜血实验"],"a":2,"e":"尿沉渣镜检可直接观察红细胞，血尿可见大量红细胞且肾小球源性者形态异常，血红蛋白尿无红细胞，故可区分。尿液颜色观察两者均可呈红色；尿潜血实验两者均阳性；尿三杯试验用于判断血尿来源部位；尿胆原试验反映肝胆代谢，均不能鉴别"},{"q":"患儿，男，5岁，鼻出血1天。有反复皮肤黏膜出血病史。血常规基本正常，出血时间延长，APTT、PT基本正常，血管性血友病因子减低，FⅧ:C降低，该患者最可能的诊断是","o":["血小板无力症","血友病A","血友病B","血管性血友病","过敏性紫癜"],"a":3,"e":"血管性血友病因血管性血友病因子缺乏致血小板黏附障碍，出血时间延长、vWF因子减低、FⅧ:C继发降低，符合本例。血友病A为FⅧ:C原发缺乏、vWF正常、出血时间正常；血小板无力症血小板计数正常但聚集功能缺陷；过敏性紫癜为血管壁异常、血小板功能正常"},{"q":"患者，男，23岁。右胸刀刺伤1小时，呼吸困难、发绀，胸部广泛皮下气肿，脉细速，右胸叩诊鼓音，呼吸音消失，气管左偏。该患者最可能的诊断是","o":["支气管哮喘","大叶性肺炎","急性左心衰竭","气胸","肺不张"],"a":3,"e":"锐器伤后呼吸困难发绀、广泛皮下气肿、患侧叩诊鼓音、呼吸音消失、气管向健侧移位，符合张力性气胸。支气管哮喘为双肺哮鸣音；大叶性肺炎叩诊浊音、发热；急性左心衰竭咳粉红色泡沫痰；肺不张气管移向患侧、叩诊浊音，均不符"},{"q":"患者，男，76岁。长期慢性阻塞性肺疾病史，因“基底肺炎”入院。动脉血气：pH 7.25，PaCO2 90mmHg，HCO3－ 38mEq/L，PaO2 34mmHg。该患者可能发生了","o":["急性呼吸性酸中毒并发慢性呼吸性酸中毒","呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血"],"a":0,"e":"慢性阻塞性肺疾病基础上有急性感染，PaCO2显著升高至90mmHg、pH降至7.25，HCO3部分升高未完全代偿，符合急性呼吸性酸中毒并发慢性呼吸性酸中毒。呼吸性碱中毒PaCO2降低；代谢性酸中毒以HCO3原发下降为主；抽取静脉血PaO2不会仅34mmHg，均不支持"},{"q":"患者，男，56岁，间断大便带血。查体：心肺及腹部无异常。拟进行直肠指诊（肛诊）检查，下列描述正确的是","o":["可确定乙状结肠内病变","可采取肘膝位，左侧卧位，仰卧位","先检查尿道括约肌紧张度","剧烈触痛提示有痔疮出血","触及包块即为癌性肿块"],"a":4,"e":"直肠指诊触及坚硬凹凸不平的包块应高度考虑直肠癌，需内镜活检确诊。乙状结肠位置较高超出指诊范围；检查应先注意肛门括约肌紧张度而非尿道括约肌；剧烈触痛提示肛周脓肿或肛裂，痔疮多为无痛性便血，均非正确描述"},{"q":"患者，女，45岁。平日素食。查体：双手指甲呈匙状。该患者最可能的病因是","o":["组织缺钙","组织缺镁","组织缺铁","组织缺锌","外伤"],"a":2,"e":"匙状甲又称反甲，是组织缺铁的特征性表现，长期素食者铁摄入不足易致缺铁性贫血。组织缺钙致佝偻病或手足搐搦；缺镁致神经肌肉兴奋性增高；缺锌表现为生长发育迟缓、味觉减退与皮炎；外伤所致甲改变为局部单发，均不符"},{"q":"患者，女，36岁，诊断为急性白血病（M4），在中华骨髓库配型成功，准备骨髓移植。预防骨髓移植GVHR有效方法是","o":["ABO血型配型","减少供体骨髓中的T细胞","HLA配型","减少供体骨髓中的B细胞","诱导特异性免疫耐受"],"a":4,"e":"诱导特异性免疫耐受使受者对供者组织相容性抗原产生特异性无应答，从根源阻断T细胞介导的移植物抗宿主反应，是预防GVHR的有效方法。HLA配型仅降低不相合程度；去除供体T细胞削弱抗白血病效应且影响植入；ABO配型防溶血；GVHR由T细胞启动，去除B细胞无效"},{"q":"患者，男，45岁，主诉头痛1个月。查体：BP 170/90mmHg，心界不大，心率75次/min，律齐有力，未及明确杂音，未发现神经系统异常。患者还可能有的体征是","o":["P2增强","上腹部血管杂音","靴形心","S2通常分裂","双下肢水肿"],"a":2,"e":"高血压长期作用致左心室肥厚扩大，心浊音界向左下增大、心腰加深可呈靴形心。P2增强见于肺心病或肺动脉高压；上腹部血管杂音提示肾动脉狭窄等继发原因；S2通常分裂为生理现象；双下肢水肿提示右心衰或肾功能不全，均非本例高血压性心脏病改变"},{"q":"患者，女，24岁。近2个月来找工作不顺利，常出现呼吸加快，伴叹气样呼吸，偶伴手足搐搦。该患者出现的呼吸困难最常见于下列哪种疾病","o":["脑出血","脑外伤","焦虑症","休克","脑膜炎"],"a":2,"e":"精神性呼吸困难表现为呼吸快而浅、伴叹息样呼吸及手足搐搦，因过度通气致呼吸性碱中毒，常见于焦虑症、癔症，本例找工作受压力促发，符合焦虑症。脑出血、脑外伤、脑膜炎为颅内病变伴意识改变；休克致呼吸浅快伴循环衰竭，均无叹息样呼吸与搐搦"},{"q":"患者，女，22岁。受凉后出现咽痛、发热1周。查体示咽充血，扁桃体Ⅱ度肿大。医生建议查血清抗“O”抗体，其检测结果增高的临床意义，下列哪项是错误的","o":["近期A群溶血性链球菌感染及链球菌感染相关疾病","抗体由高滴度逐步下降时，可认为疾病好转","抗体滴度恒定在高水平时，多为相关疾病的活动期","特异性高，无假阳性","假阴性可见于金葡菌感染或铜绿假单胞菌感染时"],"a":3,"e":"抗O抗体升高提示近期A群溶血性链球菌感染，但特异性有限，存在假阳性，故特异性高、无假阳性的说法错误。抗体滴度下降提示病情好转；持续高水平提示活动期；金葡菌或铜绿假单胞菌感染不引起抗O升高，可呈假阴性，均表述正确"},{"q":"患者，男，67岁，1个月来鲜血便伴黏液，近来消瘦明显。查体：腹软，肝、脾未及，腹部未及包块。首选的检查是","o":["腹部超声","腹部CT","肛门指诊","胃肠透视","腹平片"],"a":2,"e":"老年人鲜血便伴黏液、消瘦须首先排除直肠癌，肛门指诊简便易行，可触及直肠下段肿块并观察指套血迹，为首选检查。腹部超声与CT对直肠腔内早期病变不敏感；胃肠透视与腹平片主要显示梗阻或穿孔，均不能替代直肠指诊的初筛价值"},{"q":"一个医生给患者检查时轻夹患者手指向上、下移动，询问患者“向上”“向下”。这主要是检测","o":["运动觉","位置觉","触觉","震动觉","实体觉"],"a":0,"e":"轻夹手指上下移动并让患者判断方向，检查的是运动觉，属深感觉，障碍见于后索病损。位置觉为肢体置于某姿势后请患者描述或模仿；震动觉用音叉置于骨突处查振动感；触觉为浅感觉；实体觉为闭眼辨认手中物体，均与本检查方法不同"},{"q":"患者，男，65岁。尿线变细，排尿不畅5年。查体：前列腺触诊发现前列腺略增大，中央沟变浅，表面光滑、质韧，未及无压痛及粘连。该患者最可能的诊断是","o":["正常前列腺","急性前列腺炎","良性前列腺肥大","前列腺癌","前列腺钙化"],"a":2,"e":"老年男性尿线变细、排尿不畅，前列腺略增大、中央沟变浅、表面光滑质韧、无压痛粘连，符合良性前列腺肥大。正常前列腺不大；急性前列腺炎有明显压痛；前列腺癌质地坚硬、表面有硬结节；前列腺钙化无前列腺增大与排尿症状，均不符"},{"q":"患儿，男，5岁。于胸骨左缘第2肋间闻及S2分裂，吸气相明显，呼气相消失，则最可能是","o":["S2固定分裂","肺动脉高压","S2生理性分裂","房间隔缺损","S2反常分裂"],"a":2,"e":"S2生理性分裂于深吸气末出现、呼气时消失，因吸气时右心回血增多致肺动脉瓣关闭延迟，青少年常见。固定分裂不受呼吸影响，见于房间隔缺损；肺动脉高压以P2亢进为主；S2反常分裂为主动脉瓣关闭迟于肺动脉瓣，呼气时明显，均与本例不符"},{"q":"患者，女，18岁，2月前重感冒，近1月来心悸气短，进行性加重。查体：BP 90/60mmhg，交替脉，心界双侧扩大，心律120次/min，可闻及舒张期奔马律，心音低弱，未及确切杂音。则诊断最可能是","o":["甲状腺功能低下","缩窄性心包炎","心包积液","大面积心肌梗死","心肌炎"],"a":4,"e":"重感冒后1个月出现心悸气短、交替脉、心界双侧扩大、舒张期奔马律及心音低弱，提示重症心肌炎并发心力衰竭。甲状腺功能低下无奔马律与交替脉；缩窄性心包炎与心包积液无交替脉且心音遥远；大面积心肌梗死有剧烈胸痛与心电图定位改变，均不符"},{"q":"患者，女，16岁，未婚，因月经期鼻出血3个月就诊。该患者于同年6月月经初潮，连续3个月均出现月经期鼻出血，持续4～5天，总出血约100ml。应考虑诊断","o":["原发性高血压","再生障碍性贫血","维生素K缺乏","维生素C缺乏","子宫内膜异位症"],"a":4,"e":"女性周期性鼻出血与月经同步，考虑子宫内膜异位症，异位的子宫内膜随月经周期出血。原发性高血压无周期性；再生障碍性贫血有全血细胞减少与广泛出血；维生素K缺乏致凝血因子合成障碍；维生素C缺乏致牙龈出血，均无月经期鼻出血规律"},{"q":"患者，男，46岁。诉平日尿量增多而比重增高，空腹血糖10.8mmol/L。考虑的疾病是","o":["尿崩症","糖尿病","慢性肾盂肾炎","急性肾小球肾炎","急性肾衰竭"],"a":1,"e":"空腹血糖10.8mmol/L超过7.0诊断标准，尿量增多而比重增高因尿糖导致渗透性利尿，符合糖尿病。尿崩症尿量多而比重极低；慢性肾盂肾炎与急性肾衰竭均有肾浓缩功能障碍、尿比重降低，均无血糖升高，均不符"},{"q":"患者，女，60岁。体检时发现空腹血糖6.4mmol/L，作葡萄糖耐量试验，OGTT 2hPG为8、6mmol/L。下列叙述正确的是","o":["可诊断糖尿病","可排除糖尿病","应重复葡萄糖耐量试验","患者空腹血糖过高","患者糖耐量减低"],"a":4,"e":"空腹血糖6.4mmol/L低于7.0，OGTT2小时血糖8.6mmol/L介于7.8～11.1之间，符合糖耐量减低。血糖未达糖尿病诊断切点，不能诊断糖尿病，也不能排除随访；空腹血糖6.4未达空腹血糖减损与糖尿病标准；无需重复试验即可判定糖耐量减低"},{"q":"患者，男，64岁。胸骨后疼痛伴痰中带血2周，近2个月体重减轻2kg。查体：T 36.2℃，双肺呼吸音粗，未闻及干湿性啰音。患者最可能的诊断是","o":["急性心肌梗死","肺癌","食管炎","肺梗死","纵隔肿瘤"],"a":1,"e":"40岁以上男性胸骨后疼痛伴痰中带血、体重减轻，支气管肺癌少有大咯血而常表现为持续痰中带血，最可能。急性心肌梗死为压榨样痛伴濒死感、无痰中带血；食管炎为进食后烧灼痛；肺梗死伴呼吸困难与咯血；纵隔肿瘤影像可见占位，均不符"},{"q":"患者，男，51岁，基础高血压病史，长期吸烟。胸骨后疼痛1小时来诊，入室心电图如图所示，目前发病血管首先考虑","o":["左主干","左前降支","左旋支","右冠脉","左乳内动脉"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。心电图若示广泛前壁导联ST段抬高伴aVR抬高、血流动力学不稳定，首先考虑左主干闭塞。左前降支闭塞多表现为前间壁与前壁改变；左旋支累及侧壁；右冠脉闭塞多为下壁梗死；左乳内动脉非梗死常见责任血管\n\n官方题库中缺失图片"},{"q":"患者，女，28岁，已婚。因消瘦、乏力、多食、心悸3个月就诊。查体：甲状腺Ⅱ度肿大，双上极可闻及血管杂音。该患者不会出现以下哪项阳性体征","o":["眼球突出","Stellwag征","Mobius征","眼球震颤","Joffory征"],"a":3,"e":"突眼伴Stellwag征、Mobius征、Joffroy征均为Graves病眼征，眼球震颤不是甲亢体征，见于耳源性眩晕、小脑疾病或视力低下。Stellwag为瞬目减少；Mobius为集合不良；Joffroy为上视时额纹不皱，均与甲亢相关"},{"q":"患者，男，62岁。反复咳嗽、咳痰3周，发热1周。查体双肺散在干湿性啰音。为确定何种细菌感染，应首选哪项检查","o":["痰细菌检查","痰物理性质检查","X片检查","血清学实验","组织病理学检查"],"a":0,"e":"确定细菌感染首选痰细菌检查，涂片镜检与分离培养可鉴定菌种并做药敏，为诊断金标准。痰物理性质检查仅观性状无病原学价值；X线提示病变部位不能定性；血清学实验用于特定病原；组织病理学检查创伤大，均非首选"},{"q":"某3岁患儿，额、顶、颞及枕部突出膨大呈圆形，颈静脉充盈，颜面显小，双目下视，巩膜外露。该患儿最可能的疾患是","o":["呆小病","佝偻病","唐氏综合征","脑积水","先天性梅毒"],"a":3,"e":"巨颅、颈静脉充盈、颜面狭小及落日现象为脑积水特征，因颅内压增高压迫眼球致双目下视、巩膜外露。呆小病为智能低下与特殊面容；佝偻病为方颅、乒乓颅；唐氏综合征有特殊面容与染色体异常；先天性梅毒可致方颅但无落日现象，均不符"},{"q":"患者，女，38岁。于卧位起立时突然感觉头晕。查体：站立位BP 50/40mmHg，心肺无异常。有关这种情况的描述错误的是","o":["发生于某些长期站立于固定位置及长期卧床者","发生于服用氯丙嗪、胍乙啶等药物者","发生于交感神经切除术后患者","是由于各种刺激通过迷走神经反射引起","由于卧位或蹲位突然站起时发生"],"a":3,"e":"体位性低血压因体位骤变时交感神经反射性收缩血管功能不足、回心血量减少所致，并非迷走神经反射引起，该描述错误。长期站立或卧床者、服用氯丙嗪或胍乙啶、交感神经切除术后均可发生；卧位或蹲位突然站起为典型诱因，均为正确描述"},{"q":"患者，男，20岁。腰骶、腰背部疼痛2年，伴晨僵，弯腰受限。查体见脊柱生理弯曲消失。最可能的疾病是","o":["脊椎结核","类风湿关节炎","强直性脊柱炎","腰椎间盘突出症","脊椎肿瘤"],"a":2,"e":"青少年腰背痛伴晨僵、活动受限、脊柱生理弯曲消失，符合强直性脊柱炎，晚期脊柱强直固定。脊椎结核多有椎体破坏、成角畸形与结核中毒症状；类风湿关节炎以周围小关节为主；腰椎间盘突出症无晨僵与脊柱强直；脊椎肿瘤疼痛夜间加重，均不符"},{"q":"患者，男，40岁，有高血压和大量吸烟病史。突发胸闷3小时就诊，心电图如图所示，首先考虑","o":["急性前壁心肌梗死","急性前间壁心肌梗死","变异型心绞痛","急性广泛前壁心肌梗死","急性重症心肌炎"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。心电图若V1～V5大部分胸导联出现异常Q波或QS波，则为广泛前壁心肌梗死，多由左前降支闭塞。急性前壁仅V3～V5；前间壁为V1～V3；变异型心绞痛为一过性ST抬高；重症心肌炎无典型梗死图形\n\n官方题库中缺失图片"},{"q":"患者，男，68岁，发现黄疸1个月伴恶心、发热。经抗感染治疗后恶心、发热等症状消失，但黄疸逐渐加深，胆囊显著增大，近2日出现呕少量血。该患者最可能的诊断是","o":["急性胰腺炎","急性胆囊炎","胰头肿瘤","胆囊癌","胆总管结石"],"a":2,"e":"进行性加深的黄疸伴显著肿大而无压痛的胆囊，即Courvoisier征阳性，提示胰头肿瘤压迫胆总管。胆总管结石因慢性炎症致胆囊纤维化皱缩，胆囊多不肿大；胆囊癌以胆囊肿块为主；急性胰腺炎血淀粉酶显著升高；急性胆囊炎胆囊压痛明显，均不符"},{"q":"患者，男，20岁，平时身体健康。右侧肋骨骨折1小时入院，面色苍白，胸痛、气促。查体：呼吸35次/min，心率105次/min，血压95/58mmHg，气管左移，右肺叩诊鼓音，右肺呼吸音明显降低。该患者出现呼吸困难最可能的原因是","o":["急性左心衰竭","大叶性肺炎","急性冠脉综合征","主动脉夹层","气胸"],"a":4,"e":"肋骨骨折刺破肺组织致气胸，突然胸痛呼吸困难、气管向健侧移位、患侧叩诊鼓音、呼吸音降低及休克倾向，符合气胸。急性左心衰竭咳粉红色泡沫痰、双肺湿啰音；大叶性肺炎叩诊浊音；急性冠脉综合征有心电图改变；主动脉夹层撕裂样痛，均不符"},{"q":"患者，女，因下肢发凉入院检查。医生给患者全身涂抹碘、蓖麻油和酒精混合制剂，之后再敷淀粉，应用毛果芸香碱发汗。该医生给患者做的检查是以下哪项检查","o":["皮肤划痕症","竖毛反应","发汗实验","病理反射","感觉平面检查"],"a":2,"e":"碘淀粉法为发汗试验，碘与蓖麻油酒精涂布皮肤后敷淀粉，注射毛果芸香碱激动交感神经节后纤维致出汗，出汗处淀粉变蓝，用于判断交感神经功能障碍范围。皮肤划痕症为血管反应；竖毛反应查竖毛肌；病理反射与感觉平面检查均无需碘淀粉法"},{"q":"患者，女，39岁，血尿2天，尿常规镜下均为畸形红细胞，但除外","o":["皱缩红细胞","大型红细胞","细胞质有葫芦状外展内有细颗粒","浅黄色双面圆盘形红细胞","胞膜破裂及部分细胞质丢失"],"a":3,"e":"肾小球源性血尿的畸形红细胞包括皱缩、大型、胞质葫芦状外展伴细颗粒、胞膜破裂及胞质丢失等形态；浅黄色双面圆盘形为正常红细胞形态，不属于畸形红细胞。本例均见畸形红细胞提示肾小球病变，正常双凹圆盘形红细胞不符合"},{"q":"患者，男，46岁，突发腰痛3小时，呈剧烈绞痛。查体：急性病容，右肾区叩痛。尿常规示红细胞＋/HPF。该患者最可能的诊断是","o":["尿路结石","肾盂肾炎","急性肾炎","前列腺炎","腰椎间盘突出"],"a":0,"e":"突发剧烈绞痛伴肾区叩痛及镜下血尿，符合尿路结石，结石多为均一性红细胞。肾盂肾炎有发热、白细胞尿；急性肾炎为肾小球源性血尿伴蛋白尿、水肿；前列腺炎有尿频尿急与前列腺压痛；腰椎间盘突出无血尿，均不符"},{"q":"患儿，女，出生后30天。足月顺产，第1胎，否认有传染病接触史。入院前5天无明显诱因发热、呼吸及吞咽困难，拒乳。查体发现咽部充血红肿，扁桃体Ⅱ度肿大，并附着有难剥离的片状假膜。诊断考虑","o":["鹅口疮","慢性咽炎","急性化脓性扁桃体炎","咽白喉","急性咽炎"],"a":3,"e":"咽白喉假膜灰白、不易剥离，强行剥离易出血，伴发热、吞咽困难与拒乳，符合本例。鹅口疮为口腔白色乳凝块样物、易擦去；慢性咽炎无假膜；急性化脓性扁桃体炎渗出物易剥离；急性咽炎仅为咽部充血，均不符"},{"q":"患者，男，26岁。2周前感冒后出现口干、多饮、多尿，未重视。1天前因口干饮用大量碳酸饮料后突发昏倒，不能正确辨别时间、地点和周围亲人，但能保持简单的精神活动。患者意识状态应诊断为","o":["昏睡","嗜睡","意识模糊","谵妄","轻度昏迷"],"a":2,"e":"意识模糊表现为意识水平轻度下降，能保持简单精神活动，但对时间、地点、人物定向发生障碍，本例不能正确辨别时间地点与亲人，符合。嗜睡可唤醒且回答正确；昏睡需强刺激唤醒、很快再入睡；谵妄伴幻觉躁动；轻度昏迷对刺激无意识反应，均不符"},{"q":"患者，女，61岁。慢性咳嗽、咳痰20年，加重伴呼吸困难3天，曾明确诊断为“慢性阻塞性肺疾病”。该患目前最有可能出现的体征是","o":["可闻及干、湿啰音","呼吸运动增强","语音共振增强","叩诊呈浊音","呼气相缩短"],"a":0,"e":"慢性阻塞性肺疾病急性加重期气道分泌物增多、感染存在，可闻及干、湿啰音。呼吸运动减弱而非增强；语音共振减弱而非增强；叩诊呈过清音而非浊音；呼气相延长而非缩短，均与肺过度充气、气道阻塞的病理生理相反"},{"q":"患者，男，58岁。原发性高血压5年，平时饮酒500g/d。要想评价该患者发生冠心病的风险，主要关注的脂蛋白是","o":["乳糜微粒","极低密度脂蛋白","低密度脂蛋白","高密度脂蛋白","中间密度脂蛋白"],"a":3,"e":"高密度脂蛋白介导胆固醇逆向转运，为抗动脉粥样硬化因子，其降低是冠心病独立危险因素，本例长期大量饮酒可影响HDL-C，评估冠心病风险应重点关注。乳糜微粒转运外源性甘油三酯；极低密度脂蛋白转运内源性甘油三酯；中间密度脂蛋白为代谢产物，均非主要关注指标"},{"q":"一患者神经系统查体发现患者右侧角膜直接对光反射消失，间接对光反射存在。考虑患者损伤的是","o":["右侧三叉神经","右侧面神经","左侧三叉神经","左侧面神经","右侧动眼神经"],"a":1,"e":"角膜反射传入为三叉神经眼支、传出为面神经。刺激右角膜时右眼不眨眼、左眼眨眼存在，说明右侧传入完好而右侧面神经传出受损，故为右侧面神经病变。右侧三叉神经病变时刺激右角膜双眼均无反应；动眼神经司瞳孔对光反射与眼球运动，不参与角膜反射"},{"q":"下列哪种药物可用于本例患者发作心房颤动时的治疗","o":["毛花苷C","美托洛尔","普罗帕酮","胺碘酮","腺苷"],"a":2,"e":"本例心电图窦性心律时呈预激图形，房颤发作时激动经旁路前传，应选用能延长旁路不应期的普罗帕酮。毛花苷C、美托洛尔、腺苷抑制房室结传导，可使激动更多经旁路下传致心室率骤增甚至室颤，属禁忌；胺碘酮对旁路作用不确定，均不宜选用"},{"q":"患者，男，72岁。上腹疼痛2天，发热1天，最高达38℃。下列疾病中可能性最小的是","o":["胆囊炎","十二指肠溃疡穿孔","急性心肌梗死","胰腺炎","肠结核"],"a":4,"e":"肠结核起病缓慢，多有腹痛、腹泻与便秘交替、低热盗汗及结核病史，极少表现为急性上腹痛伴发热，可能性最小。胆囊炎有右上腹痛与Murphy征；十二指肠溃疡穿孔为突发上腹剧痛与腹膜刺激征；急性心肌梗死可表现为上腹痛；胰腺炎血淀粉酶升高，均更可能"},{"q":"患者，女，28岁，怕热多汗伴消瘦2个月，体检颈前区肿大且可闻及血管杂音。该患者的面容可能是","o":["面色苍白，颜面水肿","面色晦暗，额部有褐色色素沉着","表情淡漠，反应迟钝呈无欲状态","面色苍白，表情疲惫","面容惊愕，眼裂增宽，目光闪亮"],"a":4,"e":"甲状腺功能亢进面容为面容惊愕、眼裂增宽、眼球突出、目光闪亮、兴奋不安，本例怕热多汗、消瘦、颈部血管杂音符合甲亢。面色苍白颜面水肿为黏液性水肿；面色晦暗额部色素沉着为肝病面容；表情淡漠反应迟钝为伤寒或黏液性水肿；面色苍白表情疲惫为贫血面容"},{"q":"患者，男，40岁。高脂饮食后中上腹部疼痛8小时入院，淀粉酶1044U/L。患者可出现下列查体表现，除外","o":["肠鸣音减弱","腰部皮肤呈蓝色","蠕动波增加","腹式呼吸减弱","中上腹压痛"],"a":2,"e":"高脂饮食后上腹痛伴淀粉酶显著升高符合急性胰腺炎，炎症致麻痹性肠梗阻，肠鸣音减弱、腹式呼吸减弱、中上腹压痛，重症可致腰部皮肤青紫即Grey Turner征。蠕动波增加提示胃肠道梗阻，与胰腺炎肠管麻痹、肠鸣音减弱相反，故不会出现"},{"q":"患者，女，55岁，8年前因“心脏病”而提前退休。入院前1日夜间于睡眠中突然憋醒，不能平卧，自觉呼吸困难。查体：心尖部可闻及舒张期隆隆样杂音，双肺布满干、湿啰音。此患者最可能咳","o":["白色泡沫样痰","粉红色泡沫样痰","黄脓痰","铁锈色痰","砖红色黏稠痰"],"a":1,"e":"心尖部舒张期隆隆样杂音提示二尖瓣狭窄，夜间突发的阵发性呼吸困难、端坐呼吸、双肺满布干湿啰音是急性左心衰竭肺水肿的表现，肺泡内浆液渗出形成大量粉红色泡沫样痰。铁锈色痰为肺炎链球菌肺炎的特征，砖红色黏稠痰见于肺炎克雷伯杆菌肺炎，黄脓痰提示呼吸道化脓性感染，均非肺水肿所见"},{"q":"患者，男，45岁，主诉头痛1个月。查体：BP 170/90mmHg，心界不大，心率75次/min，律齐有力，未及明确杂音，未发现神经系统异常。该患者诊断最可能是","o":["原发性高血压2级","原发性高血压1级","原发性高血压3级","单纯收缩期高血压","正常高值"],"a":0,"e":"收缩压170mmHg已达2级标准，舒张压90mmHg属1级，血压分级取两者中较高者，故判为2级。单纯收缩期高血压要求舒张压低于90mmHg，本题舒张压已达90；正常高值收缩压不超过139mmHg；3级需收缩压达180mmHg或舒张压达110mmHg，均不符"},{"q":"6岁男童，因水肿2周就诊，外院检查发现尿蛋白阳性。为明确诊断，以下哪项检查不是首先考虑的","o":["尿常规","肾功能","24h尿蛋白定量","肾活检","血白蛋白"],"a":3,"e":"肾活检为有创检查，须在尿常规、肾功能、24小时尿蛋白定量、血白蛋白等无创检查提示适应证后才考虑，不是明确水肿伴蛋白尿病因的首选。尿常规可发现血尿蛋白尿，肾功能评估滤过功能，24小时尿蛋白定量明确蛋白程度，血白蛋白判断低蛋白血症，均为初步必查项目"},{"q":"患者，男，20岁，突然呼吸困难来诊。查体端坐呼吸，胸廓饱满，诊断为支气管哮喘。最典型的听诊特点是","o":["双肺干啰音","双肺哮鸣音","水泡音","肺泡呼吸音增强","可听到病理性呼吸音"],"a":1,"e":"支气管哮喘发作时支气管平滑肌痉挛、黏膜水肿，呼气气流受限，双肺可闻及弥漫性哮鸣音，为最典型的听诊特点。水泡音即湿啰音，是肺泡或支气管内分泌物增多所致，见于肺炎、肺水肿；一般干啰音概念宽泛而不具特异性；病理性呼吸音多指实变区的支气管呼吸音，均非哮喘特征"},{"q":"患者，男，36岁。左胫骨骨折内固定术后3周，气促、呼吸困难4天，胸痛、咯血1天入院。查体：双肺呼吸音粗，未闻及啰音，心率98次/min，律齐，左下肢水肿。该患者首先考虑诊断为","o":["院内获得性肺炎","急性支气管炎","肺血栓栓塞症","脂肪栓塞","急性上呼吸道感染"],"a":2,"e":"骨折内固定术后长期卧床，下肢深静脉血栓形成，脱落栓子阻塞肺动脉，出现呼吸困难、胸痛、咯血三联征及患肢水肿，首先考虑肺血栓栓塞症。脂肪栓塞多见于长骨骨折后早期，伴意识障碍和皮下瘀点；院内获得性肺炎以发热、咳痰为主，均无本例的血栓征象"},{"q":"患者，女，36岁。劳力性心累、气短半个月。既往关节肿痛史。查体：血压110/75mmHg，脉搏85次/min，心率145次/min，心律不齐，心音强弱不等。超声心动图提示二尖瓣重度粘连，未见钙化，开放受限。患者听诊的典型杂音为","o":["心尖区全收缩期粗糙吹风样杂音向左腋下传导","心尖区舒张中晚期隆隆样杂音","心尖区舒张早期叹气样递减性杂音","胸骨左缘第3、4肋间舒张早期叹气样递减性杂音","胸骨右缘第2肋间全收缩期递增递减性杂音"],"a":1,"e":"二尖瓣重度粘连、开放受限即二尖瓣狭窄，心尖区低调、隆隆样、舒张中晚期递增型杂音是其最重要体征，左侧卧位更清楚。心尖区全收缩期粗糙吹风样杂音向左腋下传导为二尖瓣关闭不全；舒张早期叹气样递减性杂音是主动脉瓣关闭不全；Austin Flint杂音柔和递减，见于重度主动脉瓣反流"},{"q":"患者，男，72岁。大便秘结，便血3个月。查体：直肠指检示肛门口上5cm触及质硬结节，大小约3cm×2cm，表面凹凸不平。该患者最可能的诊断是","o":["直肠息肉","直肠癌","肛周脓肿","痔疮","直肠感染"],"a":1,"e":"直肠指检触及质硬、表面凹凸不平的包块是直肠癌的典型表现，伴便血及排便习惯改变更支持。直肠息肉多柔软带蒂、表面光滑；痔疮为齿状线上下紫红色柔软静脉团；肛周脓肿局部红肿热痛、有波动感且压痛明显，均不同于质硬凹凸不平的恶性结节"},{"q":"患者，女，28岁，低热、咳嗽半个月，体检右侧Kronig峡为2cm，诊断首先考虑的是该患者的肺尖部有","o":["气胸","肺气肿","肺大疱","肺尖结核","胸膜炎"],"a":3,"e":"Kronig峡正常宽4至6cm，右侧变窄至2cm，提示肺尖部病变使清音带缩小，结合低热、咳嗽，首先考虑肺尖结核。肺气肿因肺过度充气使Kronig峡增宽、叩诊过清音；气胸叩诊鼓音、呼吸音消失；肺大疱多无肺尖清音带进行性变窄的典型改变"},{"q":"患者，女，29岁，因发热伴关节痛2周收入院。查体见面颊局部皮肤发红、呈蝶形、未突出皮肤表面。该患者最可能的诊断是","o":["猩红热","药物疹","伤寒","麻疹","系统性红斑狼疮"],"a":4,"e":"面颊部蝶形红斑、不高起皮面，伴发热、关节痛，是多系统受累的表现，最常见于系统性红斑狼疮。猩红热为弥漫性充血性皮疹伴草莓舌、咽峡炎；麻疹有科氏斑及顺序出疹；药物疹有明确用药史且形态多样，均不形成固定蝶形分布"},{"q":"患者，男，57岁。剧烈头痛1小时，头痛程度较重，无减轻，伴有意识障碍。查体：T 36.2℃，颈项强直（＋）。患者最可能的诊断是","o":["病毒性脑膜炎","血管神经性头痛","蛛网膜下腔出血","肌紧张性头痛","脑肿瘤"],"a":2,"e":"急剧发生的持续性剧烈头痛伴不同程度意识障碍而无发热，提示颅内血管性疾病，加之颈项强直等脑膜刺激征，最符合蛛网膜下腔出血。病毒性脑膜炎多有发热、脑膜刺激征较轻；血管神经性和肌紧张性头痛无意识障碍及脑膜刺激征；脑肿瘤呈慢性进行性头痛"},{"q":"患者，女，20岁，因咳嗽、咳痰伴发热5天入院。胸片示右下肺斑片状浸润影、右侧少量胸腔积液。该患者可能采取的体位是","o":["自主体位","被动体位","强迫侧卧位","强迫仰卧位","强迫坐位"],"a":0,"e":"右下肺斑片状浸润影伴少量胸腔积液为局限性肺部炎症，患者神志清、活动自如，身体体位不受限制，呈自主体位。强迫侧卧位见于一侧大量胸腔积液或胸膜炎以缓解呼吸困难；强迫仰卧位见于急性腹膜炎；强迫坐位见于心衰、肺水肿端坐呼吸，本例均不具备"},{"q":"患儿，女，1岁。因“呕吐2天，发热伴腹泻1天”入院。呕吐非喷射性，5～6次/d；腹泻8次/d，为稀水样便，量多；近1天尿少，无不洁饮食史。查体：T 37.8℃，P 110次/min，R 26次/min，BP 80/60mmHg，神志清，精神倦，唇干，皮肤干燥，前囟凹陷，颈软，双侧瞳孔等大等圆，对光反射灵敏，双肺呼吸音清，心音有力，心律齐，未闻及杂音，腹软，未及包块，肝肋下1cm，质软，脾未触及，肠鸣音7～8次/min，四肢暖，病理征未引出。血清电解质：血钠130mmol/L，血钾3、5mmol/L，血氯90mmol/L，HCO3-18mmol/L。尿常规：酮体＋＋。大便常规：白细胞＋。下列符合患儿表现的是","o":["中度低渗性脱水，轻度酸中毒，低钠低氯血症","重度等渗性脱水，中度酸中毒，低钠低氯血症","轻度等渗性脱水，中度酸中毒，低氯血症","中度低渗性脱水，轻度酸中毒，低钠高氯血症","重度等渗性脱水，重度酸中毒，高钠高氯血症"],"a":0,"e":"血钠130mmol/L、血氯90mmol/L均低于正常，属低渗性脱水伴低钠低氯血症；精神倦怠、唇干、皮肤干燥、前囟凹陷、尿少符合中度脱水；HCO3为18mmol/L，酸中毒程度轻。重度脱水应有明显循环衰竭，等渗性脱水血钠正常，高氯血症血氯应升高，均与电解质结果不符"},{"q":"一女性患者因左侧下肢麻木入院，接诊医生进行神经系统查体发现左侧腹部平肚脐以下存在痛觉减退。考虑患者损伤的是以下哪个部位","o":["皮质脊髓侧束","皮质丘脑束","脊髓丘脑侧束","脊髓丘脑前束","脊髓后索"],"a":2,"e":"痛觉和温度觉障碍均由脊髓丘脑侧束损害引起，左侧腹部平脐以下痛觉减退提示该束受累。脊髓丘脑前束与后索传导触觉，损害表现为触觉障碍；皮质脊髓侧束为运动传导束，损害致瘫痪；皮质丘脑束并非痛温觉的主要传导通路"},{"q":"患者，女，32岁，因面色出现色素斑而来皮肤科就诊。查体发现其鼻梁部皮肤出现红色斑块，病损部高起皮面并向两侧面颊部扩展。最可能是下列哪种疾病","o":["黑热病","肝脏疾病","系统性红斑狼疮","风湿性心脏病","酒渣鼻"],"a":2,"e":"鼻梁红色斑块、高起皮面并向两侧面颊扩展，是系统性红斑狼疮的典型面部皮疹。酒渣鼻的皮损主要在鼻尖和鼻翼，伴毛细血管扩张与组织肥厚；黑热病、肝脏疾病所致面色改变为弥漫性色素沉着；风湿性心脏病无此类鼻部皮疹"},{"q":"患者，男，58岁。长期抽烟，近1个月来痰中带血，体重下降，X线胸片示左上肺密度较高圆形阴影。若该患者出现浅表淋巴结肿大，最先肿大的区域是","o":["左颈后淋巴结群","右颈前淋巴结群","左锁骨上窝淋巴结","右锁骨上窝淋巴结","左颈前淋巴结群"],"a":3,"e":"肺癌多经淋巴道向右侧锁骨上窝或腋窝淋巴结转移，左上肺病灶出现浅表淋巴结肿大时首先累及右锁骨上窝。左锁骨上窝淋巴结即Virchow淋巴结，是胃癌、食管癌经胸导管转移的标志；颈前、颈后淋巴结主要引流头颈部，非肺癌转移的首站"},{"q":"患者，男，16岁，3天前淋雨后出现高热、咳嗽、咳铁锈色痰。关于该患者体格检查，描述错误的是","o":["患侧语颤增强","患侧叩诊浊音","患侧呼吸音减弱","患侧常可闻及弥漫干啰音","患侧有时可听到胸膜摩擦音"],"a":3,"e":"铁锈色痰提示肺炎链球菌大叶性肺炎，实变期语颤增强、叩诊浊音，可闻支气管呼吸音及胸膜摩擦音，呼吸音可减弱。弥漫干啰音是支气管哮喘、慢性阻塞性肺疾病等气道痉挛狭窄的体征，肺炎实变区以湿啰音或支气管呼吸音为主，故该项描述错误"},{"q":"患者，女，36岁，消瘦伴有畏热多汗，性情急躁，心悸，多考虑哪种疾病导致的消瘦","o":["肾上腺皮质功能减退症","希恩综合征","1型糖尿病","甲状腺功能亢进症","神经精神疾病"],"a":3,"e":"甲状腺功能亢进症因代谢亢进致消瘦、畏热多汗、性情急躁、心悸，可伴突眼及甲状腺肿大，与本例高度吻合。肾上腺皮质功能减退伴皮肤黏膜色素沉着、乏力低血压；1型糖尿病以多饮多尿多食消瘦为主；希恩综合征为产后大出血致腺垂体功能减退"},{"q":"患者，男，56岁，2年前患者反复出现多关节疼痛，疼痛时伴晨僵，查体在肘关节鹰嘴突周围可见大小不一、质硬、无压痛的皮下小结。该患者的皮下结节可能是","o":["风湿结节","痛风结节","结节性红斑","动脉炎结节","Osler结节"],"a":0,"e":"风湿结节位于关节或骨隆突附近，圆形、质硬、无压痛、大小不等，肘关节鹰嘴突周围为其好发部位。痛风结节伴高尿酸血症、局部红肿灼热；结节性红斑多见于小腿伸侧、有明显压痛；Osler结节位于指趾垫、伴压痛，见于感染性心内膜炎"},{"q":"患者，男，60岁，突发鼻出血入院。查体：BP 200/100mmHg，心肺正常。血常规正常。需要立即给予的处理是","o":["局部填塞止血","降压","注射止血药","冷水敷脸","补液"],"a":1,"e":"血压200/100mmHg属高血压急症级别，鼻出血与血压急剧升高相关，首要处理是迅速降压以控制出血并防止靶器官损害。局部填塞仅为止血对症措施；注射止血药、冷水敷脸、补液均未针对血压过高这一根本诱因，不能替代降压"},{"q":"患者，女，32岁。发热、盗汗、乏力12天，呼吸困难2天。查体：T 38℃，右下肺叩诊浊音，呼吸音消失。患者最可能的诊断是","o":["右胸膜间皮细胞瘤","右干酪性肺炎","右结核性胸膜炎","右大叶性肺炎","右胸膜肥厚粘连"],"a":2,"e":"发热、盗汗、乏力为结核中毒症状，右下肺叩诊浊音、呼吸音消失提示胸腔积液，结核性胸膜炎是青年胸腔积液的首要原因。大叶性肺炎叩诊浊音但语颤增强、可闻支气管呼吸音；胸膜间皮细胞瘤无明显中毒症状；胸膜肥厚粘连无急性发热与积液征"},{"q":"患者，男，32岁。自幼患麻疹后，经常咳嗽、咳痰、痰中带血，诊断为支气管扩张。该患可出现的体征是","o":["气管向患侧移位","双肺广泛干啰音","佝偻胸","肋间隙缩窄","局限固定的湿啰音"],"a":4,"e":"支气管扩张的典型体征是病变部位局限而固定的湿啰音，长期咳嗽、咳脓痰、咯血与之相符。双肺广泛干啰音见于哮喘或慢性阻塞性肺疾病；佝偻胸为佝偻病骨骼改变；肋间隙缩窄可见于肺不张，均非支气管扩张的特征性体征"},{"q":"患者，男，65岁。吸烟40余年，慢性咳嗽，咳痰20余年。双肺呼吸音减弱，肺下界下移。最可能的诊断是","o":["肺炎","慢性阻塞性肺疾病","胸腔积液","支气管哮喘","气胸"],"a":1,"e":"老年男性长期吸烟，慢性咳嗽咳痰二十余年，双肺呼吸音减弱、肺下界下移，符合慢性阻塞性肺疾病伴肺气肿。气胸突发胸痛、叩诊鼓音、呼吸音消失；肺炎急性起病伴发热；支气管哮喘为发作性呼气性呼吸困难伴哮鸣音，均无长期进行性肺过度充气表现"},{"q":"3岁儿童，高热、昏迷、抽搐2天急诊入院，疑为乙脑和中毒性痢疾。为及时诊断，应立即进行的检查是","o":["大便培养","肛拭子或盐水灌肠镜检","脑脊液常规","头颅CT","乙脑特异性IgM测定"],"a":1,"e":"高热、昏迷、抽搐需鉴别流行性乙型脑炎与中毒性细菌性痢疾，后者需尽快从粪便找到病原，肛拭子或盐水灌肠镜检可立即获得结果。大便培养耗时数日不能及时诊断；脑脊液常规和乙脑特异性IgM主要针对乙脑，不能快速排除中毒性痢疾；头颅CT无鉴别价值"},{"q":"患者，男，10岁，活动后心悸，气促8年。查体：心前区隆起，胸骨左缘3～4肋间触及收缩期震颤，同时该处闻及4/6级收缩期杂音。最可能的诊断是","o":["房间隔缺损","动脉导管未闭","室间隔缺损","法洛四联症","三尖瓣狭窄"],"a":2,"e":"胸骨左缘第3、4肋间收缩期震颤伴响亮粗糙的全收缩期杂音，是室间隔缺损的典型体征。房间隔缺损杂音在胸骨左缘第2肋间伴第二心音固定分裂；动脉导管未闭为第2肋间连续性机器样杂音；法洛四联症有明显发绀及蹲踞，均与本例不符"},{"q":"患者，男，39岁，夜尿增多半年，乏力1个月就诊。尿常规示尿蛋白＋＋＋，肾功能示尿素氮45.2mmol/L，肌酐987μmol/L。现进行移植前准备，为预防超急性排斥反应，应行下列哪项检查","o":["HLA血清学定型","HLA细胞学定型","HLA基因定型","PHA激发的淋巴细胞转化试验","淋巴细胞交叉毒性试验"],"a":4,"e":"超急性排斥反应由受者体内预存的抗供者抗体介导，移植前须做淋巴细胞交叉毒性试验，检测受者血清能否杀伤供者淋巴细胞。HLA血清学、细胞学及基因定型用于组织配型、预防急性排斥；PHA激发的淋巴细胞转化试验反映细胞免疫功能，均不能预判超急性排斥"},{"q":"患者，男，54岁，诊断为酒精性肝硬化3年。现发热并意识恍惚2小时。有助于判断患者有无肝性脑病的血液化验指标是","o":["球蛋白","丙氨酸氨基转移酶","白蛋白","血小板计数","血氨"],"a":4,"e":"肝硬化时肝脏鸟氨酸循环受损、尿素合成减少，血氨升高并在中枢积聚是肝性脑病的核心机制，故血氨是判断有无肝性脑病的关键指标。丙氨酸氨基转移酶反映肝细胞损伤，白蛋白、球蛋白反映合成功能，血小板计数反映脾亢或凝血，均不直接反映肝性脑病"},{"q":"患儿，男，12岁，因“左膝关节肿痛8年，再发7天”来诊。血常规：白细胞10.5×109/L，N 80%，L 17%，M 3%，Hb 130g/L，PLT 140×109/L。肝功能正常。为进一步确诊，应该首先进行的检查是","o":["Ⅷ因子测定","Ⅹ因子测定","Ⅺ因子测定","D-二聚体测定","纤维蛋白降解产物测定"],"a":0,"e":"儿童反复单侧膝关节肿痛、关节腔出血，最可能为血友病甲，因凝血因子Ⅷ缺乏导致内源性凝血障碍，故首选Ⅷ因子测定。因子Ⅺ缺乏即血友病丙，发病少见、出血较轻；D-二聚体和纤维蛋白降解产物反映纤溶活性，主要用于DIC筛查，非关节出血的确诊检查"},{"q":"患者，女，17岁，春游时出现支气管哮喘急性发作，下列体征最有助于诊断的是","o":["语音震颤减弱","叩诊呈过清音","肺部散在干啰音","两肺弥漫哮鸣音","两肺底水泡音"],"a":3,"e":"支气管哮喘急性发作时广泛气道痉挛，双肺弥漫性哮鸣音是最具诊断价值的体征。语音震颤减弱和叩诊过清音为肺过度充气表现，常见于肺气肿；肺部散在干啰音缺乏特异性；两肺底水泡音提示心力衰竭肺淤血，均非哮喘急性发作的特征"},{"q":"患者，男，67岁。间断大便带血2个月。要想进行肛门直肠检查，不常采用的体位是","o":["肘膝位","左侧卧位","截石位","蹲位","平卧位"],"a":4,"e":"肛门直肠检查常用肘膝位、左侧卧位、截石位及蹲位，可充分暴露肛周并利于指检和窥镜操作。平卧位时臀部受压、肛门暴露困难，且不便于观察排便及肿物脱出，故不常采用，其余体位均为常规检查体位"},{"q":"患者，女，23岁。双肘、腕、膝等关节疼痛2个月，伴脱发、口腔溃疡、光敏感。最可能的疾病是","o":["类风湿关节炎","系统性红斑狼疮","骨关节炎","化脓性关节炎","关节结核"],"a":1,"e":"多关节疼痛伴脱发、口腔溃疡、光敏感，提示多系统自身免疫损害，最符合系统性红斑狼疮。类风湿关节炎为对称性小关节肿痛、晨僵与畸形，无光过敏脱发；骨关节炎多见于负重关节、无全身症状；化脓性关节炎为单关节急性红肿热痛"},{"q":"患者，女，24岁。因习惯性流产入院，考虑诊断为继发性抗心磷脂综合征。目前哪项检测最有意义","o":["ACA","APTT","TT","AT","PT"],"a":0,"e":"抗磷脂综合征以抗磷脂抗体介导的高凝状态和病理性妊娠为特征，抗心磷脂抗体针对带负电荷磷脂、干扰磷脂依赖的凝血过程，与习惯性流产关系密切，检测最有意义。APTT、TT、PT仅是凝血筛选试验，AT为抗凝血酶，均不能反映抗磷脂抗体的存在"},{"q":"26岁哺乳期女性，近两日出现发热、大汗、寒战，右侧乳房有红、肿、热、痛，触诊有包块，质硬、最可能的诊断是","o":["急性乳腺炎","乳腺癌","乳腺囊肿","乳腺脓肿","乳腺纤维腺瘤"],"a":0,"e":"哺乳期妇女乳房红、肿、热、痛，触及硬结包块，伴寒战、发热、大汗，符合急性乳腺炎。乳腺脓肿为炎症化脓阶段、可及波动感；乳腺癌一般无炎症表现，多为单发质硬肿块、橘皮样皮肤及乳头回缩；乳腺囊肿、纤维腺瘤无急性感染症状"},{"q":"患儿，男，11岁，晨起眼睑水肿，血尿、少尿1周。血压180/105mmHg，既往无肾病史，尿沉渣：红细胞满视野，大小不一，可见大红细胞，棘形红细胞。患者血尿类型为","o":["均一性血尿","非均一性血尿","血红蛋白尿","肾后性血尿","暂时性血尿"],"a":1,"e":"尿红细胞大小不一、形态多样并见棘形红细胞，属非均一性即肾小球源性血尿，结合水肿、高血压、少尿，符合急性肾小球肾炎。均一性红细胞来自肾小球以下尿路出血，如结石、损伤、膀胱炎；血红蛋白尿为血管内溶血；肾后性血尿即均一性血尿"},{"q":"患者，男，36岁，反复上腹烧灼样痛5年。近1个月来上腹胀痛，恶心、呕吐胃内容物，吐后胀痛可缓解。最可能的诊断是","o":["急性胰腺炎","幽门梗阻","胰腺癌","慢性胆囊炎","胃黏膜脱垂"],"a":1,"e":"长期上腹烧灼样痛提示消化性溃疡，近月出现餐后上腹胀痛、呕吐宿食且吐后缓解，是幽门梗阻的典型表现。急性胰腺炎为持续性剧痛向背部放射；胰腺癌伴消瘦、黄疸；胃黏膜脱垂症状无规律，均无胃排空受阻的呕吐宿食特点"},{"q":"患者，男，77岁，因出血及呼吸困难就诊。胸部X线片在右肺部表现出广泛的异常阴影，不过不清楚这种阴影是由血液（与血液渗透）、肺炎或其他潜在疾病引起的。动脉血气：pH 7、50，PaCO2 31mmHg，HCO3－ 24mEq/L，PaO2 88mmHg。该患者可能发生了","o":["呼吸性碱中毒失代偿期","呼吸性酸中毒和低氧血症代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血"],"a":0,"e":"pH7.50大于7.45为碱血症，PaCO2降至31mmHg是原发改变，HCO3仅24mmol/L未见相应下降，符合急性呼吸性碱中毒且未获充分代偿。代谢性碱中毒应以PaCO2升高代偿；呼吸性酸中毒pH应降低；PaO2达88mmHg不支持静脉血标本"},{"q":"患者，女，26岁，患慢性肾小球肾炎。目前检测结果：尿蛋白＋，血Ccr 40ml/min，Cr 200μmol/L，BUN 10mmol/L。目前患者肾功能状态为","o":["肾功能正常","肾衰竭代偿期","肾衰竭失代偿期","肾衰竭期","尿毒症期"],"a":2,"e":"血肌酐200μmol/L呈中度增高、血尿素氮10mmol/L超过9mmol/L，肌酐清除率降至40ml/min，符合肾衰竭失代偿期。肾功能代偿期肌酐不增高、血尿素氮低于9mmol/L；肾衰竭期尿素氮超过20mmol/L；尿毒症期肌酐可达1.8mmol/L并伴明显全身症状"},{"q":"患者，女，56岁，反复多关节疼痛3年。1天前再次出现四肢多关节疼痛，伴晨僵，体温37、5℃，在肘关节鹰嘴突周围可见大小不一、质硬、无压痛的皮下小结。该患者的诊断可能是","o":["痛风","结节性多动脉炎","类风湿关节炎","囊虫病","系统性红斑狼疮"],"a":2,"e":"反复多关节疼痛伴晨僵，肘关节鹰嘴周围质硬无压痛结节为类风湿结节，结合对称性小关节受累，诊断类风湿关节炎。风湿性关节炎呈游走性大关节痛、伴心肌炎；痛风伴血尿酸升高及第一跖趾红肿；系统性红斑狼疮有多系统损害及特征性皮疹"},{"q":"患者，女，20岁。近2年间断出现抽搐发作，今晨洗漱时突然出现意识丧失，全身强直，呼吸暂停，继而四肢发生阵挛性抽搐，尿、便失禁，发作约1min后缓解。该患者最可能的诊断为","o":["低钙抽搐","癫痫大发作","癔症性发作","癫痫小发作","低血糖状态"],"a":1,"e":"突然意识丧失、全身强直、呼吸暂停后继以四肢阵挛性抽搐、尿便失禁、约一分钟自行缓解，是癫痫大发作的典型过程。癫痫小发作仅短暂意识丧失而无强直阵挛；低钙抽搐无意识丧失、以手足搐搦为主；癔症性发作多有精神诱因、意识不完全丧失"},{"q":"患者，女，38岁，面色苍白4年。实验室检查：Hb 88g/L，血清铁5μmol/L，血清总铁结合力410μmol/L，血清铁蛋白10μg/L，网织红细胞计数0.015，血清铁饱和度15%。该患者最可能的诊断是","o":["缺铁性贫血","巨幼细胞贫血","铁粒幼细胞贫血","地中海贫血","阵发性睡眠性血红蛋白尿"],"a":0,"e":"血清铁显著降低、总铁结合力升高、铁蛋白明显降低、转铁蛋白饱和度仅15%，呈小细胞低色素性贫血，符合缺铁性贫血。铁粒幼细胞贫血血清铁与铁蛋白升高；巨幼细胞贫血为大细胞性、叶酸或维生素B12缺乏；地中海贫血铁蛋白正常或升高、HbA2增高"},{"q":"患者，女，18岁。患上呼吸道感染1周后，感心悸，气短，乏力，心率98次/min。心电图示P-R间期为0、22s，应诊断为","o":["窦性心动过速","窦性心律不齐","二度Ⅰ型房室传导阻滞","二度Ⅱ型房室传导阻滞","一度房室传导阻滞"],"a":4,"e":"PR间期延长至0.22秒、超过0.20秒，每个心房冲动仍能下传心室、无QRS脱落，符合一度房室传导阻滞。二度Ⅰ型PR间期进行性延长直至脱落，二度Ⅱ型PR固定而突然脱落；窦性心动过速仅心率增快、PR间期正常，均与本例不同"},{"q":"患者，男，30岁。近10年来常有空腹痛和夜间痛，服用制酸剂可使腹痛减轻，1小时前餐后突感上腹持续性剧痛而入院。查体发现腹肌紧张。该患者查体最有诊断意义的是","o":["右上腹有压痛","肝浊音界消失","腹式呼吸消失","肠鸣音消失","腹部有移动性浊音"],"a":1,"e":"空腹痛、餐后突发持续性上腹剧痛伴腹肌紧张，提示消化性溃疡穿孔，气体进入腹腔积聚膈下使肝浊音界消失，最具诊断意义。移动性浊音提示腹腔大量积液；肠鸣音消失见于肠麻痹或弥漫性腹膜炎；腹式呼吸消失为非特异性体征"},{"q":"患者，男，35岁，因血尿就诊，无畏寒发热、咽痛、肌痛、关节痛。查体无肾区叩击痛。既往有哮喘20余年。否认肾病家族史。尿常规检查提示尿蛋白（＋），白细胞（－），亚硝酸盐（－），镜检提示红细胞30～50个/HPF；血肌酐正常。该患者最可能的诊断为","o":["IgA肾病","肾结石","膀胱移行细胞癌","韦格纳肉芽肿","急性肾小球肾炎"],"a":0,"e":"青少年反复血尿伴轻度蛋白尿、肾功能正常、无肾区叩痛及前驱感染的急性过程，最符合IgA肾病。肾结石有肾绞痛与叩击痛；膀胱移行细胞癌多为老年无痛性全程血尿；韦格纳肉芽肿伴系统损害；急性肾小球肾炎有明确前驱感染及水肿高血压"},{"q":"患者，男，28岁。反复节律性中上腹痛3年，常反酸嗳气。近2日，大便柏油样，粪便OB（＋＋＋＋）。为明确诊断，首选的辅助检查是","o":["急诊胃镜检查","X线胃肠钡餐造影","纤维结肠镜检查","逆行胰胆管造影","腹部超声检查"],"a":0,"e":"节律性上腹痛伴柏油样便、隐血强阳性，提示消化性溃疡并上消化道出血，急诊胃镜既能明确出血部位又可同时止血，为首选。X线钡餐在活动性出血期禁忌且不能治疗；纤维结肠镜查下消化道；逆行胰胆管造影针对胆胰病变；腹部超声对胃十二指肠病变价值有限"},{"q":"患者，男，26岁。上床时突觉右侧胸痛、气短。查体可见：气管左移，右侧胸廓膨隆，右肺语音震颤减弱，右肺叩诊呈鼓音，右肺呼吸音减弱。该患者最可能的诊断为","o":["大叶性肺炎","右侧气胸","右侧胸腔积液","支气管哮喘","心绞痛"],"a":1,"e":"突发胸痛气短，气管移向健侧、患侧胸廓饱满、语颤减弱、叩诊鼓音、呼吸音减弱，是右侧气胸的典型体征。胸腔积液叩诊为实音而非鼓音；大叶性肺炎叩诊浊音、语颤增强、闻及支气管呼吸音；心绞痛无胸壁体征；支气管哮喘为双肺哮鸣音及过清音"},{"q":"患者，男，38岁，无明显诱因出现皮肤黏膜黄染伴瘙痒，无腹痛，无发烧。查体：神志清楚，巩膜黄染，皮肤无出血，腹软，无压痛，肝脾未触及。下列哪项检查支持原发性胆汁肝硬化的诊断","o":["粪便黄色加深","血清结合胆红素增加","尿胆原增加","血清碱性磷酸酶减低","血清胆固醇降低"],"a":1,"e":"原发性胆汁性肝硬化属胆汁淤积性黄疸，结合胆红素反流入血，血清结合胆红素增加支持诊断。胆道梗阻时粪便颜色变浅而非加深；尿胆原减少或阴性；血清碱性磷酸酶应升高而非减低；血清胆固醇常升高而非降低，其余各项方向均相反"},{"q":"患者，男，62岁，尿频、尿急、排尿不畅2个月。前列腺液非染色涂片白细胞成堆，红细胞110个/HPF，磷脂酰胆碱小体消失。考虑该患者为","o":["肾炎","尿道炎","前列腺炎","精囊炎","膀胱炎"],"a":2,"e":"尿频、尿急、排尿不畅，前列腺液白细胞成堆增多、红细胞增多、磷脂酰胆碱小体减少甚至消失，是前列腺炎的典型特点。尿道炎以尿痛及尿道分泌物为主、前列腺液正常；精囊炎以血精为主；膀胱炎有膀胱刺激征但前列腺液无炎性改变"},{"q":"患者，男，30岁，因低热伴干咳1个月来诊。查体右上肺叩诊稍浊，可闻及支气管肺泡呼吸音和湿性啰音，PPD试验强阳性。若该患者出现浅表淋巴结肿大，最先肿大的区域可能是","o":["颌下淋巴结","颏下淋巴结","颈部淋巴结","耳后淋巴结","腋窝淋巴结"],"a":2,"e":"低热、干咳、右上肺叩诊稍浊、支气管肺泡呼吸音及湿啰音、PPD强阳性，提示肺结核，其浅表淋巴结受累最常见于颈部淋巴结。颌下与颏下淋巴结主要引流口腔颌面；耳后淋巴结引流头皮；腋窝淋巴结引流上肢及乳腺，均非肺结核淋巴结肿大的常见部位"},{"q":"患者，男，56岁。腹胀3天，结肠癌术后持续胃肠减压，胃液引流通畅。若患者出现低钠、低钾、低氯血症，最可能的化验指标是","o":["血钠145mmol/L，血钾3、5mmol/L，血氯90mmol/L","血钠130mmol/L，血钾3、0mmol/L，血氯92mmol/L","血钠150mmol/L，血钾5、5mmol/L，血氯105mmol/L","血钠140mmol/L，血钾4、5mmol/L，血氯99mmol/L","血钠135mmol/L，血钾3、5mmol/L，血氯95mmol/L"],"a":1,"e":"持续胃肠减压使胃液大量丢失，钠、钾、氯均随之丢失，血钠130mmol/L、血钾3.0mmol/L、血氯92mmol/L均低于正常，符合低钠低钾低氯血症。其余选项中血钠145及150偏高、血钾5.5为高钾、血氯105正常偏高，均与丢失胃液的电解质改变不符"},{"q":"患者，男，15岁，反复皮肤巩膜黄染、上腹不适、水肿伴浓茶样尿3个月。入院查体：全身皮肤巩膜黄染，角膜边缘出现棕褐色的色素环。骨髓检查正常，肝炎病毒两次检查阴性。考虑下列何种原因可能性大","o":["先天性因素","类脂质蛋白沉积症","铜代谢障碍","维生素A缺乏","角膜血管增生"],"a":2,"e":"角膜边缘棕褐色色素环即Kayser-Fleischer环，是铜在角膜沉积的结果，结合青少年黄疸、水肿及肝损害，提示肝豆状核变性即铜代谢障碍。类脂质蛋白沉积症无此色素环；维生素A缺乏表现为夜盲、眼干；角膜血管增生不形成K-F环，均不能解释"},{"q":"患者，男，68岁，既往多年吸烟史。诉咳嗽、咳痰3个月。为明确诊断，首先应进行","o":["胸部CT","胸部增强CT","胸部磁共振","纤维支气管镜检查及活检","胸部X线检查"],"a":4,"e":"老年长期吸烟者咳嗽咳痰三个月，需首先筛查肺部占位，胸部X线检查简便、经济，是影像学初步检查的首选。胸部CT及增强CT敏感性更高但作为进一步检查；胸部磁共振非肺部常规首选；纤维支气管镜及活检属有创检查，应在影像发现病灶后实施"},{"q":"患者，女，23岁。低热、乏力、盗汗伴咳嗽、痰中带血3个月。胸片示右上肺大片状阴影，密度不均，其内可见薄壁空洞，痰抗酸杆菌阳性。应考虑","o":["右上肺脓肿","浸润性肺结核空洞形成","右上肺炎","慢性纤维空洞肺结核","亚急性血行播散性肺结核"],"a":1,"e":"低热、盗汗、乏力、痰中带血，胸片见右上肺大片状密度不均阴影内薄壁空洞，痰抗酸杆菌阳性，符合浸润性肺结核空洞形成。慢性纤维空洞肺结核病程长、洞壁厚且伴纤维收缩；肺脓肿的高热、大量脓痰；亚急性血行播散呈双肺弥漫粟粒影，均不符"},{"q":"患者，男，66岁。进行性排尿困难1年余。近3个月来尿频，每日排尿10余次，且尿道外口有尿液溢出。查体：下腹部隆起，叩诊浊音，直肠指诊前列腺4cm×5cm大小，质韧，中央沟消失。测残余尿300ml。根据上述病史，应考虑为","o":["遗尿","真性尿失禁","压力性尿失禁","急迫性尿失禁","间歇性尿失禁"],"a":4,"e":"前列腺增生致大量残余尿、膀胱过度充盈，压力超过尿道阻力时尿液不自主溢出，尿液排后又可蓄积，呈间歇性即充溢性尿失禁。真性尿失禁因括约肌损伤、无残余尿；压力性尿失禁于腹压增加时漏尿；急迫性尿失禁伴强烈尿急，均不同"},{"q":"一老年患者，发现尿色呈鲜红色2天，每次排尿为开始尿色正常，末段尿为红色，有排尿困难，无发热和腹痛。该患者病变最有可能在","o":["肾脏","肝脏","血液系统","膀胱颈部或前列腺","肾脏或输尿管"],"a":3,"e":"排尿开始时尿色正常、终末段变红为终末血尿，提示出血位于膀胱颈部、三角区或后尿道的前列腺、精囊腺，本例伴排尿困难更支持膀胱颈部或前列腺病变。肾脏或输尿管出血为全程血尿；初始血尿提示尿道；血液系统疾病多表现为全程血尿"},{"q":"患者，男，29岁，发热、咳痰伴咯血1周入院。查体：贫血貌，全身多处出血点，胸骨后压痛，肝脾大。血常规：白细胞40×109/L，血小板30×109/L。该患者最可能的诊断是","o":["急性白血病","败血症","血小板减少性紫癜","淋巴瘤","再生障碍性贫血"],"a":0,"e":"贫血貌、全身出血点、胸骨后压痛、肝脾大，白细胞显著升高伴血小板减少，符合急性白血病，骨髓被幼稚细胞大量增殖抑制正常造血。再生障碍性贫血全血细胞减少、无肝脾大及胸骨压痛；败血症有感染中毒表现；ITP仅血小板减少、白细胞正常；淋巴瘤以淋巴结肿大为主"},{"q":"患者，男，60岁。鼻塞及涕中带血半年，无其他不适。查体：耳前淋巴结肿大，鼻中隔无偏曲。最可能的诊断是","o":["鼻窦炎","鼻咽癌","鼻炎","鼻中隔偏曲","血液系统疾病"],"a":1,"e":"鼻塞、涕中带血持续半年，出现耳前即颈部淋巴结肿大，提示鼻咽癌淋巴结转移，EB病毒与之相关。鼻窦炎以脓涕、头痛为主；鼻炎无血涕及淋巴结转移；鼻中隔偏曲为鼻腔结构异常，均不出现涕中带血伴颈部淋巴结肿大"},{"q":"患者，男，32岁，慢性肾衰竭，肾移植，需做配型。人白细胞抗原交叉配型的目的是","o":["检测供者血清有无针对受者人白细胞抗原的抗体","检测受者血清有无针对供者人白细胞抗原的抗体","检测供者淋巴细胞表面的人白细胞抗原","检测受者淋巴细胞表面的人白细胞抗原","检测供受者血型抗原"],"a":1,"e":"HLA交叉配型是检测受者血清中是否预存针对供者HLA抗原的抗体，抗体阳性会在移植后介导超急性排斥，故目的为检测受者血清抗供者人白细胞抗原抗体。检测供受者淋巴细胞表面HLA属分型检查；检测供者血清抗受者抗体方向相反；血型抗原由ABO配型确定"},{"q":"患者，女，54岁，胸闷入院，查体可见叹气样呼吸，余未见异常，该患者最可能的诊断是","o":["酸中毒","心功能不全","急性胸膜炎","抑郁症","大叶性肺炎"],"a":3,"e":"叹气样呼吸是在正常节律中插入一次深大呼吸伴叹息声，属功能性改变，见于神经衰弱、精神紧张及抑郁症，故本例考虑抑郁症。酸中毒表现为深大Kussmaul呼吸；急性胸膜炎为吸气相突然中断的抑制性呼吸；心功能不全有呼吸困难及啰音；大叶性肺炎呼吸浅快"},{"q":"患儿，男，6岁。发病第1天体温为37.5℃，伴咽痛，未予治疗；第2天体温达40.5℃，伴神志恍惚及抽搐；经输液、抗生素等治疗，第3天体温降至38.2℃。其体温变化过程是","o":["低热→超高热→中等热","中等热→高热→中等热","低热→高热→高热","中等热→超高热→中等热","低热→高热→中等热"],"a":4,"e":"按口腔温度分度，37.5℃属低热，40.5℃未超过41℃属高热，38.2℃属中等度热，体温变化为低热至高热再至中等热。超高热需超过41℃；中等热到高热的排序与第2天40.5℃不符；持续高热与第3天已降至38.2℃不符"},{"q":"患者，男，20岁，下腰背痛2年，伴足跟痛。其父有类似病史，已驼背。该患者的诊断可能是","o":["结核性脊柱炎","椎间盘突出","强直性脊柱炎","腰肌劳损","类风湿关节炎"],"a":2,"e":"青年男性慢性下腰背痛伴足跟痛、家族史及驼背，符合强直性脊柱炎，属血清阴性脊柱关节病。脊柱结核多为胸腰段成角畸形、无家族聚集；椎间盘突出无晨僵及足跟痛；腰肌劳损无脊柱强直与驼背；类风湿关节炎主要累及外周小关节"},{"q":"患者，女，58岁。近1个月来经常腹痛、腹泻，粪便呈果酱样伴腥臭味，右下腹压痛明显。最可能的诊断是","o":["细菌性痢疾","急性胰腺炎","急性阑尾炎","食物中毒","阿米巴痢疾"],"a":4,"e":"粪便呈暗红色果酱样伴腥臭味、右下腹压痛，是阿米巴痢疾的典型表现。细菌性痢疾为黏液脓血便伴明显里急后重；急性阑尾炎为转移性右下腹痛；食物中毒有集体进食史和呕吐腹泻；急性胰腺炎为暴饮暴食后上腹痛伴淀粉酶升高"},{"q":"患者，女，30岁，腹胀大2年，近期加重。查体：腹胀大如足月妊娠大小，腹中部浊音，两侧鼓音，且浊音不随体位而改变，腹无压痛，肝脾未触清。为明确诊断，首选哪项检查","o":["肝功能化验","腹腔穿刺液检查","腹部X线平片检查","X线钡餐检查","妇科B超检查"],"a":4,"e":"腹胀如足月妊娠、腹中部浊音而两侧鼓音、浊音不随体位改变，符合巨大卵巢囊肿而非移动性浊音阳性的腹水，故首选妇科B超明确来源。腹腔穿刺液检查针对腹水；腹部X线及钡餐查消化道病变；肝功能化验针对肝硬化腹水，均不能直接显示盆腔包块"},{"q":"患者，男，54岁。大便秘结，便中带血3个月。查体：直肠指检于肛门外口见紫红色柔软包块，用力时可突出增大。该患者最可能的诊断是","o":["直肠息肉","直肠癌","肛周脓肿","痔疮","直肠感染"],"a":3,"e":"肛门外观紫红色柔软包块、用力时突出增大伴便血，为痔静脉丛曲张形成的痔疮，外痔位于齿状线以下。直肠癌为质硬、凹凸不平的结节；直肠息肉多带蒂、位置较高、表面光滑；肛周脓肿局部红肿热痛、压痛明显，均不同"},{"q":"患者，女，45岁。劳力性呼吸困难10年，间断双下肢水肿5年，突发咯血200ml入院。查体：双肺底可闻及湿啰音，心率132次/min，第一心音强弱不等。胸片提示：肺动脉段突出，心影呈梨型。该患者咯血的原因考虑为","o":["肺毛细血管破裂","支气管动脉破裂","急性肺水肿","支气管静脉破裂","合并支气管扩张"],"a":3,"e":"梨形心、肺动脉段突出提示二尖瓣狭窄，肺淤血使黏膜下支气管静脉压力升高、破裂，出现较大量咯血。支气管内膜微血管或肺泡毛细血管破裂仅表现为血丝痰；急性肺水肿为大量粉红色泡沫样痰；支气管扩张咯血伴长期脓痰，均不符"},{"q":"患者，女，48岁，突发性恶心，头晕，随之呕吐鲜红色血液约1000ml。查体：BP 8/6kPa（1kPa≈7.5mmHg），P 110次/min，面色苍白，神志淡漠，无巩膜黄染，心肺未见异常，腹软，无压痛，肝脾未触及，移动性浊音阴性。下列支持肝硬化食管静脉曲张破裂出血的诊断的是","o":["服用非甾体类药物史","伴腹部剧痛","伴寒战，高烧","呕血中有凝血块","出血早期即出现血红蛋白下降"],"a":3,"e":"出血量多、在胃内停留时间短且来自食管时，呕血呈鲜红或暗红色并常混有凝血块，支持食管静脉曲张破裂。服用非甾体类药物史提示消化性溃疡；伴腹部剧痛并非静脉曲张特点；出血早期血红蛋白下降常不明显；寒战高热提示感染，均不支持"},{"q":"患者，女，27岁。停经50天，腹痛、阴道流血3小时就诊。既往有2次自然流产史。该患者最应进行以下哪项检测","o":["血小板计数","血小板功能","凝血因子活性测定","凝血酶原时间测定","抗心磷脂抗体测定"],"a":4,"e":"停经后腹痛、阴道流血并有两次自然流产史，提示习惯性流产，抗磷脂抗体介导的高凝状态与胎盘血栓形成、流产密切相关，应测抗心磷脂抗体。血小板计数与功能、凝血因子活性、凝血酶原时间均反映一般凝血功能，不能解释反复流产的免疫病因"},{"q":"某患者，突然呼吸困难，发绀，叩诊右侧呈鼓音，听诊呼吸音消失，可诊为","o":["右胸腔积液","右侧气胸","右大叶肺炎","肺梗死","支气管哮喘"],"a":1,"e":"突发呼吸困难、发绀，右侧叩诊鼓音、呼吸音消失，是右侧气胸的典型表现。右胸腔积液叩诊为实音；右大叶肺炎叩诊浊音、语颤增强；肺梗死多伴胸痛、咯血而叩诊无明显鼓音；支气管哮喘为双肺弥漫哮鸣音、叩诊过清音"},{"q":"患者，男，54岁。意识不清3小时。查体：昏迷，呼吸缓慢，双侧瞳孔缩小，对光反射存在。该患者最可能的诊断是","o":["颠茄类中毒","有机磷农药中毒","酒精中毒","氰化物中毒","一氧化碳中毒"],"a":1,"e":"昏迷、呼吸缓慢伴双侧瞳孔缩小而对光反射存在，是有机磷农药中毒的典型体征，毒蕈碱样作用使瞳孔括约肌收缩。颠茄类中毒阻断M受体致瞳孔扩大；酒精中毒瞳孔多正常或扩大；氰化物与一氧化碳中毒以组织缺氧为主，无针尖样瞳孔"},{"q":"患者，女，70岁，拔牙后伤口渗血不止3天。既往有高血压、冠心病病史，长期服用阿司匹林等药物。下列哪项表现最符合患者病情","o":["血红蛋白增高","凝血因子Ⅷ活性减低","PAgT/PAdT减低","血块收缩试验增高","vWF:Ag增高"],"a":2,"e":"长期服用阿司匹林抑制血小板环氧化酶、阻断血栓素生成，使血小板聚集与黏附功能受损，出血时间延长，故血小板聚集试验与黏附试验减低。出血时血红蛋白不会增高；凝血因子Ⅷ活性及vWF:Ag属凝血与血管性血友病指标，阿司匹林不影响凝血因子"},{"q":"患者，男，30岁。近1年来反复上腹痛，进食半小时后腹痛明显，伴反酸、胃灼热，1小时前突发上腹部剧烈疼痛，伴恶心、呕吐。该患者当前最可能出现何种体征","o":["腹式呼吸增强，肠鸣音活跃","腹式呼吸增强，肠鸣音减弱","腹式呼吸减弱，肠鸣音活跃","腹式呼吸减弱，肠鸣音减弱","腹式呼吸减弱，肠鸣音高亢"],"a":3,"e":"饥饿痛伴突发剧烈上腹痛，提示溃疡穿孔并发腹膜炎，腹膜受刺激使腹式呼吸减弱，肠麻痹使肠鸣音减弱。腹式呼吸增强见于胸膜或胸壁疾病；肠鸣音活跃或高亢见于肠梗阻早期、腹泻，均与穿孔后腹膜炎的体征相反"},{"q":"患者，女，频发晕厥，神经系统查体发现患者由立位到卧位脉搏减少达20次/min。这提示","o":["交感神经兴奋性增强","交感神经兴奋性减弱","迷走神经兴奋性增强","迷走神经兴奋性减弱","锥体束损伤"],"a":2,"e":"卧立位试验中由立位到卧位脉率减慢超过12次每分提示迷走神经兴奋性增高，本例减慢20次即为此种改变。由卧位到立位脉率增加超过12次为交感神经兴奋；交感或迷走兴奋性减弱时变化方向相反；锥体束损伤与该自主神经试验无关"},{"q":"患者，男，40岁，反复饥饿时中上腹部隐痛10年，伴反酸嗳气，在进食和服制酸剂后可缓解，今晨中上腹剧痛后腹痛持续存在。如进行腹部检查，最具诊断价值的腹部体征是","o":["腹肌紧张","腹壁柔韧感","肠鸣音亢进","肝浊音上界消失","Murphy征阳性"],"a":3,"e":"饥饿时中上腹痛10年、进食及制酸剂可缓解，提示十二指肠溃疡，突发剧痛并持续提示穿孔，气体积聚膈下使肝浊音界消失，诊断价值最大。腹壁柔韧感见于结核性腹膜炎；Murphy征阳性提示胆囊炎；肠鸣音亢进见于机械性肠梗阻"},{"q":"患者，女，25岁，服用某“减肥茶”后腹泻3天，食欲缺乏，查血钾2.8mmol/L，其心电图可能表现为","o":["QT间期延长","QRS波群增宽","u波倒置","ST段压低，T波低平，u波增高","T波倒置"],"a":3,"e":"服减肥茶腹泻致血钾2.8mmol/L，低钾血症典型心电图改变为ST段压低、T波低平或倒置、u波增高及QT-u间期延长。QT间期延长主要见于低钙及药物；QRS增宽为明显低钾的晚期改变而非主要表现；u波倒置多见于高钾或心肌缺血"},{"q":"患者，女，27岁，因为乏力、尿色偏深1周入院。查体示皮肤巩膜轻度黄染，浅表淋巴结未触及，肝脾不大。检查显示中度贫血及血小板减少。发病前无特殊用药史，既往有2次自发流产史。以下检查最有意义的是","o":["APTT","PT","TT","血浆蛋白C活性测定","抗磷脂抗体测定"],"a":4,"e":"乏力、黄疸、中度贫血伴血小板减少及两次自发流产，提示抗磷脂综合征，抗磷脂抗体测定最有意义。APTT、PT、TT仅为凝血筛选试验，不能确定抗磷脂抗体；血浆蛋白C活性测定用于遗传性易栓症，均不能解释流产与血细胞减少的组合"},{"q":"患者，男，19岁。打篮球时突然感右侧胸部剧烈疼痛、气短，逐渐加重，前来就诊。该患者还可能出现下列哪项体征","o":["右侧胸廓凹陷","右侧触觉语颤减弱","右侧胸廓运动增强","右侧触觉语颤增强","右侧叩诊清音"],"a":1,"e":"运动中突发胸痛、气短，提示自发性气胸，患侧胸膜腔积气使肺压缩，触觉语颤减弱或消失。气胸时胸廓饱满而非凹陷、呼吸运动减弱而非增强；语颤增强见于肺实变；叩诊应为鼓音而非清音，均不符合气胸体征"},{"q":"53岁女性，主诉“胸闷、胸痛2天”入院。现病史不应包括哪项内容","o":["有无头痛、头晕","有无心慌、气短","疼痛的部位、性质、持续时间","胸闷、胸痛的病因及诱因","兄弟姐妹有无类似病史"],"a":4,"e":"现病史围绕本次疾病的发生、演变与诊疗经过，胸闷胸痛的部位性质、持续时间、病因诱因及伴随的心慌气短、头痛头晕均属其范围。兄弟姐妹有无类似病史属于家族史，不应写入现病史，题干询问的正是这一不属于现病史的内容"},{"q":"患者，女，63岁，基础风湿性心脏病、二尖瓣狭窄、糖尿病病史。呕吐半日，共计3次，每次量约200ml，胸痛3小时来诊，入室BP 65/40mmHg，HR 141次/min，SpO279%；入室心电图如图所示。进一步治疗首选","o":["积极补液、抗休克治疗","洋地黄类控制心室率","直流电复律","抗休克同时尽早行急诊冠状动脉介入治疗","抗休克，待血流动力学稳定后择期行冠状动脉造影"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，风湿性心脏病二尖瓣狭窄合并糖尿病者出现胸痛、血压65/40mmHg、心率141次每分及低氧，提示急性心肌梗死并心源性休克，应在抗休克同时尽早行急诊冠状动脉介入以开通罪犯血管。单纯补液抗休克延误再灌注；洋地黄对急性心梗无效且易致心律失常；择期造影错过再灌注时机\n\n官方题库中缺失图片"},{"q":"患者，男，19岁，反复多饮、多尿6年，近半个月出现乏力入院。查血糖4.7mmol/L，血肌酐70μmol/L，血钾2.9mmol/L，血钙1.9mmol/L，血磷0.8mmol/L，血氯120mmol/L，二氧化碳结合力18mmol/L，尿pH 6.4，尿糖阴性，尿比重1.020，B超检查双肾多发结石。为明确病因，还应该做的检查是","o":["酚红排泄试验","碳酸氢根重吸收试验","氯化铵负荷试验","内生肌酐清除率试验","尿液稀释-浓缩试验"],"a":2,"e":"多饮多尿、低钾、高氯、二氧化碳结合力降低而尿pH6.4不能酸化，并双肾多发结石，符合远端肾小管性酸中毒，氯化铵负荷试验通过酸负荷观察尿液能否酸化以协助诊断。碳酸氢钠重吸收试验用于近端型；酚红排泄、内生肌酐清除率反映近端分泌与滤过功能；稀释浓缩试验查浓缩功能"},{"q":"患者，男，20岁。近3天来出现皮肤紫癜，下肢为主，鲜红色，突出皮面，伴有关节痛。既往无出血病史。出血时间延长，束臂试验阳性，尿常规示红细胞＋＋/HPF。血常规基本正常。凝血功能检测示PT、APTT均正常。该患者最可能的诊断是","o":["过敏性紫癜","血管性血友病","深静脉血栓形成","弥散性血管内凝血","血小板无力症"],"a":0,"e":"下肢对称性高出皮面的鲜红色紫癜伴关节痛、血尿，血小板及PT、APTT正常而束臂试验阳性，属血管壁通透性异常，符合过敏性紫癜。血管性血友病与血小板无力症为血小板或血管性血友病因子异常；深静脉血栓无紫癜；弥散性血管内凝血有凝血因子消耗"},{"q":"患者，男，50岁，无特殊基础疾病，长期吸烟。间断胸闷8年，短暂意识丧失2次，胸闷发作时自测心率变慢，完善Holter如图所示，目前诊断首先考虑","o":["病态窦房结综合征","冠状动脉粥样硬化性心脏病","房室传导阻滞","冠状动脉痉挛","血管迷走性晕厥"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，变异型心绞痛由冠状动脉痉挛引起，发作时暂时性ST段抬高伴高耸T波及对应导联压低，可致胸闷与短暂意识丧失，诊断依赖Holter捕捉缺血图形。病态窦房结综合征以严重心动过缓为特征；房室传导阻滞有PR延长或脱落；血管迷走性晕厥无缺血性ST改变\n\n官方题库中缺失图片"},{"q":"患者，男，18岁，全身水肿，少尿1周。血浆蛋白减低。为确诊首先应做的检验是","o":["血常规","尿常规","内生肌酐清除率","浓缩稀释试验","酚红排泄试验"],"a":1,"e":"全身水肿、少尿伴血浆蛋白减低，提示肾小球或肾小管疾病导致的水肿，尿常规可发现蛋白尿、血尿及管型，是确诊首先进行的检查。血常规无泌尿特异性；内生肌酐清除率、浓缩稀释试验、酚红排泄试验分别评估滤过、浓缩与近端分泌功能，均非病因确诊的首选"},{"q":"周边型肺癌患者，病变直径2、5cm，病灶距胸部表面深约6cm，其叩诊音应为","o":["清音","浊音","实音","浊鼓音","空瓮音"],"a":0,"e":"距胸部表面5cm以上的深部病灶且直径小于3cm时，常规叩诊常不能发现异常，仍为正常清音。浊音或实音见于肺大面积含气量减少或较浅表的实变；浊鼓音见于肺不张或肺炎充血期；空瓮音见于巨大肺空洞，均不出现于本例小而不深在的病灶"},{"q":"患者，女，22岁。误服有机磷农药，神志不清，皮肤潮湿多汗，面部肌肉束颤动，瞳孔缩小，双肺布满湿啰音。患者最可能出现","o":["端坐呼吸","Kussmaul呼吸","潮式呼吸","浅快呼吸","深大呼吸"],"a":2,"e":"有机磷农药中毒抑制胆碱酯酶并抑制呼吸中枢，出现昏迷、呼吸浅慢及节律异常，可表现为潮式呼吸。Kussmaul呼吸为代谢性酸中毒的深大呼吸；端坐呼吸见于左心衰肺水肿；深大呼吸非中毒性呼吸节律；潮式呼吸呈浅慢至深快再转浅慢并伴呼吸暂停的周期性改变"},{"q":"患儿，男，12岁。发热、咽痛2周后出现晨起眼睑和颜面水肿，随后出现全身水肿，尿呈泡沫状，无呼吸困难，无皮肤黏膜和巩膜黄染和尿黄。该患儿首先要做的检查是","o":["血清肌酐","尿常规","肝功能","甲状腺功能","心脏彩超"],"a":1,"e":"儿童咽痛后两周出现眼睑颜面水肿、全身水肿及泡沫尿，提示急性肾小球肾炎，尿常规可发现血尿、蛋白尿和管型，是首先要做的检查。血清肌酐反映滤过功能但非首选筛查；肝功能、甲状腺功能、心脏彩超分别针对肝胆、甲亢及心源性水肿，均不符合本例肾源性水肿特点"},{"q":"患者，女，50岁，有风湿性心脏病史。近期上呼吸道感染后觉心悸、气促，心电图如图所示。首先考虑","o":["心房颤动","心房扑动3∶1～4∶1下传","心房扑动2∶1～4∶1下传","心房颤动2∶1～4∶1下传","房性心动过速"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，心房扑动的心电图特征为Ⅱ、Ⅲ、aVF导联锯齿状F波、频率约300次每分，常以2:1至4:1下传，心室率规则，故诊断依赖心电图识别。心房颤动为f波紊乱、心律绝对不齐；1:1下传罕见且血流动力学不稳定；房性心动过速频率较低、无典型锯齿波\n\n官方题库中缺失图片"},{"q":"患者，女，20岁。发热38、5℃，右胸痛，伴呼吸运动减弱，语音震颤减弱，右下肺叩诊呈浊音，呼吸音减弱。诊断应首先考虑","o":["大叶性肺炎","胸腔积液","肺栓塞","浸润性肺结核","支气管哮喘"],"a":1,"e":"发热、胸痛、呼吸运动减弱、语颤减弱、叩诊浊音及呼吸音减弱，是胸腔积液的典型体征。大叶性肺炎叩诊浊音但语颤增强、可闻支气管呼吸音；肺栓塞体征多不明显；浸润性肺结核少呈急性积液体征；支气管哮喘双肺哮鸣音、叩诊过清音，均不符"},{"q":"患者，男，48岁，10年少量饮酒史。近1个月上腹疼痛，饥饿时加重，呈现疼痛－进食－缓解的规律。若胃镜下所见溃疡面较大，周边不整齐，底部不平，触之质硬，黏膜脆易出血，有可能是","o":["溃疡愈合期","溃疡瘢痕期","恶性溃疡","慢性肥厚性胃炎","慢性浅表性胃炎"],"a":2,"e":"胃镜下溃疡面大、周边不整齐、底部凹凸不平、质硬且黏膜脆易出血，是溃疡型胃癌即恶性溃疡的表现。溃疡愈合期与瘢痕期边缘整齐、底部洁净、周围黏膜水肿消退；慢性浅表性与肥厚性胃炎仅有黏膜充血或皱襞增粗，不形成溃疡"},{"q":"患者，男，45岁，明确诊断为金黄色葡萄球菌肺炎。今晨患者查体前胸部可触及握雪感，该患者可能存在下列何种并发症","o":["急性乳腺炎","乳腺癌","皮下气肿","大量胸腔积液","少量胸腔积液"],"a":2,"e":"金黄色葡萄球菌肺炎可致肺组织坏死、气体逸入胸壁皮下，触诊出现捻发感或握雪感，即皮下气肿。大量或少量胸腔积液表现为叩诊实音、呼吸音减弱而无握雪感；急性乳腺炎与乳腺癌病变局限于乳腺，无胸部皮下积气的体征"},{"q":"患者，男，23岁，低热、盗汗、乏力、食欲缺乏、消瘦3个月余，最可能的诊断是","o":["肺结核","慢性肠炎","糖尿病","甲状腺功能亢进症","慢性胃炎"],"a":0,"e":"长期低热、盗汗、乏力、食欲缺乏、消瘦为典型结核中毒症状，最符合肺结核。甲状腺功能亢进虽有消瘦但伴畏热多汗、心悸、突眼；糖尿病以多饮多尿多食消瘦为主；慢性胃炎与慢性肠炎以消化道症状为主，均无结核中毒表现"},{"q":"患者，男，45岁。反复以低血钾性周期性瘫痪入院，伴尿量增多，骨痛不适。查尿常规正常，尿pH 6.5，血pH 7.35，血钾3.0mmol/L，血氯110mmol/L。此时对诊断最有帮助的检查是","o":["肾功能检测","氯化铵负荷试验","碳酸氢钠重吸收试验","内生肌酐清除率","骨骼X线摄片检查"],"a":1,"e":"反复低钾性瘫痪、多尿、骨痛，血氯升高而血pH偏低、尿pH6.5不能酸化，提示远端肾小管性酸中毒，氯化铵负荷试验通过酸负荷判断远端排氢与尿液酸化能力，最有帮助。碳酸氢钠重吸收试验用于近端型；肾功能与内生肌酐清除率查滤过；骨骼X线仅显示骨质改变，不能定性病因"},{"q":"患者，女，28岁，低热、骨关节肿胀3天。入院检查：关节腔积液腺苷脱氨酶活性明显增高。该患者可能的诊断为","o":["结核性关节炎","反应性关节炎","系统性红斑狼疮","强直性脊柱炎","类风湿性关节炎"],"a":0,"e":"低热、关节肿胀且关节腔积液腺苷脱氨酶活性明显增高，ADA升高是结核性关节炎的重要线索。类风湿关节炎为对称性小关节肿痛伴晨僵、ADA不高；反应性关节炎有前驱感染史；强直性脊柱炎主要累及中轴关节；系统性红斑狼疮有多系统损害及自身抗体"},{"q":"患者，女，28岁。尿频、尿急、尿痛2天，无发热及腰痛，既往无类似发作史。查体：双肾区无叩击痛。实验室检查：血WBC 5.4×109/L，尿WBC 30～40个/HPF，RBC 10～15个/HPF，亚硝酸盐（＋）。该患者首先考虑的诊断是","o":["急性肾小球肾炎","急性肾盂肾炎","急性膀胱炎","急性间质性肾炎","尿道综合征"],"a":2,"e":"女性尿频、尿急、尿痛，尿白细胞显著增多、亚硝酸盐阳性，但无发热、腰痛及肾区叩痛，病变局限于下尿路，首先考虑急性膀胱炎。急性肾盂肾炎有发热寒战、腰痛及肾区叩痛；急性肾小球肾炎以血尿、蛋白尿、水肿为主；尿道综合征无真性菌尿；急性间质性肾炎常有用药史"},{"q":"患者，女，16岁。劳力性呼吸困难8年，二维超声心动图检查可见房间隔中部有5mm的连续中断。下列哪项体征有诊断意义","o":["双侧胸廓不对称，有心前区隆起","心前区有抬举性搏动","肺动脉瓣区第二心音亢进并有固定性分裂","心尖部内上方舒张早期奔马律","三尖瓣区舒张期隆隆样杂音"],"a":2,"e":"超声示房间隔中部连续中断即房间隔缺损，左向右分流使肺血流量增加，肺动脉瓣区第二心音亢进并呈固定性分裂，是有诊断意义的体征。胸廓不对称及心前区隆起、抬举性搏动均非特异；心尖部舒张早期奔马律见于心衰；三尖瓣区舒张期隆隆样杂音提示三尖瓣狭窄"},{"q":"患者，男，62岁，进食海鲜后3小时出现皮肤瘙痒伴有全身皮疹红斑，自服马来酸氯苯那敏后无改善，出现口渴、视物模糊、乏力，1小时前出现胸部压迫窒息感，持续不缓解，急诊来院。测血压80/50mmHg，ECG见图像，诊断考虑","o":["过敏性皮炎","过敏性休克","过敏性休克合并急性心肌梗死","过敏性休克合并心绞痛","急性心肌梗死心源性休克"],"a":2,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，进食海鲜后皮疹、瘙痒、血压80/50mmHg为过敏性休克，继而出现持续不缓解的胸部压迫窒息感，若心电图显示ST段抬高则提示合并急性心肌梗死。过敏性皮炎无休克；单纯过敏性休克或心绞痛不能解释持续性缺血；心源性休克无明确过敏原接触史\n\n官方题库中缺失图片"},{"q":"患者，女，26岁。因右耳外耳道疼痛、流脓，并高热3天就诊。查体发现右侧鼓膜充血穿孔，见脓液自穿孔处流出。首先考虑诊断为","o":["外耳道炎","外耳道疖肿","急性中耳炎","颅底骨折","颅内感染"],"a":2,"e":"外耳道疼痛流脓伴高热，鼓膜充血、穿孔并有脓液流出，是急性化脓性中耳炎的表现。外耳道炎与外耳道疖肿病变局限于外耳道、鼓膜完整；颅底骨折有外伤史及血性脑脊液流出；颅内感染伴头痛、呕吐及脑膜刺激征，均无中耳化脓性改变"},{"q":"患者，男，60岁，剧烈腹痛2小时。查体：板状腹。腹部平片示有少量腹腔积液。血液生化检查：AMY 11000U/L，LPS 2200U/L。下列符合腹腔积液特点的是","o":["蛋白定量＜25g/L","LDH＜200U/L","细胞计数＜100×106/L","浆液性","积液LDH/血清LDH＞0.6"],"a":4,"e":"剧烈腹痛、板状腹伴血淀粉酶和脂肪酶显著升高，提示重症急性胰腺炎，腹腔积液属炎性渗出液，渗出液积液LDH与血清LDH之比大于0.6。蛋白定量低于25g/L、LDH低于200U/L、细胞计数低于100及浆液性均为漏出液特点，不符合胰腺炎的炎性积液"},{"q":"患者，女，38岁，皮肤黏膜出血点1个月，发热、面色苍白。胸骨压痛阳性，外周血WBC 70.0×109/L，可见幼稚细胞，Hb 80g/L，PLT 50×109/L。下列哪项检查有助诊断","o":["细胞外铁","细胞内铁","过氧化酶染色","叶酸","维生素B12"],"a":2,"e":"出血点、发热、贫血、胸骨压痛，外周血白细胞显著升高并见幼稚细胞，提示急性白血病，过氧化酶染色可鉴别粒系与淋巴系，助诊及分型。细胞内外铁用于判断缺铁或铁粒幼细胞贫血；叶酸与维生素B12测定用于巨幼细胞贫血，均不能诊断急性白血病"},{"q":"患者，男，54岁。突发剧烈头痛2小时，伴惊厥。查体：颈项强直，双侧凯尔尼格征阳性。该患者的诊断最可能是","o":["颅脑外伤","蛛网膜下腔出血","颅内占位性病变","高血压脑病","败血症"],"a":1,"e":"突发剧烈头痛伴惊厥，颈项强直、凯尔尼格征阳性等脑膜刺激征明显，而无发热及外伤史，最符合蛛网膜下腔出血。颅脑外伤有明确外伤史；高血压脑病以血压显著升高和意识障碍为主、无脑膜刺激征；颅内占位起病缓慢；败血症有发热等感染中毒表现"},{"q":"患者，男，30岁，右侧第一跖趾关节突发红肿、疼痛难忍1天入院。辅助检查：血尿酸为650μmol/L，血肌酐75μmol/L，血尿素氮8.1mmol/L。目前患者最可能的诊断是","o":["慢性肾小球肾炎","急性肾小球肾炎","痛风性关节炎","类风湿关节炎","风湿性关节炎"],"a":2,"e":"第一跖趾关节突发红肿、剧痛，血尿酸650μmol/L明显升高，符合痛风性关节炎，系尿酸盐结晶沉积所致。类风湿关节炎为对称性小关节肿痛伴晨僵、尿酸正常；风湿性关节炎呈游走性大关节痛；肾小球肾炎表现为血尿、蛋白尿，均无高尿酸与急性单关节炎"},{"q":"患者，男，50岁。1周前支气管镜检查示左主支气管被肿物完全阻塞。胸片示左肺肺不张。该患者不可能出现的体征是","o":["左肺触觉语颤减弱","左肺可闻及管状呼吸音","左肺肺泡呼吸音减弱","左肺叩诊浊音","左侧呼吸运动减弱"],"a":1,"e":"左主支气管被肿物完全阻塞致左肺阻塞性肺不张，肺泡通气消失，表现为语颤减弱、肺泡呼吸音减弱、叩诊浊音及呼吸运动减弱。管状呼吸音即支气管呼吸音，需支气管通畅且肺组织实变利于传导才能闻及；支气管完全阻塞时该音不能传导，故为不可能出现的体征"},{"q":"患者，女，55岁。黄疸伴肝大、皮肤瘙痒与心动过缓。粪色变浅、呈陶土色。最可能的诊断是","o":["溶血性黄疸","先天性非溶血性黄疸","隐性黄疸","肝细胞性黄疸","胆汁淤积性黄疸"],"a":4,"e":"黄疸伴皮肤瘙痒、心动过缓及陶土色粪便，提示胆道梗阻、结合胆红素反流入血，符合胆汁淤积性黄疸。溶血性黄疸以非结合胆红素升高为主、尿胆原增加、无陶土色便；先天性非溶血性黄疸无胆道梗阻表现；隐性黄疸血胆红素未达肉眼可见黄染；肝细胞性黄疸瘙痒不显著"},{"q":"患者，男，24岁。查体时发现包皮翻起后，龟头不能露出。该患者最可能的诊断是","o":["尿道下裂","假两性畸形","包茎","包皮过长","包皮过短"],"a":2,"e":"翻起包皮后仍不能露出尿道口或阴茎头即为包茎，多因先天性包皮口狭窄或炎症外伤后粘连所致。包皮过长虽覆盖阴茎头，但翻起后能露出尿道口与阴茎头，与此不同。尿道下裂为尿道开口异位，假两性畸形属性发育异常，均非包皮遮盖所致"},{"q":"患者，女，17岁，双下肢皮肤见多个红色点状改变，直径不超过2mm，压之不褪色，不凸出表面，应诊断为","o":["瘀点","蜘蛛痣","紫癜","充血性皮疹","斑疹"],"a":0,"e":"皮肤黏膜出血直径不超过2mm且压之不褪色为瘀点，由血液淤积于皮下形成。紫癜直径为3～5mm，瘀斑则大于5mm，二者仅以大小划分。蜘蛛痣与充血性皮疹受压后多褪色或消失，皮疹受压褪色可与瘀点鉴别"},{"q":"患者，男，38岁。3年前患结核性渗出性心包炎，近2个月来呼吸困难、腹胀、水肿。查体：颈静脉怒张。X线示左、右心缘变直及心包钙化。该患者颈静脉怒张是由于","o":["上腔静脉阻塞","下腔静脉阻塞","静脉向右房回流受阻","右心房压力增高","右心室压力增高"],"a":2,"e":"缩窄性心包炎使心包广泛增厚粘连，心脏舒张受限，静脉血回流右房受阻而淤积，故见颈静脉怒张、肝大及水肿。上腔静脉阻塞表现为头颈部及上肢静脉怒张，下腔静脉阻塞以下肢与腹壁静脉曲张为主，均非全身性回流受阻"},{"q":"患者，男，45岁。有高血压史，因“阵发性心悸2天”来诊。查体：血压120/70mmHg，心率180次/min，律齐，心音正常，无杂音。1min后心率降至80次/min，律齐。30秒后又复至180次/min。最可能的诊断为","o":["窦性心动过速","阵发性心房颤动","阵发性室上性心动过速","阵发性心房扑动","三度房室传导阻滞"],"a":2,"e":"阵发性室上性心动过速突发突止，心率多在150～250次/分且节律规整，发作前后心率可骤然恢复正常。窦性心动过速多渐起渐止，心率一般不超过160次/分。心房颤动心律绝对不齐，三度房室传导阻滞心室率缓慢"},{"q":"患者发热、无力、食欲缺乏，腹痛，以左下腹明显，腹泻，早期稀便，大便次数增多后转为黏液脓血便，并有里急后重。应诊断为","o":["急性胃肠炎","急性细菌性痢疾","肠伤寒","食物中毒","肠阿米巴痢疾"],"a":1,"e":"急性细菌性痢疾由志贺菌引起，病变以直肠乙状结肠为主，表现为发热腹痛、黏液脓血便伴明显里急后重，粪便镜检见成堆脓细胞。肠阿米巴痢疾粪便呈暗红色果酱样，里急后重轻。急性胃肠炎多为稀便，无脓血及里急后重"},{"q":"患者，男，54岁。腹胀、少尿半个月，呕血1小时入院。既往有乙肝病史，未正规治疗。以下检测结果正确的是","o":["凝血酶时间缩短","凝血酶时间延长，且不被甲苯胺蓝纠正","凝血酶时间延长，且被甲苯胺蓝纠正","凝血酶活性增高","蛋白C活性增高"],"a":2,"e":"乙肝后肝硬化时血中类肝素物质增多，使凝血酶时间延长；加入甲苯胺蓝可中和肝素使TT缩短5秒以上，故延长的TT被纠正。若TT延长不被甲苯胺蓝纠正，提示非肝素类物质所致。TT缩短无临床意义，肝硬化亦无凝血酶活性或蛋白C增高"},{"q":"1岁患儿，头部向左侧偏斜，颜面偏向右侧，颈部活动较困难，应考虑为","o":["先天性斜颈","重症肌无力","脑膜炎","颈椎结核","进行性肌萎缩"],"a":0,"e":"先天性斜颈因胸锁乳突肌挛缩粗短，病侧胸锁乳突肌隆起，头偏向患侧而颜面转向健侧，颈部活动受限。重症肌无力为波动性肌无力，脑膜炎伴脑膜刺激征，颈椎结核有局部压痛与全身症状，均不表现为特征性斜颈"},{"q":"患者，女，双下肢水肿，血浆白蛋白26g/L，尿常规结果显示尿蛋白（4＋），该患者蛋白尿类型为","o":["肾小球性蛋白尿","肾小管性蛋白尿","功能性蛋白尿","组织性蛋白尿","偶然性蛋白尿"],"a":0,"e":"大量蛋白尿伴低白蛋白及水肿符合肾病综合征，因肾小球滤过膜电荷屏障受损，白蛋白等中大分子蛋白漏出，形成肾小球性蛋白尿。肾小管性蛋白尿以α1、β2微球蛋白等小分子为主。功能性及组织性蛋白尿量小，不出现低蛋白与水肿"},{"q":"患者，男，56岁，食欲减退，乏力、消瘦伴右上腹隐痛，加重1天入院。皮肤、巩膜黄染，血清胆红素520μmol/L，结合胆红素480μmol/L，粪便呈白陶土样。首先考虑下列哪种疾病","o":["梗阻性黄疸","溶血性黄疸","消化道出血","消化不良","肝硬化"],"a":0,"e":"梗阻性黄疸时结合胆红素反流入血，以结合胆红素升高为主，CB/STB大于50%，胆道完全阻塞致粪便呈白陶土色。溶血性黄疸以非结合胆红素升高为主，总胆红素多低于85.5μmol/L。肝细胞性黄疸则结合与非结合胆红素均增高"},{"q":"患者，女，51岁，慢性阻塞性肺疾病20多年。2小时前剧烈咳嗽后突然胸部剧痛，继之呼吸困难，发绀、大汗、烦躁，气管右移，左肺呼吸音减低。最可能的诊断是","o":["大叶性肺炎","急性肺梗死","自发性气胸","休克性肺炎","急性心肌梗死"],"a":2,"e":"慢性阻塞性肺疾病患者肺大疱破裂，气体进入胸膜腔形成自发性气胸，剧烈咳嗽后突发胸痛与呼吸困难，气管向健侧移位，患侧呼吸音减弱。大叶性肺炎有发热及实变征，肺栓塞多见于长期卧床，心肌梗死有心电图和心肌酶改变"},{"q":"患者，女，45岁。反复上腹痛20年，近1周出现频繁呕吐，呕吐量大，呕吐物为宿食，不含胆汁。查体：可见胃型，振水音阳性。最可能的诊断是","o":["十二指肠憩室","幽门梗阻","十二指肠梗阻","小肠梗阻","食管裂孔疝"],"a":1,"e":"幽门梗阻时胃内容物排空受阻，呕吐多为餐后隔夜宿食且不含胆汁，伴胃型及空腹振水音。十二指肠梗阻呕吐物常含胆汁，小肠梗阻呕吐频繁且带胆汁，食管裂孔疝多无大量宿食呕吐与振水音"},{"q":"患儿，男，5岁。3天前无诱因出现发热，体温最高39、5℃；2天前出现皮疹，呈密集而均匀红色细小丘疹，初见颈部，24小时内遍及全身，周身皮肤潮红，伴痒感。查血常规：WBC 8.23×109/L，L% 10.6%，N% 80.1%，Hb 131g/L，PLT 333×109/L。患儿可能出现的舌部体征为","o":["地图舌","裂纹舌","草莓舌","牛肉舌","镜面舌"],"a":2,"e":"猩红热由A组溶血性链球菌引起，发热后出密集均匀红色细小丘疹、皮肤潮红，舌乳头肿胀发红呈草莓舌。地图舌为游走性舌炎，裂纹舌见核黄素缺乏，牛肉舌见糙皮病，镜面舌见缺铁性贫血，均非猩红热表现"},{"q":"患者，66岁，既往5年高血压病史。主诉心悸1年，劳力性心累胸闷2个月。查体：心音强弱快慢绝对不齐。常规心电图示心室率，125次/min，等电位线消失，P波不可见，QRS呈正常形态。住院期间患者诉头晕胸闷明显，发作时脉搏缓慢整齐，则心电图表现最可能为","o":["窦性心动过缓","一度房室传导阻滞","二度Ⅰ型房室传导阻滞","二度Ⅱ型窦房传导阻滞","三度房室传导阻滞"],"a":4,"e":"持续性心房颤动患者出现RR绝对规则且心室率缓慢，提示并发三度房室传导阻滞，此时心房心室各自激动，P波与QRS无关，心房率快于心室率。一度房室传导阻滞仅PR延长，二度呈间歇性漏搏，窦性心动过缓心率虽慢但节律规则"},{"q":"患者，男，20岁。发热、腹痛1天，入院检查粪便为黏液脓血便，诊断细菌性痢疾，最有价值的细胞是","o":["吞噬细胞","中性粒细胞","上皮细胞","红细胞","嗜酸粒细胞"],"a":0,"e":"粪便中吞噬细胞是诊断急性细菌性痢疾的主要依据之一，镜检还见大量白细胞与成堆脓细胞。中性粒细胞增多亦见于肠炎，属非特异改变。红细胞仅提示出血，嗜酸粒细胞增多主要见于寄生虫感染与过敏"},{"q":"患者，女，33岁，经常心悸、乏力，稍微活动即自觉心悸。图中上方为入院时心电图，下方为服用普萘洛尔（30mg）后90min的心电图。请问入院时上方心电图的诊断为","o":["窦性心律，心电图正常","窦性心动过速，T波改变","窦性心动过速，陈旧性心肌梗死","窦性心动过速，右室肥厚","窦性心动过速，不完全性右束支传导阻滞"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。β受体亢进综合征表现为心悸、窦性心动过速、胸闷及ST段轻度下移、T波平坦倒置，普萘洛尔试验可使其心电图恢复，据此可判断为窦性心动过速伴T波改变。陈旧性心肌梗死有病理性Q波，右室肥厚有胸导联高R波，不完全性右束支阻滞呈rsR′波\n\n官方题库中缺失图片"},{"q":"患者，女，32岁，外阴瘙痒、白带增多5天，分泌物呈豆腐渣样，有凝乳状小块，考虑该患者为","o":["滴虫性阴道炎","阴道加德纳菌感染","真菌性阴道炎","细菌性阴道炎","宫颈炎"],"a":2,"e":"真菌性阴道炎由白念珠菌引起，典型表现为外阴瘙痒、豆渣样或凝乳状白带。滴虫性阴道炎分泌物呈黄色泡沫脓性，阴道加德纳菌感染为灰白奶油样稀薄分泌物，细菌性阴道病有线索细胞，宫颈炎多为黏液脓性分泌物"},{"q":"某患者查体所见：右胸饱满，呼吸运动减弱，语颤消失，叩诊实音，呼吸音消失。此征符合","o":["右肺大叶性肺炎","右侧胸腔积液","右气胸","右肺不张","右肺大空洞"],"a":1,"e":"大量胸腔积液时胸廓饱满，呼吸动度减弱，液体积聚使语颤消失、叩诊实音、呼吸音减弱或消失。大叶性肺炎实变期语颤增强并可闻支气管呼吸音，叩诊浊音。气胸叩诊鼓音，肺不张胸廓塌陷、气管移向患侧"},{"q":"45岁女性，反复夜间胃部胀痛2个月，既往史应包括","o":["有无胆囊炎病史","有无恶心、呕吐病史","有无腹痛、腹泻病史","药物不良饮食习惯","有无吸烟史"],"a":0,"e":"既往史着重询问与现病相关的既往疾病，反复夜间胃部胀痛需排除胆囊疾病放射痛，故应包括有无胆囊炎病史。恶心呕吐、腹痛腹泻属现症表现，药物与饮食习惯属个人史，吸烟史虽为个人史但非针对胃痛的直接既往史"},{"q":"一老年患者，60岁，反复咳嗽、咳痰10余年，加剧3天入院。查体：桶状胸，呼气相延长，两肺可闻及干、湿啰音。该患者还可能出现","o":["双肺触觉语颤增强","双肺呼吸动度增强","双肺肺泡呼吸音增强","双肺听到较弱的支气管呼吸音","叩诊肺肝界下移"],"a":4,"e":"慢性支气管炎并发肺气肿时肺过度充气，双肺叩诊过清音，肝浊音界下移，肺下界下降移动度变小。肺气肿肺泡含气增多，触觉语颤及肺泡呼吸音均减弱而非增强，呼吸动度减弱，支气管呼吸音仅在实变等异常时出现"},{"q":"患者，女，35岁。多食、多汗、消瘦半年，心率106次/min，颈部可见肿大。该患者查体最可能出现的体征是","o":["甲状腺结节性肿大，无震颤或杂音","甲状腺弥漫性肿大，伴有震颤","甲状腺肿大并结节感，质地硬","颈静脉怒张","Oliver征"],"a":1,"e":"甲状腺功能亢进症因腺体弥漫性增生肿大、血流丰富，触诊可及震颤并闻及血管杂音。单纯性甲状腺肿为弥漫或结节性肿大但无甲亢体征与震颤，甲状腺癌结节质硬、表面不平。Oliver征为主动脉弓动脉瘤的表现。颈静脉怒张属心血管体征"},{"q":"患者，女，62岁，反复右上腹疼痛，发热伴尿黄4年。2天前又出现右上腹绞痛，发冷、发热、尿黄来诊。下列表现均对本病诊断有意义，但除外","o":["胆囊肿大","墨菲征阳性","胆囊点压痛阳性","巩膜黄染","季肋点压痛阳性"],"a":4,"e":"胆总管结石伴胆管炎可见胆囊肿大、墨菲征及胆囊点压痛、巩膜黄染，均与胆道病变相关。季肋点压痛位于第10肋骨前端，提示肾脏病变，如肾盂肾炎或肾结石，对胆道疾病诊断无意义，故为除外项"},{"q":"患者，女，34岁，双手关节痛伴晨僵2个月就诊。目前诊断类风湿关节炎的标志抗体是","o":["抗Sm抗体","抗SSB抗体","抗环瓜氨酸抗体","抗dsDNA抗体","抗RNP抗体"],"a":2,"e":"抗环瓜氨酸肽抗体针对瓜氨酸表位，是诊断类风湿关节炎的标志性抗体，特异性强。抗Sm抗体与抗dsDNA抗体为系统性红斑狼疮标记抗体，抗SSB抗体多见于干燥综合征，抗RNP抗体见于混合性结缔组织病"},{"q":"患者，女，37岁，患有风湿性心脏病，二尖瓣双病变。近半年来常有活动后心悸、气紧，双下肢水肿，夜间不能平卧。腹部检查：肝在右肋下3cm、剑突下5cm，表面光滑，质地稍韧，边缘圆钝，有弥漫性压痛，肝颈静脉反流征阳性。最可能的诊断是","o":["肝脓肿","肝淤血","脂肪肝","原发性肝癌","肝棘球蚴病"],"a":1,"e":"风湿性心脏病二尖瓣病变致慢性右心衰，肝脏淤血肿大、表面光滑、边缘圆钝、质韧有压痛，肝颈静脉回流征阳性为特征。肝癌表面不平呈结节状，肝脓肿有发热及局限性隆起，脂肪肝虽边缘圆钝但无肝颈静脉回流征"},{"q":"患者，男，40岁。突起呕吐鲜血40ml，解柏油样便约300ml。既往查体提示脾大，HbSAg阳性。该患者查体一般不可能出现","o":["蜘蛛痣","肝大、质软","腹水","血压12.0/8.0kPa（90/60mmhg）","肠鸣音亢进"],"a":1,"e":"乙肝后肝硬化门脉高压致脾大、呕血黑便，实质坚硬、表面结节，不可能表现为肝大质软。肝硬化常见蜘蛛痣、腹水，静脉曲张破裂出血致血压下降，肠道积血使肠鸣音亢进，均与此病相符"},{"q":"患者，女，34岁。因昏迷而被送往急诊，被怀疑有药物过量服用。动脉血气：pH 7、15，HCO3－ 28mEq/L，PaCO2 80mmHg，PaO2 65mmHg。该患者可能发生了","o":["急性呼吸性酸中毒并发严重的低氧血症","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血","代谢性酸中毒部分代偿期"],"a":0,"e":"pH 7.15明显降低，PaCO2 80mmHg显著升高，PaO2 65mmHg下降，符合急性呼吸性酸中毒伴严重低氧血症。呼吸性碱中毒pH升高、PaCO2降低。代谢性碱中毒HCO3原发升高。代谢性酸中毒PaCO2应代偿性降低，均与本例不符"},{"q":"患者，女，60岁，心悸2小时来急诊，心电图提示R-R间期绝对不齐，最可能的诊断是","o":["心房扑动不等比下传","心房颤动","房性心动过速伴房室结文氏传导","室性心动过速","心室颤动"],"a":1,"e":"心房颤动时正常P波消失代以颤动波，心室律绝对不齐，RR间距互不相等，是最常见的心律失常之一。心房扑动不等比下传可呈不规则但多有锯齿样F波，房速文氏传导有渐进性PR延长，室速QRS宽大畸形，室颤无明确QRS"},{"q":"患者，女，32岁。面黄、酱油色尿1周。查体：中度贫血貌，巩膜黄染，肝肋下未触及，脾肋下1cm。该患者最不可能出现的是","o":["结合胆红素轻度增高","非结合胆红素明显增高","总胆红素明显增高","尿胆原明显增高","尿胆红素阳性"],"a":4,"e":"溶血性黄疸以非结合胆红素升高为主，总胆红素增高，尿胆原明显增多，但因非结合胆红素不能经肾排出，尿胆红素为阴性。梗阻性与肝细胞性黄疸结合胆红素升高，尿胆红素阳性。本例最不可能出现尿胆红素阳性"},{"q":"患者，女，25岁，关节疼痛、面部红斑、乏力半个月余。血常规示血红蛋白110g/L、血小板75×109/L，出血时间延长，束臂试验阳性，PT、APTT正常。抗核抗体阳性，抗双链DNA阳性，血小板P-选择素增高，尿常规示尿蛋白（＋）。该患者可能的诊断是","o":["原发免疫性血小板减少症","急性肾小球肾炎","慢性肾小球肾炎","肝硬化","系统性红斑狼疮"],"a":4,"e":"系统性红斑狼疮为多系统自身免疫病，见面颊红斑、关节痛、蛋白尿及血小板减少，抗核抗体与抗dsDNA阳性，血小板P选择素增高反映免疫活化。原发免疫性血小板减少症仅有血小板减少，无抗核抗体及肾损害。急慢性肾小球肾炎无多系统表现"},{"q":"患者，男，35岁。反酸、胃灼热20天，伴饥饿痛。就诊消化科，怀疑消化性溃疡，行胃镜检查。其症状可能与下列哪种细菌感染有关","o":["空肠弯曲菌","痢疾志贺氏菌","幽门螺杆菌","胎儿弯曲菌","大肠弯曲菌"],"a":2,"e":"幽门螺杆菌定植于胃黏膜，是胃炎、胃溃疡及十二指肠溃疡的主要病因，感染可表现为反酸、烧心及饥饿痛。空肠弯曲菌、胎儿弯曲菌及大肠弯曲菌多引起肠道感染与腹泻，痢疾志贺菌致细菌性痢疾，均与消化性溃疡无关"},{"q":"患者，男，37岁，饮酒后突发上腹部剧痛20min，伴恶心、呕吐、腹胀。查体：强迫体位，上腹部带状压痛，轻度肌紧张，无反跳痛。诊断首先考虑","o":["消化性溃疡穿孔","急性胰腺炎","急性胆囊炎","急性胃肠炎","急性阑尾炎"],"a":1,"e":"饮酒后突发上腹剧痛，伴恶心呕吐及上腹带状压痛、轻度肌紧张，符合急性胰腺炎，胰酶激活致胰腺自身消化。消化性溃疡穿孔有板状腹和明显反跳痛，急性胆囊炎压痛局限于右上腹墨菲征阳性，急性阑尾炎为右下腹转移性痛"},{"q":"患者，女，54岁，活动后胸闷憋气20年，查体颊红，心尖部可及舒张期隆隆样杂音。该患者心电图最可能出现的改变是","o":["P波高耸","P波增宽","V5导联R波振幅大于等于2.5mV","aVF导联R波振幅大于等于2.0mV","RV5＋SV1≥3.5mV"],"a":1,"e":"心尖舒张期隆隆样杂音提示二尖瓣狭窄，左心房肥大除极时间延长，心电图示P波增宽≥0.12秒呈双峰，称二尖瓣型P波。P波高耸为右房肥大的肺型P波。V5、aVF导联R波增高及RV5＋SV1增大均为左心室肥厚表现"},{"q":"患者，女，右上腹疼痛，向右肩放射，恶心、呕吐，伴畏寒发热1周。查体：急性病容，腹平坦，墨菲征阳性，右上腹局部肌紧张，反跳痛。该患诊断最可能为","o":["胆总管结石","化脓性胆管炎","胰头癌","胆道蛔虫","急性胆囊炎"],"a":4,"e":"右上腹痛向右肩放射、墨菲征阳性、局部肌紧张及反跳痛，为急性胆囊炎的典型表现。胆总管结石与化脓性胆管炎多伴寒战高热及明显黄疸，胰头癌为无痛性进行性黄疸，胆道蛔虫呈阵发性钻顶样剧痛"},{"q":"患儿，男，2岁，出生后3个月时儿保于外院发现心脏杂音。查体：心尖冲动弥散，胸骨左缘第3/4肋间可闻及4/6级粗糙的全收缩期杂音，传导广泛，伴震颤。应诊断为","o":["主动脉瓣狭窄","二尖瓣狭窄","室间隔缺损","房间隔缺损","动脉导管未闭"],"a":2,"e":"胸骨左缘第3、4肋间闻及粗糙响亮的全收缩期杂音伴震颤、传导广泛，是室间隔缺损的典型体征。房间隔缺损杂音多在胸骨左缘第2肋间，动脉导管未闭为连续性机器样杂音，主动脉瓣狭窄杂音位于胸骨右缘第2肋间"},{"q":"患者，男，78岁，高血压病史10年，间断服用降压药，未规律监测血压。3小时前晨练时突然倒地意识丧失、角膜反射减弱、瞳孔对光反射迟钝，其意识障碍程度属","o":["轻度昏迷","中度昏迷","深度昏迷","昏睡","嗜睡"],"a":1,"e":"中度昏迷对周围及剧烈刺激均无反应，仅防御反射存在，角膜反射减弱、瞳孔对光反射迟钝、眼球无转动。轻度昏迷上述反射仍存在。深度昏迷全身肌肉松弛、各种反射全消失。昏睡与嗜睡均可被唤醒，不属昏迷"},{"q":"患者，女，35岁。鼻出血、躯干及四肢瘀点瘀斑2天。2周前有感冒病史。血常规示血小板10×109/L，单克隆抗体血小板抗原固定试验阳性，出血时间12min，束臂试验阳性，PT、APTT正常。该患者可能的诊断是","o":["血管性血友病","原发免疫性血小板减少症","血小板无力症","再生障碍性贫血","弥散性血管内凝血"],"a":1,"e":"血小板显著减少至10×10⁹/L，单克隆抗体血小板抗原固定试验阳性提示血小板自身抗体，病前有感冒史，符合原发免疫性血小板减少症。血管性血友病APTT延长，再生障碍性贫血呈全血细胞减少，弥散性血管内凝血有凝血因子消耗与PT、APTT延长"},{"q":"患者，女，44岁，月经量增多7个月余，发现血小板减少5个月余，查体见全身多发皮下3～5mm小红点，受压不褪色。最可能的诊断是","o":["斑疹","紫癜","荨麻疹","瘀点","血肿"],"a":1,"e":"皮下出血点直径3～5mm、受压不褪色为紫癜，本例伴月经增多及血小板减少。瘀点直径不超过2mm，瘀斑大于5mm，血肿为片状出血伴皮肤显著隆起。斑疹受压多褪色，不属出血性皮损"},{"q":"患者，男，35岁，阵发性心悸3年，每次持续半小时至5小时不等，休息可终止。本次发作时心电图提示Ⅱ导联可见直立圆钝P波，心率140次/min，律齐。诊断最可能是","o":["心房扑动呈4∶1下传","心房颤动","阵发性室性心动过速","窦性心动过速","阵发性交界区心动过速"],"a":3,"e":"Ⅱ导联直立圆钝P波说明心律起源为窦房结，心率140次/分且律齐，符合窦性心动过速，休息可终止。心房扑动4∶1下传可见锯齿样F波，心房颤动P波消失且律不齐，室性心动过速QRS宽大畸形，交界区心动过速P波倒置"},{"q":"患者，女，24岁，近1周出现肉眼血尿，伴尿频、腰酸，双下肢无水肿。查体：双肾区叩击痛（＋）。血常规正常，尿常规示尿蛋白（－），镜检WBC（＋＋＋），RBC（＋＋＋＋）。该患者最可能的诊断是","o":["急性肾炎","尿路结石","尿路感染","泌尿系肿瘤","功能性血尿"],"a":2,"e":"尿频、腰酸伴肉眼血尿，尿白细胞及红细胞均明显增多而蛋白阴性，肾区叩击痛，符合尿路感染。急性肾炎以蛋白尿、红细胞管型和水肿为主，尿路结石为阵发性绞痛，泌尿系肿瘤多为无痛性血尿"},{"q":"患者，女，糖尿病3年，血糖控制不佳。1天前入院明确诊断为糖尿病酮症酸中毒。该患者目前最可能出现的呼吸改变为","o":["潮式呼吸","间停呼吸","抑制性呼吸","叹气样呼吸","库斯莫尔呼吸"],"a":4,"e":"糖尿病酮症酸中毒时严重代谢性酸中毒刺激呼吸中枢，出现深而快的库斯莫尔呼吸以排出CO2代偿。潮式呼吸与间停呼吸为呼吸中枢抑制的周期性异常呼吸，抑制性呼吸因胸痛致吸气突然中断，叹气样呼吸多为功能性"},{"q":"患者，女，42岁，突然上腹痛1天，渐重，恶心，呕吐。来诊后急查血尿淀粉酶，均明显高于正常。该患最可能的病因为","o":["胆道结石","急性胰腺炎","病毒感染","磺胺类药物","遗传或代谢障碍"],"a":1,"e":"突发上腹痛伴血尿淀粉酶显著升高，是急性胰腺炎的特征，胰酶外溢致胰腺及周围组织自身消化。胆道结石、病毒感染、药物及遗传代谢障碍仅为部分病因，不能据淀粉酶升高直接判定，题干所述临床与酶学改变指向急性胰腺炎本身"},{"q":"中年男性，突发恶心，头晕，呕新鲜血1000ml，出虚汗，无腹痛，查体：BP 10/8kPa（1kPa≈7.5mmHg），巩膜无黄染，心率120次/min，腹软，无压痛，肝脾未触及。最可能的诊断是","o":["十二指肠溃疡","食管-胃底静脉曲张破裂","胃癌","Mallory-Weiss综合征","急性胃黏膜病变"],"a":1,"e":"突发无痛性大量呕血伴休克、巩膜无黄染，符合食管胃底静脉曲张破裂，系门脉高压致曲张静脉破裂。十二指肠溃疡多有规律性腹痛，胃癌常伴消瘦贫血，Mallory-Weiss综合征先有剧烈呕吐，急性胃黏膜病变多有应激或药物诱因"},{"q":"患者，女，35岁。10年来经常出现发热伴四肢关节肿胀、酸痛。近2年来出现咳嗽伴夜间阵发性呼吸困难。查体：口唇及双面颊部发绀，脉搏90次/min，不齐，听诊心律不规整，第一心音强弱不等，心率130次/min，心尖部可闻及舒张期隆隆样杂音。最可能的诊断","o":["风湿性心脏病，二尖瓣狭窄","风湿性心脏病，二尖瓣关闭不全","甲状腺功能亢进症","病毒性心肌炎","风湿性心脏病，三尖瓣狭窄"],"a":0,"e":"心尖区舒张期隆隆样杂音是二尖瓣狭窄的特征，结合风湿热关节病史及心房颤动，诊断为风湿性心脏病二尖瓣狭窄。二尖瓣关闭不全为心尖粗糙全收缩期吹风样杂音，三尖瓣狭窄杂音在胸骨左缘下端，甲亢无器质性杂音"},{"q":"患者，男，82岁，糖尿病合并高血压30余年，自诉1个月内突发步行时下肢酸痛乏力，稍休息后可缓解，而后仍可行走。此时患者可能存在的步态是","o":["蹒跚步态","共济失调步态","慌张步态","跨阈步态","间隙性跛行"],"a":4,"e":"行走中下肢突发酸痛乏力、稍休息缓解后可再行走，为间歇性跛行，见于高血压动脉硬化致下肢缺血。蹒跚步态见于佝偻病，共济失调步态用于小脑病变，慌张步态见于帕金森病，跨阈步态见于腓总神经麻痹"},{"q":"患者，男，35岁。既往胆囊结石病史。近1周右上腹痛，呈剧烈绞痛，2天前出现黄疸。查体见表情痛苦，不安，巩膜黄染。该患者最可能的诊断是","o":["急性胰腺炎","急性胆囊炎","急性心肌梗死","急性阑尾炎","急性胃炎"],"a":1,"e":"既往胆囊结石，右上腹剧烈绞痛后出现黄疸、表情痛苦，符合急性胆囊炎，结石嵌顿致胆囊炎症。急性胰腺炎为上腹带状痛且淀粉酶升高，急性心肌梗死有胸痛及心电改变，急性阑尾炎为右下腹转移性疼痛"},{"q":"患者，男，20岁，感冒后7天出现颜面及双下肢水肿，尿少。血压150/100mmHg。尿蛋白（＋＋），潜血（＋＋），尿沉渣：红细胞104/HPF。2周后少尿，BUN 8.2mmol/L，Scr 159、3μmol/L，哪种疾病可能性大","o":["急性肾小球肾炎","急性肾盂肾炎","慢性肾炎","肾病综合征","高血压肾病"],"a":0,"e":"感冒后1周出现水肿、少尿、高血压及镜下血尿、蛋白尿，肾功能轻度受损，符合急性肾小球肾炎，链球菌感染后免疫反应致病。急性肾盂肾炎有发热及白细胞尿，肾病综合征为大量蛋白尿与低蛋白，慢性肾炎病程迁延"},{"q":"患者，男，65岁。近2个月食欲缺乏伴上腹部无规律性疼痛，体重下降6kg。胃镜示胃小弯处有一3.4cm×2.6cm的较大溃疡，边缘不整齐伴坏死。哪组区域的浅表淋巴结肿大最有诊断意义","o":["颈前淋巴结","颈后淋巴结","锁骨上窝淋巴结","腋窝淋巴结","腹股沟淋巴结"],"a":2,"e":"胃小弯巨大溃疡边缘不整齐伴坏死，高度怀疑胃癌，胃癌多经胸导管转移至左锁骨上淋巴结，即Virchow淋巴结，触诊有意义。腋窝淋巴结多引流乳腺及上肢，腹股沟淋巴结引流下肢，颈前淋巴结多与甲状腺喉部相关"},{"q":"患者，男，40岁，反复饥饿时中上腹部隐痛10年，伴反酸嗳气，在进食和服制酸剂后可缓解，今晨中上腹剧痛后腹痛持续存在。该患者可能发生的并发症是","o":["急性胰腺炎并发出血坏死","胰腺癌并发肠梗阻","胃癌并发幽门梗阻","消化性溃疡并发急性穿孔","急性胆囊炎并发胆汁性腹膜炎"],"a":3,"e":"长期饥饿痛、进食及制酸剂可缓解提示十二指肠溃疡，今晨突发持续剧痛不缓解，提示溃疡穿透浆膜层并发急性穿孔，胃肠内容物刺激腹膜。急性胰腺炎与胆囊炎疼痛部位及性质不同，胃癌幽门梗阻以呕吐宿食为主"},{"q":"患者四肢麻木入院。查体发现四肢末梢存在手套、袜套样痛觉减退。考虑患者损伤位于以下哪一部位","o":["脊髓后根","脊髓后角","丘脑","四肢末梢神经","大脑皮层"],"a":3,"e":"四肢末梢手套、袜套样对称性痛觉减退，提示多发性周围神经末梢受损，长度依赖性分布为其特点。脊髓后根或后角损害呈节段性分布，丘脑损害表现为对侧偏身感觉障碍，大脑皮层损害多为单肢或面部感觉异常"},{"q":"患者，女，25岁。反复发热、咳嗽、咳痰3年，间歇性痰中带血3个月。右下肺可闻及固定局限的湿啰音。最可能的诊断是","o":["胸腔积液","大叶性肺炎","肺癌","支气管扩张","慢性支气管炎"],"a":3,"e":"反复咳嗽咳痰3年伴间断咯血，右下肺固定局限性湿啰音，符合支气管扩张，支气管壁破坏扩张致分泌物潴留。慢性支气管炎无反复咯血及固定湿啰音，肺癌多为痰中带血，大叶性肺炎起病急，胸腔积液叩诊实音"},{"q":"患者，男，46岁。满腹剧痛10小时，腹部检查发现腹式呼吸运动减弱，腹部稍隆起，触诊全腹腹肌紧张，压痛和反跳痛。该患者最可能的诊断是","o":["急性腹膜炎","急性阑尾炎","急性胰腺炎","肝硬化","结核性腹膜炎"],"a":0,"e":"满腹剧痛，腹式呼吸减弱，全腹肌紧张、压痛与反跳痛，为腹膜炎三联征，符合急性弥漫性腹膜炎。急性阑尾炎局限于右下腹，急性胰腺炎体征偏上腹，结核性腹膜炎起病缓慢、腹壁呈揉面感"},{"q":"患者，男，77岁。吸烟50年，常年咳嗽、咳痰，近10年出现活动性呼吸困难，进行性加重。查体：桶状胸，双肺呼吸音减弱，未闻及明显干、湿啰音。最可能的诊断为","o":["慢性支气管炎并发肺气肿","气胸","胸腔积液","大叶性肺炎","慢性支气管炎"],"a":0,"e":"长期吸烟咳嗽咳痰，近年出现进行性活动后呼吸困难，桶状胸、呼吸音减弱，符合慢性支气管炎并发肺气肿，肺泡壁破坏含气量增多。单纯慢性支气管炎无进行性呼吸困难与桶状胸，气胸与胸腔积液起病或体征均不同，大叶性肺炎为急性实变"},{"q":"患者，男，39岁，突然左腰部钻顶样疼痛，大汗淋漓。他最可能采取的体位是","o":["辗转体位","被动体位","强迫侧卧位","强迫仰卧位","强迫坐位"],"a":0,"e":"左腰部钻顶样剧痛为肾或胆道结石绞痛，发作时针刺样疼痛使患者辗转反侧、坐卧不安，故取辗转体位。强迫仰卧位见于急性腹膜炎，强迫侧卧位见于胸膜疾病，被动体位见于极度衰弱，强迫坐位见于心肺功能不全"},{"q":"患者，女，42岁，有糖尿病病史，自13岁以来就一直使用胰岛素。患者定向力差，查体：T 38.8℃，WBC 14×109/L。床旁血气分析：pH 7.23，PaCO2 25mmHg。HCO3－ 12mEq/L，PaO2 118mmHg。该患者可能发生了","o":["代谢性酸中毒部分代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","呼吸性酸中毒与低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"pH 7.23降低、HCO3⁻ 12mEq/L显著减少为原发代谢性酸中毒，PaCO2 25mmHg降低系呼吸代偿，PaO2正常，属部分代偿期。呼吸性碱中毒PaCO2原发降低且pH升高，代谢性碱中毒HCO3⁻升高，静脉血PaO2不应达118mmHg"},{"q":"患者，老年女性，反复双下肢水肿半年入院。既往患慢性肾小球肾炎。尿常规：蛋白＋＋＋，血Hb92g/L。肾功能：血肌酐250μmol/L，尿素氮13.4mmol/L。为明确患者肾功能不全分期，还需进一步做哪项检查","o":["尿β2-微球蛋白测定","血β2-微球蛋白测定","内生肌酐清除率测定","血尿酸测定","血清胱抑素测定"],"a":2,"e":"肾功能不全分期依据肾小球滤过率，内生肌酐清除率可较准确反映GFR，故需进一步测定。血肌酐与尿素受肌肉量、饮食等影响，不能精确分期。血β2微球蛋白与血清胱抑素主要用于早期肾损伤的敏感判断"},{"q":"患者，男，37岁。腰痛伴右下肢放射性痛2个月，无发热、盗汗。查体：右侧直腿抬高实验阳性，小腿前外侧和足底感觉减退。该患者最可能的诊断是","o":["腰椎间盘突出症","腰肌劳损","腰椎肿瘤","腰椎结核","强直性脊柱炎"],"a":0,"e":"腰痛伴下肢放射性痛，直腿抬高试验阳性，小腿前外侧及足底感觉减退，符合腰椎间盘突出症压迫神经根。腰肌劳损无下肢放射痛，腰椎结核有低热盗汗及拾物试验阳性，强直性脊柱炎为对称性骶髂关节病变"},{"q":"患者，女，68岁，诉心悸、晕厥，动态心电图结果提示：平均心室率＜40次/min，有窦性停搏，最长RR间期达2.8s。临床诊断考虑","o":["预激综合征","房室传导阻滞","窦性心动过缓","病态窦房结综合征","期前收缩"],"a":3,"e":"平均心室率低于40次/分，有窦性停搏且最长RR间期2.8秒，伴晕厥，符合病态窦房结综合征。单纯窦性心动过缓无窦性停搏和长间歇，房室传导阻滞以PR延长或漏搏为特征，预激综合征有delta波，期前收缩为提早搏动"},{"q":"患者，男，48岁，因饱餐后突发上腹部剧痛2小时急诊入院。腹部X片示膈下半月形游离气体。该患者入院时可能的体位是","o":["被动体位","辗转体位","强迫侧卧位","强迫仰卧位","强迫俯卧位"],"a":3,"e":"膈下半月形游离气体提示胃肠穿孔致急性腹膜炎，患者仰卧并双腿蜷曲以减轻腹肌紧张，取强迫仰卧位。辗转体位见于胆石症肾绞痛，强迫侧卧位见于胸膜疾病，强迫俯卧位见于脊柱疾病，被动体位见于意识丧失"},{"q":"患者，男，54岁。会阴部肿胀2个月。查体：会阴部透光试验阳性。该患者最可能的诊断是","o":["腹股沟斜疝","精索鞘膜积液","睾丸肿瘤","阴囊外伤水肿","丝虫病"],"a":1,"e":"会阴部肿胀且透光试验阳性，提示鞘膜腔内液体增多，符合精索鞘膜积液，透光时呈橙红色均质半透明。腹股沟斜疝与睾丸肿瘤含实质组织而不透光，阴囊外伤水肿无典型透光，丝虫病多伴乳糜尿或象皮肿"},{"q":"患者，男，60岁。主诉：咳嗽、咯血3个月余。既往：吸烟30年，20支/d。查体：右肺呼吸明显降低，叩诊实音。右侧锁骨上淋巴结肿大。该患者最可能的咯血出血形式是","o":["痰中带血","暗红色黏液痰","大咯血","脓血痰","粉红色泡沫痰"],"a":0,"e":"老年吸烟者咳嗽咯血，右肺呼吸音降低、叩诊实音，锁骨上淋巴结肿大提示肺癌转移，支气管肺癌少有大咯血，主要表现为痰中带血。暗红色黏液痰多见于肺栓塞，脓血痰见于肺脓肿，粉红色泡沫痰见于急性左心衰"},{"q":"患者，女，45岁，因右侧胸痛并气促10小时来诊。肺部CT可见右下肺有楔形实变影。超声检查发现左下肢深静脉有血栓形成。近1个月有口服药物避孕史，家族中无类似患者。以下哪项描述不正确","o":["因为在血栓栓塞急性期，所以应该积极溶栓治疗","华法林可以抑制多种凝血因子活性，应该单独在溶栓后立即使用","因华法林前期有抑制蛋白C和蛋白S的作用，所有早期需要与肝素合用","在抗凝过程中维持INR在2.0～2.5","应该行狼疮抗凝物的筛查"],"a":1,"e":"华法林早期先抑制蛋白C和蛋白S，反而有促凝倾向，故溶栓后不能单独立即使用，须与肝素重叠至少数日，该项描述不正确。抗凝期间维持INR 2.0～2.5、早期与肝素合用及筛查狼疮抗凝物均为合理处理"},{"q":"患者，女，发现周身水肿、血脂升高2年，入院检查血清白蛋白25.8g/L，尿常规结果显示尿蛋白（＋＋＋＋），说明","o":["肾小球滤过膜改变","肾小管对蛋白回吸收障碍","功能性蛋白尿","组织性蛋白尿","偶然性蛋白尿"],"a":0,"e":"周身水肿、血脂升高、血清白蛋白显著降低及大量蛋白尿，符合肾病综合征，其机制为肾小球滤过膜电荷屏障受损，白蛋白漏出增多。肾小管回吸收障碍以小分子蛋白为主，功能性、组织性及偶然性蛋白尿量小，不引起低蛋白水肿"},{"q":"患者因“头痛1天”入院。查体：患者去枕仰卧，一侧下肢髋、膝关节屈曲直角，检查者将患者小腿抬高伸膝仅90°即感到痛。这提示患者哪项检查阳性","o":["直腿抬高实验","4字实验","Kernig征","Brudzinski征","Hoffmann征"],"a":2,"e":"髋膝屈曲成直角后被动伸膝受限并疼痛，为Kernig征阳性，属脑膜刺激征。直腿抬高试验为被动抬高下肢出现放射痛，4字试验检查骶髂关节，Brudzinski征为被动屈颈引起下肢屈曲，Hoffmann征为上肢病理反射"},{"q":"患者，男，50岁，反复出现尿频、尿急2年，偶伴无痛性肉眼血尿，无水肿。查体双肾无叩击痛。尿常规示尿蛋白（－），镜检WBC 0～4个/HPF，RBC（＋＋）。该患者最可能的诊断是","o":["肾结核","膀胱炎","膀胱癌","前列腺增生症","慢性肾炎"],"a":2,"e":"反复尿频尿急伴无痛性肉眼血尿，尿蛋白阴性而红细胞增多，无肾区叩痛，符合膀胱癌，肿瘤刺激与出血所致。膀胱炎有明显尿痛且白细胞增多，肾结核有慢性过程与脓尿，前列腺增生见老年男性排尿困难，慢性肾炎有蛋白尿管型"},{"q":"患者，女，20岁，皮肤瘀斑反复发作伴月经增多2年。无出血性疾病家族史。肝脾不大。血常规：血红蛋白100g/L，血小板120×109/L。出血时间正常，束臂试验阳性，PT、APTT正常，血小板黏附及聚集功能均正常。该患者可能的诊断为","o":["过敏性紫癜","原发免疫性血小板减少症","单纯性紫癜","血友病A","血管性血友病"],"a":2,"e":"血小板及出血时间均正常，血小板黏附聚集功能正常，仅束臂试验阳性，提示血管壁脆性增加，结合青年女性月经期瘀斑，符合单纯性紫癜。过敏性紫癜四肢对称伴关节腹痛，原发免疫性血小板减少症血小板减少，血友病A与血管性血友病均有凝血异常"},{"q":"患者，男，25岁。有左下肢深静脉血栓性静脉炎，突然左胸痛，伴有气短。查体：呼吸急促，气管居中，双肺叩之清音，呼吸音正常，左下肺湿啰音。最可能的诊断是","o":["肺栓塞","肺炎","气胸","心绞痛","急性左心衰竭"],"a":0,"e":"下肢深静脉血栓性静脉炎基础上突发胸痛、气短、呼吸急促，符合肺栓塞，栓子脱落阻塞肺动脉。气胸叩诊鼓音且呼吸音消失，肺炎有发热与实变，心绞痛为压榨样胸痛，急性左心衰咳粉红色泡沫痰"},{"q":"患者，男，45岁。突发胸骨后压榨样疼痛，最可能的原因是","o":["食管癌","自发性气胸","胸膜炎","心肌梗死","心包炎"],"a":3,"e":"突发胸骨后压榨样疼痛是急性心肌梗死的典型表现，疼痛剧烈伴濒死感、持续时间长。心绞痛性质相似但历时短暂、休息或含硝酸酯可缓解。自发性气胸伴呼吸困难及呼吸音减弱，胸膜炎疼痛随呼吸加剧，食管癌以吞咽困难为主"},{"q":"患者，女，26岁，明确诊断大动脉炎，血沉明显升高。今晨活动后出现明显胸闷伴疼痛，约1小时入院，可能的诊断是","o":["急性前壁缺血","左主干病变伴广泛心肌缺血","变异型心绞痛","急性下壁缺血","陈旧前壁心肌梗死伴室壁瘤形成"],"a":1,"e":"大动脉炎患者活动后出现胸闷痛，心电图运动中出现ST段抬高提示透壁性心肌缺血，多因左主干或近段严重狭窄，故考虑左主干病变伴广泛心肌缺血。变异型心绞痛为静息时痉挛，下壁或前壁缺血范围局限，陈旧心梗伴室壁瘤有病理性Q波"},{"q":"患者，女，20岁，反复四肢紫癜3年，感冒时尤甚。血常规：WBC 5、0×109/L，血小板计数30×109/L，Hb 100g/L，脾无肿大，血小板自身抗体阳性。最可能的诊断是","o":["过敏性紫癜","单纯性紫癜","血友病","慢性弥散性血管内凝血","原发免疫性血小板减少症"],"a":4,"e":"血小板明显减少至30×10⁹/L，血小板自身抗体阳性，脾不大，反复紫癜，符合原发免疫性血小板减少症，感冒可诱发或加重。过敏性紫癜与单纯性紫癜血小板计数正常，血友病为凝血因子缺乏，慢性弥散性血管内凝血有凝血指标异常"},{"q":"患者，女，18岁，下肢水肿、少尿15天，近2天出现发热。尿常规尿蛋白（＋＋＋），白细胞10～13个/HPF，红细胞13～15个/HPF，红细胞管型0～1个/LPF。最可能的诊断是","o":["肾病综合征合并上呼吸道感染","肾病综合征合并泌尿系统感染","感染所致尿改变","急性肾盂肾炎","急性肾炎合并泌尿系统感染"],"a":4,"e":"下肢水肿少尿、尿蛋白阳性及红细胞管型提示急性肾小球肾炎，近2日发热且尿白细胞增多提示合并泌尿系统感染。肾病综合征以大量蛋白尿和低蛋白为主，急性肾盂肾炎以白细胞管型与发热为主而无红细胞管型，单纯感染无水肿少尿"},{"q":"患者，男，63岁。吸烟，反复咳嗽、咳白色泡沫痰20余年，气促10年。2天前因受凉后出现发热伴咳黄脓痰，气喘不能平卧。查体：双肺语颤减弱，可闻及散在干、湿啰音。该患者最可能的诊断是","o":["慢性阻塞性肺疾病","肺大疱","支气管扩张","肺结核","肺癌"],"a":0,"e":"长期吸烟咳嗽咳白色泡沫痰、气促，受凉后咳黄脓痰加重，双肺语颤减弱及干湿啰音，符合慢性阻塞性肺疾病急性加重。支气管扩张以大量脓痰和反复咯血、固定湿啰音为特征，肺结核有低热盗汗，肺癌局限性体征，肺大疱无大量脓痰"},{"q":"患者，女，47岁。外阴瘙痒，灼痛，白带增多呈豆腐渣样。阴道分泌物清洁度分级为Ⅳ级。最可能的诊断是","o":["细菌性阴道炎","真菌性阴道炎","子宫内膜炎","老年性阴道炎","子宫颈癌"],"a":1,"e":"外阴瘙痒灼痛、白带豆腐渣样，镜检清洁度Ⅳ度，符合真菌性阴道炎，由白念珠菌引起。细菌性阴道病分泌物呈灰白奶油样稀薄并见线索细胞，老年性阴道炎见于绝经后，子宫内膜炎与宫颈癌分泌物性质不同且无豆渣样改变"},{"q":"患者，男，19岁，上呼吸道感染后持续发热，胸部CT考虑为大叶性肺炎，并且病灶累及胸壁。患者不会出现下列哪项体征","o":["患侧呼吸音减弱","可闻及管状呼吸音","可闻及湿啰音","硬币叩击征","胸膜摩擦音"],"a":3,"e":"大叶性肺炎实变时患侧呼吸音减弱，可闻管状呼吸音及湿啰音，累及胸壁胸膜可闻胸膜摩擦音，均与肺实变累及范围相关。硬币叩击征用于检查气胸或胸腔积液，实变时不出现，故为不会出现的体征"},{"q":"患者，男，48岁，10年少量饮酒史。近1个月上腹疼痛，饥饿时加重，呈现疼痛－进食－缓解的规律。最可靠的诊断措施是","o":["超声检查","上消化道内镜","上消化道钡餐","依据临床表现","根据药物的治疗效果"],"a":1,"e":"饥饿时中上腹痛、疼痛－进食－缓解规律提示十二指肠溃疡，确诊最可靠的是上消化道内镜，可直接观察黏膜并取活检。上消化道钡餐仅提供间接影像，腹部超声对空腔脏器溃疡价值有限，临床表现与药物疗效均不能作为确诊依据"},{"q":"患者，男，35岁，劳力性心悸气短1年，心悸3个月。诊断风湿性心脏病、二尖瓣狭窄、快室率心房颤动，予以地高辛0.25mg、1次/d，患者用药后心电图的改变不包括","o":["T波高耸，基底部狭窄，呈帐篷型T波","ST段下垂型压低","ST-T呈“鱼钩型”","双向T波，初始部分倒置，终末部分直立","Q-T间期缩短"],"a":0,"e":"地高辛中毒或治疗量心电图可见ST段下垂型压低呈鱼钩型、T波双向或倒置、QT间期缩短。帐篷型高耸T波基底部狭窄是高钾血症表现，并非地高辛作用，故为不包括项"},{"q":"一长期头歪的小儿患者来院检查，接诊医生发现患者颈部胸锁乳突肌萎缩，头部向右侧转无力。据此推测，患儿损伤部位为以下哪部分","o":["颈第5～6神经根","左侧副神经","右侧副神经","臂丛神经","面神经"],"a":1,"e":"副神经支配胸锁乳突肌与斜方肌，损伤后同侧肌肉萎缩，向对侧转头及同侧耸肩无力。患儿胸锁乳突肌萎缩且向右侧转头无力，提示左侧副神经受损。右侧副神经损伤应向左转头无力，臂丛与颈神经根损害以上肢症状为主，面神经支配面部表情肌"},{"q":"患者，男，41岁。阵发性心悸气短2年，M型超声心动图检查见二尖瓣前叶CD段于全收缩期呈吊床样下垂，二维超声心动图示收缩期二尖瓣前叶向左房脱出并超过瓣环连线。下列哪项体征具有诊断意义","o":["心尖区舒张中晚期隆隆样杂音伴开瓣音","心尖区收缩中期喀喇音并收缩晚期杂音","心尖区舒张晚期杂音并舒张早期奔马律","心尖区舒张中晚期杂音并肿瘤落音","心尖区全收缩期杂音并舒张时晚期奔马律"],"a":1,"e":"超声示二尖瓣前叶收缩期脱入左房呈吊床样下垂，符合二尖瓣脱垂，典型体征为心尖区收缩中期喀喇音合并收缩晚期杂音。舒张中晚期隆隆样杂音伴开瓣音见于二尖瓣狭窄，肿瘤落音见于左房黏液瘤，全收缩期杂音见于二尖瓣关闭不全"},{"q":"患者，女，30岁，近期为乌发多次服用何首乌，近2日出现目黄、尿黄。既往无肝炎病史、无饮酒史，无家族性疾病。其黄疸最可能的原因是","o":["病毒性肝炎","脂肪肝","自身免疫性肝病","肝硬化","药物性肝病"],"a":4,"e":"患者多次服用何首乌后出现目黄尿黄，无病毒性肝炎、饮酒及家族史，药物中毒性肝损伤导致肝细胞坏死或胆汁淤积，符合药物性肝病。脂肪肝多无症状且转氨酶轻度升高，自身免疫性肝病与肝硬化各有相应病史与检查特点"},{"q":"患者，女，31岁，头痛、呕吐、意识不清1天入院。化验检查脑脊液中氯化物明显减少，考虑诊断为","o":["结核性脑膜炎","化脓性脑膜炎","病毒性脑膜炎","隐球菌性脑膜炎","流行性乙型脑炎"],"a":0,"e":"脑脊液氯化物降低以结核性脑膜炎最明显，因细菌分解葡萄糖产酸及蛋白增高所致，结合头痛呕吐意识障碍，考虑结核性脑膜炎。化脓性脑膜炎氯化物亦可降低但不如结核显著，病毒性脑膜炎氯化物多正常，隐球菌性脑膜炎可取墨汁染色鉴别"},{"q":"患者，女，19岁，受凉后突然畏寒，高热，左侧胸痛伴咳嗽，咯少量铁锈色痰，胸部X片见左下肺大片淡薄阴影。其最可能的诊断是","o":["金黄色葡萄球菌肺炎","肺炎球菌性肺炎","原发性支气管癌合并阻塞性肺炎","结核性胸膜炎","急性原发性肺脓肿"],"a":1,"e":"受凉后寒战高热、胸痛并咳铁锈色痰，胸片见大片淡薄阴影，为肺炎链球菌肺炎的典型表现，铁锈色痰最具特征。金黄色葡萄球菌肺炎咳黄色脓痰，原发性支气管癌合并阻塞性肺炎起病缓，结核性胸膜炎以胸痛与胸腔积液为主"},{"q":"患者，女，32岁。阵发性劳力性呼吸困难3年，咳痰带血丝1个月。M型超声心动图检查可见二尖瓣前叶呈城墙样改变，后叶同向运动。下列体征具有诊断意义的是","o":["心尖区3级收缩期杂音，向腋下传导","肺动脉瓣区第二心音亢进伴有分裂","胸骨左缘第2肋间Graham-Steell杂音","心尖区隆隆样舒张中晚期杂音","心尖区隆隆样舒张早期杂音"],"a":3,"e":"超声二尖瓣前叶城墙样改变、后叶同向运动是二尖瓣狭窄的表现，最具诊断意义的体征是心尖区舒张中晚期低调隆隆样递增型杂音。舒张早期杂音可见于主动脉瓣关闭不全的相对性二尖瓣狭窄，收缩期杂音提示关闭不全，Graham-Steell杂音为肺动脉瓣舒张期杂音"},{"q":"患者，男，26岁。间歇性水肿6年，近1周水肿加重。尿蛋白（＋＋＋）。血生化：总蛋白51、2g/L，清蛋白20、5g/L。最可能的诊断是","o":["肝炎后肝硬化","原发性高血压","慢性肾盂肾炎","慢性肾小球肾炎","肾病综合征"],"a":4,"e":"间歇水肿、尿蛋白强阳性及血清白蛋白显著降低，符合肾病综合征，大量蛋白尿与低蛋白血症为其核心。慢性肾小球肾炎蛋白尿量较少且水肿不显著，肝炎后肝硬化以肝功能异常为主，慢性肾盂肾炎与高血压肾病均无如此大量蛋白尿"},{"q":"患者，女，45岁。近4年来经常腰痛，劳累及气候变化时加剧。3天前搬重物后腰痛加剧，疼痛放射至左下肢。最可能的疾病是","o":["脊椎结核","类风湿关节炎","强直性脊柱炎","腰椎间盘突出症","腰肌劳损"],"a":3,"e":"慢性腰痛反复发作，搬重物后加剧并向左下肢放射，直腿抬高试验常阳性，符合腰椎间盘突出症，髓核突出压迫神经根。腰肌劳损无下肢放射痛，脊椎结核有拾物试验阳性与全身症状，强直性脊柱炎起病缓慢且活动受限，类风湿关节炎多为小关节病变"},{"q":"患者，女，42岁，因“反复活动后胸闷，气短5年”入院。查体：面颊部紫红色，口唇发绀，左侧卧位心尖区可闻及舒张中期隆隆样杂音。患者可能出现的面容为","o":["慢性病容","满月面容","肾病面容","二尖瓣面容","贫血面容"],"a":3,"e":"风湿性心脏病二尖瓣狭窄致肺淤血与右心负荷增加，面颊紫红、口唇发绀称二尖瓣面容。慢性病容见于消耗性疾病，满月面容见于库欣综合征，肾病面容为眼睑苍白水肿，贫血面容为面色苍白无华"},{"q":"患者，女，70岁，左侧肢体不自在抖动、僵硬5年，右侧肢体受累3个月入院。查体：面部呆板、无表情、行动迟缓、小碎步。该患者最可能的诊断是","o":["脑梗死","脑性瘫痪","小脑疾病","帕金森病","脊髓病变"],"a":3,"e":"肢体抖动、僵硬、面部呆板无表情、行动迟缓及小碎步，符合帕金森病，静止性震颤伴肌张力增高为其特点。脑梗死多急性起病有偏瘫，脑性瘫痪起病于婴幼儿，小脑疾病为意向性震颤与共济失调，脊髓病变无静止性震颤"},{"q":"患者，男，66岁，咳嗽、咳痰、痰中带血3个月余。既往抽烟40余年，查体可触及颈前肿大淋巴结，质硬，无压痛，与周围组织粘连明显。该患者最可能的疾患是","o":["囊肿","非特异性淋巴结炎","囊状瘤","恶性肿瘤","血液系统疾病"],"a":3,"e":"老年长期吸烟者咳嗽咳痰带血，颈部淋巴结质硬、无压痛、与周围组织粘连固定，符合恶性肿瘤淋巴结转移。非特异性淋巴结炎多有压痛且质软，淋巴结结核可粘连但常有波动感或瘘管，囊肿质软有波动，血液系统疾病多为全身性淋巴结肿大"},{"q":"患者，女，68岁，腹痛、腹胀半年余，进食后加重。今日晨起排便，粪便呈黑色、发亮，遂来就诊。考虑诊断为","o":["肛裂","胆道结石","幽门梗阻","上消化道出血","过敏性肠炎"],"a":3,"e":"粪便黑色发亮呈柏油样，提示上消化道出血，血红蛋白在肠道内与硫化物结合成硫化铁所致。肛裂为便后鲜血，胆道结石多伴黄疸与右上腹痛，幽门梗阻以呕吐宿食为主，过敏性肠炎为黏液便或血便但无柏油样改变"},{"q":"患者，女，37岁，患风湿性心脏病20余年，心脏彩超示二尖瓣狭窄。1周前感冒后出现呼吸困难、咳嗽、水肿，查体可见颈静脉怒张。最可能出现以下哪种情况","o":["上腔静脉阻塞","下腔静脉阻塞","左心衰竭","右心衰竭","主动脉瓣关闭不全"],"a":3,"e":"二尖瓣狭窄长期肺动脉高压致右心室负荷增加，最终出现右心衰竭，表现为体循环淤血、水肿及颈静脉怒张。左心衰竭以肺淤血呼吸困难为主，上腔静脉阻塞限于头颈部，下腔静脉阻塞以下肢静脉曲张为主，主动脉瓣关闭不全有周围血管征"},{"q":"患者，女，57岁。水肿、间断血尿18年。查体：血压190/120mmHg，BUN 27mmol/L，CO2CP 12mmol/L，血清钾7.2mmol/L，血清钙1.95mmol/L，血红蛋白50g/L。则其心电图表现最可能是","o":["Q-T间期缩短，T波高耸，基底部狭窄","ST段压低，T波低平及U波增高","U波倒置","ST段水平下移","QRS波群明显增宽，Q-T间期延长"],"a":4,"e":"血清钾7.2mmol/L属重度高钾血症，超过7mmol/L时QRS波群进一步增宽、PR及QT间期延长，甚至P波消失呈窦室传导。QT缩短、T波高耸基底窄见于轻中度高钾，ST压低、T低平及U波增高为低血钾表现"},{"q":"患者，男，38岁。右手腕部外伤后出现“枪刺刀”畸形。该患者最可能的诊断是","o":["耻骨骨折","尺神经损伤","Smith骨折","Colles骨折","桡神经损伤"],"a":3,"e":"腕部外伤后出现枪刺刀或餐叉样畸形，为桡骨远端伸直型骨折即Colles骨折，骨折块向背侧桡侧移位。Smith骨折为屈曲型、移位方向相反，尺神经损伤呈爪形手，桡神经损伤表现为垂腕"},{"q":"患者，男，48岁。于3年前年开始出现头昏、头重，多次在当地医院按照脑供血不足进行治疗，但症状时好时坏。4个月前头昏加重，自觉头脑不清醒，情绪低落，疲倦乏力、精力不足，兴趣减退、厌恶交际，入睡困难、注意力不集中、记忆力减退，性功能障碍。该患者最可能的诊断是","o":["焦虑症","抑郁症","人格障碍","睡眠障碍","躯体形式障碍"],"a":1,"e":"情绪低落、兴趣减退、疲倦乏力、注意力及记忆力下降、入睡困难和性功能障碍，符合抑郁症，核心为持续情绪低落与兴趣丧失。焦虑症以过度担忧紧张为主，睡眠障碍仅表现为失眠，人格障碍为人格模式偏离，躯体形式障碍以躯体症状为主"},{"q":"患者，男，18岁。诊断1型糖尿病2年，平时每日用胰岛素32U，血糖控制正常。近1周因胰岛素用完停用。此次因“乏力3天，昏迷3小时”入院，拟诊“糖尿病酮症酸中毒”。患者呼吸为何种气味，能支持该诊断","o":["大蒜味","芳香味","氨臭味","肝臭味","烂苹果味"],"a":4,"e":"糖尿病酮症酸中毒时大量脂肪氧化产生酮体，丙酮经肺呼出使气息呈烂苹果味，为特征性表现。大蒜味见于有机磷中毒，氨臭味见于膀胱炎或尿毒症，肝臭味见于肝坏死，芳香味无特异诊断意义"},{"q":"患者，女，30岁，腹胀大3年。查体：腹如足月妊娠大小，无压痛，肝脾触不清，叩诊腹中部浊音，两侧鼓音，浊音不随体位改变。下列诊断可能性最大的是","o":["肝硬化腹水","巨大卵巢囊肿","结核性腹膜炎","原发性肝癌","自发性腹膜炎"],"a":1,"e":"腹中部叩诊浊音、两侧鼓音且浊音不随体位改变，为巨大卵巢囊肿的特点，肠管被挤向两侧。肝硬化腹水叩诊为移动性浊音，浊音随体位移至低位，结核性腹膜炎有揉面感，原发性肝癌与自发性腹膜炎均无此典型叩诊表现"},{"q":"患者，女，68岁。近4年来，每年冬季咳嗽、咳白色黏痰，伴气喘。近1周症状加重，无发热。此患者可能出现的异常体征","o":["支气管呼吸音","支气管肺泡呼吸音","支气管呼吸音＋湿啰音","哮鸣音","语音震颤增强"],"a":2,"e":"老年慢性咳喘患者近1周加重，肺部可出现异常支气管呼吸音即管样呼吸音，并伴湿啰音，提示肺实变或炎症渗出。哮鸣音为弥漫性干啰音，语音震颤增强见于实变而本例肺含气增多，单纯支气管呼吸音无湿啰音则不符合"},{"q":"患者，男，56岁。半年前开始反复出现腹胀、食欲缺乏。曾患乙型病毒性肝炎。查体手掌大小鱼际处发红，颈部可见一血管痣。患者该体征的形成原因可能是","o":["雄激素减少","醛固酮增多","抗利尿激素分泌增多","雄激素的灭活减少","雌激素增多"],"a":4,"e":"手掌大小鱼际发红为肝掌，颈部血管痣为蜘蛛痣，均因肝硬化时肝脏对雌激素灭活减弱、血中雌激素增多所致。醛固酮与抗利尿激素增多参与腹水水肿形成，雄激素减少或灭活改变并非肝掌蜘蛛痣的主要机制"},{"q":"患者，女，54岁，既往曾患亚急性甲状腺炎，近期肥胖，颜面明显，伴下肢黏液性水肿。该患者肥胖最可能的原因是","o":["单纯性肥胖","下丘脑性肥胖","库欣综合征","甲状腺功能减退症","多囊卵巢综合征"],"a":3,"e":"既往亚急性甲状腺炎，出现肥胖、颜面明显及下肢黏液性水肿，符合甲状腺功能减退症，因皮下蛋白质与水潴留致非凹陷性黏液性水肿。库欣综合征为向心性肥胖满月脸多血质，单纯性肥胖无黏液性水肿，下丘脑性与多囊卵巢各有相应表现"},{"q":"患者，男，23岁，抵抗力下降、反复感染1年，结合相关检查诊断为艾滋病。该患者粪便检查可能发现","o":["钩虫","纤毛虫","鞭毛虫","隐孢子虫","阿米巴原虫"],"a":3,"e":"艾滋病患者免疫力低下，易合并肠道隐孢子虫感染，粪便呈稀水样，改良抗酸染色可发现卵囊。钩虫、鞭毛虫、纤毛虫感染各有不同粪便特点，阿米巴原虫感染典型为暗红色果酱样便，均非艾滋病特征性机会感染"},{"q":"患者，男，25岁。突发右侧胸痛、胸闷、呼吸困难，下列最可能出现的体征是","o":["胸壁静脉曲张","皮下气肿","右侧肋间隙变窄","胸壁压痛","胸骨叩击痛"],"a":1,"e":"突发右侧胸痛胸闷呼吸困难提示自发性气胸，气体经胸膜破损逸入皮下形成皮下气肿，触诊有捻发感或握雪感。肋间隙变窄见于肺不张，胸壁静脉曲张见于上腔静脉阻塞，胸壁压痛多为肋软骨炎或骨折，胸骨叩击痛无特异性"},{"q":"一患者反复咳嗽、咳脓痰、咯血，每次胸片示同一部位呈卷发样阴影改变，在听诊时应出现哪种改变","o":["两肺底可闻及捻发音","支气管语音","局限性水泡音","高调干啰音","低调干啰音"],"a":2,"e":"反复咳嗽咳脓痰咯血，胸片同一部位卷发样阴影为支气管扩张的典型影像，病变部位固定故听诊呈局限性水泡音即固定湿啰音。两肺底捻发音多见于心衰或肺纤维化，支气管语音见于肺实变，高调与低调干啰音为气道狭窄所致"},{"q":"患者，男，77岁。吸烟50年，常年咳嗽、咳痰，近10年出现活动性呼吸困难、并进行性加重。明确诊断为慢性支气管炎合并肺气肿，其肺部叩诊呈","o":["清音","过清音","鼓音","浊音","实音"],"a":1,"e":"慢性支气管炎合并肺气肿时肺泡壁破坏、肺含气量增多且弹性减弱，叩诊呈过清音，肺下界下降。鼓音见于气胸或肺空洞，浊音见于肺炎等实变前期，实音见于大量胸腔积液，清音为正常肺部叩诊音"},{"q":"患者，男，18岁。淋雨后出现咳嗽、咳痰，伴高热寒战，肺部叩诊呈浊音，气管无偏移。该患者主要考虑","o":["肺结核","支气管肺炎","大叶性肺炎","自发性气胸","肺不张"],"a":2,"e":"淋雨后高热寒战、咳嗽咳痰、肺部叩诊浊音，符合大叶性肺炎实变期，气管无偏移说明无大量胸腔积液或气胸。肺结核起病缓且有低热盗汗，支气管肺炎为散在斑点状阴影，自发性气胸叩诊鼓音，肺不张气管移向患侧"},{"q":"患者，女，20岁，反复性尿频、尿急、偶有终末性血尿半年，首先考虑为","o":["急性肾盂肾炎","肾结核","膀胱炎","滴虫性阴道炎","急性肾小球肾炎"],"a":2,"e":"反复尿频、尿急伴终末血尿提示膀胱三角区炎症，尿白细胞及红细胞增多符合膀胱炎，膀胱刺激征不剧烈且无全身感染中毒表现。肾结核以进行性尿频、尿急伴血尿、午后低热盗汗为特征；急性肾盂肾炎必有发热寒战与肾区叩痛；急性肾小球肾炎以血尿、蛋白尿、水肿和高血压为主，尿频尿急不明显"},{"q":"患者，男，20岁，高热2天，X线胸片发现右上肺大片状实变影。该患最不可能出现的是","o":["铁锈色痰","咳嗽","胸痛","呼吸急促","桶状胸"],"a":4,"e":"高热、肺部大片实变提示大叶性肺炎，常见咳嗽、胸痛、呼吸急促及铁锈色痰。桶状胸为胸廓前后径增大、肋间隙饱满，是慢性阻塞性肺疾病的特征，急性实变不会在数日内形成。铁锈色痰为肺炎链球菌肺炎典型表现；胸痛系炎症累及胸膜；呼吸急促源于肺实变致通气换气面积减少"},{"q":"患者，男，40岁。行胃大部切除术后第4天时，出现左侧腮腺肿大；检查口腔时，在腮腺导管口处加压，有脓性分泌物。最可能的诊断是","o":["急性流行性腮腺炎","腮腺导管结石","急性化脓性腮腺炎","腮腺肿瘤","Mikulicz综合征"],"a":2,"e":"胃肠道术后抵抗力低下，腮腺导管口加压有脓性分泌物，单侧腮腺肿痛，符合急性化脓性腮腺炎。腮腺导管结石肿胀与进食相关、无脓液；急性流行性腮腺炎多为双侧、无化脓；Mikulicz综合征同时累及泪腺与下颌下腺且无痛；腮腺肿瘤呈无痛性渐进肿大"},{"q":"患者，男，25岁。胸闷、气短12天，伴乏力、低热、盗汗，左侧腋后线第7肋间以下语颤减低，叩浊，呼吸音减低，腹部正常。拟考虑为","o":["胸膜间皮细胞瘤","系统性红斑狼疮","充血性心力衰竭","结核性胸膜炎","肝硬化"],"a":3,"e":"青壮年低热、盗汗，左侧腋后线第7肋间以下语颤减低、叩浊、呼吸音减低，为胸腔积液征，结合结核中毒症状符合结核性胸膜炎。胸膜间皮瘤病程长、胸痛剧烈且积液血性；系统性红斑狼疮有多系统损害；充血性心力衰竭积液为漏出液、双侧对称；肝硬化以腹水为主而非单侧胸水"},{"q":"36岁患者，主诉呕血1天入院，系统回顾不应记录哪部分内容","o":["咳嗽、咳痰","胸闷、气短","头痛、头晕","腹痛、腹泻","尿频、尿急"],"a":3,"e":"呕血属消化系统急症，与本次疾病直接相关的腹痛、腹泻应写入现病史，系统回顾不再重复记录。咳嗽、咳痰属呼吸系统回顾，胸闷、气短属循环系统回顾，头痛、头晕属神经系统回顾，尿频、尿急属泌尿系统回顾，均需逐一询问以排查伴随疾病"},{"q":"患者，男，60岁。左侧股骨颈骨折，卧床2个月后左下肢肿痛，逐渐加重。超声检查发现左下肢股静脉血栓形成。以下最不可能出现的检查结果是","o":["D-二聚体增高","FDP增加","APTT正常","血浆组织型纤溶酶原激活剂测定减低","血浆纤溶酶原活性减低"],"a":4,"e":"下肢深静脉血栓属血栓性疾病，纤溶活性受抑，纤溶酶原活性增高而非减低，血浆纤溶酶原活性减低提示纤溶活性增强，多见于原发性或继发性纤溶。D-二聚体增高与FDP增加反映继发纤溶活跃，见于血栓；APTT正常说明内源性凝血未被明显激活；组织型纤溶酶原激活剂减低亦提示纤溶受抑"},{"q":"患者，男，36岁，发热、咳嗽3天，现病史还应了解的内容不包括","o":["有无药物过敏","有无咳痰","有无胸痛","有无咯血","发热的程度"],"a":0,"e":"发热、咳嗽3天的现病史应围绕呼吸道症状展开，包括有无咳痰、胸痛、咯血及发热程度。药物过敏史属既往史内容，不写入现病史。咳痰性状提示感染性质；胸痛提示病变累及胸膜；咯血需鉴别肺结核与支气管扩张；发热程度反映病情轻重"},{"q":"患者，男，15岁。学校跑步时突然晕倒，1年前曾有类似发作。体检于心尖部可闻及舒张期杂音，超声心动图显示舒张期在二尖瓣前叶曲线下方有云雾状回声。该患者最可能的诊断是","o":["二尖瓣狭窄","二尖瓣关闭不全","左房黏液瘤","二尖瓣脱垂","主动脉瓣关闭不全"],"a":2,"e":"舒张期心尖区杂音、晕厥，超声见二尖瓣前叶下方云雾状回声，为左房黏液瘤随体位移动阻塞二尖瓣口所致，可闻及肿瘤扑落音。二尖瓣狭窄杂音为器质性隆隆样、随体位变化不明显；二尖瓣关闭不全为收缩期吹风样杂音；二尖瓣脱垂为收缩中晚期喀喇音；主动脉瓣关闭不全为舒张期叹气样杂音"},{"q":"患者，男，65岁。既往有慢性阻塞性肺疾病病史。3天前，受凉后出现发热伴意识模糊、定向力丧失、言语杂乱及幻听、幻视。该意识障碍属于","o":["昏睡","嗜睡","谵妄","轻度昏迷","意识模糊"],"a":2,"e":"急性感染发热期出现意识模糊、定向力丧失、幻觉错觉、躁动及言语杂乱，兴奋性增高，符合谵妄。嗜睡为病理性睡眠过多、可唤醒；昏睡需强刺激唤醒、答话含糊；意识模糊以定向障碍为主而无明显兴奋；轻度昏迷对强烈刺激有防御反射但不能被唤醒"},{"q":"突发剧烈头痛患者独立行走入院，头颅CT提示蛛网膜下腔出血。查体可以发现以下哪种神经体征","o":["颈强直","Babinski征","Oppenheim征","Hoffmann征","Gordon征"],"a":0,"e":"蛛网膜下腔出血血液刺激脑膜产生脑膜刺激征，颈强直为其典型表现，屈颈时阻力增高。Babinski征、Oppenheim征、Gordon征均为锥体束征，提示上运动神经元损害；Hoffmann征亦为锥体束征，见于颈髓病变，均非脑膜受激惹体征"},{"q":"患者，女，76岁，反复胸痛10余年，加重1个月入院。临床诊断：冠状动脉粥样硬化性心脏病，PCI术后；高血压；陈旧脑梗。入院查体：血压180/100mmHg，心率62次/min，呼吸18次/min。入院心电图检查结果如下，正确诊断为","o":["窦性心律，心电图正常","窦性心律，右束支传导阻滞","窦性心律，急性心肌梗死","窦性心律，陈旧性心肌梗死，束支阻滞","窦性心律，房室传导阻滞"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，心电图诊断需结合P波、QRS时限、ST-T动态演变及束支阻滞图形；在束支阻滞时急性梗死图形常被掩盖，陈旧性心肌梗死则表现为病理性Q波且无急性ST段抬高。窦性心律、房室传导阻滞各有其PR间期与脱落特点，正常心电图无异常Q波与ST-T改变\n\n官方题库中缺失图片"},{"q":"患者，男，40岁。畏寒、发热6天，肝区疼痛1天。腹部检查：肝右肋下2cm，质软，触痛，边缘整齐，肝右侧肋间隙局限性压痛，并有叩击痛。该患者最有可能的诊断是","o":["肝癌","肝脓肿","肝炎","多囊肝","肝棘球蚴病"],"a":1,"e":"寒战高热、肝区局限性剧烈压痛与叩击痛、肝脏质软边缘整齐，符合肝脓肿。肝癌质硬如石、表面结节凹凸不平；肝炎为弥漫性轻度压痛、无局限叩痛；多囊肝与肝棘球蚴病表面呈结节状、无急性感染中毒表现。肝区叩击痛对肝脓肿诊断有重要意义"},{"q":"患者，男，65岁，肝硬化8年。近来出现低热，右上腹疼痛，伴明显消瘦。查体：面色晦暗，颈部及前胸可见蜘蛛痣，腹膨隆，肝于右肋下3cm，触痛（＋），移动性浊音（＋）。为明确诊断，该患首选的生化检查为","o":["AFP","T/A","ALT","TIBL（胆红素测定）","血清蛋白电泳"],"a":0,"e":"肝硬化背景出现低热、右上腹痛、消瘦、肝大触痛及腹水，高度提示原发性肝癌，血清AFP为辅助诊断首选标志物。T/A非首选；ALT反映肝细胞炎症；胆红素测定评估黄疸；血清蛋白电泳用于蛋白异常病变的筛查，均不能特异诊断肝癌"},{"q":"患者，男，30岁，突发寒战、高热、呼吸频速，右上肺触觉语颤增强，叩诊浊音，闻及管状呼吸音。最可能的诊断是","o":["胸腔积液","气胸","肺不张","肺水肿","大叶性肺炎"],"a":4,"e":"寒战高热、语颤增强、叩诊浊音、管状呼吸音为肺实变典型体征，符合大叶性肺炎。胸腔积液语颤减弱、叩浊但呼吸音消失；气胸叩诊鼓音、呼吸音消失；肺不张气管移向患侧、语颤减弱；肺水肿双肺满布湿啰音、咳粉红色泡沫痰"},{"q":"患者，男，16岁。3天前无明显诱因出现发热，最高体温40℃，伴剧烈头痛、呕吐。查体：颈项强直，皮肤散在少量瘀点。该患者可能的面容是","o":["急性病容","苦笑面容","面具面容","满月面容","黏液水肿面容"],"a":0,"e":"高热、剧烈头痛、呕吐、颈项强直及瘀点提示流行性脑脊髓膜炎，急性感染性疾病呈急性病容，面色潮红、表情痛苦、鼻翼扇动。苦笑面容见于破伤风；面具面容见于帕金森病；满月面容见于库欣综合征；黏液水肿面容见于甲状腺功能减退"},{"q":"患者，女，50岁。肝素治疗中，实验室检查示TT延长。若想排除是不是肝素导致的TT延长，可以向标本中加入哪个物质再测定TT","o":["甲苯胺蓝","甲苯","蛋白物质","凝血酶","钙离子"],"a":0,"e":"肝素通过增强抗凝血酶作用延长TT，甲苯胺蓝可中和肝素，加入后TT缩短5秒以上即证实TT延长由肝素所致。甲苯、蛋白物质及钙离子不能特异性中和肝素；凝血酶为TT试验试剂而非纠正物，加入凝血酶仅使纤维蛋白原凝固，无法鉴别肝素影响"},{"q":"患者，女，45岁，因“心累、气紧，呼吸困难3天”入院。查体：胸骨左缘第3、4肋间可闻及舒张期叹气样杂音，心尖区可闻及舒张期隆隆样杂音。心尖部可触及舒张期震颤，胸片示左房、左室增大。最可能的诊断是","o":["风湿性心脏病，二尖瓣狭窄伴关闭不全","风湿性心脏病，二尖瓣狭窄伴主动脉瓣关闭不全","风湿性心脏病，主动脉瓣狭窄伴关闭不全","高血压心脏病，心功能不全","先天性心脏病，室间隔缺损"],"a":1,"e":"胸骨左缘第3、4肋间舒张期叹气样杂音为主动脉瓣关闭不全，心尖区舒张期隆隆样杂音伴震颤为器质性二尖瓣狭窄，加之左房左室增大，符合风湿性心脏病联合瓣膜病。二尖瓣狭窄伴关闭不全以心尖收缩期杂音为主；主动脉瓣狭窄伴关闭不全为收缩期喷射性杂音；高血压心脏病无瓣膜杂音；室间隔缺损为收缩期杂音"},{"q":"患者，男，28岁。自幼身体常易出现瘀斑，其姐姐也有相同的症状。完善相关检查，诊断为异常纤维蛋白原血症。下列哪项实验室检查肯定是存在的","o":["TT延长","TT缩短","APTT延长","AT延长","APTT缩短"],"a":0,"e":"异常纤维蛋白原血症患者纤维蛋白原结构异常，凝血酶时间延长，因纤维蛋白原功能缺陷致纤维蛋白形成障碍。TT缩短无临床意义；APTT主要反映内源性凝血因子，纤维蛋白原异常时APTT可正常；AT为抗凝血酶，其延长并非常规对应指标；APTT缩短见于血栓前状态"},{"q":"患者老年女性，因“牙龈出血、下肢皮肤瘀点1周”就诊。查血常规示血小板减少，凝血检查正常。请问该患者血小板计数水平最有可能是","o":["＜100×109/L","＜80×109/L","＜70×109/L","＜50×109/L","＜30×109/L"],"a":4,"e":"血小板低于30×10⁹/L时自发性出血明显，牙龈出血、皮肤瘀点提示血小板显著减少。血小板轻中度减少（＜100、＜80、＜70×10⁹/L）多无自发性出血，常仅在创伤后出血；本例凝血检查正常，排除凝血因子缺乏导致的出血"},{"q":"患者，男，23岁。乏力、食欲缺乏1周，尿黄3天。查体：肝大，肋下3cm，触痛（＋），脾未扪及。TB 110μmol/L，CB 50μmol/L，抗HAV-IgM（＋）。最不可能出现异常的是","o":["尿胆原","AST","凝血酶原时间","B超肝内胆管扩张","粪胆原"],"a":3,"e":"抗HAV-IgM阳性、转氨酶升高、黄疸提示急性甲型肝炎，属肝细胞性损伤，肝内胆管无机械性梗阻，故B超不应出现肝内胆管扩张。尿胆原因肝细胞处理胆红素能力下降而增多；AST反映肝细胞坏死；凝血酶原时间可因肝脏合成功能受损延长；粪胆原随胆汁排泄改变而变化"},{"q":"患者，男，出现右膝关节血肿。实验室检测结果：PT 14、6s，APTT 150s，FIB 2、9g/L；加正常血浆纠正后测定PT为14.0s，APTT为46、0s。FⅧ:C为110%，FⅨ:C为5%。该患者初步诊断为","o":["血友病A","血友病B","遗传性因子Ⅺ缺乏症","血管性血友病","因子Ⅷ的抑制物存在"],"a":1,"e":"APTT显著延长而PT、纤维蛋白原正常，正常血浆纠正后APTT恢复正常，提示内源性凝血因子缺乏；FⅧ:C正常而FⅨ:C仅5%，符合血友病B。血友病A为FⅧ缺乏，本例FⅧ正常；遗传性因子Ⅺ缺乏为FⅪ减低；血管性血友病FⅧ常伴vWF异常；抑制物存在时纠正试验不能纠正"},{"q":"患者，女，37岁。突发心悸10min。心电图示心率164次/min，P波与QRS波无固定关系，QRS波时限＞0.12s，可见室性融合波。最可能的诊断是","o":["心房扑动","房性心动过速","室性心动过速","交界区心动过速","窦性心动过速"],"a":2,"e":"心率164次/分、QRS宽大畸形＞0.12秒、P波与QRS无固定关系即房室分离，并见室性融合波，为室性心动过速的特征。心房扑动与房性心动过速QRS多正常；交界区心动过速QRS窄；窦性心动过速P波与QRS呈固定1∶1关系且QRS正常"},{"q":"患者，男，62岁，慢性咳嗽咳痰十余年，劳力性心悸气短1年。查体发现心界向左扩大，P2增强，可及剑突下搏动。则该患者心电图特征最可能的是","o":["Ⅱ、Ⅲ导联P波电压0、1mV","电轴左偏－30°，逆钟向转位","RaVL＋SV3＞2.8mV","V1导联呈rS型，r波电压1.0mV","aVR导联呈Rs型，RaVR电压0.5mV"],"a":4,"e":"慢性咳喘、P2增强、剑突下搏动提示慢性肺源性心脏病、右室肥大，心电图表现为aVR以R波为主呈Rs型、RaVR＞0.5mV。电轴左偏、逆钟向转位及RaVL+SV3增高为左室肥大表现；V1呈rS型为正常或左室占优图形；Ⅱ、Ⅲ导联P波0.1mV属正常，肺型P波应＞0.25mV"},{"q":"患者，男，35岁，发作性心悸5年，突发突止，发作时心电图表现如下，最可能的诊断为","o":["正常心电图","窦性心动过速","房性心动过速","室上性心动过速","室性心动过速"],"a":3,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。阵发性心悸突发突止是阵发性室上性心动过速的典型病史，其心电图QRS多窄、心律规整；室性心动过速QRS宽大畸形并可见房室分离、室性融合波；窦性心动过速心率渐快渐慢；房性心动过速可见异位P波。诊断需依赖发作时心电图\n\n官方题库中缺失图片"},{"q":"患者，男，62岁，身高170cm，体重110kg。头晕3个月。血脂检查示胆固醇5.3mmol/L，三酰甘油10.3mmol/L。要想明确头晕原因，最需要的检查是","o":["腹部B超","颅脑CT","颅脑MRA","脑电图","颈动脉彩超"],"a":4,"e":"肥胖、重度高甘油三酯血症为动脉粥样硬化高危因素，头晕需排查颈动脉狭窄致脑供血不足，颈动脉彩超可直接评估斑块与狭窄程度。颅脑CT对早期缺血不敏感；颅脑MRA为血管成像但非首选筛查；脑电图用于癫痫；腹部B超与头晕关系不大"},{"q":"一大叶肺炎患者，胸痛明显。胸片示近胸膜处，均匀一致片状影，在听诊时可能出现下列体征。但应除外","o":["支气管语音","胸语音","耳语音","硬币叩击征","胸膜摩擦音"],"a":3,"e":"大叶性肺炎实变累及胸膜时可闻支气管语音、胸语音、耳语音等语音共振增强，并可有胸膜摩擦音。硬币叩击征为气胸或大量胸腔积液体征，叩击时闻及金属音，肺实变不出现。支气管语音等均为实变时传导增强的表现，胸膜摩擦音为炎症累及胸膜所致"},{"q":"患者，女，24岁。尿频、尿急、尿痛，血尿伴发热1天，无呕吐，腰痛。尿常规：蛋白（＋），白细胞满视野，红细胞30～40个/HPF。最可能的诊断是","o":["急性膀胱炎","急性肾盂肾炎","急性肾小球肾炎","膀胱结核","肾结核"],"a":0,"e":"官方答案为【膀胱炎】，但依据教材，正确答案为【急性肾盂肾炎】。尿频尿急尿痛伴发热、腰痛及肾区叩击痛，尿白细胞满视野，属上尿路感染，教材明确指出伴有发热、腰痛、尿频、尿急、尿痛见于急性肾盂肾炎。急性膀胱炎仅有膀胱刺激征，无发热与腰痛；膀胱结核有午后低热盗汗、病程缓慢；急性肾小球肾炎以血尿蛋白尿水肿为主"},{"q":"患儿，女，5岁。呕吐3天，伴惊厥2次。2个月前确诊为肾病综合征，低盐饮食2个月，无不洁饮食史。查体：血压80/50mmHg，嗜睡，颜面部及双下肢水肿，颈软，双肺呼吸音粗，心脏无异常，腹软，肝脾未触及，病理征未引出。血清电解质：血钠130mmol/L，血钾3.5mmol/L，血氯95mmol/L，钙2、3mmol/L，HCO3- 20mmol/L。尿常规：蛋白（＋＋＋），红细胞（－）。该患儿最可能的诊断是","o":["肾病综合征伴病毒性脑炎","肾病综合征伴急性胃肠炎","肾病综合征伴低钙惊厥","肾病综合征伴低钠血症","肾病综合征伴低钾血症"],"a":3,"e":"低盐饮食、呕吐致钠丢失，血钠130mmol/L低于正常，低钠血症可引起嗜睡、惊厥。血钙2.3mmol/L正常，不支持低钙惊厥；血钾3.5mmol/L正常，排除低钾血症；无发热及脑膜刺激征，病毒性脑炎依据不足；无腹泻史，急性胃肠炎可排除"},{"q":"一患者反复干咳，且有低热、盗汗等症状，经纤维支气管镜检查证实为支气管内膜有一占位性病变。该患在听诊时可出现的体征为","o":["两肺布满干啰音","支气管语音","耳语音","局限性干啰音","局限性湿啰音"],"a":3,"e":"支气管内膜占位致局部支气管狭窄，气流通过产生局限性干啰音，教材明确指出局限性干啰音常见于支气管内膜结核或肿瘤。两肺布满干啰音见于广泛气道痉挛如哮喘；语音共振类体征为肺实变表现；局限性湿啰音提示局部渗出性病变如肺炎，与本例气道狭窄不符"},{"q":"患者，女，40岁。腹泻半年，粪便果酱色，有黏液脓血，粪便培养（－），直肠指检未扪及肿块。为明确诊断，首选的辅助检查是","o":["急诊胃镜检查","纤维结肠镜检查","X线胃肠钡餐造影","腹部超声波检查","腹部CT检查"],"a":1,"e":"慢性腹泻、果酱色黏液脓血便、培养阴性且直肠指检未及肿块，需行纤维结肠镜直接观察结肠黏膜并活检。急诊胃镜用于上消化道出血；X线胃肠钡餐对黏膜细节分辨率低；腹部超声与CT对肠道腔内病变诊断价值有限，均非首选"},{"q":"四肢肌力正常患者检查Romberg征时发现睁眼时稳，但闭眼后站立不稳，向两侧摇晃不稳。考虑存在以下哪一方面的问题","o":["深感觉障碍","小脑半球病变","小脑蚓部病变","锥体束病变","锥体外系病变"],"a":0,"e":"Romberg征睁眼稳、闭眼站立不稳并向两侧摇晃，为感觉性共济失调，因深感觉障碍时视觉代偿维持平衡，闭眼后失去代偿。小脑半球病变出现同侧肢体共济失调、指鼻试验异常；小脑蚓部病变表现为躯干性共济失调，睁闭眼均不稳；锥体束病变以肌力减弱、病理征阳性为主；锥体外系病变以肌张力改变与不自主运动为主"},{"q":"患者，女，46岁。反复出现劳力性心累气促20余年，近10年加重。就医曾经诊断“风湿性心脏病、二尖瓣狭窄”。1周前出现咳嗽，咳白色稀薄痰液，不能平卧。心脏听诊心率112次/min，律齐，心尖区可闻舒张期杂音。肺部听诊可闻湿性啰音。诊断首要考虑“风湿性心脏病、二尖瓣狭窄”合并","o":["急性支气管炎","慢性支气管炎","肺结核","肺水肿","肺脓肿"],"a":3,"e":"二尖瓣狭窄致左房压升高、肺静脉淤血，出现白色稀薄痰、不能平卧及双肺湿啰音，符合急性肺水肿。急性支气管炎以咳嗽咳痰为主、无端坐呼吸；慢性支气管炎为长期咳喘；肺结核有低热盗汗、咯血；肺脓肿咳大量脓臭痰，均与本例不符"},{"q":"患者，男，52岁，食管癌术后7天。今起嘱患者正常饮食后，胸部引流袋引乳糜状液体800ml。以下能鉴别乳糜性和假性乳糜性胸腔积液的项目为","o":["细胞总数","胆固醇含量","三酰甘油含量","淀粉酶含量","白蛋白含量"],"a":2,"e":"乳糜性胸腔积液中乳糜微粒致三酰甘油显著升高（多＞1.2mmol/L），假性乳糜液以胆固醇升高为主而三酰甘油不高，故测定三酰甘油可鉴别。细胞总数、白蛋白含量在两者重叠，无鉴别价值；淀粉酶升高提示胰源性积液；胆固醇虽在假性乳糜液升高，但单独鉴别意义不及三酰甘油"},{"q":"一长跑运动员，30岁。测血压为140/70mmHg，进而诊断为风湿性心脏病，主动脉瓣关闭不全。下列体征对其诊断最有意义的是","o":["双下肢结节性红斑","股动脉枪击音","Austin-Flint杂音","Graham-Steell杂音","胸骨左缘第3肋间舒张期叹气样杂音"],"a":4,"e":"主动脉瓣关闭不全的典型体征为胸骨左缘第3肋间（主动脉瓣第二听诊区）舒张期递减型叹气样杂音，最具诊断意义。股动脉枪击音为周围血管征，特异性较低；Austin-Flint杂音为严重反流所致心尖区舒张期隆隆样杂音，非直接体征；Graham-Steell杂音见于二尖瓣狭窄并肺动脉高压；结节性红斑非心脏体征"},{"q":"患者，男，65岁，既往有高血压、2型糖尿病史，因胸痛4小时来诊，行心电图检查如图，请问下一步最关键检查是","o":["急诊冠脉造影","冠脉CT重建","胸部增强CT","超声心动图","平板运动试验"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，胸痛4小时伴心电图动态ST段抬高提示急性心肌梗死，急诊冠脉造影可明确闭塞血管并同期介入治疗。冠脉CT重建为无创筛查、耗时较长；胸部增强CT用于主动脉夹层；超声心动图评估室壁运动但不能定位罪犯血管；平板运动试验禁用于急性冠脉综合征\n\n官方题库中缺失图片"},{"q":"患者，男，42岁，因发绀1小时入院。查体：T 36℃，P 105次/min，R 24次/min，BP 80/50mmHg，呼吸急促，不规则，伴呕吐及阵发性四肢抽搐，无二便失禁。据家人描述其独自进食大量的过夜变质蔬菜。患者出现发绀的原因最可能为","o":["血液中硫化血红蛋白增多","血液中高铁血红蛋白增多","淤血性周围性发绀","缺血性周围性发绀","血液中血红蛋白减少"],"a":1,"e":"变质蔬菜富含亚硝酸盐，吸收后使血红蛋白二价铁氧化为三价铁，形成高铁血红蛋白而失去携氧能力，出现肠源性青紫症，氧疗无效、亚甲蓝可纠正。硫化血红蛋白血症由含硫药物引起；淤血性周围性发绀见于右心衰竭，肢体末端冰凉；缺血性发绀见于休克；血红蛋白减少致贫血而非发绀"},{"q":"患者，女，26岁。半月前开始性情急躁，失眠，怕热，出汗和心慌，血清甲状腺素增高，TRAb阳性。该患者体格检查时，最典型的体征是","o":["眼球明显突出且双侧不对称","脉搏不齐","心前区可闻及Ⅲ级以上收缩期杂音","甲状腺弥漫性肿大","心脏明显扩大"],"a":3,"e":"甲状腺素升高、TRAb阳性提示Graves病，最典型体征为甲状腺弥漫性肿大，伴血管杂音与震颤。眼球突出在Graves病多为双侧对称，明显不对称并非典型；脉搏不齐、心前区杂音及心脏扩大为心血管表现，非本病最具特征性的体征"},{"q":"某老年男性，胸部体检示胸廓前后径明显增宽，肋间隙饱满，腹上角增大。此胸廓形态为","o":["漏斗胸","扁平胸","桶状胸","鸡胸","正常胸廓"],"a":2,"e":"胸廓前后径增宽、肋间隙饱满、腹上角增大呈圆桶状，符合桶状胸，见于慢性阻塞性肺疾病及老年人。扁平胸前后径不及左右径一半，见于瘦长体型；漏斗胸为胸骨下段凹陷；鸡胸为胸骨向前突出如鸡爪；正常胸廓前后径小于左右径，均与本例不符"},{"q":"患者，男，68岁。进行性呼吸困难2年，双下肺可闻及吸气末爆破音，可见杵状指。HRCT示双下肺网格改变，诊断为特发性肺纤维化。该患者出现呼吸困难的主要机制是","o":["肺泡通气不足","通气/血流比失调","肺内分流","小气道狭窄","弥散功能障碍"],"a":4,"e":"特发性肺纤维化致肺间质增厚、弥散膜面积减少，氧弥散受阻，出现进行性呼吸困难、吸气末爆破音及杵状指，DLCO下降。肺泡通气不足见于呼吸泵衰竭；通气/血流比失调见于肺栓塞；肺内分流见于先心病；小气道狭窄见于哮喘与慢阻肺，均非本病主要机制"},{"q":"一患者，20年前患乙型肝炎，3小时前突然呕吐鲜红色血液约1000ml，心悸头晕，血压下降。查体：可见蜘蛛痣，脾大、肋下2cm。最可能的诊断是","o":["急性胃黏膜病变","胃溃疡","胆管癌","食管-胃底静脉曲张破裂","Mallory-Weiss综合征"],"a":3,"e":"乙肝病史、蜘蛛痣、脾大提示肝硬化门静脉高压，突发大量呕血伴休克，最可能为食管-胃底静脉曲张破裂。急性胃黏膜病变常有应激或药物诱因、出血量较小；胃溃疡出血多为少量黑便；胆管癌出血少见且伴黄疸；Mallory-Weiss综合征先有剧烈呕吐后呕血"},{"q":"患者，女，51岁。近几个月来反复发生鼻出血及刷牙后牙龈出血，前往医院检查发现出血时间（BT）延长。以下均易导致BT延长，除了","o":["血小板功能正常，计数增多","血小板功能异常","某些凝血因子缺乏","血管壁缺陷","口服氯吡格雷"],"a":0,"e":"出血时间延长反映血管壁与血小板一期止血缺陷，血小板功能异常、血管壁缺陷、某些凝血因子缺乏及服用氯吡格雷抑制血小板均可致BT延长。血小板计数增多但功能正常时一期止血功能不受损，BT不延长，反而见于血小板增多症时BT正常或缩短，故为例外"},{"q":"患者，女，26岁。胸部隐痛15天，伴低热，胸闷，气促。查体：颈静脉怒张，心界向两侧明显扩大，坐位时呈三角形，仰卧位心底部浊音区增宽。此患者最可能的诊断是","o":["急性心肌炎","缩窄性心包炎","扩张型心肌病","缺血性心肌病","急性心包炎伴心包积液"],"a":4,"e":"颈静脉怒张、心界向两侧扩大且随体位改变，坐位呈三角形、卧位心底部浊音区增宽，为心包积液典型表现，结合低热提示急性心包炎伴积液。缩窄性心包炎心界不大、无体位改变；扩张型心肌病心界普大但不随体位变化；急性心肌炎无心包积液征；缺血性心肌病有冠心病史"},{"q":"患者，女，68岁。1年前于坐位早餐时无明显诱因突感心悸，随之意识丧失跌倒，数分钟后意识恢复，无大汗、肢体抽搐、口吐白沫和大小便失禁。1年来反复发作上述症状3次，发作与体位和运动无关。查体：BP 130/70mmHg，心率48次/min。心电图示二度Ⅱ型房室传导阻滞。该患者意识丧失最可能的原因是","o":["低血糖","迷走神经张力增高","癫痫发作","体位性低血压","心律失常"],"a":4,"e":"反复晕厥、心率48次/分、二度Ⅱ型房室传导阻滞，无抽搐及大小便失禁，提示严重缓慢心律失常致脑供血中断即阿-斯发作，属心源性晕厥。低血糖有出汗饥饿感；迷走神经张力增高多有诱因、心率可恢复；癫痫有抽搐与舌咬伤；体位性低血压与体位变动相关"},{"q":"患者，男，60岁，近半年来尿频伴进行性排尿困难，排尿费力，不伴明显尿痛。下列哪种疾病可能性较大","o":["膀胱结石","肾结石","膀胱结核","输尿管末端结石","前列腺增生症"],"a":4,"e":"老年男性尿频伴进行性排尿困难、尿线细、排尿费力而无明显尿痛，符合前列腺增生症。膀胱结石伴尿流突然中断与尿痛；肾结石以肾绞痛为主；膀胱结核有进行性膀胱刺激征与终末血尿；输尿管末端结石伴肾绞痛及镜下血尿，均无进行性排尿困难"},{"q":"患者，女，65岁，因冠心病平素服阿司匹林，近1周来持续柏油样便，头昏、心悸。查体：巩膜无黄染，心率100次/min，律齐，双肺呼吸音清，腹软，无压痛，肝脾未触及。最可能的诊断为","o":["胃癌","消化性溃疡","急性胃黏膜病变","食管静脉曲张破裂","慢性胃炎"],"a":2,"e":"服用阿司匹林后出现持续柏油样便、头晕心悸，无腹痛及黄疸，符合急性胃黏膜病变（急性糜烂出血性胃炎）。消化性溃疡多有节律性上腹痛；胃癌常有消瘦、贫血与上腹痛；食管静脉曲张破裂出血量大、多有肝病史；慢性胃炎出血量少、多表现为隐血阳性"},{"q":"患者，女，26岁。10天来全身皮肤出血点伴牙龈出血来就诊。血常规：PLT 35×109/L，临床诊断为慢性免疫性血小板减少症（ITP）。下列支持ITP诊断的实验室检查是","o":["凝血时间延长","血块收缩减低","抗核抗体阳性","骨髓巨核细胞增多，产板型增多","骨髓巨核细胞增多，原始、幼稚巨核细胞增多"],"a":1,"e":"ITP时血小板减少致血块收缩不良，血块收缩试验减低，是支持诊断的实验室依据。凝血时间主要反映内源性凝血因子，ITP正常；抗核抗体阳性提示系统性红斑狼疮；ITP骨髓巨核细胞增多伴成熟障碍，产板型减少而非增多，原始幼稚巨核细胞显著增多更倾向血液系统恶性病变"},{"q":"患者，男，50岁，有乙肝病史30年，饮酒史20年。近1个月来消瘦，并出现上腹部疼痛等症状。查体：巩膜黄染，上腹部触到质硬包块，表面可触及大小不等结节，有压痛。最可能的诊断是","o":["原发性肝癌","晚期肝硬化","慢性肝炎","转移性肝癌","转移性胃癌"],"a":0,"e":"乙肝、饮酒史，消瘦、上腹硬块表面高低不平、压痛明显，符合原发性肝癌。晚期肝硬化肝脏缩小、质硬、边缘锐利、表面小结节；慢性肝炎肝轻中度肿大、质稍韧；转移性肝癌多为多发结节且原发灶症状在前；转移性胃癌以消化道症状为主、肝转移较晚"},{"q":"患者，女，32岁，进行性膀胱刺激征，经抗生素治疗不见好转，伴右侧腰部胀痛及午后潮热。最可能的诊断是","o":["急性肾盂肾炎","急性膀胱炎","肾结核","急性肾盂肾炎并乳头坏死","急性肾盂肾炎并肾周脓肿"],"a":2,"e":"进行性膀胱刺激征经抗生素治疗无效，伴右侧腰痛与午后潮热，提示肾结核，尿液结核分枝杆菌感染致膀胱黏膜进行性损害。急性肾盂肾炎起病急、抗生素治疗有效；急性膀胱炎症状轻微、无发热潮热；肾盂肾炎并乳头坏死或肾周脓肿均有高热与明显腰痛，抗感染治疗可部分缓解"},{"q":"患者，男，20岁。胸痛7天，伴低热、咳嗽、气促。查体：心界明显扩大，未见心尖冲动，心音遥远，颈静脉怒张。该患者最可能的诊断是","o":["肺炎伴胸腔积液","慢性缩窄性心包炎伴右室功能不全","急性心包炎伴心包积液","急性病毒性心肌炎伴右室功能不全","急性心肌梗死伴右室功能不全"],"a":2,"e":"低热、胸痛、气促，心界扩大、心尖冲动消失、心音遥远、颈静脉怒张，为大量心包积液伴心脏压塞表现，符合急性心包炎伴积液。肺炎伴胸腔积液以呼吸系统症状为主、无心音遥远；缩窄性心包炎心界不大、无奇脉；病毒性心肌炎与心肌梗死均无体循环淤血与心音遥远"},{"q":"25岁男性，低热1个月，X线可见右肺尖继发性肺结核。该患右肺上界叩诊的宽度，可能为","o":["3cm","5cm","7cm","9cm","11cm"],"a":0,"e":"肺上界叩诊带正常宽约4～6cm，肺结核浸润纤维化使肺尖皱缩、Kronig峡变窄，故该患者宽度约3cm。5cm属正常宽度，不符合结核的缩窄改变；7cm以上增宽见于肺气肿等含气量增多；9cm与11cm明显增宽，均与上肺结核的纤维收缩相反"},{"q":"一患者入院查体发现存在明显皮肤定位觉、两点辨别觉、实体觉障碍。考虑患者损伤","o":["神经干","脊髓后索","脊髓前角","脊髓后角","皮质"],"a":4,"e":"皮肤定位觉、两点辨别觉与实体觉均属复合感觉（皮质感觉），为大脑皮质综合分析的结果，障碍定位于皮质。神经干病变表现为该神经分布区各种感觉障碍；脊髓后索病变致深感觉障碍、感觉性共济失调；脊髓前角损害为下运动神经元瘫痪；脊髓后角病变表现为分离性感觉障碍"},{"q":"中年男性，突发呕血约400ml。追问病史，4年来常有黑便，伴上腹隐痛，反酸。此次呕血后，腹痛有缓解。查体：急性病容，贫血貌，P 120次/min，BP 90/45mmHg，上腹压痛（＋），肠鸣音活跃。诊断首先考虑","o":["急性胃黏膜病变","肝硬化食管-胃底静脉曲张破裂出血","胃癌侵蚀血管","Dieulafoy病","消化性溃疡合并出血"],"a":4,"e":"慢性反复上腹痛伴反酸、黑便，此次呕血后腹痛缓解，为消化性溃疡出血的典型规律。急性胃黏膜病变起病急、无慢性节律性腹痛；食管静脉曲张破裂出血量大、有肝病史、疼痛不缓解；胃癌疼痛无规律伴消瘦贫血；Dieulafoy病出血量多但无慢性溃疡史"},{"q":"患者，男，54岁。晕厥10min。查体：昏迷状态，双侧瞳孔散大，对光反射迟钝。该患者最可能的诊断是","o":["颠茄类中毒","吗啡类中毒","毒蕈类中毒","有机磷农药中毒","巴比妥类中毒"],"a":0,"e":"双侧瞳孔散大、对光反射迟钝伴昏迷，符合颠茄类（阿托品样）中毒，其阻断M受体致瞳孔散大。吗啡类、巴比妥类、有机磷中毒均致瞳孔缩小；毒蕈中毒以毒蝇碱样作用致瞳孔缩小、多汗流涎；有机磷尚有蒜味与肌颤，均与散大不符"},{"q":"患者，女，36岁，有乙型病毒性肝炎病史。主诉食欲缺乏、乏力3周。血清学检查：抗-HAVIgG（＋），HBsAg（＋）和抗-HBcIgM（＋）。可诊断为","o":["急性甲型肝炎","急性乙型肝炎","乙型肝炎合并甲型肝炎","慢性乙型肝炎急性发作","急性甲型肝炎合并急性乙型肝炎"],"a":3,"e":"有乙肝病史，HBsAg阳性、抗-HBcIgM阳性提示乙型肝炎病毒活动复制，抗-HAVIgG阳性仅表示既往感染甲肝有免疫力，故为慢性乙型肝炎急性发作。急性甲型肝炎应为抗-HAVIgM阳性；急性乙型肝炎无既往乙肝史；乙型肝炎合并甲型肝炎需抗-HAVIgM阳性；单纯慢性乙肝无IgM抗体阳性"},{"q":"患者，男，21岁，昨夜会餐，5小时后开始出现恶心、呕吐胃内容物，伴腹痛、腹泻。查体：体温37℃，心肺听诊正常，腹软、无压痛。最可能的诊断是","o":["Meniere病","急性胃肠炎","急性胰腺炎","幽门梗阻","肠梗阻"],"a":1,"e":"会餐后急性起病，恶心呕吐、腹痛腹泻，无发热及腹膜刺激征，符合急性胃肠炎。Meniere病以眩晕、耳鸣、听力下降为主；急性胰腺炎为上腹剧痛向背部放射、血淀粉酶升高；幽门梗阻呕吐隔夜宿食、无腹泻；肠梗阻有停止排气排便与肠鸣音亢进"},{"q":"患者，男，42岁，晕厥2次，既往体健。查体：二尖瓣区3级吹风样杂音。心电图示RV5 4.2mV，胸前导联T波深倒。该患者最可能的诊断是","o":["风湿性心脏病","肥厚型心肌病","瓣膜性心脏病","冠状动脉粥样硬化性心脏病","高血压心脏病"],"a":1,"e":"晕厥、胸骨左缘收缩期杂音、RV5电压4.2mV及胸前导联T波深倒，提示左室肥厚伴复极异常，符合肥厚型心肌病（心尖肥厚型可致T波深倒）。风湿性心脏病与瓣膜性心脏病以瓣膜杂音为主；冠心病虽有ST-T改变但多有胸痛；高血压心脏病有长期高血压史，本例未提及"},{"q":"风湿性心脏病心力衰竭患者用洋地黄和利尿剂治疗，出现食欲缺乏，头痛，心电图为室性期前收缩二联律。应首先考虑","o":["洋地黄剂量不足","低钾","洋地黄中毒","风湿活动","心力衰竭加重"],"a":2,"e":"洋地黄治疗中出现食欲缺乏、头痛及室性期前收缩二联律，为洋地黄中毒的典型表现，胃肠道症状和各类心律失常是其主要反应。洋地黄剂量不足心衰症状不缓解、无心律失常；低钾可诱发心律失常但多有乏力腹胀；风湿活动有发热关节痛；心衰加重表现为呼吸困难水肿加重"},{"q":"患者，女，8岁。发热4天，打喷嚏、流涕、流泪、眼结膜充血、面部出米粒样丘疹1天而入院。口腔检查：扁桃体Ⅰ度肿大，口腔黏膜充血，颊黏膜处见帽针头大小白色斑点。考虑下列诊断最可能性的是","o":["风疹","鹅口疮","麻疹","药物中毒","化脓性扁桃体炎"],"a":2,"e":"发热、喷嚏流涕、结膜充血及面部皮疹，颊黏膜帽针头大小白色斑点即麻疹黏膜斑（Koplik斑），为麻疹早期特征。风疹发热低、皮疹消退快、无Koplik斑；鹅口疮为白色念珠菌斑、不易擦去、无发热皮疹；药物中毒有服药史；化脓性扁桃体炎以扁桃体脓性渗出为主"},{"q":"患者，男，26岁。咳嗽、高热3天，1周前有淋浴受凉史。自述咳痰为铁锈色，可能是哪种细菌感染","o":["肺炎链球菌","乙型溶血性链球菌","肺炎克雷伯菌","铜绿假单胞菌","金黄色葡萄球菌"],"a":0,"e":"受凉后高热、咳铁锈色痰为肺炎链球菌肺炎的典型表现，红细胞渗出后被巨噬细胞吞噬分解形成铁锈色痰。乙型溶血性链球菌致咽炎、猩红热；肺炎克雷伯菌咳砖红色胶冻样痰；铜绿假单胞菌痰呈黄绿色；金黄色葡萄球菌痰为脓性、可呈乳黄色"},{"q":"患者，男，65岁。心电图表现为：RV1＋SV5＝1、15mV，V1呈Rs型，且R/S＞1，平均电轴＋110°，应考虑为","o":["左房肥大","右房肥大","左室肥大","右室肥大","双房肥大"],"a":3,"e":"RV1+SV5=1.15mV＞1.05mV、V1呈Rs型且R/S＞1、电轴右偏+110°，符合右室肥大诊断标准。左房肥大表现为P波双峰、V1ptf增大；右房肥大表现为肺型P波；左室肥大以RV5+SV1＞4.0mV、电轴左偏为特点；双房肥大兼有两侧P波改变"},{"q":"患者，女，35岁，咳嗽、咳痰、低热、盗汗1个月，查体发现大量胸腔积液，痰涂片：抗酸杆菌（＋）。符合该患者胸腔积液特点的是","o":["比重低于1、018","黏蛋白定性阳性","蛋白定量＜25g/L","细胞计数＜100×106/L","LDH＜200IU"],"a":1,"e":"痰抗酸杆菌阳性、低热盗汗、大量胸腔积液，为结核性胸膜炎，积液属渗出液，黏蛋白定性（Rivalta试验）阳性，蛋白＞30g/L、LDH＞200U/L、细胞数常＞100×10⁶/L、比重＞1.018。比重低于1.018、蛋白＜25g/L、细胞＜100×10⁶/L及LDH＜200均符合漏出液"},{"q":"44岁女性，恶心、呕吐2个月就诊，个人史应记录","o":["是否已婚","是否怀孕","有无不良饮食习惯","有无消瘦","有无溃疡病史"],"a":2,"e":"个人史记录出生地、居住史、生活习惯与嗜好、职业接触及冶游史，不良饮食习惯属生活习惯与饮食规律，应写入个人史。是否已婚属婚姻史；是否怀孕属生育史；有无消瘦属现病史或一般状况；有无溃疡病史属既往史"},{"q":"患者，女，18岁，乏力、食欲缺乏2周。查体：巩膜轻度黄染，心肺及腹部未查及异常。为了鉴别其黄疸类型，应首选的检查项目是","o":["ALP、AST、GGT","STB、TAG","STB、结合胆红素、尿胆原、尿胆红素","ALT、TAG、血清蛋白电泳","AFP、CEA、CA199"],"a":2,"e":"鉴别溶血性、肝细胞性与梗阻性黄疸，首选总胆红素、结合胆红素及尿胆原、尿胆红素联合检测，依据CB/STB比值与尿胆红素有无判断黄疸类型。ALP、AST、GGT对梗阻性黄疸有提示但不能单独分型；TAG与蛋白电泳非黄疸鉴别首选；AFP、CEA、CA199用于肿瘤筛查"},{"q":"患者，女，42岁，因系统性红斑狼疮合并肾衰竭而入院治疗，采用激素冲击疗法，连续应用糖皮质激素1周。该患者肾衰症状有所缓解，但却出现发热、咳嗽、气喘等症状，听诊肺部有啰音。患者咳痰为砖红色胶冻样，可能是哪种细菌感染","o":["肺炎链球菌","乙型溶血性链球菌","肺炎克雷伯菌","铜绿假单胞菌","金黄色葡萄球菌"],"a":2,"e":"砖红色胶冻样痰是肺炎克雷伯菌肺炎的典型特征，该菌有厚荚膜，痰黏稠带血呈砖红色。肺炎链球菌咳铁锈色痰；乙型溶血性链球菌所致肺炎少见、痰稀薄；铜绿假单胞菌痰呈黄绿色；金黄色葡萄球菌痰为黄色脓性、易形成肺脓肿"},{"q":"一年轻患者，突发胸痛呼吸困难，胸片示气管纵隔左偏，右肺野中外带内无肺纹理。在听诊时，下列对诊断有帮助的是","o":["耳语音","胸语音","羊鸣音","支气管语音","硬币叩击征"],"a":4,"e":"突发胸痛、呼吸困难，胸片示气管纵隔向左移位、右肺中外带无肺纹理，提示右侧气胸，硬币叩击征可在气胸侧闻及金属样叩击音，有助于诊断。耳语音、胸语音、支气管语音及羊鸣音均为语音共振增强表现，见于肺实变或压迫性肺不张，气胸时呼吸音减弱、语音共振减弱"},{"q":"患者进行临床神经系统检查时发现：去枕平卧，屈髋和屈膝后小腿抬高仅100°即出现伸膝受阻及疼痛。这提示该患者存在","o":["Kernig征阳性","Babinski征阳性","Brudzinski阳性","颈强直","Oppenheim征阳性"],"a":0,"e":"仰卧屈髋屈膝后抬高小腿、伸膝受限伴疼痛为Kernig征阳性，属脑膜刺激征，见于脑膜炎、蛛网膜下腔出血。Babinski征与Oppenheim征为病理反射，提示锥体束损害；Brudzinski征为被动屈颈时引发髋膝屈曲；颈强直为屈颈阻力增高，均与本检查操作不同"},{"q":"患儿，女，7岁，突然出现高热、头痛、喷射状呕吐2天。查体示皮肤出血点，颈项强直。脑脊液检查外观浑浊，脑脊液涂片镜检革兰阴性双球菌。根据以上结果可初步诊断","o":["淋病奈瑟菌性脑膜炎","葡萄球菌性脑膜炎","肠球菌性脑膜炎","脑膜炎奈瑟菌性脑膜炎","肺炎链球菌性脑膜炎"],"a":3,"e":"高热、喷射性呕吐、皮肤瘀点及颈项强直提示化脓性脑膜炎，脑脊液浑浊、涂片见革兰阴性双球菌，符合脑膜炎奈瑟菌感染。淋病奈瑟菌主要致泌尿生殖道感染；葡萄球菌为革兰阳性球菌；肠球菌为革兰阳性球菌；肺炎链球菌为革兰阳性双球菌，染色不符"},{"q":"患者，男，38岁，6年来反复上腹疼，夜间加重伴反酸，2周来呕吐隔日酸臭食物，腹胀加重。下列哪项体征最有诊断意义","o":["肠鸣音亢进","有反跳痛","可见胃蠕动波","Murphy氏征阳性","季肋点有压痛"],"a":2,"e":"慢性上腹痛、夜间加重、反酸，近期呕吐隔夜酸臭食物、腹胀，提示幽门梗阻，可见胃蠕动波为其特征性体征，自左肋缘向右推进。肠鸣音亢进见于肠梗阻；反跳痛提示腹膜炎；Murphy征阳性见于胆囊炎；季肋点压痛提示肾盂肾炎，均与幽门梗阻无关"},{"q":"患者，女，30岁，发热1周，左腹股沟区可扪及5cm×4cm×3cm大小肿物，有压痛，有波动感。为明确诊断应采用的检查是","o":["切开","诊断性穿刺","腹部B超","CT检查","钡剂灌肠"],"a":1,"e":"腹股沟区肿物伴压痛、波动感，考虑脓肿或囊性包块，诊断性穿刺可抽出脓液明确性质并做病原学检查。切开属治疗且盲目切开有风险；腹部B超对腹股沟浅表肿物价值有限；CT非首选；钡剂灌肠用于肠道病变，均不能明确肿物性质"},{"q":"有一溃疡病史男性患者，因1小时前腹痛加重住院。查体：腹部柔韧，全腹部压痛，立位腹平片见膈下游离气体。患者最可能的诊断为","o":["消化道溃疡穿孔","消化道肿瘤","慢性胃炎","急性胃炎","急性胆囊炎"],"a":0,"e":"溃疡病史、突发腹痛加重、板状腹、全腹压痛，立位腹平片见膈下游离气体，为消化道溃疡穿孔的确诊依据。消化道肿瘤多慢性经过；慢性胃炎与急性胃炎无膈下游离气体；急性胆囊炎疼痛位于右上腹、Murphy征阳性，X线无游离气体"},{"q":"患者，男，73岁。晨起时突发晕厥1天，意识约2～3min后恢复，伴一过性左侧上肢无力，活动不灵，发作时无抽搐及大小便失禁，发作后无后遗症状。患者有长期吸烟史，有动脉粥样硬化病史5年。查体：BP 128/75mmHg，心率58次/分，律齐；生理反射正常引出，病理反射均为阴性。该患者其最可能的病因是","o":["阿-斯综合征","短暂性脑缺血发作","急性脑梗死","体位性低血压","急性脑出血"],"a":1,"e":"突发短暂意识丧失、一过性左侧肢体无力、数分钟恢复且无后遗症，有动脉粥样硬化与吸烟史，符合短暂性脑缺血发作。阿-斯综合征为心源性晕厥、无局灶神经体征；急性脑梗死与脑出血症状持续不缓解、多遗留神经缺损；体位性低血压与体位改变相关、无肢体无力"},{"q":"患者，男，38岁。阵发性全腹痛5天，疼痛剧烈时面色苍白、大汗淋漓，缓解时无任何不适，肌内注射阿托品不能使腹痛缓解，但静脉注射葡萄糖酸钙有明显效果。近期常用金属酒具热酒喝。外周血点彩红细胞15%，尿卟啉（±）。最可能的诊断是","o":["卟啉病","急性肠梗阻","铅中毒","神经官能症","急性胰腺炎"],"a":2,"e":"阵发性脐周绞痛、阿托品无效而钙剂有效，金属酒具热酒史，外周血点彩红细胞15%，尿卟啉阳性，符合铅中毒，点彩红细胞为铅中毒筛查指标。卟啉病虽有腹痛与尿卟啉阳性但无点彩红细胞及铅接触史；急性肠梗阻有停止排气排便；神经官能症无实验室异常；急性胰腺炎血淀粉酶升高、疼痛持续"},{"q":"患者，女，18岁。1个月余前患者无明显诱因咽痛、发热，测得最高体温为39、8℃，伴食欲下降，未予重视；3天后出现颜面部对称性红斑，伴皮温升高，偶有瘙痒，体温正常。查体见鼻梁部皮肤出现红色斑块，病损处高起皮面并向两侧面颊部扩展。发现此鼻部体征应考虑诊断","o":["系统性红斑狼疮","二尖瓣面容","肝脏疾病","酒渣鼻","黑热病"],"a":0,"e":"鼻梁部红色斑块高起皮面并向两侧面颊扩展，伴发热及面部对称红斑，为系统性红斑狼疮的蝶形红斑。二尖瓣面容为双颊紫红、口唇发绀；肝脏疾病可见肝掌蜘蛛痣；酒渣鼻皮损在鼻尖鼻翼伴毛细血管扩张；黑热病有长期发热、脾大与色素沉着"},{"q":"患者，女，35岁。因鼻腔干燥、嗅觉减退2个月余就诊。查体：鼻黏膜萎缩，鼻甲缩小，鼻腔宽大。考虑诊断为","o":["急性鼻炎","慢性萎缩性鼻炎","化脓性鼻窦炎","过敏性鼻炎","鼻肿瘤"],"a":1,"e":"鼻黏膜萎缩、分泌物减少、鼻甲缩小、鼻腔宽大伴嗅觉减退，符合慢性萎缩性鼻炎。急性鼻炎为黏膜充血肿胀、鼻塞流涕；化脓性鼻窦炎有脓涕与头痛；过敏性鼻炎有清水样涕、喷嚏、黏膜苍白水肿；鼻肿瘤为局限性占位、非弥漫性萎缩"},{"q":"患者，女，38岁，右拇指疼痛2个月。查体：右手拇指活动时出现弹响伴疼痛，局部压痛。该患者最可能的诊断是","o":["尺神经损伤","腱鞘囊肿","桡神经损伤","狭窄性腱鞘炎","正中神经损伤"],"a":3,"e":"拇指活动时出现弹响伴疼痛、局部压痛，为狭窄性腱鞘炎（扳机指）的典型表现，因屈肌腱在A1滑车处卡压所致。尺神经损伤表现为爪形手、手部感觉障碍；桡神经损伤为垂腕；正中神经损伤为猿手；腱鞘囊肿为无痛性囊性肿物、无弹响"},{"q":"患者，男，70岁。咳嗽、咳痰20年。查体：双肺可闻及小水泡音，肝肋下3cm，质软，无触痛。考虑肝大是由于哪种疾病所致","o":["肝淤血","肺癌","肝硬化","肝癌","肺气肿"],"a":0,"e":"长期咳喘、双肺小水泡音提示慢性肺源性心脏病、右心衰竭，肝大质软无触痛、表面光滑、边缘圆钝，符合肝淤血，肝颈静脉回流征阳性为特征。肝硬化晚期肝缩小、质硬；肝癌质硬如石、表面结节；肺癌与肺气肿不直接引起肝大；肝淤血与慢性右心衰相关"},{"q":"患者，女，35岁，尿频、尿急、尿痛伴腰痛、发热、寒战1天，右侧肾区有压痛、叩击痛。其发热原因最可能是","o":["膀胱炎","慢性肾盂肾炎","急性肾盂肾炎","急性肾小球肾炎","慢性肾小球肾炎"],"a":2,"e":"尿频尿急尿痛伴发热寒战、腰痛及右肾区叩击痛，为急性肾盂肾炎的典型表现，属上尿路感染，体温骤升伴寒战。膀胱炎无发热与腰痛；慢性肾盂肾炎病程迁延、反复发作；急、慢性肾小球肾炎以血尿蛋白尿水肿高血压为主，无膀胱刺激征与肾区叩痛"},{"q":"患者，男，45岁。消瘦，腹胀，尿少1个月。肝炎病史15年。查体：慢性病容，可见肝掌及前胸蜘蛛痣，腹软，肝不大，脾肋下2cm，移动性浊音阳性。实验室检查：GGT 150U/L，A/G比例倒置。肝炎标志物阳性。最可能的诊断是","o":["肝炎后肝硬化","慢性肝炎","酒精性肝硬化","急性肝炎","肝癌"],"a":0,"e":"肝炎史15年，肝掌、蜘蛛痣、脾大、移动性浊音阳性、A/G倒置且肝炎标志物阳性，符合肝炎后肝硬化失代偿。慢性肝炎无腹水与脾大；酒精性肝硬化需长期大量饮酒史、本例未强调；急性肝炎病程短；肝癌多有肝大质硬结节、AFP显著升高"},{"q":"4岁女童，吃花生米时突然出现惊慌、气促，抱送急诊发现患儿吸气极度困难，出现“三凹征”。最可能诊断为","o":["气管异物","支气管哮喘发作","小儿肺炎","胸腔积液","胸膜炎"],"a":0,"e":"儿童进食花生时突发惊慌、气促、吸气极度困难伴三凹征，提示上气道机械性阻塞，最可能为气管异物，吸气性呼吸困难为其特点。支气管哮喘为呼气性呼吸困难伴哮鸣音；小儿肺炎有发热、咳嗽、湿啰音；胸腔积液与胸膜炎无三凹征、起病相对缓慢"},{"q":"患者，男，55岁。高血压3年，予氨氯地平＋美托洛尔＋哌唑嗪控制不佳，入院心电图如下所示，进一步诊治不合理的是","o":["联合利尿剂控制血压","筛查电解质","筛查肾上腺CT","完善卡托普利试验","筛查肾动脉超声"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。就知识点而言，高血压联合三种药物控制不佳需排查继发性高血压，应筛查电解质、肾动脉超声、肾上腺CT及卡托普利试验以明确原发性醛固酮增多症、肾动脉狭窄等病因。利尿剂可通过减少血容量辅助降压，但病因未明时单纯加量不合理\n\n官方题库中缺失图片"},{"q":"患者，男，20岁。1周前着凉后轻咳，低热、右胸刺痛，近日来活动后气短。查体：右下胸部叩诊呈浊音，浊音区上方可闻及支气管肺泡呼吸音，下方呼吸音显著减弱。最可能的诊断是","o":["气胸","肺脓肿","中等量胸腔积液","少量胸腔积液","胸膜增厚"],"a":2,"e":"右下胸叩浊、浊音区上方闻支气管肺泡呼吸音、下方呼吸音显著减弱，为中等量胸腔积液的典型体征，上方为压迫性肺不张致支气管音传导增强。气胸叩诊鼓音；肺脓肿有高热脓痰、空洞液平；少量积液仅肋膈角变钝；胸膜增厚无浊音区上方支气管肺泡呼吸音"},{"q":"患者，男，75岁，晕厥2次，既往有心肌梗死病史。查体：二尖瓣区3级吹风样杂音。心电图示心率130次/min，QRS波130ms。该患者最不可能的诊断是","o":["室性心动过速","心房颤动伴右束支传导阻滞","房性心动过速伴差异性传导","心房颤动伴预激综合征","房室结折返性心动过速伴预激综合征"],"a":4,"e":"宽QRS心动过速可见于室性心动过速、房颤伴束支阻滞或预激、房速伴差异性传导。房室结折返性心动过速的折返环位于房室结双径路，QRS通常正常，预激综合征的旁路参与的是房室折返性心动过速而非房室结折返，二者机制互斥，故该组合最不可能"},{"q":"患者，女，30岁。妊娠3个月，面色发黄、食欲缺乏1个月。查体：轻度贫血貌，巩膜轻度黄染。心肺及肝脾无异常。实验室检查：ALT 270U/L，AST 380U/L。患者不可能出现的实验室检查结果是","o":["结合胆红素中度增高","非结合胆红素轻度增高","总胆红素明显增高","尿胆原多为中度增高","尿胆红素阳性"],"a":1,"e":"ALT、AST显著升高伴黄疸提示肝细胞性黄疸，此时结合胆红素中度增高、总胆红素升高、尿胆红素阳性及尿胆原增多均符合肝细胞损伤与胆汁反流的改变。非结合胆红素明显增高以溶血性黄疸为特征，系大量红细胞破坏所致；本例无溶血证据，以结合胆红素升高为主，非结合胆红素轻度增高并非其典型表现"},{"q":"患者，女，20岁。持续头痛1个月。近来工作紧张，生活不规律，失眠，食欲良好。查体：心肺及腹部无异常，四肢神经反射正常。该患者头痛的原因最可能是","o":["病毒性脑炎","紧张性头痛","高血压","脑血管疾病","血管性头痛"],"a":1,"e":"长期工作紧张、失眠，头痛呈重压感、紧箍感，无神经系统阳性体征，符合紧张性头痛。病毒性脑炎有发热、意识改变；高血压头痛伴血压升高；脑血管疾病多有局灶神经体征；血管性头痛即偏头痛，多为一侧搏动性痛、伴恶心畏光，与本例不符"},{"q":"患者，女，54岁，主诉心前区疼痛，呼吸困难2周。查体：BP 100/80mmHg，P100次/min，心音低钝、遥远。吸气时收缩压降低15mmHg。最可能的诊断","o":["急性心肌梗死","肺气肿伴右心衰竭","大量心包积液","肺栓塞","心肌炎"],"a":2,"e":"心音低钝遥远、脉压小、吸气时收缩压下降15mmHg（奇脉），符合大量心包积液致心脏压塞。急性心肌梗死有胸痛与ST-T动态演变；肺气肿伴右心衰竭有长期咳喘、肺过度充气；肺栓塞有胸痛咯血、D-二聚体升高；心肌炎心率快、心音低但无奇脉与心音遥远"},{"q":"一患者步态不稳入院。查体发现患者肌力正常，饮水无呛咳，行走时向右侧倾斜，闭目难立征：睁闭眼都向右侧倒。考虑患者损伤以下哪个部位","o":["右侧大脑皮层","右侧小脑","延髓右侧","右侧基底基底区","脑桥右侧"],"a":1,"e":"Romberg征睁眼、闭眼均向右侧倾倒，提示小脑性共济失调，小脑半球病变导致同侧肢体共济运动障碍，故定位于右侧小脑。感觉性共济失调仅闭眼时不稳；大脑皮层病变以偏瘫、失语等为主；脑桥与延髓病变多伴交叉性瘫痪与脑神经体征；基底节病变以肌张力障碍与震颤为主"},{"q":"患者，女，36岁。劳力性呼吸困难半个月，既往关节肿痛史。超声提示二尖瓣重度粘连，未见钙化，开放受限。查体：血压110/75mmHg，脉搏85次/min，心率145次/min，心律不齐，心音强弱不等。患者还可有其他视诊体征，如","o":["二尖瓣面容","心前区明显隆起","负性心尖冲动常见","可见胸骨右缘第2肋间异位搏动","毛细血管搏动征"],"a":0,"e":"二尖瓣重度粘连、开放受限，心率145次/分、心律不齐、心音强弱不等提示心房颤动，基础病为风湿性二尖瓣狭窄，其视诊特征为二尖瓣面容，面色晦暗、双颊紫红、口唇轻度发绀。心前区隆起多见于儿童期起病的先心病；负性心尖冲动见于粘连性心包炎；胸骨右缘第2肋间搏动为主动脉弓病变；毛细血管搏动征为主动脉瓣关闭不全的周围血管征"},{"q":"患儿，女，13岁。3个月前其家长无意中发现颈前增粗，患儿诉无任何不适，发病以来饮食正常。既往体健，无肿瘤家族病史。查体：T36.5℃，P82次/min，R22次/min，BP 120/70mmHg，甲状腺呈对称性Ⅱ度肿大，表面光滑，质软，无压痛。该患儿最可能的诊断是","o":["甲状腺功能亢进症","单纯性甲状腺肿","甲状腺癌","慢性淋巴性甲状腺炎","亚临床甲状腺炎"],"a":1,"e":"甲状腺对称性Ⅱ度肿大、表面光滑、质软、无压痛，无甲亢症状及体征，符合单纯性甲状腺肿。甲状腺功能亢进症伴怕热、心悸、突眼及血管杂音；甲状腺癌质硬、结节状、固定；慢性淋巴性甲状腺炎质韧、可伴甲减；亚临床甲状腺炎无症状、仅实验室异常"},{"q":"患儿，4岁，因肺炎就诊，体检时发现心前区隆起，听诊胸骨左缘第3～4肋间闻及响亮而粗糙的4/6级收缩期杂音伴收缩期震颤。为明确诊断，进一步检查应首选","o":["心电图","心脏正侧位片","心脏彩色多普勒","心内膜心肌活检","心脏核素扫描"],"a":2,"e":"胸骨左缘第3、4肋间响亮粗糙的收缩期杂音伴震颤，为室间隔缺损的典型表现，心脏彩色多普勒可直接显示缺损部位与分流方向，为首选确诊检查。心电图仅间接提示心室肥厚；心脏X线示心影改变；心内膜心肌活检用于心肌病变；核素扫描分辨率低、非首选"},{"q":"患者，男，26岁。被卡车撞倒后昏迷，外耳道溢液，起初为血色，之后为无色清水样。考虑损伤部位为","o":["外耳道损伤","中耳损伤","前庭损伤","颅内出血","颅底骨折"],"a":4,"e":"外伤后外耳道先流血性液后流无色清水样液，为脑脊液耳漏，提示颅底骨折累及颞骨岩部。外耳道损伤仅为局部出血、无清水样液；中耳损伤多见鼓膜穿孔、无持续清亮溢液；前庭损伤以眩晕为主；颅内出血无外耳道溢液，均与本例不符"},{"q":"患者，男，53岁。腰痛、肋骨痛2个月。经影像学检查发现脊柱、骨盆等部位多发骨质疏松。该患者血清电解质水平最可能出现","o":["血钾4、0mmol/L","血钠130mmol/L","血氯115mmol/L","血钙3.17mmol/L","血磷0.9mmol/L"],"a":3,"e":"多发骨质疏松伴骨痛，提示甲状旁腺功能亢进等致骨吸收增加，血钙升高至3.17mmol/L，为最可能出现的电解质异常。血钾4.0mmol/L正常；血钠130mmol/L为低钠、无对应表现；血氯115mmol/L轻度升高非特征；血磷0.9mmol/L大致正常，甲旁亢虽可低磷但本值未明显降低"},{"q":"患儿，男，7岁。学校体检发现心脏杂音1个月，无自觉症状。查体：心尖区闻及2级柔和收缩早期吹风样杂音，不传导。最可能的诊断是","o":["二尖瓣关闭不全","生理性杂音","室间隔缺损","二尖瓣狭窄","主动脉瓣关闭不全"],"a":1,"e":"儿童心尖区2/6级柔和收缩早期吹风样杂音、不传导、无震颤，心脏无增大，符合生理性杂音。二尖瓣关闭不全杂音粗糙、3/6级以上、向左腋下传导；室间隔缺损为胸骨左缘第3、4肋间响亮粗糙杂音伴震颤；二尖瓣狭窄为舒张期隆隆样杂音；主动脉瓣关闭不全为舒张期叹气样杂音"},{"q":"患者，男，36岁，因头晕胸痛半月来诊。血压160/35mmHg，胸片提示靴型心。下列体征不可能出现的是","o":["毛细血管搏动征","水冲脉","胸骨右缘2肋间的收缩期震颤","胸骨左缘3/4肋间的舒张早期递减性杂音","枪击音"],"a":2,"e":"血压160/35mmHg脉压增大、靴型心提示主动脉瓣关闭不全，可见毛细血管搏动征、水冲脉、枪击音等周围血管征及胸骨左缘第3、4肋间舒张期递减性杂音。胸骨右缘第2肋间收缩期震颤为主动脉瓣狭窄的体征，与关闭不全矛盾，故不可能出现"},{"q":"某患者十二指肠球部溃疡病史8年，突发剧烈上腹痛，迅速波及全腹。查体：板状腹，全腹压痛，反跳痛，肌紧张，高度怀疑十二指肠球部溃疡合并穿孔。此时最有诊断价值的检查为","o":["急性胃镜","饮水超声","X线钡餐","立位腹平片","吞线试验"],"a":3,"e":"十二指肠溃疡突发穿孔，板状腹、全腹压痛反跳痛肌紧张，立位腹平片见膈下游离气体为确诊依据，敏感性高。急性胃镜在穿孔时禁用；饮水超声敏感性低；X线钡餐在急性穿孔禁用、且造影剂外漏风险大；吞线试验用于消化道出血定位，均不适用"},{"q":"患者，男，35岁。低热、乏力、盗汗，胸腔积液细胞分类计数时，淋巴细胞数达到65%。最可能的诊断是","o":["细菌性肺炎","结核病","肺梗死","气胸","创伤"],"a":1,"e":"低热、乏力、盗汗为结核中毒症状，胸腔积液淋巴细胞占65%以淋巴细胞为主，符合结核性胸膜炎。细菌性肺炎积液以中性粒细胞为主、伴高热；肺梗死积液多为血性、起病急；气胸与创伤无淋巴细胞为主渗出，且无发热盗汗等结核表现"},{"q":"患者，女，55岁。高血压20年，不规则服药。某日晨突发头痛，意识不清，30min后送到医院。查体：昏迷，血压190/120mmHg，双眼向右侧凝视，左足外旋位。该患者最可能的病变部位是","o":["右侧脑干","右侧半球表面","右侧半球深部","左侧半球表面","左侧半球深部"],"a":2,"e":"长期高血压突发昏迷、双眼向右侧凝视、左足外旋，提示右侧半球深部（基底节区）出血，出现左侧偏瘫与凝视麻痹，双眼向病灶侧凝视。脑干病变多为交叉性瘫痪与意识障碍早期出现；半球表面病变多为皮质功能缺损、较少深昏迷；左侧半球病变应表现为右侧偏瘫、双眼向左凝视，方向相反"},{"q":"患者，女，20岁，因进行性心累气紧3个月来诊。查体发现BP 90/70mmHg，心界双侧扩大，随体位改变，心率120次/min，律齐，心音低弱遥远，无病理性杂音。本患者与心肌炎鉴别点主要为","o":["肝大","双侧心界扩大","心动过速，心音低弱","心界随体位改变而变化","移动性浊音"],"a":3,"e":"心界双侧扩大并随体位改变、心音低弱遥远、无病理性杂音，符合大量心包积液；与心肌炎的鉴别要点是心界随体位改变而变化，心肌炎心界扩大但固定、不随体位变动。肝大、双侧心界扩大、心动过速心音低弱及移动性浊音在两者均可出现，非鉴别关键"},{"q":"患者，女，24岁，因脚踝受伤来到急诊，焦虑面容。床旁血气：pH 7.55，HCO3－ 23mEq/L，PaCO2 27mmHg，PaO2 105mmHg，SO2 100%。该患者可能发生了","o":["呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","呼吸性酸中毒与低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"pH7.55＞7.45、PaCO2 27mmHg低于正常、HCO3-正常，为急性呼吸性碱中毒失代偿，焦虑致过度通气使CO2排出过多，肾脏尚未来得及代偿。代谢性酸中毒与代谢性碱中毒以HCO3-原发改变为主；呼吸性酸中毒PaCO2应升高；PaO2 105mmHg排除低氧血症，且为动脉血而非静脉血"},{"q":"医生帮一垂体瘤患者检查视野，发现存在双眼颞侧视野缺损。推测损伤是以下哪一部位","o":["视神经","视网膜","视交叉","视束","枕叶"],"a":2,"e":"垂体瘤向上压迫视交叉中部，损伤交叉的鼻侧视网膜纤维，导致双眼颞侧偏盲。视神经病变表现为单眼视力下降或全盲；视束病变致双眼同向偏盲；视网膜病变多为单眼不规则缺损；枕叶病变致同向偏盲伴黄斑回避，均非双颞侧偏盲"},{"q":"患者，女，25岁。近日反复出现皮肤出血点，以双下肢为著。日前曾有发热咽痛，现已痊愈。以下哪项不参与该患者止血过程","o":["血管壁","血小板","凝血因子","炎症因子","纤溶因子"],"a":3,"e":"机体止血依赖血管壁收缩、血小板黏附聚集、凝血因子级联激活形成血栓及纤溶系统调节，炎症因子不参与止血过程。血管壁损伤启动止血；血小板形成初步血栓；凝血因子完成二期止血；纤溶因子溶解血栓以保持血管通畅，均为止血机制的组成部分"},{"q":"患者，男，28岁，以“大量心包积液”收入院，入院后床旁心电图标准设置下波形振幅过小，无法清晰显示，按以下哪项心电图设置参数进行更改会有所帮助","o":["20mm/s、5mm/mV","25mm/s、10mm/mV","25mm/s、20mm/mV","25mm/s、5mm/mV","50mm/s、10mm/mV"],"a":2,"e":"标准心电图走纸速度为25mm/s、定标电压10mm/mV。心包积液致波形振幅过小时应提高增益至20mm/mV，走纸速度不变，故25mm/s、20mm/mV合适。20mm/s会压缩时间轴而不增高波形，25mm/s、5mm/mV反而使振幅更低，50mm/s仅用于心率过快时展开波形"},{"q":"患者，男，26岁，发热、咳嗽、咳铁锈色痰。下列确定早期肺实变较敏感的方法是","o":["叩诊","触觉语颤","耳语音","管状呼吸音","管状呼吸音伴语颤增强"],"a":2,"e":"耳语音检查时嘱病人耳语发音，肺实变时语音传导增强，可清楚听到音调较高的耳语音，是发现早期肺实变的敏感方法。触觉语颤与听觉语颤虽也增强，但出现较晚且受胸壁影响；管状呼吸音为实变期支气管传导增强的体征；叩诊浊音需实变范围较大才明显"},{"q":"患者，男，64岁。因头晕黑蒙1年来诊。查体：心率42次/min，心律整齐，心音强弱不等，可及大炮音。该患者考虑","o":["二尖瓣狭窄","三度房室传导阻滞","高血压","主动脉瓣狭窄","频发室性期前收缩"],"a":1,"e":"心率42次/min、心律规整并闻及大炮音，提示心房与心室各自独立收缩、房室传导完全中断，符合三度房室传导阻滞伴交界性或室性逸搏心律。二尖瓣狭窄可有心尖舒张期杂音但无大炮音；频发室早心律不齐；高血压和主动脉瓣狭窄均不产生大炮音"},{"q":"患者，男，37岁。发热1周，伴乏力、腹胀、腹泻。查体示热病容，脾肋下3cm。血常规检查白细胞偏低，发病后曾服用退热药及磺胺药，但发热未退，临床怀疑为伤寒。为进一步确诊，首选应做的检查是","o":["尿培养","粪便培养","骨髓培养或血培养","抗O试验","肥达反应"],"a":2,"e":"伤寒确诊依赖病原分离，骨髓培养阳性率高且受抗菌药物影响较小，血培养在病程早期阳性率亦高，故首选骨髓培养或血培养。肥达反应为血清学回顾性诊断，不能早期确诊；尿、粪便培养阳性率低；抗O试验用于风湿热，与伤寒无关"},{"q":"患者，女，38岁。咳嗽、低热3个月，咯血1天就诊。怀疑肺结核，并对其进行病原学诊断。其中痰标本涂片后应选用的方法是","o":["革兰氏染色","墨汁染色","鞭毛染色","奈瑟染色","抗酸染色"],"a":4,"e":"结核分枝杆菌细胞壁含大量脂质，抗酸染色后呈红色杆菌，是痰标本病原学诊断的首选方法。革兰氏染色用于一般细菌，分枝杆菌不易着色；墨汁染色用于隐球菌等有荚膜真菌；鞭毛染色观察细菌鞭毛，奈瑟染色多用于白喉杆菌，均不用于结核"},{"q":"患者，女，55岁。高血压20年，不规则服药。某日晨突发头痛，意识不清，30min后送到医院。查体：昏迷，血压190/120mmHg，双眼向右侧凝视，左足外旋位。该患者最可能的诊断是","o":["晕厥","脑出血","脑血栓形成","蛛网膜下脑出血","心肌梗死"],"a":1,"e":"高血压患者活动中突发剧烈头痛、昏迷并出现凝视与偏瘫，符合脑出血，系血压骤升致脑内小动脉破裂。脑血栓形成多在安静时起病、进展较缓；蛛网膜下腔出血以剧烈头痛和脑膜刺激征为主，偏瘫少见；晕厥为一过性意识丧失，无偏瘫；心肌梗死无脑部定位体征"},{"q":"患者，女，26岁。发作性咳嗽、咳痰、呼吸困难，可自行缓解。关于该患者症状发作时体征的描述正确的是","o":["呈吸气性呼吸困难","胸廓呈呼气位","两肺叩诊呈过清音","语音共振稍增强","Kronig峡消失"],"a":2,"e":"支气管哮喘发作时小气道痉挛、肺过度充气，叩诊呈过清音，伴呼气性呼吸困难和双肺干啰音。吸气性呼吸困难见于上气道梗阻；哮喘发作时胸廓呈吸气位而非呼气位；语音共振因含气量增多而减弱；Kronig峡消失并非哮喘的典型体征"},{"q":"患者，女，28岁。恶心、尿色变黄6天，体检发现巩膜中度黄染，肝肋下2cm可及，血谷丙转氨酶840U/L，总胆红素85μmol/L。对本例明确诊断最有意义的检查为","o":["腹部超声检查","肝炎病毒标志物检查","全套肝脏生化检查","腹部增强CT检查","肥达外婓试验"],"a":1,"e":"患者急性起病、ALT显著升高伴黄疸，属急性肝细胞性损害，肝炎病毒标志物可明确病原学诊断，对病因判断最有意义。腹部超声与增强CT主要观察形态和梗阻；全套肝脏生化反映损害程度但不能定病原；肥达外婓试验用于伤寒，与肝炎无关"},{"q":"一患者术后突然出现右侧胸痛，咳嗽，咯少量血痰。胸片示右肺下野可见模糊片影。最可能出现下列哪项体征","o":["右侧出现耳语音","右侧触觉语颤增强","右侧听觉语颤增强","右肺听到湿啰音","右肺听到干啰音"],"a":3,"e":"术后长期卧床易并发肺栓塞，肺梗死灶出血、渗出使局部可闻及湿啰音。触觉语颤、听觉语颤及耳语音增强见于肺实变，需肺组织致密传导，本例片状阴影以出血渗出为主；干啰音为气道痉挛或狭窄的表现，与本例不符"},{"q":"一年轻人因用力后突然感到一侧胸痛，进行性呼吸困难，伴大汗淋漓。查体：一侧胸部语音震颤减弱，呼吸音消失，气管向健侧移位。首先应想到患哪种疾病","o":["支气管哮喘","胸腔积液","大叶肺炎","气胸","肺不张"],"a":3,"e":"用力后突发一侧胸痛、进行性呼吸困难，查体见语颤减弱、呼吸音消失、气管推向健侧，为大量气胸的典型表现。胸腔积液虽也推气管向健侧，但叩诊呈实音且起病较缓；肺不张气管移向患侧；大叶肺炎语颤增强、叩诊浊音；哮喘为双肺弥漫性干啰音"},{"q":"一女性患者长期存在双下肢接触凉水后疼痛不适感。查体：双下肢轻微触摸后疼痛难耐。以上情况考虑为","o":["痛觉正常","痛觉过敏","痛觉消失","痛觉减退","触觉过敏"],"a":1,"e":"痛觉过敏指对正常痛刺激反应增强，轻微触碰即诱发难忍疼痛，属痛觉障碍类型之一。痛觉减退与消失均为反应减弱或丧失；痛觉正常者轻触不引起疼痛；触觉过敏是触觉阈降低，而本例突出的是疼痛反应过强，故判为痛觉过敏"},{"q":"患者，男，53岁。头痛3小时，呈持续性，程度剧烈。查体：T 36℃，意识模糊，烦躁，脑膜刺激征阳性。该患者最可能的诊断是","o":["蛛网膜下腔出血","脑炎","脑膜脑炎","脑肿瘤","脑梗死"],"a":0,"e":"突发剧烈头痛、意识障碍伴脑膜刺激征而体温正常，提示蛛网膜下腔出血，系脑膜受血液刺激所致。脑炎与脑膜脑炎多有发热及脑脊液炎性改变；脑肿瘤呈慢性进行性头痛；脑梗死多为局灶性神经缺损，脑膜刺激征阴性"},{"q":"患者，男，46岁，劳力性胸痛2个月，突感心悸、胸闷，血压为90/60mmHg，心尖S1强弱不等；心电图示心室率150次/min，P波与QRS波群无固定关系，QRS波增宽为0、14s，可见室性融合波。最可能的诊断为","o":["频发室性期前收缩","心房颤动","心房扑动","阵发性室上性心动过速","阵发性室性心动过速"],"a":4,"e":"心室率150次/min、QRS增宽0.14s、房室分离及室性融合波，均为室性心动过速的特征，融合波是确诊的重要依据。房颤与房扑为室上性，QRS多不增宽；阵发性室上速心律规整、QRS窄；频发室早为间歇发作，无持续宽QRS心动过速"},{"q":"患者，女，15岁，自幼偏食不喜肉蛋。查体：浅表淋巴结不大，睑结膜苍白。心尖区2级收缩期杂音，肝脾不大。外周血RBC 4.0×1012/L，Hb 70g/L，RC 0.015，MCV 60fl，MCHC 260g/L，WBC 5.0×109/L，PLT 120×109/L，骨髓细胞外铁（－），铁粒幼细胞0、01。最可能的诊断是","o":["巨幼细胞贫血","缺铁性贫血","再生障碍性贫血","环状铁粒幼细胞贫血","遗传性球形红细胞增多症"],"a":1,"e":"青少年偏食，小细胞低色素性贫血，骨髓细胞外铁阴性、铁粒幼细胞极低，符合缺铁性贫血。巨幼细胞贫血为大细胞性；再障为正细胞正色素性且全血细胞减少；铁粒幼细胞贫血可见环形铁粒幼细胞、细胞外铁增多；遗传性球形红细胞增多症属溶血性贫血"},{"q":"一胸腔积液患者，胸部X线片显示右侧肋膈角变钝，该侧胸部的叩诊音应为","o":["清音","浊音","实音","浊鼓音","空瓮音"],"a":0,"e":"肋膈角变钝仅提示少量胸腔积液，液体位于膈上、肺下，胸壁大部叩诊仍为清音。浊音与实音见于中大量积液或肺实变；浊鼓音为肺泡含气减少时浊音与鼓音的混合，见于肺炎消散期、肺不张；空瓮音见于张力性气胸或巨大空洞"},{"q":"患者，男，30岁。反复心悸1个月，1周前有上呼吸道感染。查体：主动脉瓣可闻及舒张期高调递减型叹气样杂音，周围血管征阳性。目前该患者在安静状态下可能明显出现哪项体征","o":["颈动脉搏动","颈静脉搏动","颈静脉充盈","颈静脉塌陷","颈动脉杂音"],"a":0,"e":"主动脉瓣关闭不全致脉压增大，安静状态下可见明显颈动脉搏动，重者可有点头运动。颈静脉搏动反映三尖瓣关闭不全时右心房压力传导；颈静脉充盈提示右心压力升高或容量过多；颈静脉塌陷见于低血容量；颈动脉杂音非本病体征"},{"q":"患者，男，55岁，乏力、消瘦、食欲减退5年加重1个月，有大量腹水，既往慢性乙型肝炎病史30余年。化验提示血清白蛋白20g/L。符合该患者腹腔积液特点的是","o":["不自凝","蛋白定量＞30g/L","细胞计数＜500×106/L","乳酸脱氢酶＞200IU","比重高于1、018"],"a":0,"e":"肝硬化低蛋白血症所致腹腔积液为漏出液，因不含纤维蛋白原而不自凝。蛋白定量＞30g/L、LDH＞200U及比重高于1.018均为渗出液特点；漏出液细胞数通常远低于100×10⁶/L，细胞计数＜500×10⁶/L并非其特征性表现"},{"q":"患者，女，53岁。发作性眩晕3小时。患者于转头后突然出现眩晕，四肢无力，摔倒在地，四肢无法活动，持续约5分钟后恢复正常，无大小便失禁。发作时查体：血压145/91mmHg，神志清，四肢肌力0级，肌张力低。间歇期查体无异常，脑电图正常。该患者最可能的诊断是","o":["癫痫","短暂脑缺血发作","位置性眩晕","高血压脑病","癔症"],"a":1,"e":"突发眩晕、四肢肌力0级而神志清楚、5分钟完全恢复，且脑电图正常，符合椎基底动脉系统短暂性脑缺血发作的猝倒发作。位置性眩晕仅有头晕无肢体瘫痪；癫痫多有意识障碍及脑电图异常；高血压脑病伴血压极度升高与头痛；癔症无客观体征"},{"q":"患者，女，48岁。左乳腺肿块1个月。查体：左乳腺内下方触及2cm×2cm大小包块，质硬，无触痛，表面光滑。该患者不可能出现的临床表现是","o":["皮肤橘皮样改变","乳头内陷","乳头有血性分泌物溢出","局部红肿和疼痛","腋窝淋巴结肿大和粘连"],"a":4,"e":"乳腺质硬无痛性肿块考虑乳腺癌，早期即可出现皮肤橘皮样变、乳头内陷、血性溢液或局部红肿疼痛。腋窝淋巴结转移虽常见，但形成明显肿大并粘连固定提示局部晚期浸润，与尚表面光滑、可活动的小肿瘤阶段不符，故该表现不可能出现"},{"q":"一男性患者步态不稳、脚踏棉花，医生接诊时考虑患者深感觉存在障碍，需要进行震动觉检查。以下哪个部位不适合进行震动觉检查","o":["胫骨","内、外踝","髂骨上棘","膝盖骨","肚脐周围"],"a":4,"e":"振动觉检查需用128Hz音叉柄置于骨突起处，胫骨、内外踝、髂前上棘、膝盖均为合适部位。肚脐周围为柔软腹壁，缺乏骨性突起，音叉振动难以有效传导定位，不适合用于震动觉检查"},{"q":"患者，男，60岁。四肢关节肿痛20年，以双手小关节为重。查体见双手尺偏畸形，右肘关节屈曲畸形。最可能的疾病是","o":["类风湿关节炎","骨关节炎","软组织炎","退行性关节炎","痛风"],"a":0,"e":"双手小关节对称性肿痛伴尺偏畸形、晨僵，符合类风湿关节炎的晚期关节破坏。骨关节炎与退行性关节炎多累及膝、髋等负重关节，无对称性小关节尺偏；痛风为单关节急性发作伴血尿酸升高；软组织炎无关节畸形"},{"q":"患者，女，36岁。头晕、乏力2年。平时月经过多，素食为主。查体：贫血貌。心肺无异常。实验室检查：Hb 88g/L，MCV 70fl。患者指甲最不可能出现的表现是","o":["指甲中部凹陷","指甲边缘翘起","指甲变厚","表面粗糙有条纹","出现“反甲”"],"a":2,"e":"缺铁性贫血的特征性指甲改变为匙状甲（反甲），表现为指甲变薄、中央凹陷、边缘翘起、表面粗糙有条纹。指甲变厚与匙状甲相反，不会出现；其余四项均为反甲的具体表现"},{"q":"患者，男，70岁，皮肤瘀斑2天。有心肌梗死病史，长期服用阿司匹林肠溶片。下列实验室检查不符合的是","o":["血小板P-选择素增高","血小板聚集率降低","出血时间延长","血小板黏附功能降低","APTT延长"],"a":4,"e":"阿司匹林抑制血小板环氧合酶、减少血栓素生成，使聚集与黏附功能降低、出血时间延长，但不影响凝血因子，故APTT正常。APTT延长提示内源性凝血因子缺乏或存在抗凝物；血小板聚集率降低、黏附功能降低及出血时间延长均符合其抗血小板作用"},{"q":"患者，女，30岁，3天前脚外伤后出现发热，最可能出现","o":["左锁骨上淋巴结肿大","右锁骨上淋巴结肿大","滑车上淋巴结肿大","腋窝淋巴结肿大","腹股沟淋巴结肿大"],"a":4,"e":"下肢感染或外伤后，淋巴液沿下肢回流至腹股沟淋巴结，引起该组淋巴结肿痛。滑车上淋巴结收集前臂和手部淋巴；腋窝淋巴结引流上肢及乳腺；左锁骨上淋巴结多见于消化道肿瘤转移，右锁骨上多见于胸部肿瘤"},{"q":"患者，男，60岁。近期腹痛明显，排便次数减少，偶有排便成细长条状，体重减轻明显，食欲不佳。考虑患者最可能的疾病是","o":["肠癌","肠炎","肠息肉","溃疡性结肠炎","克罗恩病"],"a":0,"e":"老年患者腹痛、排便减少、大便变细伴体重下降与食欲减退，提示结肠或直肠占位，以肠癌最常见。肠炎与溃疡性结肠炎以腹泻、黏液脓血便为主；肠息肉多无进行性消瘦；克罗恩病常有慢性腹泻、腹痛及肠外表现"},{"q":"患者，男，19岁。平素劳力尚可，无明显心悸、气促。体检时发现胸骨左缘第3肋间出现叹气性递减型舒张期杂音，血压120/60mmHg。该患者可出现下列体征，但除外","o":["水冲脉","颈静脉搏动","毛细血管搏动征","枪击音","杜氏双重音"],"a":1,"e":"胸骨左缘第3肋间叹气样递减型舒张期杂音提示主动脉瓣关闭不全，可伴水冲脉、毛细血管搏动征、枪击音及Duroziez双重音。颈静脉搏动是三尖瓣关闭不全的表现，反映右心室收缩时右房压力传导，不属于主动脉瓣关闭不全的周围血管征"},{"q":"患者，女，25岁。肝炎系列检查示HBsAg（－），抗-HBs（＋），抗-HBc（－），HBeAg（－），抗-Hbe（－），表明","o":["急性肝炎初期","慢性迁延性肝炎且有传染性","乙肝恢复并产生免疫力","既往乙肝病毒感染，病毒复制","慢性活动性肝炎"],"a":2,"e":"抗-HBs阳性为保护性抗体，提示机体对乙肝病毒已产生免疫力，HBsAg与HBeAg阴性说明无病毒复制和传染性。急性肝炎初期HBsAg阳性；慢性迁延性或活动性肝炎均有HBsAg持续阳性、抗-HBc阳性；大三阳提示病毒复制活跃，与本例不符"},{"q":"患者，女，23岁。自幼身体常易出现瘀斑，1个月前剖宫产术后伤口延迟愈合，辅助检查示TT明显延长且Fg活性下降，APTT、PT正常，考虑诊断为","o":["异常纤维蛋白原血症","血友病A","血友病B","血小板无力症","血小板促凝活性增高"],"a":0,"e":"TT延长见于纤维蛋白原异常或肝素样物质增多，本例Fg活性下降而APTT、PT正常，符合异常纤维蛋白原血症。血友病A、B分别为因子Ⅷ、Ⅸ缺乏，表现为APTT延长而TT正常；血小板无力症为血小板功能缺陷，TT正常；促凝活性增高不会导致出血"},{"q":"患者，男，32岁。下腹痛伴夜尿2天。查体：前列腺触诊发现前列腺弥漫性肿大，压痛明显。患者最可能的诊断是","o":["正常前列腺","急性前列腺炎","良性前列腺肥大","前列腺癌","前列腺钙化"],"a":1,"e":"前列腺弥漫性肿大伴明显压痛，是急性前列腺炎的典型表现，多伴尿频尿急及发热。良性前列腺肥大表面光滑有韧感、无压痛，见于老年人；前列腺癌质硬、无压痛并可触及硬结节；正常前列腺体积正常且无压痛"},{"q":"患者，男，52岁，诊为高血压20年，活动时气短1年。心电图显示如下，心电图的诊断考虑为","o":["急性心肌梗死","低血钾","一度房室传导阻滞","心房增大","左室肥大"],"a":4,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。长期高血压致左心室后负荷增加，左室肥大心电图表现为胸导联R波增高、电轴左偏及继发性ST-T改变。心房增大表现为P波增宽或高尖；一度房室传导阻滞为PR间期延长；急性心肌梗死有异常Q波和ST段弓背抬高；低血钾以U波增高、T波低平为著\n\n官方题库中缺失图片"},{"q":"患者，男，77岁。吸烟50年，常年咳嗽、咳痰，近10年出现活动性呼吸困难、并进行性加重。明确诊断为慢性支气管炎合并肺气肿，该患者胸廓改变最常见的是","o":["脊柱后凸","桶状胸","扁平胸","漏斗胸","鸡胸"],"a":1,"e":"慢性支气管炎合并肺气肿时肺泡含气量增多、肺过度充气，胸廓前后径增大呈桶状胸。扁平胸前后径不及左右径一半，见于瘦长体型或消耗性疾病；漏斗胸为胸骨下段内陷；鸡胸为胸骨向前突出，均为发育畸形，与肺气肿无关"},{"q":"某患，突发呕血2000ml，为新鲜血。查体：面色晦暗，颈面部及双上肢可见散在蜘蛛痣，肝掌，腹膨隆，脾大，肋下2cm，移动性浊音阳性。该患者出血原因考虑为","o":["食管静脉曲张破裂出血","脾功能亢进","消化性溃疡","胃癌","Dieulafoy病"],"a":0,"e":"大量呕血伴蜘蛛痣、肝掌、腹水及脾大，提示肝硬化门静脉高压，食管胃底静脉曲张破裂是常见大出血原因。消化性溃疡为呕血最常见病因但无肝硬化体征；胃癌出血量较少且慢性病程；Dieulafoy病为胃黏膜下恒径动脉破裂；脾功能亢进仅致血细胞减少"},{"q":"患者，女，25岁，既往健康。2小时前打扫室内清洁时突然出现咳嗽、胸闷、呼吸困难。查体：两肺满布干啰音。该例诊断应为","o":["慢性喘息型支气管炎","慢性阻塞性肺疾病","支气管哮喘","心源性哮喘","气胸"],"a":2,"e":"既往健康者在打扫卫生时突发咳嗽、胸闷、呼吸困难，双肺满布干啰音，符合支气管哮喘的急性发作。慢性喘息型支气管炎与COPD均为长期反复咳喘；心源性哮喘有心脏病史、多闻湿啰音；气胸为一侧呼吸音消失、叩诊鼓音"},{"q":"患者，男，60岁。主诉：血压偏高2年，近1周头晕、胸闷、心悸。若反复多次测量血压在收缩压170～195mmHg、舒张压95～98mmHg之间波动，则其血压水平为","o":["临界高血压","1级高血压","2级高血压","3级高血压","单纯收缩期高血压"],"a":3,"e":"收缩压波动于170～195mmHg，已达3级高血压标准（≥180mmHg），舒张压虽仅1级，按分级以较高者为准，故判为3级高血压。1级为140～159/90～99mmHg；2级为160～179/100～109mmHg；单纯收缩期高血压需舒张压正常，本例不符合"},{"q":"患者，男，56岁，因血糖升高应用胰岛素治疗。近期拟检测糖化血红蛋白，该物质的测定可以反映的血糖水平是","o":["近1～2周","近3～4周","近5～6周","近6～8周","近8～12周"],"a":4,"e":"糖化血红蛋白是血红蛋白与葡萄糖缓慢非酶结合的产物，反映红细胞生存期内约8～12周的平均血糖水平，用于评价长期血糖控制。糖化白蛋白反映前2～3周血糖，时间较短；1～2周或3～4周均短于红细胞寿命，不符合其代谢特点"},{"q":"患者，男，75岁。患高血压病史20年，夜尿增多3年，双下肢轻度水肿2个月入院。血压180/100mmHg，血红蛋白79g/L，血肌酐250μmol/L，尿蛋白＋＋。下列哪项检查有助于确定肾功能不全分期","o":["尿β2-微球蛋白测定","血β2-微球蛋白测定","24h尿蛋白定量测定","血尿酸测定","内生肌酐清除率测定"],"a":4,"e":"内生肌酐清除率近似肾小球滤过率，是判断肾功能损害程度和肾功能不全分期的首选指标。血、尿β2-微球蛋白主要反映肾小管早期损伤；24小时尿蛋白定量反映蛋白尿程度；血尿酸用于痛风及高尿酸血症，均不能用于分期"},{"q":"患者，男，22岁，高热3天，突发意识不清、定向力丧失、出现幻觉、言语杂乱。此时患者的意识状态是","o":["意识模糊","昏睡","谵妄","轻度昏迷","中度昏迷"],"a":2,"e":"高热患者突发意识模糊、定向力丧失、幻觉及言语杂乱，伴兴奋躁动，符合谵妄，常见于急性感染发热期。昏睡、轻度及中度昏迷均以意识抑制为主，无幻觉躁动；意识模糊仅有轻度意识清晰度下降，不伴明显感觉错乱"},{"q":"患者，男，24岁。上腹痛半年，饥饿及进食后均有腹痛，伴有反酸、嗳气，并常有腹泻。既往胃镜示胃小弯、十二指肠球部及球后多发溃疡。胃液分析：基础排酸量（BAO）＞30mmol/h，最大酸排量（MAO）＞40mmol/h。最可能的诊断为","o":["多发性溃疡","复合性溃疡","复合溃疡恶变","胰岛β细胞瘤","胃泌素瘤"],"a":4,"e":"胃小弯、十二指肠球部及球后多发溃疡，基础排酸量与最大酸排量显著增高，伴腹泻，提示胃泌素瘤。多发性溃疡与复合性溃疡只是形态描述；胰岛β细胞瘤表现为低血糖；胃泌素瘤才是高胃酸、多发不典型溃疡和腹泻的病因"},{"q":"患者，男，60岁，全身乏力、食欲缺乏3个月就诊。查体：皮肤黝黑，口腔有蓝黑色色素斑片沉着。皮肤未见静脉曲张，腹部检查无特殊。腹部B超未见异常。可能的诊断是","o":["肝硬化","肾上腺皮质功能减退","消化道肿瘤","肺结核","甲状腺功能亢进"],"a":1,"e":"皮肤黏膜弥漫性色素沉着伴口腔蓝黑色斑片、乏力，符合肾上腺皮质功能减退，因ACTH及黑色素细胞刺激素增多所致。肝硬化为肝病面容、色素以面颊眶周为主；消化道肿瘤无弥漫性黏膜色素斑；甲亢表现为突眼、面容惊愕"},{"q":"患者，女，25岁，心悸、气短10年。查体：心尖部S1亢进时，并可听到开瓣音及舒张中、晚期隆隆样杂音，P2亢进。此患者的诊断是","o":["主动脉瓣关闭不全","主动脉瓣狭窄","二尖瓣关闭不全","二尖瓣狭窄","二尖瓣相对性狭窄"],"a":3,"e":"心尖区舒张中晚期隆隆样杂音伴S1亢进、开瓣音，是风湿性二尖瓣狭窄的典型体征，开瓣音提示瓣叶活动尚可。主动脉瓣关闭不全为叹气样舒张期杂音；二尖瓣关闭不全为收缩期吹风样杂音；相对性二尖瓣狭窄杂音柔和递减、无开瓣音及S1亢进"},{"q":"患儿，男，11岁。出生1个月时发现心脏杂音，当时查体：于胸骨左缘2肋间及3/6级粗糙收缩期杂音，伴P2增强，S2固定分裂。现患儿渐感劳力性心累气紧，活动后出现发绀，杵状指。诊断考虑","o":["左心衰竭","右心衰竭","法洛四联症","肺静脉异位引流","艾森门格综合征"],"a":4,"e":"幼儿期胸骨左缘第2肋间收缩期杂音伴S2固定分裂，提示房间隔缺损；后期出现发绀与杵状指，说明肺动脉高压致左向右分流逆转为右向左分流，即艾森门格综合征。法洛四联症自幼发绀、无S2固定分裂；心衰无此先天性畸形基础"},{"q":"患者，男，37岁。于搬货后出现腰痛、左下肢疼痛，咳嗽时加重，休息后缓解，无关节肿胀。该患者最可能的诊断是","o":["腰肌纤维组织炎","腰肌劳损","腰椎间盘突出","髋关节结核","强直性脊柱炎"],"a":2,"e":"搬重物后腰痛并向一侧下肢放射，咳嗽增加腹压时加重、休息缓解，符合腰椎间盘突出压迫神经根。腰肌纤维组织炎与腰肌劳损仅有腰部酸痛，无下肢放射痛；髋关节结核病变在髋；强直性脊柱炎以晨僵和下腰痛起病，非急性根性痛"},{"q":"一名四肢力量正常患者入院后不能按照医生要求用左手摆出右手一样的姿势。考虑患者损伤在以下哪个部位","o":["脊髓后索","周围神经","脊髓侧索","小脑","锥体束"],"a":2,"e":"四肢肌力正常但不能按指令完成左手模仿右手的姿势，提示锥体束受累导致的随意运动执行障碍，定位在脊髓侧索。脊髓后索主管位置觉与振动觉，受损为深感觉障碍；小脑损害表现为共济失调；周围神经为下运动神经元瘫，伴肌力减退"},{"q":"患者，男性，32岁，因阵发性心动过速至门诊就诊，既往无心肌炎、高血压、糖尿病等病史，ECG如图。可能的诊断为","o":["预激综合征","完全左束支传导阻滞","不完全左束支传导阻滞","完全右束支传导阻滞","不完全右束支传导阻滞"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。预激综合征因房室旁路存在，心电图表现为PR间期缩短、QRS起始部预激波及QRS增宽，易诱发房室折返性心动过速。完全与不完全左束支传导阻滞QRS增宽但PR正常、无预激波；右束支阻滞V1呈rsR'型\n\n官方题库中缺失图片"},{"q":"患者，男，46岁。阵发性心悸、头晕5年，发作性心前区疼痛1周。胸部X线检查见心影呈靴型。下列哪项体征具有诊断意义","o":["心尖冲动向左下移位，呈抬举性","心浊音界向左下扩大，心腰凹陷","主动脉瓣区第二心音亢进","主动脉瓣第二听诊区叹气样舒张期杂音","脉压增大，伴有水冲脉"],"a":3,"e":"靴型心提示左心室增大，主动脉瓣第二听诊区叹气样递减型舒张期杂音是主动脉瓣关闭不全的特征性体征，具有确诊意义。心尖冲动左下移位与心浊音界向左下扩大仅提示左室肥大；主动脉瓣区第二心音亢进非特异；水冲脉为周围血管征，均不如杂音特异"},{"q":"患者，女，38岁，主诉：酱油色尿2周。2周前曾因“感冒”服用对乙酰氨基酚类药物，期间曾发现尿色呈酱油色。查体见贫血外貌，双下肢散在出血点，巩膜轻度黄染。血常规示 Hb 85g/L，WBC 10.3×109/L，PLT 64×109/L。考虑药物性溶血性贫血，哪型超敏反应是其发病机制","o":["Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅲ型超敏反应","Ⅳ型超敏反应","不是超敏反应"],"a":1,"e":"药物性溶血性贫血由药物相关抗体结合红细胞表面抗原、介导补体或吞噬破坏所致，属Ⅱ型超敏反应。Ⅰ型为IgE介导的速发型反应如哮喘；Ⅲ型为免疫复合物沉积所致血清病样反应；Ⅳ型为迟发型细胞免疫反应；本例Coombs试验可阳性，故非不是超敏反应"},{"q":"患者，女，52岁，有“风湿性心脏病”病史。入院后检查心电图：心室率85次/min，电轴150°，PⅠ、PⅡ、PavL切迹明显，P波时限＞0.13s，V1Ptf为0.08mm·s，V1R/S＞1，V5R/S＜1，P-R间期0.22s。应考虑为","o":["右心室肥大","左心房、右心室肥大","右心房、右心室肥大","左心房、右心室肥大伴一度房室传导阻滞","右心室肥大伴一度房室传导阻滞"],"a":3,"e":"PⅠ、Ⅱ、aVL切迹明显且时限＞0.13s提示左心房肥大；电轴右偏、V1R/S＞1、V5R/S＜1提示右心室肥大；PR间期0.22s达一度房室传导阻滞标准，故三者并存。单纯右室肥大或左房右室肥大均遗漏PR延长；右房右室肥大应有Ⅱ、Ⅲ、aVF高尖P波"},{"q":"患者，男，15岁。因“鼻塞、流涕1周，加重伴脓涕、头痛2天”就诊。查体：左右颧部明显按压痛，双肺呼吸音清，未闻及明显干、湿啰音。最可能的诊断是","o":["急性鼻炎","急性支气管炎","急性上颌窦炎","急性筛窦炎","急性额窦炎"],"a":2,"e":"鼻塞、脓涕、头痛伴左右颧部压痛，为上颌窦炎的典型表现，上颌窦压痛检查即按压颧部。筛窦炎压痛在鼻根与内眦之间；额窦炎压痛在眉弓及额部；急性鼻炎无鼻窦压痛；急性支气管炎以咳嗽咳痰为主，无面部压痛"},{"q":"患者，男，50岁，无特殊基础疾病，长期吸烟。间断胸闷8年，短暂意识丧失2次，胸闷发作时自测心率变慢，完善Holter如图所示，进一步诊治不可选","o":["地尔硫䓬药物治疗","硝酸酯类药物治疗","冠状动脉CTA评估","冠状动脉造影","永久起搏器植入"],"a":0,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。胸闷伴心率减慢及晕厥，提示病态窦房结综合征或严重传导阻滞，地尔硫䓬抑制窦房结与房室结，可加重心动过缓乃至晕厥，属禁用。硝酸酯类扩张冠脉；CTA与造影评估冠脉病变；永久起搏器用于症状性心动过缓\n\n官方题库中缺失图片"},{"q":"一患者体检发现眼球向下及向外运动受限。据此推测损伤以下哪条神经","o":["动眼神经","滑车神经","展神经","交感神经","面神经"],"a":1,"e":"滑车神经支配上斜肌，主要使眼球向下、向外运动，受损时该方向活动减弱。动眼神经麻痹表现为眼球向内、向上、向下受限并上睑下垂、瞳孔散大；展神经损伤为外展不能；交感神经损害出现Horner征；面神经损伤为面部表情肌瘫痪"},{"q":"患儿，男，6个月。1个月前出现面部灰暗，哭闹及吃奶时出现青紫。查体：较瘦，口周发绀，心前区可闻及3级收缩期喷射音。X线示：右室肥大，肺动脉段凹陷，心脏呈靴形，肺野清晰。此患儿最可能的诊断是","o":["室间隔缺损","房间隔缺损","肺动脉段狭窄","动脉导管未闭","法洛四联症"],"a":4,"e":"6个月患儿发绀、喷射性杂音、靴形心、肺动脉段凹陷且肺野清晰，符合法洛四联症，由肺动脉狭窄、室缺、主动脉骑跨和右室肥大组成。室缺、房缺、动脉导管未闭均为左向右分流，肺野充血且无发绀；单纯肺动脉狭窄无室缺与主动脉骑跨"},{"q":"患者乏力，黄疸，脾大，末梢血网织红细胞为10%，非结合胆红素升高，对自身免疫性溶血性贫血的诊断最重要的是","o":["HAM试验","渗透脆性试验","Coombs试验","冷溶血试验","高铁血红蛋白还原试验"],"a":2,"e":"自身免疫性溶血性贫血因体内产生抗红细胞自身抗体，Coombs试验检测红细胞表面或血清中不完全抗体，是确诊的关键。HAM试验用于阵发性睡眠性血红蛋白尿；渗透脆性试验用于遗传性球形红细胞增多症；冷溶血试验用于冷凝集素病；高铁血红蛋白还原试验筛查G6PD缺乏"},{"q":"患者，男，40岁。乏力，食欲缺乏3周。查体：巩膜黄染，心肺无异常，肝肋下1cm，轻触痛，脾不大。查HAV-Ag阳性。近1周患者黄疸逐渐加重，但ALT逐渐降低，这说明","o":["急性肝炎逐渐好转","转为慢性活动性肝炎","有较多的肝细胞坏死","症状与化验不符","无临床意义"],"a":2,"e":"黄疸进行性加深而ALT反而下降，出现酶胆分离，提示肝细胞大量坏死、肝功能衰竭，而非病情好转。急性肝炎好转应黄疸消退、ALT下降；慢性活动性肝炎病程长；症状与化验并非真正矛盾；这种分离有明确病理基础，并非无临床意义"},{"q":"患者，女，42岁。右上腹疼痛1年，常在进食油脂重食物后发作。昨晚吃炖猪蹄后1小时出现右上腹痛，向右肩部放射，呕吐2次，腹部检查最可能发现压痛的部位是","o":["肋脊点","McBurney点","上输尿管点","季肋点","胆囊点"],"a":4,"e":"进食油腻后右上腹绞痛向右肩放射伴呕吐，符合胆石症或胆囊炎，压痛点位于右锁骨中线与肋缘交界的胆囊点。McBurney点压痛提示阑尾炎；肋脊点与季肋点压痛提示肾脏病变；上输尿管点压痛为输尿管结石或炎症"},{"q":"患者，男，32岁，主诉最近5天严重呕吐，极度疲劳。查体：眼凹，黏膜干燥，心率为110次/min，血压为90/50mmHg。站立时，血压下降，心率升高。动脉血气：pH 7、50，PaCO2 47mmHg，HCO3- 38mEq/L，PaO2 80mmHg。该患者可能发生了","o":["代谢性碱中毒部分代偿期","呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","呼吸性酸中毒和低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"pH 7.50＞7.45，HCO₃⁻ 38mmol/L显著升高，PaCO₂轻度升高，提示代谢性碱中毒伴部分呼吸代偿，因代偿未使pH正常故为部分代偿期。呼吸性碱中毒PaCO₂应降低；代谢性酸中毒pH降低、HCO₃⁻下降；呼吸性酸中毒pH降低；静脉血PaO₂不会达80mmHg"},{"q":"患者，女，36岁。劳力性心累气短半个月，既往关节肿痛史。超声提示二尖瓣重度粘连，未见钙化，开放受限。查体血压110/75mmHg，脉搏85次/min，心率145次/min，心律不齐，心音强弱不等。患者心律异常最可能为","o":["大炮音","频发房性期前收缩","心房颤动","阵发性室上性心动过速","频发室性期前收缩"],"a":2,"e":"脉搏85次/min而心率145次/min，心律绝对不齐、心音强弱不等，符合心房颤动的脉搏短绌。大炮音见于三度房室传导阻滞；频发房早或室早有提前搏动与代偿间歇，非持续绝对不齐；阵发性室上速心律规整"},{"q":"患者，女，25岁，运动后心悸气短3年。查体：心脏左下可闻及浊音，心腰狭窄，靴型心。主要诊断是","o":["主动脉瓣关闭不全","肺心病","扩张型心肌病","单纯二尖瓣狭窄","高血压心脏病"],"a":0,"e":"靴型心、心腰凹陷、心浊音界向左下扩大，提示左心室明显增大，结合主动脉瓣关闭不全的舒张期叹气样杂音可确诊。单纯二尖瓣狭窄为梨形心；肺心病为右室增大；扩张型心肌病心影普大呈球形；高血压心脏病虽有左室大，但本例杂音更支持瓣膜病"},{"q":"患者，女，23岁。发热4天，叩诊右肺呈实音，不可能存在的疾病是","o":["大叶性肺炎","肺不张","肺结核","肺脓肿","气胸"],"a":4,"e":"叩诊实音见于肺实变或大量胸腔积液，大叶性肺炎、肺不张、肺结核及肺脓肿均可出现。气胸时胸膜腔积气，叩诊呈鼓音而非实音，故不可能为气胸；张力性气胸可呈空瓮音，但亦非实音"},{"q":"患者，男，18岁，剧烈头痛、呕吐、意识不清2小时，入院诊断为化脓性脑膜炎。其脑脊液的特点是","o":["外观微混","蛋白质（＋）","氯化物增高","葡萄糖明显减低","中性粒细胞轻度增加"],"a":3,"e":"化脓性脑膜炎脑脊液典型改变为葡萄糖明显降低、氯化物降低、蛋白质显著增高及中性粒细胞大量增多，外观浑浊。外观微混不符合化脓性改变；蛋白质仅(+)过轻；氯化物应降低而非增高；中性粒细胞应显著增多而非轻度"},{"q":"患者，男，56岁。胸骨后压榨性疼痛半天口含硝酸甘油不缓解而就诊，心电图显示Ⅱ、Ⅲ、aVF导联出现异常Q波，ST段弓背抬高，查体：BP 150/90mmHg，心率92次/min。最可能的诊断是","o":["高血压","心包积液","急性心肌梗死","心律失常","肺心病"],"a":2,"e":"胸骨后压榨性疼痛持续不缓解，Ⅱ、Ⅲ、aVF导联异常Q波伴ST段弓背抬高，符合急性下壁心肌梗死。高血压无心肌梗死图形；心包积液为低电压、电交替；心律失常仅有节律异常；肺心病表现为右室肥大，均无异常Q波与ST抬高"},{"q":"患者，女，28岁。受凉后寒战，咳嗽、咳痰、胸痛。查体：体温38.5℃，右下肺语颤增强，可闻湿性啰音。白细胞总数17×109/L，中性粒细胞90%。最可能的诊断为","o":["上呼吸道感染","急性支气管炎","急性肺脓肿","肺炎球菌肺炎","肺结核"],"a":3,"e":"受凉后寒战高热、咳痰胸痛，右下肺语颤增强与湿啰音提示肺实变，白细胞及中性粒细胞显著升高，符合肺炎球菌肺炎。上呼吸道感染与急性支气管炎无肺实变体征；急性肺脓肿有脓臭痰和空洞；肺结核起病缓慢，伴低热盗汗"},{"q":"中年女性，喜生食蔬菜，2个月来时常发作右上腹钻顶样疼痛难以忍受，但可自然缓解。1小时前再次发作，下列最有助于诊断的是","o":["尿淀粉酶","急诊超声","粪便查虫卵","纤维内镜","立位腹平片"],"a":1,"e":"喜生食蔬菜者出现右上腹钻顶样剧烈疼痛、可自行缓解，提示胆道蛔虫症，急诊超声可直接显示胆管内蛔虫回声。尿淀粉酶用于胰腺炎；粪便查虫卵阳性率低；纤维内镜为有创手段且非首选；立位腹平片主要诊断肠梗阻或消化道穿孔"},{"q":"患者，男，55岁。间断性心前区疼痛2个月，与劳累有关，静息心电图未见异常，运动实验提示有ST段下移0.15mV。首先考虑","o":["急性心肌梗死","心肌病","高血压冠心病","肺气肿","冠状动脉粥样硬化性心脏病"],"a":4,"e":"劳累诱发心前区疼痛、休息可缓，运动试验ST段下移0.15mV，提示心肌缺血，符合冠状动脉粥样硬化性心脏病心绞痛。急性心肌梗死疼痛持续且伴ST抬高；心肌病无典型劳力性心绞痛；肺气肿以呼吸困难为主；本例未提及高血压，不选高血压冠心病"},{"q":"患者，女，30岁，月经减少1年就诊，伴怕冷、乏力、便秘。查体：反应迟钝，颜面水肿，眉毛稀疏，舌体大，HR 50次/min。需要完善下列哪项检查确诊","o":["性激素水平","肾功能","甲状腺功能","妇科B超","血常规"],"a":2,"e":"怕冷、乏力、便秘、反应迟钝、颜面水肿、眉毛稀疏、舌体大及心率缓慢，为甲状腺功能减退的黏液性水肿表现，确诊需查甲状腺功能。性激素与妇科B超针对妇科疾病；肾功能异常无眉毛稀疏；血常规仅提示贫血，不能解释全部症状"},{"q":"患者，女，26岁。双臂皮肤出现皮疹，呈对称性，双面颊和鼻梁部位呈蝶形红斑，同时伴有膝、踝关节痛。若怀疑为系统性红斑狼疮，需做哪项过筛试验","o":["E花环试验","抗核抗体检查","淋巴细胞转化试验","CIC检测","补体水平检测"],"a":1,"e":"蝶形红斑、光过敏及多关节痛提示系统性红斑狼疮，抗核抗体是首选过筛试验，敏感性高。E花环试验与淋巴细胞转化试验检测T细胞功能；CIC检测反映免疫复合物；补体水平用于评估活动度，均非过筛首选"},{"q":"一患者发热、咳嗽、胸痛、咳铁锈色痰，胸片示肺炎吸收消散期。此时患者患侧胸部叩诊音应为","o":["清音","实音","鼓音","浊音","空瓮音"],"a":3,"e":"肺炎吸收消散期肺泡内渗出物尚未完全清除，肺泡含气量减少，叩诊呈浊音，实变期可为实音。清音为正常含气肺组织；鼓音见于气胸或肺空洞；空瓮音为张力性气胸或巨大空洞的金属回响；本例无胸膜腔积气，不选鼓音"},{"q":"患者，女，38岁。自述头迷，头晕，左上肢血压13.3/10.7kPa（1kPa≈7.5mmHg）。右上肢血压21.3/12.0kPa，左侧桡动脉搏动较右侧弱。首选考虑是下列何种疾病所致","o":["主动脉缩窄","多发大动脉炎","严重贫血","动静脉瘘","甲状腺功能减退症"],"a":1,"e":"双侧上肢血压相差明显（右侧显著高于左侧）伴左侧桡动脉搏动减弱，提示左侧上肢动脉供血受阻，见于多发性大动脉炎。主动脉缩窄表现为上肢血压高、下肢血压低；严重贫血与甲减无局部血压差；动静脉瘘为局部血流量增多"},{"q":"患者，男，70岁，有长期吸烟史。右胸部疼痛3个月，伴咳痰、痰中带血。查体：气管右偏，右上肺叩浊，呼吸音明显减弱。诊断上首先应考虑","o":["右上肺炎","右上肺癌","右上浸润性肺结核","右上包裹性积液","右上纵隔肿瘤"],"a":1,"e":"老年长期吸烟者出现胸痛、痰中带血、右上肺叩浊及气管向患侧移位，提示右上肺癌伴肺不张。右上肺炎起病急、有发热；浸润性肺结核多见于青年、病程长；包裹性积液叩诊实音且气管移向健侧；纵隔肿瘤少见痰中带血"},{"q":"患者，女，24岁，着凉后出现高热、咳嗽、咳痰3天，伴右侧胸痛，咳嗽或深吸气时加重。该患最不可能出现的体征是","o":["右侧胸廓饱满","右侧语音震颤增强","叩诊病变部位呈浊音","听诊病变部位可闻及湿啰音","气管位置居中"],"a":0,"e":"高热、咳嗽、胸痛随深吸气加重，提示大叶性肺炎累及胸膜，可见病侧语颤增强、叩诊浊音及湿啰音，气管居中。胸廓饱满是气胸或大量胸腔积液的体征，肺炎实变时胸廓对称、呼吸动度减弱，故最不可能出现"},{"q":"患者，女，34岁。腹泻便秘交替3个月，伴发热，体温午后升高，夜间盗汗。1年前曾患肺结核。查体：轻度贫血，心肺听诊无异常，腹平软，右下腹轻度压痛，粪便常规检查（－）。最可能的诊断是","o":["肠结核","结肠易激综合征","慢性阑尾炎","结核性腹膜炎","慢性结肠炎"],"a":0,"e":"腹泻与便秘交替、午后低热、盗汗、既往肺结核史伴右下腹痛，符合肠结核，凭结核中毒症状与肠功能紊乱可判断。肠易激综合征无发热盗汗；慢性阑尾炎为持续性右下腹痛；结核性腹膜炎以腹水和腹膜增厚为主；慢性结肠炎无结核证据"},{"q":"患者，女，35岁。体检时发现甲状腺弥漫性肿大，未闻及血管杂音，血压150/50mmHg，胸骨左缘第3、4肋间可闻及舒张期叹气样杂音。最可能的诊断是","o":["甲亢性心脏病","室间隔缺损","主动脉瓣狭窄","主动脉瓣关闭不全","动静脉瘘"],"a":3,"e":"胸骨左缘第3、4肋间舒张期叹气样杂音伴脉压显著增大，符合主动脉瓣关闭不全。甲亢性心脏病应有甲状腺血管杂音及高代谢表现；室间隔缺损为收缩期杂音；主动脉瓣狭窄为收缩期喷射性杂音；动静脉瘘为连续性杂音，均无典型舒张期叹气样杂音"},{"q":"高血压老年患者突发左侧肢体无力。神经系统查体发现左侧肢体肌力0级，右侧周围性面瘫。考虑损伤位于","o":["右侧大脑皮层","右侧基底节区","左侧基底节区","脑干右侧","颈段脊髓"],"a":3,"e":"左侧肢体瘫痪伴右侧周围性面瘫，属交叉性偏瘫，为一侧脑干病变累及同侧脑神经核与未交叉的皮质脊髓束，定位于右侧脑干。右侧大脑皮层或基底节病变引起左侧偏瘫伴左侧中枢性面瘫；左侧基底节致右侧偏瘫；颈段脊髓损害为四肢瘫或截瘫"},{"q":"患者来院检查，接诊医生神经系统查体发现患者伸舌偏左。以此推测患者损伤以下哪一部分","o":["左副神经","右副神经","左舌下神经","右舌下神经","左舌咽神经"],"a":2,"e":"舌下神经支配舌肌，单侧麻痹时伸舌舌尖偏向患侧，伸舌偏左提示左侧舌下神经损伤。副神经支配胸锁乳突肌与斜方肌，损伤后转头耸肩无力；舌咽神经主司咽部感觉与运动；右侧舌下神经损伤则舌尖偏右"},{"q":"患者，女，32岁，进行性膀胱刺激征，经抗生素治疗不见好转，伴右侧腰部胀痛及午后潮热。最合理的治疗措施是","o":["积极对症治疗","服碱性药，减轻尿路刺激症状","用抗真菌药","联合应用抗生素，作局部处理","抗结核治疗"],"a":4,"e":"进行性膀胱刺激征经抗生素治疗无效，伴腰痛与午后潮热，提示泌尿系统结核，应行抗结核治疗。单纯细菌感染用抗生素有效；抗真菌药仅用于真菌感染；服碱性药与对症处理只能缓解症状，不能针对结核分枝杆菌"},{"q":"患者，女，40岁，胃溃疡10年，突然大出血2小时，血压75/45mmHg；经输血后血压升至120/75mmHg，恢复正常，出血停止，但出现少尿，200ml/24h，考虑急性肾衰竭。下列检查对确诊最有帮助的是","o":["尿渗透压","血常规","尿常规","血肌酐","尿比重"],"a":3,"e":"急性肾衰竭以肾小球滤过率急剧下降、血肌酐和尿素氮迅速升高为确诊依据，血肌酐最有帮助。尿渗透压与尿比重反映肾小管浓缩功能，用于鉴别肾前性因素；尿常规可见管型提示肾实质损害；血常规不能判断肾功能"},{"q":"患者，男，37岁。近1个月来经常排鲜血便，血量少、不与粪便混合，伴里急后重，不发烧，无腹痛。最可能的诊断是","o":["直肠癌","急性坏死性肠炎","胃癌","肠结核","Crohn病"],"a":0,"e":"鲜血便量少、滴落于排便之后或附于粪便表面，伴里急后重而无发热腹痛，符合直肠癌。急性坏死性肠炎有剧烈腹痛与发热；胃癌出血多为黑便或呕血；肠结核与Crohn病常有腹痛、腹泻及黏液脓血便"},{"q":"中年女性，反复排黏液血便2年，复发5天，伴低热左下腹疼痛。查体：贫血貌，左下腹压痛（＋）。首选的诊断方法为","o":["粪潜血检查","纤维结肠镜","X线钡剂灌肠","OT试验","骨髓穿刺术"],"a":1,"e":"反复黏液血便伴低热、左下腹痛及贫血，需首先排除结肠肿瘤或炎症性肠病，纤维结肠镜可直接观察并活检，是首选诊断方法。粪潜血仅作筛查；X线钡剂灌肠不能取活检；OT试验查结核感染；骨髓穿刺针对血液系统疾病"},{"q":"患者，男，38岁，发作性心悸伴气短3小时，急检心电图各导联均未见正常P波，而V1导联有明显的f波，频率为460次/min，心室率绝对不规则。下列体征具有诊断意义的是","o":["S1、S2同时减弱伴奇脉","A2减弱伴水冲脉","S1强弱不等伴短绌脉","S1减弱伴重搏脉","P2增强伴交替脉"],"a":2,"e":"各导联无正常P波、V1导联f波频率460次/min、心室率绝对不规则，符合心房颤动，其特征体征为第一心音强弱不等和脉搏短绌。奇脉见于心包积液；水冲脉见于主动脉瓣关闭不全；重搏脉与交替脉分别为心肌病和左心衰的体征"},{"q":"患者，男，46岁，因“尿频、尿急、尿痛1周，尿道口脓性分泌物”就诊。分泌物涂片革兰染色镜检示大量白细胞，在白细胞内发现革兰阴性双球菌。最可能感染的病原菌是","o":["金黄色葡萄球菌","梅毒螺旋体","淋病奈瑟菌","溶血链球菌","表皮葡萄球菌"],"a":2,"e":"尿道口脓性分泌物涂片见白细胞内革兰阴性双球菌，是淋病奈瑟菌的典型镜下表现，为淋病确诊依据。金黄色葡萄球菌与表皮葡萄球菌为革兰阳性球菌；梅毒螺旋体需暗视野显微镜观察；溶血链球菌为革兰阳性链状排列"},{"q":"患者，女，36岁。劳力性心累气短半月，既往关节肿痛史。超声提示二尖瓣重度粘连，未见钙化，开放受限。查体：血压110/75mmHg，脉搏85次/min，心率145次/min，心律不齐，心音强弱不等。如触及震颤，则应为","o":["胸骨左缘第2肋间收缩期震颤","胸骨右缘第2肋间收缩期震颤","胸骨左缘第3、4肋间收缩期震颤","心尖收缩期震颤","心尖舒张期震颤"],"a":4,"e":"二尖瓣狭窄时舒张期血流通过狭窄瓣口产生湍流，可在心尖区触及舒张期震颤，左侧卧位更明显。胸骨左缘第2肋间收缩期震颤见于肺动脉瓣狭窄；胸骨右缘第2肋间为主动脉瓣狭窄；胸骨左缘第3、4肋间为室缺；心尖收缩期震颤见于重度二尖瓣关闭不全"},{"q":"一糖尿病患者因右侧肢体无力入院。入院查体发现巴宾斯基征阳性，损伤部位不可能是","o":["左侧基底节区","左侧大脑皮层","脑干左侧","右侧脊髓侧索","左侧脊髓侧索"],"a":4,"e":"右侧肢体无力伴巴宾斯基征阳性，说明右侧锥体束受损；脊髓内皮质脊髓束在延髓交叉，故脊髓病变须在右侧，左侧脊髓侧索只能引起左侧偏瘫，故不可能。左侧基底节、皮层及脑干左侧病变均在交叉以上，可引起右侧偏瘫"},{"q":"患者神经系统查体，发现双下肢震动觉减退，但未见明显感觉障碍平面。考虑该患者病变累及以下哪个部位","o":["脊髓侧索","脊髓丘脑前束","神经根","脊髓前角","脊髓后索"],"a":4,"e":"震动觉检查用128Hz音叉置于骨突处，其传导通路位于脊髓后索，双下肢震动觉减退而无感觉平面提示后索病变。脊髓侧索为运动传导束；脊髓丘脑前束传导触觉；神经根损害呈节段性分布；脊髓前角受损表现为下运动神经元瘫痪"},{"q":"患者，女，28岁。近3个月出现体重下降5kg，伴腹泻、心悸、手抖，遂至门诊就诊。关于该患者查体时的甲状腺检查，说法不正确的是","o":["甲状腺外观可不突出","甲状腺质地中等","触诊比视诊更能明确病变性质","可能触及甲状腺震颤","甲状腺可触及疼痛"],"a":4,"e":"体重下降、腹泻、心悸、手抖提示甲状腺功能亢进，其甲状腺弥漫性肿大、质软、可触及震颤及血管杂音，但无压痛；甲状腺疼痛见于亚急性甲状腺炎。甲状腺外观可不突出；触诊判断质地与结节比视诊更可靠"},{"q":"患者，男，63岁，面色苍白半年。查体：贫血貌，腹部无异常。大便隐血阳性。血常规：Hb 70g/L，MCV 72fl。临床给予口服硫酸亚铁治疗，该药物在消化道的主要吸收部位是","o":["胃","肝","回肠","直肠","十二指肠和空肠上段肠黏膜"],"a":4,"e":"口服硫酸亚铁在消化道主要于十二指肠和空肠上段吸收，该部位绒毛丰富且酸性环境利于铁溶解与转运。胃主要吸收酒精和少量药物；回肠吸收胆盐和维生素B12；直肠仅吸收少量水分，均非铁吸收部位"},{"q":"患者，女，28岁，因肥胖1年而就诊。查体：面呈满月，皮肤痤疮增多，口唇有小须，背部毳毛多见，项部脂肪垫肥厚，血压20/13、3kPa（1kPa≈7、5mmHg）。疑为库欣综合征，为了进一步明确诊断，应做的检查是","o":["血浆皮质醇测定","24h尿钾测定","24h尿蛋白测定","24h尿乳酸测定","血清醛固酮测定"],"a":0,"e":"满月脸、痤疮、小须、背部毳毛、项部脂肪垫及高血压提示库欣综合征，血浆皮质醇测定用于明确皮质醇增多。24h尿钾、蛋白、乳酸均非特异；血清醛固酮用于原发性醛固酮增多症，与原发性皮质醇增多不同"},{"q":"患者，男，68岁，既往多年吸烟史。咳嗽咳痰3个月，胸片及胸部CT未见异常，痰涂片发现瘤细胞，下一步最佳检查应选","o":["胸部薄层CT","胸部增强CT","胸部磁共振","纤维支气管镜检查及活检","同位素骨扫描"],"a":3,"e":"痰涂片找到瘤细胞而胸片及CT未见异常，提示隐匿性支气管肺癌，纤维支气管镜检查及活检可直接观察并取组织确诊。胸部薄层或增强CT已做且无异常；磁共振对肺内病变价值有限；同位素骨扫描仅用于评估骨转移"},{"q":"患者，女，34岁，3年前开始出现面部水肿，晨起明显，伴双下肢轻度水肿。1周前着凉后水肿加重，尿少、乏力、食欲缺乏来诊。患者可能的面容是","o":["急性病容","贫血面容","肾病面容","肝病面容","伤寒面容"],"a":2,"e":"面部及双下肢水肿、晨起明显伴尿少乏力，提示肾脏疾病，其典型面容为肾病面容，表现为面色苍白、眼睑颜面水肿、舌淡胖有齿痕。急性病容见急性感染；贫血面容无水肿；肝病面容晦暗有色素沉着；伤寒面容表情淡漠"},{"q":"患儿，男，8个月。呕吐2天，发热伴水样便1天。查体：T 37.8℃，R 26次/min，P 110次/min，BP 80/60mmHg，神志清，精神倦，唇干，皮肤干燥，前囟凹陷，心肺无异常，腹软，肝肋下1cm，质软，脾未触及，四肢暖。根据患儿目前病情，应首先进行的检查是","o":["血培养","大便培养","血电解质分析","肝肾功能检查","脑脊液检查"],"a":2,"e":"婴儿呕吐、水样便伴唇干、皮肤干燥、前囟凹陷，提示中度以上脱水，首先应查血电解质以明确脱水性质和有无低钾、低钠等紊乱。血培养与大便培养针对病原学；肝肾功能非脱水首要检查；无脑膜刺激征，暂不必查脑脊液"},{"q":"患者，女，29岁。清理房间后出现鼻痒、喷嚏，继而出现胸闷、呼吸困难、端坐位，两肺布满哮鸣音。最可能的诊断是","o":["急性支气管炎","支气管哮喘","急性左心衰竭","肺炎","气胸"],"a":1,"e":"清理房间接触尘螨后鼻痒、喷嚏，继而胸闷、呼吸困难、端坐呼吸伴双肺哮鸣音，符合支气管哮喘急性发作。急性支气管炎起病缓、无典型哮鸣；急性左心衰竭有心脏病史及湿啰音；肺炎有发热实变；气胸为单侧呼吸音减弱"},{"q":"患儿，男，1岁。间歇性抽搐3小时。查体：双侧上肢肌肉强直性肌痉挛，呈“助产手”，该患者的诊断最可能是","o":["小儿癫痫","婴儿痉挛","低钙血症","高热惊厥","重症感染"],"a":2,"e":"1岁患儿间歇性抽搐，双上肢强直性肌痉挛呈助产士手，是手足搐搦症的典型表现，由低钙血症所致。小儿癫痫与婴儿痉挛属大脑功能障碍；高热惊厥伴发热；重症感染有中毒症状，均无此典型手部姿势"},{"q":"患者，女，23岁。头痛伴剧烈呕吐2天。1个月前诊断为急性淋巴细胞白血病，行化疗后骨髓恢复正常。查体：浅表淋巴结不大，心肺无异常。颈项强直，双侧Babinski征阳性。患者最可能的病因是","o":["病毒性脑炎","血管性头痛","颅内白血病浸润","蛛网膜下腔出血","癫痫病发作"],"a":2,"e":"急性淋巴细胞白血病化疗缓解后出现头痛、呕吐、颈项强直及双侧病理征，提示白血病细胞浸润中枢神经系统。病毒性脑炎有发热及脑脊液改变；蛛网膜下腔出血无白血病缓解后复发背景；血管性头痛与癫痫无脑膜刺激征"},{"q":"患者，男，52岁，诉心悸头晕1个月。心电图示：QRS波群宽大，时限0.13s，P波与QRS波无关，P波多于QRS波群，心室率40次/min，律规整。可诊断为","o":["交界区逸搏心律","窦性心动过缓","二度房室传导阻滞","未下传的房性期前收缩呈二联律","三度房室传导阻滞，室性逸搏心律"],"a":4,"e":"QRS宽大0.13s、P波与QRS无关且P波多于QRS、心室率40次/min且规整，符合三度房室传导阻滞伴室性逸搏心律。交界性逸搏心律QRS窄、频率40～60次/min；窦缓P与QRS相关；二度阻滞有固定PR间期及脱漏；未下传房早为间歇出现"},{"q":"患者，女，45岁。运动中感觉眩晕、恶心、乏力，随即意识丧失，摔倒在地，3min后自行恢复正常。无大小便失禁，缓解后无意识及肢体功能障碍，其最可能的病因是","o":["短暂脑缺血发作","低血糖症","心率失常","迷走神经张力异常增高","分离（转换）性障碍"],"a":0,"e":"运动中突发眩晕、乏力、意识丧失，3分钟自行恢复且无后遗症，结合教材将短暂性脑缺血发作列为脑源性晕厥病因，考虑TIA。低血糖有饥饿出汗；心律失常多伴心悸；迷走神经张力增高常由体位或情绪诱发；分离障碍无自限性典型过程"},{"q":"患者，女，50岁，发现血脂升高、蛋白尿、周身水肿10余年。查体发现少量胸腔积液。实验室检查：清蛋白20g/L，三酰甘油7.22mmol/L，总胆固醇8.34mmol/L，尿蛋白（＋＋＋）。符合该患者胸腔积液特点的是","o":["浑浊","葡萄糖低于血糖水平","LDH＞200U/L","能自凝","积液蛋白/血清总蛋白＜0.5"],"a":4,"e":"大量蛋白尿、低白蛋白及高脂血症符合肾病综合征，胸腔积液为漏出液，积液蛋白/血清总蛋白＜0.5。浑浊、葡萄糖低于血糖、LDH＞200U/L及能自凝均为渗出液特点，不符合低蛋白血症所致漏出液"},{"q":"患者，女，28岁。恶心、尿色变黄6天，体检发现巩膜中度黄染，肝肋下2cm可及，血谷丙转氨酶840U/L，总胆红素85μmol/L。本例抗HAV-IgM阳性，抗HBs阳性，抗HBc阳性，最可能的病原学诊断是","o":["甲型病毒性肝炎","乙型病毒性肝炎","甲型病毒性肝炎和乙型病毒性肝炎重叠感染","戊型病毒性肝炎","丙型病毒性肝炎"],"a":0,"e":"抗HAV-IgM阳性是近期甲型肝炎病毒感染的特异性指标，抗HBs与抗HBc阳性仅提示既往感染乙肝且已恢复，故本次发病为甲型病毒性肝炎。乙肝需HBsAg阳性；重叠感染须有现症乙肝证据；戊肝、丙肝无相应抗体支持"},{"q":"某2岁患儿，前额突出，头顶平坦呈方形，出汗多。该患儿可能性最大的疾患是","o":["脑积水","佝偻病","甲状腺功能减退症","肢端肥大症","库欣病"],"a":1,"e":"2岁患儿前额突出、头顶平坦呈方形，伴出汗多，为佝偻病方颅的典型表现。脑积水为巨颅伴落日现象；甲状腺功能减退为呆小症伴智能落后；肢端肥大症与库欣病均见于成人，与患儿年龄不符"},{"q":"患者，男，45岁。半天前跑步后出现右下腹疼痛伴发热、畏寒，6小时前转至脐周疼痛。此时最应注意的腹部体征是","o":["脐周有无压痛","McBurney点是否压痛","墨菲征是否阳性","季肋点有无压痛","肠鸣音是否改变"],"a":1,"e":"腹痛由右下腹转移至脐周虽不典型，但仍需警惕急性阑尾炎，应重点检查McBurney点有无固定压痛与反跳痛。墨菲征针对胆囊炎；季肋点用于肾脏病变；肠鸣音改变提示肠梗阻或腹泻，均非本例首要"},{"q":"患者，女，36岁。半年前开始发现面色逐渐变白，甲床颜色亦变浅。1周前开始出现活动后易疲乏来医院就诊。既往体检曾发现子宫肌瘤，未处理。该患者就诊时的面容可能是","o":["急性病容","慢性病容","黏液水肿面容","贫血面容","苦笑面容"],"a":3,"e":"面色及甲床逐渐变白、活动后疲乏，伴子宫肌瘤史，提示慢性失血性贫血，呈贫血面容，表现为面色苍白、唇舌色淡、表情疲惫。急性病容见急性感染；黏液水肿面容见甲减；苦笑面容见破伤风；慢性病容为消耗性表现"},{"q":"患者，男，63岁。慢性咳嗽、咳痰伴呼吸困难20年，今晨用力咳嗽后突然出现呼吸困难加重，发绀，不能平卧。查体右侧呼吸动度减弱伴叩诊为鼓音、呼吸音消失。该患最有可能的诊断是","o":["左侧肺不张","右侧胸腔积液","右下大叶性肺炎","右侧气胸","右侧肺不张"],"a":3,"e":"慢支肺气肿患者用力咳嗽后突发呼吸困难、发绀，右侧叩诊鼓音、呼吸音消失，提示右侧气胸。肺不张叩诊浊音、气管移向患侧；胸腔积液叩诊实音；大叶性肺炎叩诊浊音并有湿啰音；左侧肺不张体征应在左侧"},{"q":"患者，女，33岁。因面部红斑1年入院，考虑诊断为系统性红斑狼疮。患者既往有多次流产病史，实验室检查示ACA＋，APTT延长。目前考虑诊断为","o":["系统性红斑狼疮合并抗心磷脂抗体综合征","Evans综合征","血管栓塞","TTP","HUS"],"a":0,"e":"系统性红斑狼疮患者多次流产、抗心磷脂抗体阳性及APTT延长，符合合并抗心磷脂抗体综合征，抗体致血液高凝并引起流产。Evans综合征为溶血加血小板减少；TTP与HUS为微血管病性溶血；血管栓塞是其后果而非独立诊断"},{"q":"患者，男，20岁。多次于郊外春游时出现胸闷、窒息感，呼气性呼吸困难，回家休息后好转。该患发作时最不可能出现的体征是","o":["呼吸运动度变小","语音共振减弱","叩诊呈过清音","双肺满布干啰音","呼吸音增强"],"a":4,"e":"该患郊外春游反复发作胸闷、呼气性呼吸困难、可自行缓解，符合支气管哮喘。发作时胸廓胀满呈吸气位，呼吸动度变小，语音共振减弱，叩诊呈过清音，两肺满布干啰音，肺泡呼吸音普遍减弱而非增强。呼吸音增强见于运动、发热、贫血或酸中毒等通气增强时，一侧增强多为对侧病变后的代偿，与哮喘气道受限相反"},{"q":"患者，女，50岁，3次分娩史。半年来，咳嗽、下楼梯时出现尿失禁症状。该患者尿失禁为","o":["真性尿失禁","压力性尿失禁","持续性尿失禁","间歇性尿失禁","急迫性尿失禁"],"a":1,"e":"多产妇女膀胱颈部及尿道括约肌功能受损，咳嗽、下楼梯等腹压骤增时尿液不自主溢出，为压力性尿失禁，轻度仅在咳嗽打喷嚏抬重物时溢尿。真性尿失禁为括约肌完全丧失致尿液持续流出，与腹压无关；急迫性尿失禁伴强烈尿急、来不及如厕，属逼尿肌无抑制收缩；充溢性尿失禁因尿潴留膀胱过度充盈后溢出"},{"q":"一男性患者，30岁。淋雨后出现咳嗽，咯铁锈色痰，发热，右侧胸痛。查体：BP 130/80mmHg，右肺中上野叩诊实音。该患者最不可能出现下列哪种体征","o":["右肺可闻及胸膜摩擦音","右肺触觉语颤增强","右肺可闻及管状呼吸音","肺泡呼吸音增强","呼吸浅快"],"a":3,"e":"淋雨后寒战高热、咳铁锈色痰、胸痛、局部叩诊实音，符合大叶性肺炎实变期。实变肺组织传导良好，可闻支气管呼吸音、触觉语颤增强，累及胸膜可见胸膜摩擦音，发热缺氧使呼吸浅快。肺泡呼吸音在实变区减弱或消失、被病理性支气管呼吸音取代，不可能增强；单侧增强只见于对侧病变后的代偿"},{"q":"患者，男，20岁。右侧呼吸运动减弱，语颤消失，右下叩诊实音，实音区上方闻及支气管呼吸音。首先应考虑为","o":["支气管哮喘","大叶性肺炎","支气管扩张","胸腔积液","支气管肺癌"],"a":3,"e":"右侧呼吸运动减弱、语颤消失、叩诊实音提示胸腔积液；积液压迫肺组织形成压迫性肺不张，肺变致密利于支气管音传导，故积液区上方可闻支气管呼吸音，但较弱而遥远。大叶性肺炎叩诊浊音、语颤增强而非消失；气胸叩诊鼓音、呼吸音消失；支气管肺癌以局限喘鸣或阻塞体征为主，均无积液区实音加语颤消失的组合"},{"q":"患者，男，22岁，打篮球时突然呼吸困难，明确诊断为右侧大量气胸。关于该患者的体格检查，描述错误的是","o":["右侧胸廓膨满","气管移向左侧","右侧叩诊为鼓音","右侧呼吸音弱","右侧可闻及支气管呼吸音"],"a":4,"e":"大量气胸时气体进入胸膜腔，患侧胸廓膨满、呼吸运动减弱，气管心脏被推向健侧即左侧，叩诊呈鼓音，呼吸音减弱或消失，这些均符合。支气管呼吸音是肺实变或压迫性肺不张致肺组织致密、支气管音传导增强所致；气胸时肺被压缩含气减少、传导障碍，不可能闻及，它可见于大叶性肺炎或大量心包积液的Ewart征"},{"q":"患者，女，46岁，2型糖尿病病史10年，1天前明确诊断为糖尿病酮症酸中毒，该患者最可能出现的呼吸改变是","o":["规则呼吸后出现长周期呼吸停止又开始呼吸","呼吸深快","正常的呼吸节律中插入1次深大呼吸","吸气相突然中止，呼吸运动短暂的突然受到抑制","一种由浅慢逐渐变为深快，然后再由深快转为浅慢，随之出现一段呼吸暂停后，又开始上述变化的周期性呼吸"],"a":1,"e":"糖尿病酮症酸中毒属严重代谢性酸中毒，细胞外液碳酸氢根不足、pH降低，通过深快呼吸排出CO2代偿，称库斯莫尔呼吸。比奥呼吸为规则呼吸后出现长周期呼吸暂停再开始，见于颅内压增高、呼吸抑制；潮式呼吸由浅慢渐深快再转浅慢并暂停，见于脑皮质损伤、心衰；正常节律中插入深大呼吸为叹息样呼吸，均非酸中毒表现"},{"q":"患者突然高热，右侧胸痛，下列哪项有助于单纯少量胸腔积液与单纯肺炎实变的鉴别","o":["呼吸运动","气管位置","叩诊音","胸膜摩擦音","肺泡呼吸音"],"a":3,"e":"胸膜摩擦音为纤维蛋白性胸膜炎时脏壁两层胸膜随呼吸摩擦产生，少量积液时两层尚未完全分开仍可闻及，肺炎实变累及胸膜亦可出现，但随积液增多摩擦音消失、吸收过程中再出现，这一动态变化有助于鉴别。呼吸运动、叩诊音在少量积液与实变时可重叠；气管位置多居中无鉴别价值；肺泡呼吸音两者均可减弱，均不如摩擦音特异"},{"q":"一位发热患者，体温在39℃以上，未用任何退热降温措施，24小时内体温波动达2℃以上，最低时体温仍高于正常。这种热型是","o":["稽留热","弛张热","间歇热","波浪热","回归热"],"a":1,"e":"弛张热又称败血症热型，体温常在39℃以上，24小时内波动超过2℃，但最低仍高于正常，见于败血症、风湿热、重症肺结核及化脓性炎症。稽留热维持39～40℃数天至数周、24小时波动不超过1℃，见于大叶性肺炎、伤寒高热期；间歇热骤升至高峰后降至正常、高热与无热期交替，见于疟疾；波浪热渐升渐降呈波浪状，见于布鲁菌病"},{"q":"患者，女，45岁，外阴瘙痒伴泡沫样分泌物，白带增多变黄绿色。镜检分泌物，考虑为寄生虫感染，下列哪种为妇科常见","o":["丝虫","阴道滴虫","溶组织变形虫","阿米巴原虫","弓形虫"],"a":1,"e":"外阴瘙痒、泡沫状黄绿色白带、镜检见寄生虫，符合滴虫性阴道炎，病原体为阴道毛滴虫，属妇科常见寄生虫感染。丝虫微丝蚴见于乳糜尿，多由标本污染而来；溶组织阿米巴主要致阿米巴痢疾、见于粪便；弓形虫为细胞内原虫，多经血清学或组织检查诊断，均非阴道分泌物中的常见寄生虫"},{"q":"患者，男，78岁，头痛伴意识障碍4小时，头颅CT提示蛛网膜下腔出血，以下心电图表现和脑出血相关的是","o":["T波高耸","宽而深的倒置T波，往往伴QT延长","窄而深的倒置T波，往往伴QT缩短","T波表现为类似冠状动脉粥样硬化性心脏病的“冠状T”","T波平坦"],"a":1,"e":"急性脑血管意外如蛛网膜下腔出血、脑出血可引起宽而深的倒置T波，常伴显著QT间期延长，系脑部损伤致心肌复极异常。高耸T波多见于高钾血症或急性心肌梗死超急性期；冠状T为对称深倒置T波，典型见于心肌缺血或心梗；窄而深倒置伴QT缩短不符合脑源性改变，T波平坦无特异性"},{"q":"患儿，男，8岁。受凉后突发左侧脸肿胀，张口受限。查体：左侧以耳垂为中心颜面肿胀，有压痛，导管处加压未见脓性分泌物。血常规正常。可能的诊断是","o":["急性流行性腮腺炎","急性化脓性腮腺炎","腮腺肿瘤","蚊虫叮咬","外伤"],"a":0,"e":"儿童受凉后以耳垂为中心腮腺迅速肿胀、压痛，导管口无脓性分泌物，血常规正常，符合急性流行性腮腺炎。急性化脓性腮腺炎多为单侧、导管口溢脓、白细胞升高；腮腺肿瘤病程缓慢、质硬无痛；蚊虫叮咬、外伤均有明确局部因素、肿胀局限于叮咬或外伤处，均与本例不符"},{"q":"患者，男，45岁。低热、乏力、食欲缺乏1周。查体：皮肤黏膜黄染，肝肋下2cm，脾肋下1cm。实验室检查：总胆红素50μmol/L，结合胆红素20μmol/L，非结合胆红素30μmol/L，尿胆原（＋＋），尿胆红素（－）。该患者黄疸最可能的原因是","o":["溶血性黄疸","肝细胞性黄疸","梗阻性黄疸","黄疸性质不明","药物性黄疸"],"a":1,"e":"总胆红素、结合与非结合胆红素均增高，结合胆红素/总胆红素约40%处于20%～50%区间，尿胆原增高，符合肝细胞性黄疸，伴肝脾大及肝功能受损。溶血性黄疸以非结合胆红素增高为主、比值＜20%、尿胆红素阴性；梗阻性黄疸以结合胆红素增高为主、比值＞50%、尿胆红素强阳性而尿胆原减少"},{"q":"患者，男，30岁，因四肢瘀斑、牙龈出血1周入院。查体：贫血貌，皮肤黏膜多发出血，胸骨下端轻度压痛。实验室检查：白细胞增高，分类见幼稚细胞，血红蛋白90g/L，血小板12×109/L，ATPP 40s（对照 45s），PT 13s（对照 11s），TT 24s（对照 13s），D-二聚体 5.3mg/L（参考范围0～0.25mg/L）。以下判断正确的是","o":["ATPP和PT正常，D-二聚体增高，考虑出血导致继发改变，可不需要处理","患者D-二聚体增高，说明高凝状态，可考虑使用华法林抗凝治疗","TT延长，有出血风险，应该加用凝血酶","尽快输注血小板和纤维蛋白原输注","尽快输注血小板，为避免高凝状态，不应该输注纤维蛋白原"],"a":3,"e":"急性白血病伴广泛出血、血小板显著降低、D-二聚体明显增高及凝血时间异常，符合弥散性血管内凝血，因凝血因子与纤维蛋白原大量消耗，需在治疗原发病基础上补充血小板与纤维蛋白原。D-二聚体增高提示继发纤溶亢进而非单纯高凝，华法林抗凝会加重出血；TT延长、纤维蛋白原消耗时补充纤维蛋白原正是纠正措施，单用凝血酶无益"},{"q":"患者，男，55岁，肥胖体型，反复多关节肿痛20年，平时未重视。1周前再次于大量饮酒后复发，尤以右侧第一跖趾关节疼痛明显。查体可见右侧跖趾关节周围大小不一的灰白色结节，应诊断为","o":["风湿结节","痛风结节","结节性红斑","动脉炎结节","Osler结节"],"a":1,"e":"中老年男性，饮酒后第一跖趾关节急性剧痛、反复多年，关节周围灰白色结节，符合痛风结节即痛风石，为尿酸盐结晶在皮下沉积所致，好发于耳郭及跖趾、指趾关节。风湿结节多见于类风湿关节炎、位于关节伸侧；结节性红斑好发小腿伸侧、为疼痛性红色结节；Osler结节见于感染性心内膜炎、位于指趾末端"},{"q":"患者，男，78岁，高血压病史30余年，因“反复发作胸闷、气紧4年余，加重伴双下肢水肿3天”入院。查体：呼吸急促，大汗淋漓，面色苍白。该患者的体位可能是","o":["被动体位","强迫坐位","强迫侧卧位","强迫仰卧位","辗转体位"],"a":1,"e":"高血压心脏病、心衰发作，胸闷气紧、双下肢水肿、大汗淋漓而端坐呼吸，为强迫坐位。该体位可协助呼吸肌运动、加大膈肌活动度、增加肺通气，并减少回心血量、减轻心脏负荷。被动体位见于极度衰竭或意识丧失不能自行调整者；强迫侧卧位见于一侧胸膜炎、大量胸腔积液；辗转体位见于胆石症、肾绞痛"},{"q":"年轻男性，发热5天，每天体温维持在39℃～41℃，24小时内体温波动相差不超过1℃。体检发现腹部玫瑰疹，肝脾大。最可能的诊断为","o":["大叶肺炎","流行性出血热","风湿热","疟疾","伤寒"],"a":4,"e":"持续稽留热39～41℃、24小时波动不超过1℃，伴腹部玫瑰疹、肝脾大，符合伤寒。大叶性肺炎虽为稽留热，但有咳嗽咳铁锈色痰、肺部实变体征，无玫瑰疹；流行性出血热有发热、出血、肾损害五期经过；风湿热为弛张热伴游走性关节炎；疟疾为间歇热，寒战高热与无热期交替"},{"q":"患者，女，40岁。咳嗽、气短1个月，伴午后发热、盗汗，右侧胸痛。查体：气管左移，右侧胸廓饱满，叩诊实音。最不可能出现的体征是","o":["右侧呼吸音减弱","右侧触觉语颤减弱","可听到支气管呼吸音","可听到胸膜摩擦音","右侧可听到支气管肺泡呼吸音"],"a":3,"e":"咳嗽气短、午后低热盗汗、右侧胸痛，气管左移、右胸饱满、叩诊实音，符合右侧大量胸腔积液。积液量大时脏壁胸膜被分开，胸膜摩擦音消失，仅在少量积液或吸收过程中两层胸膜再接触时才出现；积液区呼吸音、语颤减弱，积液区上方因压迫性肺不张可闻支气管呼吸音或支气管肺泡呼吸音"},{"q":"患儿，女，8岁。发热，鼻出血，四肢大量瘀点瘀斑2天，发病前1周有感冒史，血小板15×109/L，骨髓增生活跃，巨核细胞增多，成熟受阻。最可能的诊断为","o":["急性原发免疫性血小板减少症","再生障碍性贫血","慢性原发免疫性血小板减少症","过敏性紫癜","弥散性血管内凝血"],"a":0,"e":"儿童病毒感染后急性起病，皮肤黏膜广泛瘀点瘀斑、血小板显著减少，骨髓巨核细胞增多伴成熟受阻，符合急性原发免疫性血小板减少症。慢性ITP病程长、起病隐袭；再生障碍性贫血全血细胞减少、骨髓增生低下、巨核细胞减少；过敏性紫癜血小板正常、以对称性紫癜为主；DIC有凝血因子消耗、PT延长及D-二聚体增高"},{"q":"患者，女，27岁。3天前淋雨后寒战、高热，胸痛，咳嗽，咳铁锈色痰。考虑诊断为","o":["干酪性肺炎","阻塞性肺炎","肺脓肿","大叶性肺炎","病毒性肺炎"],"a":3,"e":"淋雨后寒战高热、胸痛、咳铁锈色痰，为大叶性肺炎的典型表现，肺炎链球菌感染致肺泡急性炎症实变。干酪性肺炎起病较缓、有结核中毒症状、痰找结核杆菌阳性；阻塞性肺炎有肿瘤等阻塞因素、反复同一部位；肺脓肿咳大量脓臭痰、影像有空洞液平；病毒性肺炎以干咳为主、痰少"},{"q":"患者，女，30岁，因怕热、多汗、心悸、多食、消瘦4个月就诊。关于甲状腺检查，错误的是","o":["注意观察甲状腺的大小和对称性","要先视诊后再进行触诊","检查时嘱被检查者做呼吸动作，可见甲状腺随呼吸动作而向上移动","检查时嘱被检查者做吞咽动作，可见甲状腺随吞咽动作而向上移动","如不易辨认，嘱被检查者两手放于枕后，头向后仰，再进行观察即较明显"],"a":2,"e":"甲状腺位于气管前方，借悬韧带连于喉与气管，吞咽时随喉和气管上下移动，故嘱做吞咽动作可见其向上移动，不易辨认时两手放枕后、头后仰更易观察，视诊后再触诊并注意大小与对称性。随呼吸移动的是颈部气管或胸腺等结构，甲状腺不随呼吸上下移动，此项描述错误"},{"q":"患者，男，70岁，前列腺癌病史2年。为评估血栓前状态，下列可用来评估纤溶活性的检查中，有利于区分原发纤溶和继发纤溶的是","o":["D-二聚体","FDPs","血浆组织型纤溶酶原激活剂","血浆纤溶酶原激活抑制剂-1活动测定","优球蛋白溶解时间"],"a":0,"e":"D-二聚体是交联纤维蛋白经纤溶酶降解的特异产物，继发性纤溶如DIC、血栓时增高，原发性纤溶时纤维蛋白原未经交联即被降解、D-二聚体不增高，故可鉴别两者。FDPs为纤维蛋白（原）降解产物，原发与继发纤溶均增高、不能区分；t-PA、PAI-1反映纤溶激活与抑制；优球蛋白溶解时间反映总体纤溶活性，均无鉴别价值"},{"q":"患者，男，66岁。因胸闷2小时入院，完善冠脉造影，考虑诊断为急性心肌梗死。除常见的肌酶增高外，可以增高的指标还有","o":["TAT","AT","PT","APTT","TT"],"a":0,"e":"急性心肌梗死为急性血栓事件，凝血系统激活，凝血酶生成增多并与抗凝血酶结合形成凝血酶-抗凝血酶复合物即TAT，故增高。AT为抗凝物质、消耗后减低；PT、APTT、TT反映凝血途径筛选，多无显著缩短，不能反映凝血酶生成的早期激活，不作为急性心梗的敏感指标"},{"q":"患者，女，34岁，近1年来反复上腹痛，进食半小时后腹痛明显，伴反酸、胃灼热，1小时前突发上腹部剧烈疼痛，伴恶心、呕吐。该患者查体所见除外下列哪项","o":["肠鸣音消失","肠型","腹式呼吸减弱","板状腹","压痛、反跳痛"],"a":1,"e":"溃疡病史、突发上腹剧痛伴呕吐，提示消化性溃疡穿孔致急性弥漫性腹膜炎，可见板状腹、全腹压痛反跳痛、腹式呼吸减弱，肠鸣音因肠麻痹而消失。肠型为肠梗阻时肠管扩张蠕动增强在腹壁的可见轮廓、伴肠鸣音亢进，与穿孔后肠鸣音消失、肠管麻痹相反，不会出现"},{"q":"一剧烈头痛患者入院。接诊医生查体发现患者右侧瞳孔散大，右侧眼睑下垂，直接对光反射消失。考虑患者损伤的神经是","o":["滑车神经","动眼神经","展神经","交感神经","面神经"],"a":1,"e":"右侧瞳孔散大、上睑下垂、直接对光反射消失，提示动眼神经麻痹。动眼神经含副交感纤维支配瞳孔括约肌，损伤后瞳孔散大、对光反射消失，并支配提上睑肌及大部分眼外肌。滑车神经支配上斜肌、损伤为眼球向下外运动受限；展神经支配外直肌、损伤为外展受限；交感神经麻痹表现为瞳孔缩小、眼睑下垂的Horner征；面神经支配表情肌"},{"q":"患者，男，66岁，胸闷、气短10年，加重伴呼吸困难2天入院。既往冠心病史多年。查体发现少量胸腔积液。那么该患者的胸腔积液LDH可能为","o":["＜100IU","＜150IU","＜200IU","＞200IU","＞300IU"],"a":2,"e":"冠心病心衰所致胸腔积液为漏出液，LDH＜200U/L，积液/血清LDH＜0.6，蛋白含量低，因静水压升高或胶体渗透压降低形成、无炎症。渗出液LDH＞200U/L、积液/血清LDH＞0.6，见于感染、肿瘤、结核等；＞300IU更支持恶性或化脓性积液"},{"q":"患者，女，35岁。1个小时前因与家人不和，自服药水1小瓶，把药瓶打碎扔掉。家人发现后5分钟患者腹痛、恶心，并呕吐1次，吐出物有大蒜味，逐渐神志不清，急送医院就诊，病后大小便失禁，出汗多。检查该患者瞳孔，可能发现何种体征","o":["双侧瞳孔放大","双侧瞳孔缩小","双侧瞳孔大小不等","瞳孔对方反射消失","集合反射消失"],"a":1,"e":"服农药后腹痛、呕吐、大蒜味、出汗、神志不清、大小便失禁，为有机磷农药中毒，毒蕈碱样作用致瞳孔括约肌收缩，出现双侧瞳孔缩小。瞳孔散大见于阿托品等抗胆碱药、青光眼绝对期或濒死状态；双侧瞳孔大小不等提示颅内病变如脑疝、脑外伤；对光反射消失、集合反射消失非本例特征"},{"q":"一名17岁的糖尿病患者来到急诊，为Kussmaul呼吸，床旁血气：pH 7.05，HCO3- 5mEq/L，PaCO2 12mmHg，PaO2 108mmHg。该患者可能发生了","o":["严重的代谢性酸中毒部分代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒失代偿期","呼吸性酸中毒与低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"糖尿病患者Kussmaul呼吸，pH 7.05明显降低、HCO3-仅5mEq/L极度减少，原发为代谢性酸中毒；PaCO2 12mmHg低于正常提示呼吸代偿排出CO2，但pH未恢复正常，故为部分代偿期。呼吸性碱中毒应以PaCO2降低为原发、HCO3-继发降低；代谢性碱中毒pH升高；本例PaO2 108mmHg不支持低氧血症，也非静脉血"},{"q":"患者，男，40岁。上腹痛1天，腹部检查右下腹McBurney点有固定压痛和反跳痛，应首先考虑的疾病是","o":["盲肠肿瘤","输尿管结石","急性阑尾炎","肠系膜淋巴结炎","前列腺癌伴腹腔转移"],"a":2,"e":"转移性右下腹痛、右下腹McBurney点固定压痛和反跳痛，是急性阑尾炎的典型体征，因炎症波及浆膜和壁层腹膜所致。盲肠肿瘤多为慢性过程、可触及包块；输尿管结石为阵发性绞痛伴血尿、无腹膜刺激征；肠系膜淋巴结炎多见于儿童、先有上呼吸道感染、压痛不固定；前列腺癌腹腔转移属晚期、有排尿症状"},{"q":"患者，男，18岁。右膝关节肿胀疼痛，伴潮热盗汗3个月。最可能的疾病是","o":["类风湿关节炎","创伤性关节炎","骨肿瘤","关节结核","化脓性关节炎"],"a":3,"e":"儿童及青壮年负重大关节如脊柱、髋、膝肿痛，伴低热盗汗、乏力，符合关节结核，活动期结核中毒症状明显，关节呈梭形肿胀。类风湿关节炎多为对称性小关节、晨僵；创伤性关节炎有外伤史；骨肿瘤疼痛夜间明显、生长快；化脓性关节炎起病急、红肿热痛显著、全身中毒症状重"},{"q":"患者，男，35岁，阵发性心悸3年，发作时持续半小时至5小时不等，休息可终止。本次发作时心律齐，180次/min。下列哪项有助于室上性心动过速的诊断","o":["心电图示宽大畸形QRS波","按压颈动脉窦能终止发作","既往冠状动脉粥样硬化性心脏病、心绞痛病史","心电图上发现室性融合波","可见房室分离"],"a":1,"e":"阵发性室上性心动过速突发突止、心律绝对规整、心率150～250次/分，刺激迷走神经如按压颈动脉窦可终止发作。宽大畸形QRS波、室性融合波、房室分离均为室性心动过速的特点；既往冠心病心绞痛史提示器质性心脏病但不是室上速诊断依据，且室上速QRS一般正常"},{"q":"患者，男，60岁。突发右侧胸痛、呼吸困难3小时。右侧股骨头坏死2个月，未行手术治疗。查体：巩膜黄染，右肺呼吸音低，心脏无异常，双下肢轻度凹陷性水肿。患者最可能出现的并发症是","o":["自发性气胸","肺梗死","脑梗死","感染性心内膜炎","急性心肌梗死"],"a":1,"e":"长期制动如股骨头坏死未手术易形成下肢深静脉血栓，突发胸痛、呼吸困难、发绀，提示肺梗死即肺栓塞，为血栓脱落阻塞肺动脉所致。自发性气胸多有肺大疱、叩诊鼓音、呼吸音消失；脑梗死以神经定位体征为主；感染性心内膜炎有发热、杂音、栓塞现象；急性心肌梗死有心电图及心肌酶动态改变"},{"q":"患者，男，57岁，头痛剧烈，喷射性呕吐，体检示皮肤出血性瘀斑，脑膜刺激征（＋）。培养此病原菌应选用","o":["巧克力色血琼脂培养基","鲍-金培养基","罗氏培养基","吕氏培养基","远藤培养基"],"a":0,"e":"剧烈头痛、喷射性呕吐、皮肤出血性瘀斑、脑膜刺激征阳性，符合流行性脑脊髓膜炎，病原菌为脑膜炎奈瑟菌，培养需巧克力即加热血琼脂培养基并在CO2环境。鲍-金培养基用于百日咳杆菌；罗氏培养基用于结核分枝杆菌；吕氏培养基用于白喉棒状杆菌；远藤培养基用于肠道细菌"},{"q":"患者查体时发现肢体僵硬，肌肉坚实，上肢伸直时存在明显阻力增加。考虑患者存在以下哪个体征","o":["肌力增加","肌张力增加","震颤","病理征阳性","脑膜刺激征阳性"],"a":1,"e":"肢体僵硬、肌肉坚实、被动伸直时阻力增加，为肌张力增高，即静息时肌肉紧张度及被动运动阻力增大，本质是牵张反射增强。肌力是主动运动的力量、与阻力无关；震颤为不自主节律性抖动；病理征阳性指锥体束征如巴宾斯基征；脑膜刺激征为颈强直、克尼格征等，均非本例表现"},{"q":"患者，男，50岁，田间劳动后突然跌倒，随即昏迷，1天后出现发热。查体：T 37.9℃，BP 160/95mmHg。该患者最可能的诊断是","o":["巴比妥类中毒","中暑","流行性脑脊髓膜炎","脑出血","流行性乙型脑炎"],"a":3,"e":"活动中突然跌倒昏迷、随后发热、血压升高，符合脑出血，先昏迷后发热是中枢性发热的特点。流行性脑脊髓膜炎、流行性乙型脑炎、中暑均为先发热后昏迷；巴比妥类中毒有误服药物史、先昏迷后可有体温降低。脑出血发热系出血刺激体温调节中枢或吸收热所致"},{"q":"患者，男，55岁，心电图检查显示胸导联T波直立，u波倒置，下列说法正确的是","o":["多提示心肌病","多提示冠状动脉粥样硬化性心脏病","多提示肺源性心脏病","多提示心包积液","多提示低钾血症"],"a":1,"e":"胸导联T波直立伴u波倒置，是心肌缺血的表现，多提示冠状动脉粥样硬化性心脏病，u波倒置与心肌缺血或心室负荷改变相关。低钾血症表现为T波低平或倒置、u波增高而非倒置；心肌病、肺源性心脏病、心包积液各有相应心电图与临床特征，均非u波倒置的典型病因"},{"q":"一高楼跌落患者送入医院，医师接诊后查体发现患者双下肢完全不能移动，双上肢活动正常，小便潴留，双侧巴宾斯基征阳性。考虑患者损伤","o":["大脑皮层","颈段脊髓","胸段脊髓","脊髓圆锥","马尾神经"],"a":2,"e":"双下肢截瘫、双上肢正常、尿潴留、双侧病理征阳性，提示胸段脊髓横贯性损害，因病变平面以下运动、感觉及括约肌功能障碍。颈段脊髓损伤累及四肢；脊髓圆锥与马尾神经损伤表现为会阴部感觉障碍、括约肌障碍但无病理征、多为弛缓性瘫痪；大脑皮层病变多为单侧偏瘫"},{"q":"某幼儿在玩耍时，突然出现烦躁不安、唇发绀、呼吸困难，查体呈三凹征，考虑可能的原因是","o":["气管异物","呼吸衰竭","大量胸腔积液","自发性气胸","急性支气管炎"],"a":0,"e":"幼儿玩耍中突发呼吸困难、发绀、烦躁及吸气性三凹征，提示上呼吸道即气管异物阻塞，吸气性呼吸困难伴三凹征为其典型表现。呼吸衰竭为多种疾病终末状态；大量胸腔积液、自发性气胸多见于较大儿童、叩诊及呼吸音改变不同；急性支气管炎起病较缓、以咳嗽为主、无骤发窒息"},{"q":"患者，男，32岁，因腹痛、腹胀入院。经行肠系膜动脉造影等检查确诊为小肠动脉血栓栓塞，经溶栓治疗治愈。1个月后患者出现左下肢肿胀、疼痛，彩色多普勒示左髂内静脉血栓，辅助检查示AT降低，APTT、PT正常，考虑诊断为","o":["再生障碍性贫血","先天性AT缺陷症","血友病","肝脏疾病","白血病"],"a":1,"e":"反复动静脉血栓形成如肠系膜动脉及髂静脉血栓，实验室见抗凝血酶AT降低而APTT、PT正常，符合遗传性抗凝血酶缺陷症。AT为重要生理性抗凝物质，缺乏时凝血酶及因子Ⅹa等不能被有效灭活、易致血栓。血友病为因子Ⅷ或Ⅸ缺乏、APTT延长；肝脏疾病多有多种凝血因子合成减少、PT延长；再障、白血病以血细胞异常为主"},{"q":"患者查体发现伸肌和屈肌肌张力均增高，做被动运动时各个方面肌力增加是均匀一致。考虑损伤以下哪个部位","o":["锥体外系","周围神经","四肢肌肉","神经根","锥体系"],"a":0,"e":"伸肌与屈肌肌张力均增高、被动运动各方向阻力均匀一致，为铅管样强直，属锥体外系即基底节损害表现，伴震颤时呈齿轮样强直。锥体系损害表现为痉挛状态即折刀现象，起始阻力大、终末突然减弱；周围神经、神经根损害致肌张力减低、肌力减退；四肢肌肉本身病变亦为肌力下降而非阻力均匀增高"},{"q":"患者，男，56岁。胸骨后压榨性疼痛半天口含硝酸甘油不缓解而就诊，心电图显示Ⅱ、Ⅲ、aVF导联出现异常Q波，ST段弓背抬高，查体：BP 150/90mmHg，心率92次/分。病变部位是","o":["下壁","前壁","后壁","前侧壁","广泛前壁"],"a":0,"e":"Ⅱ、Ⅲ、aVF导联出现异常Q波、ST段弓背抬高，定位为急性下壁心肌梗死。前壁梗死异常Q波见于V1～V4；广泛前壁为V1～V5多数胸导联；后壁梗死V7～V9出现异常Q波、V1～V2出现高R波与ST压低的对应改变；前侧壁为Ⅰ、aVL及V5、V6导联改变"},{"q":"患者，男，19岁。体检发现：气管居中，两侧胸廓饱满，呼吸运动减弱，两肺叩诊呈过清音，呼气时间延长，可闻及哮鸣音。考虑诊断为","o":["哮喘","胸腔积液","大叶性肺炎","气胸","肺不张"],"a":0,"e":"青年，气管居中、两肺过清音、呼气延长、哮鸣音，符合支气管哮喘，为变态反应性气道炎症致广泛可逆性气道阻塞、呼气性呼吸困难。胸腔积液叩诊浊音或实音、语颤减弱、气管推向健侧；气胸叩诊鼓音、单侧呼吸音消失、气管移位；大叶性肺炎为实变体征、叩诊浊音；肺不张气管移向患侧、叩诊浊音"},{"q":"患者突发心悸，心电图示心率160次/min，QRS波时间0.10s，未见P波，R-R绝对不齐。最可能为","o":["房室交界性逸搏心率","阵发性室上性心动过速","阵发性室性心动过速","窦性心动过速","心房颤动"],"a":4,"e":"心律绝对不齐、P波消失、QRS波不增宽，符合心房颤动，因心房失去协调收缩、f波350～600次/分致心室律绝对不规则。窦性心动过速心律规整、有窦性P波；阵发性室上速心律规整、突发突止；室性心动过速QRS宽大畸形；房室交界性逸搏心律缓慢而规整"},{"q":"患者，男，52岁。因“呼吸困难伴双下肢水肿进行性加重3周”就诊。查体：BP 90/80mmHg，P 100次/min，奇脉，颈静脉怒张，心音低钝，X线见心脏向双侧扩大，双肺野清晰，最可能的诊断是","o":["扩张型心肌病","病毒性心肌炎","肥厚性心脏病","高血压心脏病","心包积液"],"a":4,"e":"呼吸困难、颈静脉怒张、奇脉、心音低钝、心脏向两侧扩大而双肺清晰，符合大量心包积液，因心包腔内压升高致心脏舒张受限、静脉回流受阻。扩张型心肌病亦心界扩大但多有肺淤血、无奇脉；肥厚性心脏病心界不大；高血压心脏病有长期高血压及左室增大；病毒性心肌炎有心律失常、心功能不全"},{"q":"患者，男，45岁，主诉头痛1个月。查体：BP 170/90mmhg，心界不大，心率75次/min，律齐有力，未及明确杂音，未发现神经系统异常。哪项诊断可能性最低","o":["尿毒症","肾动脉狭窄","甲状腺功能亢进","原发性醛固酮增多症","脑部肿瘤"],"a":4,"e":"中老年头痛伴血压明显升高、心界不大、无神经系统定位体征，尿毒症、肾动脉狭窄、甲亢、原醛均可引起继发性高血压。脑部肿瘤虽可有头痛、颅内压增高，但多伴神经定位体征、视乳头水肿或癫痫，且一般不直接导致持续性血压升高为本例主要表现，可能性最低"},{"q":"患者，女，19岁。受凉后出现咽痛、高热，右肩、右膝、左踝关节疼痛，伴活动后心悸、气促。最可能的疾病是","o":["结核性关节炎","风湿热","痛风关节炎","变异型骨关节炎","类风湿关节炎"],"a":1,"e":"青少年咽痛高热后出现游走性多关节疼痛及活动后心悸气促，符合风湿热，为A组链球菌感染后的变态反应性疾病、可累及关节与心脏。结核性关节炎起病缓、有结核中毒症状、单关节；痛风关节炎多见于中老年男性、第一跖趾关节；骨关节炎退行性、无发热；类风湿关节炎为对称性小关节、晨僵"},{"q":"患者，男，28岁，因四肢无力1个月入院。查：尿pH 7.0，血钾2.3mmol/L，血钙1、95mmoL/L，血氯114mmol/L，血pH 7.2，血肌酐80μmol/L。患者最可能诊断是","o":["Ⅰ型肾小管性酸中毒","Ⅱ型肾小管酸中毒","Ⅲ型肾小管性酸中毒","Ⅳ型肾小管性酸中毒","Fanconi综合征"],"a":0,"e":"代谢性酸中毒血pH 7.2而尿pH不能相应降低即尿pH 7.0＞6.0、伴低钾血症，符合Ⅰ型即远端肾小管性酸中毒，因远曲小管排H+障碍。Ⅱ型为近端肾小管HCO3-重吸收障碍，尿pH可＜5.5、常伴糖尿氨基酸尿即Fanconi综合征；Ⅲ型为混合型；Ⅳ型伴高钾血症，本例低钾可排除"},{"q":"患者，男，66岁，因“反复咳嗽、咳痰20年，活动后气促5年，加重伴双下肢水肿1天”收入院。1天前，上呼吸道感染后症状加重，伴夜间阵发性呼吸困难。查体：半卧位，口唇及四肢发绀，颈静脉怒张，肝颈静脉反流征阳性，双肺可闻及细湿啰音，双下肢凹陷性水肿。目前该患者的发绀类型是","o":["肺性发绀","心性混合性发绀","淤血性周围性发绀","缺血性周围性发绀","混合性发绀"],"a":4,"e":"慢性阻塞性肺疾病致肺通气换气障碍产生中心性即肺性发绀，并发右心衰竭致体循环淤血、周围血流缓慢产生周围性即淤血性发绀，二者并存为混合性发绀。肺性发绀仅为呼吸系统疾病所致；心性混合性发绀特指发绀型先心病因异常分流；淤血性、缺血性周围性发绀仅反映周围循环障碍，不能涵盖本例肺部因素"},{"q":"患者，女，55岁。高血压20年，不规则服药。某日晨突发头痛，意识不清，30min后送到医院。查体：昏迷，血压190/120mmHg，双眼向右侧凝视，左足外旋位。为明确诊断，最有价值的辅助检查是","o":["腰穿检查","脑电图检查","脑超声检查","头颅CT检查","开颅探查"],"a":3,"e":"长期高血压患者突发剧烈头痛、意识障碍、双眼凝视及偏瘫体征，首先考虑急性脑出血，头颅CT可迅速显示高密度出血灶、为首选检查。腰穿对脑出血有诱发脑疝风险且不能直接定位；脑电图、脑超声对出血定性定位价值有限；开颅探查为有创手段、非诊断首选"},{"q":"一高血压患者，突发呼吸困难，咳嗽，咳粉红色泡沫状痰，听诊时双肺底布满水泡音，此时该患者的肺部叩诊音应为","o":["浊音","实音","鼓音","浊鼓音","过清音"],"a":3,"e":"急性左心衰竭肺水肿时肺泡内含气量减少、肺泡壁松弛，叩诊呈兼有浊音与鼓音特点的浊鼓音。鼓音见于气胸或含气空腔；实音见于大量胸腔积液；过清音见于肺气肿；单纯浊音见于肺实变或中等量积液，均不同于肺水肿时含气减少的浊鼓音"},{"q":"34岁女性，腹痛3小时入院。婚姻史应记录的内容不包括","o":["性生活情况","夫妻关系","结婚年龄","丈夫健康状况","生育次数"],"a":4,"e":"婚姻史记录婚姻状况、结婚年龄、配偶健康状况、性生活情况及夫妻关系。生育次数含妊娠与生育次数、流产次数等属于生育史范畴，不属于婚姻史。性生活情况、夫妻关系、结婚年龄、丈夫健康状况均为婚姻史内容"},{"q":"患者，男，42岁，近2年来经常出现头昏、无力，伴心前区疼痛。查体：BP 150/60mmHg，P 90次/min，心尖部向左下移位，听诊胸骨左缘3肋间可闻及舒张期叹气样杂音。X线见左室增大。其病变可能为","o":["二尖瓣狭窄","二尖瓣狭窄合并肺动脉高压","主动脉瓣狭窄","主动脉瓣关闭不全","冠心病、心绞痛"],"a":3,"e":"胸骨左缘第3肋间即主动脉瓣第二听诊区舒张期递减型叹气样杂音、向左下传导，伴脉压增大、心尖左下移位及左室增大，符合主动脉瓣关闭不全。二尖瓣狭窄杂音在心尖区、舒张期隆隆样；主动脉瓣狭窄为收缩期喷射性杂音、脉压减小；冠心病心绞痛无特征性杂音"},{"q":"患者，女，56岁。会阴部渗液1个月。查体：小阴唇结节、溃烂。患者最可能的诊断是","o":["外阴溃疡","外阴白斑","外阴皮肤癌变","阴部感染","尖锐湿疣"],"a":2,"e":"小阴唇出现结节、溃烂，应首先考虑癌变，局部色素脱失白斑亦有恶变倾向。外阴溃疡多为感染或白塞病等、表现为浅表溃烂而非结节；外阴白斑为色素脱失斑片；尖锐湿疣呈乳头状或蕈样突起；阴部感染以红肿疼痛、分泌物增多为主"},{"q":"老年男性，慢性咳嗽、活动后呼吸困难40年，明确诊断为慢性阻塞性肺疾病。该患者的听诊特点是","o":["肺泡呼吸音减弱，伴呼气延长","吸气相延长","大水泡音","鼾音","痰鸣音"],"a":0,"e":"慢性阻塞性肺疾病因气道阻塞、肺弹性回缩力减退，呼气流速受限，听诊为肺泡呼吸音减弱伴呼气音延长。吸气相延长见于上气道阻塞的吸气性呼吸困难；大水泡音见于肺水肿或空洞；鼾音为低调干啰音、痰鸣音为气管内黏液所致，均非COPD主要听诊特点"},{"q":"一患者四肢肌力正常，大便控制不佳，入院查体发现肛周反射消失。患者损伤可能是以下哪个部位","o":["颈髓第1～2节段","胸髓第11～12节段","腰髓第2～4节段","骶髓第4～5节段","大脑皮层"],"a":3,"e":"肛门反射即肛门外括约肌收缩的反射中枢在骶髓4～5节，肛门反射消失、大便失禁提示骶髓4～5节段病变。颈髓1～2病变累及四肢及呼吸；胸髓11～12为下肢上运动神经元瘫；腰髓2～4与膝反射、下肢运动相关；大脑皮层病变以偏瘫为主，均不单独表现为肛门反射消失"},{"q":"某患者车祸后出现昏迷，头部CT提示蛛网膜下腔出血，该患者有可能出现","o":["颈强直","斜颈","头部活动自如","落日现象","扑翼样震颤"],"a":0,"e":"蛛网膜下腔出血时血液刺激脑膜，出现脑膜刺激征，包括颈强直、克尼格征和布鲁津斯基征，颈强直为屈颈时阻力增加。斜颈为颈部肌肉痉挛致头颈偏斜；落日现象见于脑积水；扑翼样震颤见于肝性脑病；头部活动自如与脑膜刺激征相悖"},{"q":"患者，女，59岁，因“间断关节痛4个月”就诊，查类风湿因子阳性。有关类风湿因子的描述正确的是","o":["以变性IgG刺激机体产生IgG型为主的抗体","能与变性IgG发生特异性结合反应","以IgG型类风湿因子为主，但也有IgM类、IgA类、IgD类和IgE类","特异性高，阳性仅见于类风湿性关节炎患者","参与Ⅰ型超敏反应"],"a":1,"e":"类风湿因子是变性IgG刺激机体产生的自身抗体，其本质为抗变性IgG的抗体，能与变性IgG发生特异性结合，主要为IgM型。RF以IgM型为主而非IgG型；其特异性不高、也见于系统性红斑狼疮、慢性感染及部分正常人；RF参与的是Ⅲ型超敏反应即免疫复合物型，而非Ⅰ型"},{"q":"患者，女，33岁。多尿、乏力、腰痛1年，有重金属接触史。尿常规：尿蛋白（＋＋＋）。诊断为肾小管性蛋白尿，其特点为","o":["尿蛋白常以白蛋白增多为主","尿蛋白以小分子量蛋白如β2-微球蛋白为主","尿中常出现大分子蛋白如IgG","尿蛋白常＞2g/24h","尿中免疫球蛋白的轻链显著增高"],"a":1,"e":"肾小管性蛋白尿因近端肾小管重吸收小分子蛋白障碍，尿中蛋白以β2-微球蛋白、α1-微球蛋白等小分子为主、尿蛋白量常较少，见于重金属中毒、间质性肾炎。肾小球性蛋白尿以白蛋白等中分子为主、尿蛋白常＞2g/24h；尿中出现IgG等大分子蛋白提示滤过膜严重损伤；免疫球蛋白轻链增高为溢出性蛋白尿"},{"q":"患者，男，72岁，处于慢性阻塞性肺疾病急性加重期。患者通过面罩吸氧，2L/min，动脉血气测量为pH 7、44，PaCO2 54mmHg，HCO3－ 36mEq/L，PaO2 60mmHg。此时患者处于","o":["呼吸性酸中毒和低氧血症代偿期","呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血"],"a":0,"e":"慢性阻塞性肺疾病患者PaCO2 54mmHg升高、HCO3- 36mEq/L继发性增高，pH 7.44在正常高限，提示慢性呼吸性酸中毒经肾脏潴留HCO3-代偿；PaO2 60mmHg降低提示低氧血症。呼吸性碱中毒PaCO2应降低；代谢性酸碱失衡HCO3-为原发改变；本例PaO2仅60mmHg不支持单纯代谢性酸中毒"},{"q":"患者，女，42岁，进食后突发右上腹痛、恶心呕吐，伴寒战、发热。查体：巩膜黄染，心肺听诊正常，腹软，右上腹压痛，无反跳痛，肝脾未触及。最可能的诊断是","o":["急性胃肠炎","肝脓肿","胆总管结石","幽门梗阻","急性出血坏死性肠炎"],"a":2,"e":"进食后右上腹痛、寒战高热、黄疸，为夏科三联征，提示胆总管结石伴急性胆管炎，胆道梗阻致胆红素反流入血、右上腹压痛。急性胃肠炎以腹泻呕吐为主、无黄疸；肝脓肿有弛张热、肝区叩痛；幽门梗阻为呕吐宿食；急性出血坏死性肠炎病情凶险、以腹痛休克为主"},{"q":"患者，男，65岁。入院后查胸部X线示右侧中等量的胸腔积液，此时查体可发现以下体征，除了","o":["右侧呼吸运动减弱，心尖冲动左移","右侧肋间隙饱满","气管右移","右侧触觉语颤减弱","右侧可闻及支气管呼吸音"],"a":2,"e":"右侧中等量胸腔积液使纵隔气管被推向健侧即左侧，故气管右移为错误描述；同时可见右侧肋间隙饱满、呼吸运动减弱、语颤减弱，积液区上方可闻支气管呼吸音。气管移向患侧见于肺不张、胸膜增厚粘连，而积液和气胸均推气管向健侧"},{"q":"患者，男，50岁。呼吸困难，颈静脉怒张，心界明显向两侧扩大，平卧位时第2、3肋间心界增宽，心尖冲动减弱，心音低钝，胸骨左缘3、4肋间有舒张早期额外心音，肝大，腹水征（＋）。最可能的诊断是","o":["肝硬化","心肌病","冠心病","心包积液","缩窄性心包炎"],"a":3,"e":"颈静脉怒张、心界向两侧扩大且随体位改变即卧位心底部增宽、心音低钝、胸骨左缘3、4肋间舒张早期心包叩击音、肝大腹水，符合大量心包积液。缩窄性心包炎心界不大或轻度增大、以舒张受限为主；肝硬化无心脏体征；心肌病心界普大但不随体位改变；冠心病有胸痛及心电图定位改变"},{"q":"患者，男，60岁。皮肤巩膜黄染，肝功能检查提示胆汁淤积性黄疸。B超：胆囊肿大，胆总管及肝内胆管扩张，但未见结石。查粪便隐血试验反复阳性。为明确诊断，首选的辅助检查是","o":["X线胃肠钡餐造影","纤维结肠镜检查","急诊胃镜检查","逆行胰胆管造影","磁共振腹部检查"],"a":3,"e":"胆汁淤积性黄疸伴胆囊肿大、胆管扩张而无结石，粪便隐血反复阳性，提示壶腹周围癌或胰头癌，ERCP可直接观察壶腹与乳头病变并造影判断胆道梗阻部位、为确诊首选。胃肠钡餐对胆道病变价值有限；纤维结肠镜用于结肠病变；急诊胃镜难以观察胆道；磁共振为无创替代但直接观察与造影以ERCP更优"},{"q":"患者，男，23岁。排尿不适、尿道口流脓3天就诊，有不洁性史，临床怀疑淋病。关于淋病的病原体实验室检查错误的是","o":["分离培养具有很高的特异性，是诊断的“金标准”","直接镜检发现革兰阴性双球菌可确诊","PCR检查敏感性高，有利于早期快速确诊，但易出现假阳性","血清学试验结果需结合其他方法加以证实","培养阴性不能排除淋病"],"a":1,"e":"淋病病原体为淋病奈瑟菌，直接镜检见革兰阴性双球菌对男性尿道分泌物有提示意义，但女性宫颈标本易受杂菌干扰、敏感性低，不能据此确诊，分离培养才是金标准。培养阴性不能排除淋病；PCR敏感但易假阳性需结合临床；血清学试验特异性有限需其他方法佐证"},{"q":"患者，女，45岁。近日反复发生鼻出血，出血量不大，查体可见皮肤紫癜，以双下肢为著。以下哪项检查结果不可能出现","o":["BT延长","束臂试验阳性","vWD:Ag增高","血小板计数正常","PT、APTT正常"],"a":2,"e":"反复鼻出血、下肢紫癜、束臂试验阳性而血小板计数及PT、APTT正常，符合血管性血友病或血小板功能异常，vWF抗原即vWD:Ag应减低、增高不可能出现。BT延长反映血小板黏附聚集障碍；束臂试验阳性提示毛细血管脆性增加；vWF增高见于血栓性疾病、妊娠、应激等，与本例出血倾向相反"},{"q":"患者，女，23岁，淋雨后出现高热、寒战、咳嗽、咳痰及右侧下胸痛。查体最可能出现的体征是","o":["语音共振减弱","语音震颤减弱","叩诊呈过清音","右下肺可闻及支气管呼吸音","可闻及干啰音"],"a":3,"e":"淋雨后高热寒战、咳嗽咳痰、右侧下胸痛，符合大叶性肺炎实变，实变肺组织传导增强、可闻病理性支气管呼吸音即管样呼吸音。语音震颤与语音共振应增强而非减弱；叩诊为浊音而非过清音；干啰音为气道狭窄所致，非实变体征"},{"q":"患者，男，30岁。发热2天，上厕所时昏倒在地，急测血压37/0mmHg，面色苍白，脉搏细速，医院诊断为流行性出血热休克期。患者产生休克最主要的原因是","o":["小血管通透性增加，血浆外渗，血容量减少","水电解质平衡失调","内脏大出血","继发细菌感染","小动脉痉挛"],"a":0,"e":"流行性出血热休克期休克主要因病毒损伤小血管内皮，致血管通透性增加、血浆大量外渗，有效循环血容量锐减，表现为血压骤降、面色苍白、脉搏细速。水电解质紊乱为继发因素；内脏大出血非主要机制；继发细菌感染多见于后期；小动脉痉挛是某些休克机制，本病以血管扩张、通透性增高为主"},{"q":"患者，男，60岁，右上腹疼痛伴黄疸3个月余。超声检查肝脏多发性散在性光团，AFP（－）。诊断继发性肝癌，其诊断的关键是","o":["肝穿刺","找出原发病灶","CT检查","MRI检查","肝血管造影"],"a":1,"e":"肝脏多发占位、AFP阴性，诊断继发性肝癌的关键在于找出原发病灶，因继发癌多来自胃肠道、胰腺等，明确原发灶对治疗与预后判断至关重要。肝穿刺可证实病理但无法区分原发继发；CT、MRI、肝血管造影均为定位影像手段，不能替代寻找原发灶这一确诊关键"},{"q":"某男性患者，规律性上腹痛20年，曾做胃镜诊断为十二指肠球部溃疡。最近1周来规律性上腹痛，排黑便。对于该患者，“规律性上腹痛20年”应为","o":["既往史","现病史","系统回顾","个人史","家族史"],"a":1,"e":"现病史记述本次疾病从起病到就诊的发生发展全过程，该患规律性上腹痛20年、近1周再发并排黑便，属本次发病的演变、应归入现病史。既往史为本次病以外的既往疾病史；系统回顾为各系统症状的补充询问；个人史含生活习惯、职业；家族史为家族成员健康状况"},{"q":"患者近3日出现腹痛、便秘，无排气，伴有恶心、呕吐，行立位腹平片可见液气平面，该患者最可能罹患的疾病是","o":["肠梗阻","慢性肠炎","急性肠炎","急性胃炎","慢性胃炎"],"a":0,"e":"腹痛、便秘、停止排气排便、恶心呕吐，立位腹平片见液气平面，符合肠梗阻，为肠内容物通过障碍，机械性者可见肠管扩张气液平、伴阵发性绞痛。急慢性肠炎、胃炎以腹泻或上腹不适为主，无停止排气及液气平"},{"q":"患者，男，75岁。咳嗽、咳痰、喘息30余年，5年来间断加重，伴有双下肢水肿。1周来咳喘并下肢水肿加重伴有嗜睡入院。以下检查对诊断具有重要意义的是","o":["MRI检查","心电图","脑电图","血气分析","痰培养"],"a":3,"e":"慢性阻塞性肺疾病患者咳喘加重伴嗜睡、下肢水肿，提示呼吸衰竭合并肺性脑病及右心衰，血气分析可判断缺氧、CO2潴留及酸碱失衡、对诊断与治疗至关重要。心电图、脑电图、MRI不能直接反映通气换气功能；痰培养用于病原学、非判断呼吸衰竭的关键"},{"q":"患者，男，59岁，反复反酸、上腹痛10余年，每次持续1个月左右，未系统治疗。近半年，持续腹痛不缓解，无反酸，伴头晕、乏力，消瘦，低热。查体：贫血貌，剑下压痛（＋），未触及异常包块，肠鸣音正常。该患者最可能的诊断是","o":["胆汁反流性胃炎","萎缩性胃炎","胃溃疡","胃癌","十二指肠溃疡"],"a":3,"e":"中老年患者慢性上腹痛10余年、近期疼痛规律改变且持续不缓解，伴消瘦、贫血、低热，应警惕胃癌，疼痛失去原有节律并出现消耗表现是恶变信号。消化性溃疡疼痛有周期性节律性、进食可缓解；萎缩性胃炎、胆汁反流性胃炎症状无特异消瘦贫血；十二指肠溃疡多见于青年、有节律性"},{"q":"患者，女，28岁，于心尖部听到舒张中、晚期低调的隆隆样杂音，较局限，并有S1亢进，于S2稍后可听到一短促、高调清脆的拍击样声音，此音为","o":["病理性S3","病理性S4","开瓣音","心包叩击音","重叠奔马律"],"a":2,"e":"心尖区舒张中晚期低调隆隆样杂音、S1亢进，为二尖瓣狭窄；S2后0.05～0.06秒出现的短促高调清脆拍击样额外心音为开瓣音、提示瓣叶弹性尚好。心包叩击音在S2后0.09～0.12秒、见于缩窄性心包炎；病理性S3、S4及重叠奔马律均为舒张期低频音，性质与拍击样开瓣音不同"},{"q":"患者，男，82岁，喘憋1周，加重1天。查体：心率56次/min，呼吸20次/min，血压137/64mmHg。既往有冠状动脉粥样硬化性心脏病，高血压。心电图诊断正确的是","o":["窦性心动过缓，U波明显","心房颤动，交界区逸搏","心房扑动，U波明显","心房颤动，U波明显","心房颤动，3度房室传导阻滞，交界区逸搏"],"a":4,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。该题需依据心电图判断：心房颤动表现为P波消失代之以f波、RR绝对不齐；三度房室传导阻滞时心房激动不能下传，阻滞以下出现交界性逸搏心律，QRS形态正常、频率40～60次/分，心室律慢而规整；窦性心动过缓、心房扑动各有相应P波或F波特点，仅凭临床资料难以区分\n\n官方题库中缺失图片"},{"q":"患者，女，30岁。近2个月盘状红斑，辅助检查提示抗核抗体阳性，抗sm抗体阳性，抗双链DNA阳性。最可能的诊断是","o":["类风湿性关节炎","骨关节炎","系统性红斑狼疮","干燥综合征","感染性关节炎"],"a":2,"e":"青年女性盘状红斑，抗核抗体、抗Sm抗体及抗双链DNA抗体阳性，符合系统性红斑狼疮，抗Sm为标记性抗体、抗dsDNA与疾病活动相关。类风湿关节炎以对称性小关节肿痛、类风湿因子阳性为主；干燥综合征有口干眼干、抗SSA或SSB阳性；骨关节炎为退行性变；感染性关节炎有感染证据"},{"q":"老年男性，78岁，胸痛24小时，下列哪项心电图改变提示急诊介入治疗指征","o":["V2～V5QS型","新发左束支传导阻滞","V1～V5T波深大倒置","V1～V3ST段抬高0.3mv","V1～V4ST段压低0.2mv"],"a":1,"e":"新发左束支传导阻滞伴胸痛，提示急性心肌缺血或心肌梗死、属高危表现，为急诊介入治疗指征。V1～V5 ST段抬高、V2～V5 QS波、T波深倒等多提示前壁广泛病变或陈旧改变，但新发束支阻滞在胸痛背景下更能反映急性严重缺血需紧急再灌注"},{"q":"患者，女，78岁，起搏器植入术后8年。根据以下心电图，最可能的诊断是","o":["感知异常","起搏异常","感知及起搏均异常","正常起搏器功能伴室性期前收缩","急性心肌梗死"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。起搏器心电图需判断感知与起搏功能：感知异常表现为感知不足或过度感知，起搏异常表现为起搏脉冲不能夺获心肌；本例选项还涉及室性期前收缩及急性心肌梗死，均须依据心电图图形鉴别，仅凭起搏器植入史无法确定\n\n官方题库中缺失图片"},{"q":"患者，男，66岁，因头晕半年来诊。查体：血压180/95mmHg，心界扩大，未及杂音。临床诊断原发性高血压，则下列体征最可能出现的是","o":["奇脉","Duroziez双重杂音","烧瓶心","P2增强","靴形心"],"a":4,"e":"长期原发性高血压致左心室肥厚增大，心浊音界向左下扩大、心腰加深，呈靴形心。烧瓶心为心包积液、随体位改变；P2增强见于肺动脉高压、肺源性心脏病；Duroziez双重杂音、奇脉分别为周围血管征和心包填塞等表现，均非高血压心脏病的典型改变"},{"q":"一患者受凉后咳嗽、高热、咯铁锈色痰，胸痛，随呼吸运动而加重，屏住呼吸时减轻。胸片示右肺下野外带近胸膜处均匀一致大片状影。此患者在听诊时最易出现的体征为","o":["羊鸣音","硬币叩击征","胸膜摩擦音","捻发音","哨笛音"],"a":2,"e":"咳嗽高热、铁锈色痰、胸痛随呼吸加重而屏气减轻，病变位于肺外周近胸膜处，累及胸膜产生纤维蛋白性胸膜炎，出现胸膜摩擦音、屏气时消失。羊鸣音为肺实变时语音共振增强；硬币叩击征见于气胸或胸腔积液；捻发音见于肺淤血或早期结核；哨笛音为干啰音、见于气道狭窄"},{"q":"患儿，女，2岁，因出生1个月感冒发现心脏杂音来诊。查体：胸骨左缘2肋间闻及3级柔和吹风样收缩期杂音，伴P2增强，S2分裂且不受呼吸影响。最可能的诊断是","o":["S2通常分裂","肺动脉瓣狭窄","S2生理性分裂和生理性杂音","房间隔缺损","S2反常分裂"],"a":3,"e":"胸骨左缘第2肋间柔和收缩期杂音、P2增强及S2固定分裂即不受呼吸影响，为房间隔缺损的典型表现，因左向右分流使右心血流增加、肺动脉瓣关闭延迟。S2通常分裂随呼吸变化；生理性分裂见青少年、无固定分裂；肺动脉瓣狭窄杂音粗糙、P2减弱；反常分裂为主动脉瓣关闭晚于肺动脉瓣，见于左束支阻滞等"},{"q":"患者，女，50岁。突发眩晕伴呕吐，不能睁眼，伴听力下降，无视物模糊，无头痛。查体：BP 120/70mmHg，可见眼球水平方向震颤，HR 70次/min，鼻窦无压痛，全腹无压痛。血常规正常，腹部B超未见异常。可能的诊断是","o":["青光眼","脑肿瘤","耳石症","鼻窦炎","急性胆囊炎"],"a":2,"e":"突发眩晕伴呕吐、眼球水平震颤、不能睁眼，由体位改变诱发，符合耳石症即良性阵发性位置性眩晕。青光眼以眼痛、视力下降、眼压升高为主；脑肿瘤头痛、神经定位体征渐进；鼻窦炎有鼻塞、鼻窦压痛；急性胆囊炎有右上腹痛、墨菲征阳性，本例鼻窦及腹部检查均正常可排除"},{"q":"患者，女，24岁，发热1天后出现肉眼血尿，无尿频、尿急、尿痛。尿常规：尿蛋白（＋），红细胞30～40个/HPF，白细胞10～20个/HPF。为明确诊断，应进行的检查是","o":["尿蛋白定量","膀胱镜","肾盂造影","尿细菌培养","血常规检查"],"a":3,"e":"发热后出现肉眼血尿伴尿白细胞增多，需明确是否为尿路感染，尿细菌培养可确定病原菌并做药敏、为明确诊断的关键。尿蛋白定量用于评估蛋白尿程度；膀胱镜、肾盂造影为有创或影像检查、非首选；血常规不能确定泌尿系感染"},{"q":"青春期女性，自月经来潮，经量明显多于同龄人，幼时常有皮肤黏膜出血表现，检查发现血小板计数正常，vWD:Ag减低，该患者最可能的诊断是","o":["血友病A","血友病B","血友病C","血管性血友病","以上均不是"],"a":3,"e":"自幼皮肤黏膜出血、青春期月经过多，血小板计数正常而血管性血友病因子抗原即vWD:Ag减低，符合血管性血友病，因vWF缺乏致血小板黏附障碍及因子Ⅷ不稳定。血友病A、B、C分别为因子Ⅷ、Ⅸ、Ⅺ缺乏，vWF正常、以深部关节肌肉出血为主、APTT延长，与本例不符"},{"q":"患者，男，45岁。便秘1年，一直服用含硫药物，发绀持续数月。当血中硫化血红蛋白超过（ ）时，可引起皮肤黏膜青紫","o":["1g/L","3g/L","5g/L","30g/L","50g/L"],"a":2,"e":"服用含硫药物或便秘致肠内硫化氢产生增多，血液硫化血红蛋白达到5g/L即可出现发绀，其特点为持续数月、血液呈蓝褐色、分光镜检查可证实。3g/L未达阈值；1g/L更低；30g/L、50g/L远超实际阈值"},{"q":"患者，男，54岁。突发抽搐8小时。查体：四肢肌肉呈持续性强直性痉挛，肌肉压痛剧烈。该患者最可能的诊断是","o":["癫痫","高血压脑病","蛛网膜下腔出血","破伤风","颅内占位"],"a":3,"e":"四肢肌肉持续性强直性痉挛伴剧烈肌肉压痛，符合破伤风，由破伤风梭菌毒素致运动神经元持续兴奋，可有苦笑面容、角弓反张。癫痫为阵挛性抽搐、发作后意识恢复；高血压脑病有剧烈头痛、血压极高、意识障碍；蛛网膜下腔出血有剧烈头痛、脑膜刺激征；颅内占位有慢性颅内压增高及定位体征"},{"q":"患者，男，18岁，间断活动后胸痛来诊，入室心电图如下所示，进一步问诊及查体应注意包括如下方面，除了","o":["猝死家族史","既往用药史","有无晕厥史","既往心电图","听诊有无心脏杂音"],"a":1,"e":"青年活动后胸痛，需警惕肥厚型心肌病等，问诊与查体应重点询问猝死家族史、有无晕厥史、既往心电图以对比动态变化，并听诊有无心脏杂音。既往用药史对胸痛病因判断价值相对次要，为该题的除外项"},{"q":"患者，男，70岁。因头晕胸痛半月来诊，既往有10年高血压病史。查体血压160/75mmHg，心率102次/min，S1增强，心界左侧扩大，伴抬举样搏动。与该患者S1增强无关的是","o":["心室肥厚收缩有力","心动过速","左心室充盈不足","二尖瓣狭窄","舒张期变短"],"a":3,"e":"S1强度取决于心室内压上升速率及收缩开始时房室瓣位置：心室肥厚收缩有力、心动过速、舒张期缩短、左室充盈不足使二尖瓣位置低垂，均增强S1。本例为高血压心脏病、左室肥厚、心率快，S1增强源于上述机制、与二尖瓣狭窄无关；二尖瓣狭窄虽可致S1亢进，但非本例原因"},{"q":"患者，女，67岁。活动后心悸、气短3年，有慢性支气管炎病史10年。查体：心脏听诊发现心率127次/min，心律不齐。心电图P波消失代之f波，心室律绝对不规律，QRS波群形态正常。该患者心律不齐最可能的诊断是","o":["室性期前收缩","心房颤动","阵发性室性心动过速","阵发性室上性心动过速","二度Ⅰ型房室传导阻滞"],"a":1,"e":"P波消失代之以f波、RR绝对不齐、QRS波形态正常，符合心房颤动。室性期前收缩为提前出现的宽大畸形QRS波；阵发性室性心动过速为连续宽大畸形QRS；阵发性室上速心律规整、突发突止；二度Ⅰ型房室传导阻滞PR间期逐渐延长直至脱落，均有各自P波或规律，与本例不符"},{"q":"患者，24岁，女性。消瘦、乏力半年，心慌、手抖1月就诊。查体：T 36.4℃，P 99次/min，R 21次/min，Bp 140/62mmHg，甲状腺激素增高。该患者不大可能出现的体征是","o":["奇脉","水冲脉","Duroziez双重杂音","枪击音","毛细血管搏动征"],"a":0,"e":"甲状腺功能亢进致高动力循环，出现水冲脉、Duroziez双重杂音、枪击音及毛细血管搏动征等周围血管征。奇脉为吸气时收缩压下降超过10mmHg，见于心包积液、缩窄性心包炎、严重哮喘等，甲亢一般不会出现"},{"q":"下列哪位患者最可能诊断为先天性心脏病，动脉导管未闭","o":["患儿，男，6岁，胸骨左缘2肋间3级粗糙吹风样杂音，伴P2增强，S2固定分裂","患者，女，3岁，胸骨左缘2肋间闻及连续性粗糙响亮机器样杂音，伴震颤","患者，38岁，胸骨左缘3/4肋间闻及舒张期哈气样递减杂音","患儿，男，1岁，胸骨左缘3/4肋间隙闻及粗糙响亮的4级全收缩期杂音伴震颤","患者，男，27岁，胸骨右缘2肋间粗糙喷射性收缩期递增递减性杂音伴震颤"],"a":1,"e":"胸骨左缘第2肋间连续性粗糙响亮机器样杂音、覆盖收缩与舒张期并伴震颤，为动脉导管未闭的特征。房间隔缺损为胸骨左缘2肋间收缩期杂音伴S2固定分裂；室间隔缺损为胸骨左缘3、4肋间全收缩期粗糙杂音；主动脉瓣狭窄为胸骨右缘2肋间收缩期喷射性杂音；舒张期哈气样杂音见于主动脉瓣关闭不全"},{"q":"患者突感呼吸困难，气喘、胸闷。对于确诊支气管哮喘最有意义的是","o":["气管移位","双肺叩诊呈过清音","两肺有干啰音","肺肝界下移","心界缩小"],"a":2,"e":"支气管哮喘为气道慢性炎症致广泛可逆性气道阻塞，发作时双肺弥漫性干啰音即哮鸣音为其典型体征，结合反复发作、呼气性呼吸困难有重要诊断意义。过清音、肺肝界下移、心界缩小为肺气肿改变、亦见于COPD、非哮喘特异；气管移位提示胸腔积液或气胸等占位"},{"q":"患者，女，32岁。阵发性心悸3个月。发作时心电图示：心室率240次/分，Ⅱ、Ⅲ、aVF导联P波倒置，QRS波群正常，并与P波保持固定关系。预防室上性心动过速最有效的方法是","o":["口服维拉帕米","口服胺碘酮","口服地高辛","射频消融术","口服美托洛尔"],"a":3,"e":"阵发性室上性心动过速多由房室结折返或旁路折返引起，射频消融术可阻断折返环路或消融旁路达到根治，是预防复发最有效的方法。维拉帕米、胺碘酮、地高辛、美托洛尔等药物仅能控制急性发作或减少发作，需长期服用且不能根治"},{"q":"患者，女，50岁，糖尿病3年。口服降糖药治疗，血糖控制良好。那么患者的空腹血糖范围应是","o":["3.3～3.9mmol/L","3.9～6.1mmol/L","6.1～7.0mmol/L","7.0～7.8mmol/L","7.8～8.4mmol/L"],"a":1,"e":"成人空腹血浆或血清葡萄糖参考区间为3.9～6.1mmol/L，糖尿病治疗良好的患者空腹血糖应控制在此范围。低于3.9mmol/L为低血糖；6.1～7.0mmol/L为空腹血糖受损；≥7.0mmol/L需考虑糖尿病。血糖控制目标因人而异，但本题问的是参考范围"},{"q":"患者，男，32岁，上腹胀痛，伴恶心、呕吐大量隔宿食物，呕吐后腹胀痛减轻，最可能的诊断是","o":["青光眼","急性胃炎","幽门梗阻","癔症","急性胰腺炎"],"a":2,"e":"上腹胀痛、呕吐大量隔宿食物、吐后症状减轻，为幽门梗阻的典型表现，因胃排空受阻、食物滞留发酵。急性胃炎、急性胰腺炎呕吐后腹痛不缓解；青光眼、癔症为神经性呕吐、无隔宿宿食及腹胀"},{"q":"患者，男，52岁，以“间断胸痛5年，加重2小时”收入院。平素体力活动、锻炼等无明显胸闷、胸痛，多于凌晨睡眠时心前区不适、胸痛，10余分钟可自行缓解。今日凌晨再次发作，持续半小时未缓解。根据心电图最可能的诊断是","o":["胃食管反流","急性下壁心梗","心包积液","变异型心绞痛","主动脉夹层"],"a":3,"e":"静息状态下即凌晨睡眠时发作胸痛、与体力活动无关、可持续十余分钟自行缓解，符合变异型心绞痛，因冠状动脉痉挛致一过性心肌缺血、发作时ST段抬高。胃食管反流多有反酸烧心；急性下壁心梗胸痛持续不缓解、有心肌酶动态演变；心包积液、主动脉夹层疼痛性质与病程均不同"},{"q":"一瘫痪患者入院时查体发现其左侧肢体肌力3级，左侧巴宾斯基征阳性，左侧中枢性面瘫。考虑患者损伤以下哪个部位","o":["颈段脊髓","左侧基底节区","右侧基底节区","左侧小脑","脑桥"],"a":2,"e":"左侧肢体偏瘫、左侧病理征及中枢性面瘫，为右侧大脑半球即基底节区病变，因运动纤维在延髓交叉，故一侧脑部病变表现为对侧偏瘫。颈段脊髓病变不致面瘫；左侧基底节区病变应表现为右侧偏瘫；小脑病变以共济失调为主；脑桥病变多伴同侧面神经或外展神经损害及交叉性瘫痪"},{"q":"患者，女，26岁，腹痛、腹泻入院。粪便呈果酱样便，镜检粪便中出现夏科-莱登结晶，考虑该患者为","o":["细菌性痢疾","阿米巴痢疾","溃疡性结肠炎","直肠息肉","重症霍乱"],"a":1,"e":"果酱样即暗红色粪便、镜检见夏科-莱登结晶及大量变性红细胞，符合阿米巴痢疾，由溶组织内阿米巴感染结肠所致。细菌性痢疾为黏液脓血便、红细胞少于白细胞、无夏科-莱登结晶；溃疡性结肠炎为慢性黏液脓血便；直肠息肉为无痛性血便；重症霍乱为米泔水样便"},{"q":"患者，女，20岁。突然发冷发热，体温达39.0℃，面色潮红，伴右胸呼吸运动减弱，可听到管状呼吸音。其诊断首先考虑","o":["胸腔积液","大叶性肺炎","肺梗死","肺结核","肺癌"],"a":1,"e":"骤起寒战高热、胸痛、右胸呼吸运动减弱及病理性支气管呼吸音即管状呼吸音，符合大叶性肺炎实变期。胸腔积液叩诊浊音、语颤减弱、呼吸音消失；肺梗死有胸痛、咯血、呼吸困难及下肢静脉血栓基础；肺结核起病缓、有低热盗汗；肺癌病程长、有肺不张或肿块体征"},{"q":"患者，男，48岁。“双侧股骨干骨折2小时”收入住院。入院查体：体温36.5℃，脉搏细弱，血压60/40mmHg，四肢冰冷，并出现发绀、无尿。该患者出现的发绀是","o":["肺性发绀","心性混合性发绀","淤血性周围性发绀","缺血性周围性发绀","混合性发绀"],"a":3,"e":"严重创伤致失血性休克，心输出量骤减、周围血管收缩、局部血流障碍，出现四肢冰冷、发绀，属缺血性周围性发绀。淤血性周围性发绀见于右心衰、缩窄性心包炎等体循环淤血、血流缓慢，肢端温度可正常或温暖；肺性发绀为呼吸系统疾病所致中心性发绀；心性混合性发绀见于发绀型先心病"},{"q":"患者，男，70岁。已确诊为冠心病，近日出现夜间呼吸困难，咯粉红色泡沫样痰。查体：BP 120/90mmHg，心率104次/min，律齐，心界向左下扩大，心音低钝。还可出现的体征是","o":["水冲脉","奇脉","脱落脉","交替脉","短绌脉"],"a":3,"e":"冠心病、夜间呼吸困难、粉红色泡沫痰、心界向左下扩大、心音低钝，符合急性左心衰竭，严重者可出现交替脉，即脉搏强弱交替、为左室收缩力交替变化所致、是左心衰的特征性体征。水冲脉、枪击音等为周围血管征；奇脉见于心包填塞；短绌脉见于房颤；脱落脉见于二度房室传导阻滞"},{"q":"患者，男，30岁，上腹部规律性疼痛反复发作10年，加重1周，呕血、黑便2天。最可能的诊断是","o":["出血性胃炎","消化性溃疡出血","胃癌出血","食管-胃底静脉曲张破裂出血","胆道出血"],"a":1,"e":"长期规律性上腹痛、近期加重并呕血黑便，出血后疼痛常可缓解，符合消化性溃疡出血。胃癌出血疼痛无规律、伴消瘦贫血、多见于中老年；食管胃底静脉曲张破裂出血量大、有肝硬化的肝功能减退与门脉高压表现；出血性胃炎有应激或药物因素；胆道出血伴黄疸、右上腹绞痛"},{"q":"患者，26岁。近1个月来低热、盗汗，伴咳嗽，痰中带血丝。应首先考虑的是","o":["肺结核","支气管扩张","肺癌","风湿性心脏病二尖瓣狭窄","急性肺水肿"],"a":0,"e":"低热、盗汗为结核中毒症状，痰中带血提示咯血，我国咯血首要病因为浸润性、空洞性肺结核及干酪样肺炎，故首先考虑肺结核。支气管扩张以反复大量脓痰和咯血为特点，无低热盗汗；肺癌多见于老年，常表现为持续痰中带血；二尖瓣狭窄咯血多为暗红色；急性肺水肿咳粉红色泡沫样痰"},{"q":"患者，女，72岁。心慌3天，突发头痛，右侧面瘫，伴有右侧肢体活动不灵1天。既往房颤病史20年。复查心电图显示心率54次/min，窦性节律。患者最可能发生的是","o":["蛛网膜下腔出血","急性脑栓塞","急性脑膜炎","高血压脑病","脑肿瘤"],"a":1,"e":"房颤时心房失去有效收缩，附壁血栓脱落堵塞脑动脉，突发偏瘫、面瘫，故为急性脑栓塞。蛛网膜下腔出血以剧烈头痛和脑膜刺激征为主，无房颤栓子来源；急性脑膜炎伴发热及脑膜刺激征；高血压脑病有血压极度升高；脑肿瘤起病缓慢，均无房颤栓子基础"},{"q":"患者，男，28岁，因尿频、尿急、尿痛4个月、加重伴尿失禁1周就诊。尿常规检查提示白细胞（＋＋），尿潜血（＋＋＋），多种抗生素治疗无明显缓解。该患者的诊断最有可能是","o":["急性膀胱炎","泌尿系结核","间质性膀胱炎","慢性膀胱炎","腺性膀胱炎"],"a":1,"e":"慢性膀胱刺激征历时4个月、多种抗生素无效并出现血尿和尿失禁，提示泌尿系结核，结核结节溃疡形成致尿频尿急并进行性加重。急性膀胱炎病程短、抗生素治疗有效；间质性膀胱炎以膀胱容量减小和尿频为主，无结核中毒史；腺性膀胱炎为慢性增生性病变，无典型结核过程"},{"q":"患者，男，69岁，检测发现单克隆Ig明显升高。M蛋白增高所导致的疾病，不包括下列哪种","o":["重链病","轻链病","原发性巨球蛋白血症","真性红细胞增多症","多发性骨髓瘤"],"a":3,"e":"M蛋白为单克隆免疫球蛋白，重链病、轻链病、原发性巨球蛋白血症和多发性骨髓瘤均属浆细胞或B细胞克隆增殖病，产生异常单克隆Ig。真性红细胞增多症为骨髓增殖性肿瘤，以红细胞及血细胞比容显著增高为特征，不分泌单克隆免疫球蛋白，故不属于M蛋白增高疾病"},{"q":"患者，男，59岁。阴部肿胀、疼痛3个月。查体：精索部位呈串珠样肿胀。该患者最可能的诊断是","o":["输精管结核","精索静脉曲张","腹股沟斜疝","鞘膜积液","睾丸癌"],"a":0,"e":"精索触诊呈串珠样肿胀是输精管结核的特征性表现，结核病变使输精管呈结节状增粗。精索静脉曲张表现为精索迂曲扩张的蚯蚓状团块，站立时明显；丝虫病所致硬结靠近附睾；精索急性炎症有挤压痛及局部皮肤红肿，均非串珠样改变"},{"q":"患者，男，34岁，因预计综合征行射频消融术，术后2天心电图示delta波消失，但多个导联T波仍倒置，其原因可能为","o":["心肌受损","射频消融未成功","电张调整性T波改变","急性冠脉综合征","心血管神经症"],"a":2,"e":"射频消融成功后delta波消失，但心室激动顺序骤变后T波可呈记忆性倒置，持续一段时间才恢复，称电张调整性T波改变。delta波消失已说明消融成功，故非未成功；心肌受损与急性冠脉综合征应有相应ST段及酶学动态改变；心血管神经症无器质性心电图依据"},{"q":"患者，女，35岁。有糖尿病家族史。实验室检查：空腹血糖6.8mmol/L。为确诊糖尿病，最有意义的检查是","o":["重复测空腹血糖","测餐后2h血糖","多次测任意血糖","口服葡萄糖耐量试验","糖化血红蛋白"],"a":3,"e":"空腹血糖6.8mmol/L处于正常与糖尿病之间的空腹血糖受损区间，尚不足以确诊，需行75g口服葡萄糖耐量试验，了解机体对葡萄糖负荷的调节能力，是诊断可疑糖尿病的关键试验。重复空腹血糖仍可能停留在临界值；餐后2h血糖和糖化血红蛋白反映不同时点或平均血糖，不能替代OGTT的确诊价值"},{"q":"患者，女，20岁。因进行性呼吸困难3个月来诊。查体发现BP 90/70mmHg，心界双侧扩大，随体位改变，心率120次/min，律齐，心音低弱遥远，无病理性杂音。患者不可能出现","o":["水冲脉","颈静脉怒张","奇脉","肝大","移动性浊音"],"a":0,"e":"心界双侧扩大随体位改变、心音低弱遥远、脉压减小，符合大量心包积液及心脏压塞，可有颈静脉怒张、奇脉、肝大和移动性浊音。水冲脉是脉压增大时脉搏骤起骤落，见于主动脉瓣关闭不全、甲亢等，心包积液时脉压减小，故不可能出现水冲脉"},{"q":"患者，男，67岁。长期吸烟，有重度高血压、冠心病及糖尿病病史，未服用药物治疗。生气后突发剧烈头痛，继而意识丧失，伴有呕血，起病前无发热症状。其最可能的诊断是","o":["高血压脑病","急性脑炎","颅内肿瘤","急性脑出血","急性脑梗死"],"a":3,"e":"长期高血压、吸烟、糖尿病等动脉粥样硬化基础，情绪激动后突发剧烈头痛、意识丧失，伴呕血为应激性黏膜病变，符合急性脑出血。高血压脑病以血压极度升高和弥漫性脑症状为主，多无偏瘫；急性脑炎有发热；颅内肿瘤起病缓慢；脑梗死多为安静起病、意识障碍较轻"},{"q":"患者，男，20岁。单杠运动后突发右侧胸痛，伴咳嗽时加剧，渐感呼吸困难。最可能是","o":["自发性气胸","心绞痛","肋间神经痛","肋骨骨折","肺栓塞"],"a":0,"e":"青壮年单杠用力后突发病侧撕裂样胸痛，咳嗽和呼吸时加剧并出现呼吸困难，是自发性气胸的典型表现，因肺泡破裂气体进入胸膜腔。心绞痛多为压迫感、劳累诱发、休息缓解；肋间神经痛沿神经分布、无呼吸困难；肋骨骨折有明确外伤及局部压痛；肺栓塞常伴咯血和右心负荷表现"},{"q":"患者，男，49岁，规律性夜间腹痛5年，近1个月疼痛节律性消失，变为餐后腹痛伴呕吐，吐出大量隔夜宿食，应考虑并发","o":["大出血","慢性穿孔","急性穿孔","幽门梗阻","溃疡癌变"],"a":3,"e":"溃疡病史者疼痛节律消失，转为餐后上腹痛并呕吐大量隔夜宿食，是幽门梗阻的典型表现，因幽门痉挛水肿或瘢痕收缩致胃排空受阻、胃内容物潴留。大出血表现为呕血黑便；慢性穿孔为持续性钝痛；急性穿孔为突发剧痛和腹膜刺激征；癌变多伴体重下降和疼痛节律改变"},{"q":"患者，男，32岁，在其左边第3肋间可闻及典型的早期舒张期杂音，被认为具有主动脉瓣关闭不全。以下哪项支持主动脉瓣关闭不全的诊断，可以将其与肺动脉瓣关闭不全的早期舒张期杂音（Graham Stell杂音）区分开来","o":["左方第2肋间杂音最响亮","左心室长大","杂音在吸气末最明显","血压无变化","第一心音增强"],"a":1,"e":"主动脉瓣关闭不全时左心室舒张期同时接受左房血流和主动脉反流血液，容量负荷增加致左心室肥厚扩张，故左心室长大支持该诊断。Graham Steell杂音为肺动脉高压致肺动脉瓣相对关闭不全，右室扩大为主，杂音于吸气末增强；第一心音增强、血压无变化均无鉴别价值"},{"q":"患儿，女，1岁。前额左右突出，头顶平坦呈方形，夜间易惊醒，出汗多。该患儿最可能患的疾病是","o":["小儿佝偻病","变形性骨炎","脑积水","肢端肥大症","Marfan综合征"],"a":0,"e":"方颅伴夜间易惊、多汗等神经兴奋表现，符合小儿佝偻病，因维生素D缺乏致骨样组织钙化障碍，骨膜增生形成方颅。脑积水为巨颅伴落日现象；变形性骨炎为成人骨增厚畸形；肢端肥大症为成人生长激素过多致肢端和颅骨增大；Marfan综合征以细长指趾和晶状体脱位为特征"},{"q":"患者，男，40岁。10年前有风湿性关节炎史。近2周来有心悸、气促，伴夜间阵发性呼吸困难。查体：心尖部第一心音减弱，可闻及4/6级全收缩期吹风样杂音和舒张期隆隆样杂音，最可能是","o":["风湿性心脏病，二尖瓣狭窄伴关闭不全","风湿性心脏病，二尖瓣狭窄伴肺动脉瓣狭窄","风湿性心脏病，二尖瓣狭窄伴主动脉瓣狭窄","风湿性心脏病，二尖瓣狭窄伴主动脉瓣关闭不全","风湿性心脏病，二尖瓣狭窄伴三尖瓣狭窄"],"a":0,"e":"心尖区舒张期隆隆样杂音为二尖瓣狭窄的特征，心尖区粗糙的全收缩期吹风样杂音提示二尖瓣关闭不全，两者并存故为二尖瓣狭窄伴关闭不全。主动脉瓣病变杂音位于主动脉瓣区；三尖瓣狭窄罕见且杂音在胸骨左下缘；肺动脉瓣狭窄为收缩期喷射性杂音，均不相符"},{"q":"患者，男，40岁，主诉乏力、酱油色尿2周。2周前曾因“感冒”服用对乙酰氨基酚类药物，期间曾发现尿色呈酱油色。查体见贫血外貌，巩膜轻度黄染。血常规示Hb 65g/L，WBC 18×109/L，PLT 104×109/L。对其诊断最有价值的检测项目是","o":["抗核抗体检测","过敏原皮肤试验","Coombs实验","血清免疫复合物测定","骨髓穿刺"],"a":2,"e":"贫血、黄疸、酱油色尿提示溶血性贫血，服用对乙酰氨基酚等药物可诱发免疫性溶血，Coombs试验检测红细胞表面或血清中的不完全抗体，是诊断自身免疫性溶血的关键。抗核抗体用于结缔组织病筛查；过敏原皮肤试验针对Ⅰ型变态反应；骨髓穿刺主要评估造血系统，均非确诊所需"},{"q":"患者，男，38岁。不明原因发热、胸痛、咳嗽2天。下列哪项体征有助于肺炎与胸腔积液的鉴别诊断","o":["语颤增强","呼吸急促","呼吸音减低","叩诊为浊音","捻发音"],"a":0,"e":"肺炎实变时肺泡内充满炎性渗出物，语颤传导良好而增强，胸腔积液则因液体阻隔使语颤减弱，故语颤增强有助于两者鉴别。叩诊浊音在两者均可出现；呼吸音减低多见于胸腔积液；呼吸急促为非特异性表现；捻发音提示肺泡或间质病变，无鉴别意义"},{"q":"患者，男，50岁。反复乏力、消瘦，食欲缺乏10年。查体：肝脾未见异常。实验室检查：ALP升高，HBsAg（＋），HBeAg（＋）。保肝治疗后好转。为明确有无肝硬化，首选的实验室检查项目是","o":["GPT","GOT","AFP","MAO","R-GT"],"a":3,"e":"MAO加速胶原纤维交联，其活性与肝内结缔组织增生及纤维化程度正相关，80%以上重症肝硬化者升高，是判断肝纤维化和肝硬化的首选指标。GPT、GOT反映肝细胞损伤程度；AFP用于筛查肝癌；R-GT升高多见于胆汁淤积和酒精性肝病，均不能直接反映纤维化"},{"q":"患者，女，42岁，诊断类风湿性关节炎10年。近1个月来乏力，烦渴，伴有腰痛。查尿常规：pH 6.0，WBC 4个/HPF，RBC 1个/HPF，蛋白（-）。肾功能：血肌酐94μmol/L，尿素氮7.2mmol/L。电解质：钙2.0mmol/L，钠138mmol/L，钾3.2mmol/L，氯108mmol/L，HCO3-27mmol/L。最可能的诊断是","o":["泌尿系感染","Ⅰ型肾小管酸中毒","Ⅱ型肾小管酸中毒","Fanconi综合征","Bartter综合征"],"a":1,"e":"尿pH6.0、低钾、低钙并烦渴乏力，符合Ⅰ型肾小管酸中毒，因远端肾小管泌氢障碍，尿液不能酸化，晨尿pH可大于7.0，类风湿关节炎可继发干燥综合征导致此型。Ⅱ型者近端小管重吸收碳酸氢根障碍，尿pH可低于5.5且尿糖氨基酸阳性；Fanconi综合征为广泛近端小管功能异常；Bartter综合征以低钾碱中毒和血压正常为特点"},{"q":"患者，女，23岁。因呼吸困难、头晕就诊，其他症状包括指尖和口周围的刺痛和麻木，动脉血气：pH 7.54，PaCO2 22mmHg，HCO3－ 22mEq/L，PaO2 115mmHg。该患者可能发生了","o":["呼吸性碱中毒失代偿期","抽取的是静脉血","代谢性酸中毒部分代偿期","呼吸性酸中毒和低氧血症代偿期","代谢性碱中毒部分代偿期"],"a":0,"e":"pH7.54升高、PaCO2显著降低至22mmHg，HCO3正常，提示肺泡过度通气致二氧化碳排出过多，为呼吸性碱中毒失代偿期，低碳酸血症引起手足和口周麻木刺痛。若抽取静脉血PaO2不会高达115mmHg；代谢性酸中毒时pH应降低、HCO3减少；呼吸性酸中毒以PaCO2升高为原发改变"},{"q":"患者，女，40岁，发热牙龈出血伴月经量增多2周。查体：体温39、2℃，贫血貌，浅表淋巴结未及，胸骨压痛，肝肋下1cm，脾肋下2cm。RBC 3.0×1012/L，Hb 72g/L，WBC 32×109/L，BPC 28×109/L。为明确诊断，最有必要进行下列哪项检查","o":["骨髓涂片检查","肝肾功能检查","骨髓活检组织学检查","X线检查","血培养"],"a":0,"e":"发热、贫血、出血倾向、胸骨压痛及肝脾肿大，外周血白细胞显著升高伴血小板减少，符合急性白血病，骨髓涂片可观察原始细胞比例和形态，是确诊的首选。肝肾功能与X线不具特异性；骨髓活检主要用于涂片取材困难或评估纤维化；血培养用于感染性疾病，均非首选"},{"q":"患者，男，67岁。外出旅游中突发高热，寒战，伴腰痛、尿急、尿痛。最先考虑的检查是","o":["尿常规","尿细菌培养","泌尿系超声","静脉肾盂造影","肾功能"],"a":0,"e":"高热寒战伴腰痛、尿急尿痛提示急性肾盂肾炎，尿常规可快速发现白细胞、红细胞及脓尿，是最先进行的筛查。尿细菌培养可明确病原菌但耗时，非首选；泌尿系超声用于排查梗阻和结石；静脉肾盂造影和肾功能检查用于评估结构和功能，均不作为初诊首选"},{"q":"患者，男，56岁，诉咳嗽3个月、咯血2天。既往多年吸烟史。右锁骨上窝触及1枚1cm×1cm质硬淋巴结。胸片提示右肺门包块。下一步最佳检查是","o":["胸部CT","胸部增强CT","胸部磁共振","纤维支气管镜检查及活检","同位素骨扫描"],"a":3,"e":"老年吸烟男性咳嗽咯血、肺门包块伴右锁骨上质硬淋巴结，提示中央型肺癌，纤维支气管镜可直接观察并取活检取得病理确诊。胸部CT及增强CT只能定位定性、不能取得病理；磁共振对肺内病变价值有限；同位素骨扫描仅用于筛查骨转移，均非下一步最佳检查"},{"q":"患儿，男，5个月，出生时诊断为法洛四联症。近2天常于哭闹时突发四肢抽搐，青紫加重，神志不清，呼吸急促，持续时间约1～2min。首先考虑为","o":["脑栓塞","心力衰竭","缺氧发作","休克","脑脓肿"],"a":2,"e":"法洛四联症患儿哭闹后青紫加重、抽搐和神志不清，是缺氧发作的典型表现，因漏斗部痉挛致肺血流骤减、脑缺氧。脑栓塞多见于房颤或感染性心内膜炎，起病突然但无青紫加重过程；心力衰竭以呼吸困难和水肿为主；休克有循环衰竭表现；脑脓肿有发热和局灶体征"},{"q":"患者，男，45岁，自述头昏。体检测血压，上肢血压为21、3/13、3kPa（1kPa≈7、5mmHg），下肢血压为18、7/13、3kPa。该患者最可能的诊断为","o":["血管闭塞性脉管炎","甲状腺功能亢进症","动脉导管未闭","主动脉缩窄","主动脉瓣关闭不全"],"a":3,"e":"正常下肢血压高于上肢20～40mmHg，本例下肢血压低于上肢，提示主动脉缩窄，因缩窄段使上肢血压升高、下肢供血减少。主动脉瓣关闭不全为正脉压增大而非上下肢压差逆转；血管闭塞性脉管炎以下肢缺血为主但上肢血压不高；甲亢和动脉导管未闭无此上下肢血压差"},{"q":"一老年患者，发现尿色呈鲜红色2天，每次排尿为开始尿色正常，末段尿为红色，有排尿困难，无发热和腹痛。该患者尿色呈鲜红色，最有可能为","o":["真性血尿","血红蛋白尿","卟啉尿","进食某些食物和药物引起","梗阻性黄疸"],"a":0,"e":"尿色鲜红且终末段变红、伴排尿困难，提示终末段血尿，出血部位在膀胱颈部、三角区或前列腺，镜检见大量红细胞故为真性血尿。血红蛋白尿呈酱油色且镜检无红细胞；卟啉尿和食物药物所致尿色改变镜检亦无红细胞；梗阻性黄疸为结合胆红素升高致尿色深黄而非血尿"},{"q":"患者，男，15岁，乏力、面色苍白，酱油色尿，巩膜黄染，肝脾不大。外周血：RBC 3、90×1012/L，Hb 100g/L，MCV 88fl，MCHC 320g/L，WBC 4.0×109/L，PLT 100×109/L，RC 16%。最可能的诊断是","o":["缺铁性贫血","溶血性贫血","再生障碍性贫血","白血病","巨幼红细胞贫血"],"a":1,"e":"贫血、黄疸、酱油色尿伴网织红细胞显著升高至16%，提示骨髓红细胞系代偿性增生，结合正常细胞性贫血，符合溶血性贫血。缺铁性贫血为小细胞低色素且网织红细胞不高；再生障碍性贫血网织红细胞减少；白血病外周血可见原始细胞；巨幼红细胞贫血为大细胞性"},{"q":"60岁老年男性患者出现无症状性肉眼血尿，首先应考虑","o":["膀胱炎","膀胱结核","前列腺增生","肾结石","膀胱癌"],"a":4,"e":"老年男性无痛性肉眼血尿是泌尿系肿瘤的重要信号，膀胱癌最为常见，肿瘤表面破溃出血致尿色发红而不伴疼痛。膀胱炎和膀胱结核均有明显尿频尿急尿痛；肾结石伴肾区绞痛；前列腺增生以夜尿和进行性排尿困难为主，血尿不明显，均不符合无痛性血尿特点"},{"q":"患者，女，50岁。20年前曾患甲亢，行131I治疗后痊愈。近半年开始出现面色苍白、颜面水肿、皮肤干燥、注意力不集中。该患者的面容是","o":["慢性病容","贫血面容","黏液性水肿面容","肾病面容","甲状腺功能亢进面容"],"a":2,"e":"131I治疗后出现甲状腺功能减退，黏液性水肿面容表现为面色苍黄、颜面水肿、睑厚面宽、目光呆滞、反应迟钝及毛发稀疏。肾病面容为面色苍白、眼睑颜面水肿伴舌缘齿痕；贫血面容唇舌色淡；甲亢面容惊愕、眼裂增宽、眼球突出，与本例相反"},{"q":"患儿，男，5岁，玩积木玩具时突发呼吸困难，胸骨上窝、锁骨上窝和肋间隙明显凹陷。下列最有可能的疾病是","o":["室间隔缺损","肺栓塞","神经肌肉疾病","肺炎","气道阻塞"],"a":4,"e":"玩耍时突发呼吸困难并见胸骨上窝、锁骨上窝和肋间隙凹陷的三凹征，为吸气性呼吸困难，提示上气道阻塞，异物吸入最为可能。室间隔缺损表现为心脏杂音和反复肺部感染；肺栓塞多伴咯血和右心负荷增加；神经肌肉疾病致呼吸肌无力；肺炎伴发热和湿啰音，均无典型三凹征"},{"q":"患者，男，40岁，反复饥饿时中上腹部隐痛10年，伴反酸嗳气，在进食和服制酸剂后可缓解，今晨中上腹剧痛后腹痛持续存在。为确诊疾病，应选择的检查手段是","o":["血清淀粉酶测定","癌胚抗原测定","胃镜检查","X线腹部平片","腹部超声检查"],"a":2,"e":"慢性周期性上腹痛、进食和制酸剂可缓解，符合消化性溃疡，胃镜可直接观察溃疡部位、大小并取活检，是确诊的首选。血清淀粉酶用于急性胰腺炎；癌胚抗原用于肿瘤辅助判断；腹部平片主要显示穿孔的膈下游离气体；腹部超声对胃十二指肠病变价值有限"},{"q":"患者，女，28岁。恶心、尿色变黄6天，体检发现巩膜中度黄染，肝肋下2cm可及，血谷丙转氨酶840U/L，总胆红素85μmol/L。最可能的诊断是","o":["急性胆道感染","病毒性肝炎","钩体病","遗传性胆道疾病","原发性胆汁性肝硬化"],"a":1,"e":"恶心、尿黄、巩膜黄染伴ALT显著升高至840U/L，符合急性病毒性肝炎，转氨酶可达正常上限数十倍且ALT升高更明显。急性胆道感染常有发热和右上腹绞痛；钩体病有发热、腓肠肌痛和疫水接触史；遗传性胆道疾病起病缓慢；原发性胆汁性肝硬化以ALP升高和抗线粒体抗体阳性为主"},{"q":"患者，女，66岁，来到急诊室，有明显的肺水肿。动脉血气：pH 7.10，HCO3－ 8mEq/L，PaCO2 25mmHg，BE -20mEq/L，脉搏140/min，PaO2 40mmHg，SO2 52%。该患者可能发生了","o":["呼吸性酸中毒和低氧血症代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","代谢性酸中毒失代偿期和Ⅰ型呼吸衰竭","抽取的是静脉血"],"a":3,"e":"pH7.10显著降低、HCO3明显减少、BE为-20，提示代谢性酸中毒失代偿，PaCO2下降为呼吸代偿；PaO2仅40mmHg低于60mmHg，符合Ⅰ型呼吸衰竭。呼吸性酸中毒以PaCO2升高为原发；呼吸性碱中毒pH升高；抽取静脉血PaO2不会如此之低且pH更低，均不符合"},{"q":"患者，男，40岁。反复左上腹疼痛4年，消瘦，乏力，经常腹泻，稀水样便。大便镜检：无RBC和WBC，有较多的脂肪小滴和肌肉纤维。结肠镜：全结肠未见改变。B超：肝胆正常，胰腺回声粗糙。应首先考虑哪种疾病","o":["慢性胆囊炎","慢性结肠炎","急性胰腺炎","慢性胰腺炎","急性胆囊炎"],"a":3,"e":"慢性左上腹痛、消瘦腹泻，粪便见大量脂肪小滴和肌肉纤维提示脂肪泻，B超胰腺回声粗糙，符合慢性胰腺炎致胰腺外分泌功能不全。慢性胆囊炎和胆石症无脂肪泻；结肠镜正常可排除慢性结肠炎；急性胰腺炎为急性剧烈腹痛伴淀粉酶升高，均无慢性经过"},{"q":"一高血压病患者因口角流涎入院检查。接诊医生查体发现存在左侧中枢性面瘫。以下不是该患者临床表现的是","o":["左侧鼻唇沟浅","左侧露齿浅","左侧鼓腮漏气","左额额纹浅","不能吹口哨"],"a":3,"e":"中枢性面瘫仅累及病灶对侧下半部面肌，因上半部面肌受双侧皮质支配，故鼻唇沟变浅、露齿浅、鼓腮漏气、不能吹口哨均可出现，而额纹不受累，左额额纹浅不属于其表现，额纹变浅见于周围性面瘫"},{"q":"患者，男，71岁，退休机械师。患者有呼吸困难、咳嗽和痰液增多的病史，有120包/年的吸烟史，5年前戒烟，现被送往ICU。检查中使用了呼吸机辅助，仍存在通气不足，肢端发绀。动脉血气：pH 7、21，PaCO2 75mmHg，HCO3－ 30mEq/L，PaO2 41mmHg。此时患者最可能发生了","o":["急性呼吸性酸中毒并发慢性呼吸性酸中毒","呼吸性碱中毒失代偿期","代谢性酸中毒部分代偿期","代谢性碱中毒部分代偿期","抽取的是静脉血"],"a":0,"e":"长期大量吸烟的COPD患者通气不足，PaCO2高达75mmHg、pH7.21，HCO3仅轻度升高未及充分代偿，提示在慢性呼吸性酸中毒基础上合并急性加重，即急性呼吸性酸中毒并发慢性呼吸性酸中毒。呼吸性碱中毒PaCO2降低；代谢性酸碱失衡以HCO3原发改变为主；PaO2不低不支持静脉血"},{"q":"患者，女，62岁，夜间看电视时出现头痛，随后恶心、呕吐胃内容物，呕吐呈喷射样，最可能的诊断为","o":["幽门梗阻","胃潴留","霍乱","脑出血","急性心肌梗死"],"a":3,"e":"突发头痛伴喷射样呕吐提示颅内压急剧升高，常见于脑出血，因颅内血肿占位刺激呕吐中枢。幽门梗阻呕吐含隔夜宿食、非喷射性；胃潴留为餐后呕吐；霍乱以剧烈腹泻为主；急性心肌梗死以胸痛和心电图改变为主，均无喷射性呕吐与突发头痛组合"},{"q":"患者，男，82岁，喘憋1周，加重1天。查体：心率56次/min，呼吸20次/min，血压137/64mmHg。既往有冠状动脉粥样硬化性心脏病，高血压。这样的心电图比较常见下列哪种情况","o":["血钾6.0mmol/L","血钾2.1mmol/L","血钠130mmol/L","血钠160mmol/L","洋地黄中毒"],"a":4,"e":"器质性心脏病患者出现双向性室性心动过速等复杂心律失常，是洋地黄中毒的特征性表现，因洋地黄抑制Na+-K+泵致细胞内钙超载和触发活动。高钾血症以T波高尖、QRS增宽为主；低钾血症以U波增高和ST压低为主；低钠、高钠主要影响意识，均无双向性室速"},{"q":"患儿，女，2岁，在幼儿园进食后出现腹痛、血便和肾衰竭。同时进食儿童也有数人出现相同的症状，被诊断为出血性结肠炎。细菌培养只有大肠埃希菌生长，可能的病原菌是","o":["肠毒素性大肠埃希菌","肠出血性大肠埃希菌","肠致病性大肠埃希菌","肠侵袭性大肠埃希菌","肠凝聚性大肠埃希菌"],"a":1,"e":"腹痛、血便及肾衰竭，培养为大肠埃希菌，符合肠出血性大肠埃希菌感染，其产生志贺样毒素损伤肠黏膜致出血性结肠炎，并可并发溶血尿毒综合征致肾衰竭。肠毒素性大肠埃希菌致水样泻；肠致病性多见于婴幼儿腹泻；肠侵袭性引起痢疾样脓血便；肠凝聚性与慢性腹泻相关"},{"q":"一年轻女性因下肢无力入院。查体发现患者上腹壁反射存在，中腹壁反射及下腹壁反射消失。推测脊髓损伤以下哪个节段","o":["胸髓第2～4节段","胸髓第6～7节段","胸髓第7～8节段","胸髓第9～10节段","胸髓第11～12节段"],"a":3,"e":"腹壁反射上腹壁由胸髓7～8节、中腹壁由胸髓9～10节、下腹壁由胸髓11～12节支配，上腹壁反射存在而中、下腹壁反射消失，提示胸髓9～10节段病损。胸髓2～4节与腹壁反射无关；胸髓7～8节损害应累及上腹壁反射；胸髓11～12节仅影响下腹壁反射"},{"q":"患者，男，68岁。突然发生寒战、高热（体温39℃）、咳嗽、咳痰，痰呈黏稠、砖红色、胶冻状。引起感染最可能的病原菌是","o":["克雷伯杆菌","流感嗜血杆菌","铜绿假单胞菌","葡萄球菌","肺炎球菌"],"a":0,"e":"寒战高热伴黏稠砖红色胶冻状痰是肺炎克雷伯菌肺炎的特征，因细菌荚膜使痰液黏稠并带血。流感嗜血杆菌多致会厌炎或儿童中耳炎；铜绿假单胞菌痰呈蓝绿色、有特殊气味；葡萄球菌肺炎痰为脓性或带血丝；肺炎链球菌肺炎典型为铁锈色痰，均非砖红色胶冻样"},{"q":"患者，男，40岁，患慢性乙型肝炎10余年。近2个月出现大量腹水，腹部膨隆。欲查清该患者的脾大情况，最宜选择下列哪种检查方法","o":["浅部触诊法","双手触诊法","深部滑行触诊法","深压触诊法","浮沉触诊法"],"a":4,"e":"大量腹水时脏器被液体隔开，常规触诊难以触及，浮沉触诊法以并拢手指冲击腹壁，排开腹水使脾脏浮起触及，是腹水患者查脾的首选。浅部触诊用于腹壁浅表病变；双手触诊适用于无腹水时的肝脾检查；深部滑行触诊用于腹腔内肿块；深压触诊用于反跳痛和压痛点"},{"q":"患有糖尿病的30岁男性患者因为急性呼吸困难来到急诊室，动脉血气为：pH 7.33，PaCO2 24mmHg，PaO2 111mmHg，HCO3－ 12mEq/L","o":["代谢性酸中毒部分代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","呼吸性酸中毒和低氧血症代偿期","抽取的是静脉血"],"a":0,"e":"糖尿病患者出现急性呼吸困难，pH7.33偏低、HCO3显著降低、PaCO2代偿性下降而仍未恢复正常，符合代谢性酸中毒部分代偿期，常见于糖尿病酮症酸中毒。呼吸性碱中毒pH升高且PaCO2原发降低；代谢性碱中毒HCO3升高；呼吸性酸中毒PaCO2升高，均与本例不符"},{"q":"患者，男，38岁。3年前患结核性心包炎，近1～2个月呼吸困难伴腹胀、水肿。该患者最可能出现的体征是","o":["颈静脉怒张","颈静脉塌陷","颈动脉搏动增强","颈动脉搏动消失","颈部血管杂音"],"a":0,"e":"结核性心包炎后心包缩窄，限制心室充盈致体循环淤血，出现颈静脉怒张、肝大和水肿，故最可能出现颈静脉怒张。颈静脉塌陷提示血容量不足；颈动脉搏动增强见于主动脉瓣关闭不全等脉压增大情况；颈动脉搏动消失见于大动脉闭塞；颈部血管杂音为血管狭窄表现"},{"q":"一肺癌患者，病灶直径为4cm，距体表距离为4cm，其叩诊音应为","o":["清音","浊音","实音","浊鼓音","过清音"],"a":1,"e":"肺内占位距胸壁4cm、直径4cm，超过5cm深部病灶或3cm以下小病灶才常无叩诊改变，本例大小及深度足以使叩诊呈浊音。清音为正常肺组织；实音见于大量胸腔积液或肺实变；浊鼓音为肺含气量减少与空洞混合；过清音见于肺气肿，均不符合"},{"q":"一尿毒症患者，随呼吸运动胸痛明显，在肺部听诊时，最可能出现的体征为","o":["胸语音","耳语音","羊鸣音","支气管语音","胸膜摩擦音"],"a":4,"e":"尿毒症可并发纤维蛋白性胸膜炎，胸膜表面粗糙，呼吸时脏壁两层胸膜摩擦产生胸膜摩擦音，随呼吸运动出现、屏气消失。胸语音、耳语音、羊鸣音和支气管语音均属语音共振异常，主要见于肺实变或空洞等，与胸膜摩擦无关"},{"q":"患者，女，50岁。劳累后心前区疼痛2小时，休息后可自行缓解。既往高血压病史3年，未行诊治。心电图检查：V1～V3导联ST段压低。该患者危险分级所应用的生化指标为","o":["CKMB 乳酸脱氢酶","乳酸脱氢酶 肌红蛋白","肌红蛋白 AST","AST 肌钙蛋白","CKMB 肌钙蛋白"],"a":4,"e":"肌钙蛋白和CK-MB对心肌损伤特异度高，是急性冠脉综合征诊断和危险分层的核心指标，肌钙蛋白升高提示心肌坏死风险。肌红蛋白出现最早但特异性低；乳酸脱氢酶和AST特异性差、窗口期晚，均不用于危险分层的主要判断"},{"q":"患者，女，68岁，外阴瘙痒1个月。阴道分泌物发现线索细胞，考虑诊断为","o":["滴虫性阴道炎","真菌性阴道炎","细菌性阴道炎","淋菌性阴道炎","慢性宫颈炎"],"a":2,"e":"线索细胞是阴道鳞状上皮细胞黏附大量加德纳菌等细小细菌而成，是细菌性阴道炎的诊断依据之一。滴虫性阴道炎分泌物中找到阴道毛滴虫；真菌性阴道炎可见白念珠菌菌丝和孢子；淋菌性阴道炎为淋病奈瑟菌感染；慢性宫颈炎以宫颈黏液脓性分泌物为主"},{"q":"患者，男，70岁。患高血压合并左心衰竭，长期口服ACEI类药物及利尿剂，1周前自行调整用药剂量后自觉乏力、腹胀。今日来院复查，行血电解质检查，最符合该患者目前情况的检查结果是","o":["血钾3.0mmol/L","血钠150mmol/L","血氯115mmol/L","血钙2.09mmol/L","血磷1.7mmol/L"],"a":0,"e":"呋塞米等利尿剂使钾排出增多，ACEI虽保钾但剂量调整后排钾占优势，低钾血症可引起乏力、腹胀，故最符合血钾3.0mmol/L。血钠150mmol/L为高钠血症；血氯115mmol/L为高氯血症；血钙、血磷异常无乏力腹胀的利尿剂相关性，均非该用药背景下的典型改变"},{"q":"患者，男，60岁，主诉：血压偏高2年，近1周头晕、胸闷、心悸。患者脉压增大，应考虑","o":["主动脉瓣狭窄","主动脉瓣关闭不全","贫血","动脉硬化","心肌梗死"],"a":3,"e":"老年高血压患者脉压增大≥60mmHg，多因主动脉和大动脉弹性减退、顺应性下降，即动脉硬化所致，收缩压升高而舒张压不高。主动脉瓣狭窄致脉压减小；贫血虽可脉压增大但无贫血依据且非老年高血压主因；心肌梗死多有胸痛和心电图改变，均非本例首选"},{"q":"患者，男，64岁。排尿不畅1年余。直肠指检：前列腺增大，表面光滑，按压前列腺，无明显压痛。该患者最可能的诊断是","o":["正常前列腺","前列腺肥大","前列腺癌","急性前列腺炎","慢性前列腺炎"],"a":1,"e":"老年男性排尿不畅，直肠指检前列腺增大、表面光滑、有韧感且无压痛，符合良性前列腺肥大，正中沟常消失。前列腺癌质硬、表面有硬结节；急性前列腺炎肿大有明显压痛；正常前列腺体积正常、无排尿症状；慢性前列腺炎多伴会阴不适和前列腺液异常"},{"q":"患者，男，34岁。面黄1周。查体：皮肤及巩膜黄染，心肺无异常，肝肋下2cm，轻触痛。实验室检查：ALT 300U/L。其他最可能出现的实验室检查结果是","o":["血中结合胆红素和游离胆红素均增多","尿三胆试验均阳性","粪便颜色变深","血清总胆红素升高，结合胆红素减少","血中结合胆红素显著增加，而未结合胆红素减少"],"a":0,"e":"ALT显著升高伴皮肤巩膜黄染，符合急性肝细胞性黄疸，肝细胞摄取、结合和排泄胆红素均受损，血中结合胆红素与游离胆红素均增多。血清总胆红素升高而结合胆红素减少见于溶血性黄疸；结合胆红素显著增加、未结合胆红素减少见于阻塞性黄疸；尿三胆均阳性不符合肝细胞性黄疸规律"},{"q":"患者，男，58岁。进行性排尿困难1年，伴无痛性肉眼血尿、尿频、夜尿增多。查体未见明显异常。尿常规示尿蛋白（-），镜检WBC 0～4个/HPF，RBC（+++）。该患者最可能的诊断是","o":["尿路感染","泌尿系结石","膀胱肿瘤","前列腺增生症","前列腺炎"],"a":2,"e":"进行性排尿困难伴无痛性肉眼血尿、尿红细胞显著增多，提示膀胱肿瘤，肿瘤浸润膀胱颈或前列腺部尿道致排尿困难，无痛性血尿为其特点。尿路感染有尿频尿急尿痛；泌尿系结石伴绞痛；前列腺增生和前列腺炎血尿不明显且以前列腺症状为主，均不符"},{"q":"患者，女，45岁。双腕关节指间关节肿痛伴晨僵半年，查体示手指关节呈梭形改变。最可能的疾病是","o":["骨关节炎","类风湿关节炎","系统性红斑狼疮","代谢性骨病","痛风性关节炎"],"a":1,"e":"双手对称性的腕关节和指间关节肿痛伴晨僵，手指呈梭形改变，是类风湿关节炎的典型表现，因滑膜慢性增生性炎症致关节畸形。骨关节炎多累及负重关节、晨僵短暂；系统性红斑狼疮有皮疹和多系统损害；代谢性骨病无对称性小关节滑膜炎；痛风多为单关节急性红肿热痛伴尿酸升高"},{"q":"患者，男，50岁，喜食肥肉。心前区阵发性疼痛2个月，活动后加重。查体：心率83次/min，律齐。心电图示ST段下移，冠脉CTA示冠脉降支80%狭窄，TG 6.8mmol/L。该患者引起冠状动脉狭窄最可能的原因是","o":["冠心病","高脂血症","高尿酸血症","糖尿病","肥胖"],"a":1,"e":"冠状动脉CTA示冠脉明显狭窄，TG高达6.8mmol/L，高甘油三酯是动脉粥样硬化的重要危险因素，长期高脂饮食致脂质沉积形成斑块。冠心病是狭窄导致的结果而非病因；高尿酸血症与痛风相关；糖尿病和肥胖为危险因素但本例以高脂血症最直接"},{"q":"患者，男，35岁，经常发生无明确诱因的上腹部疼痛，左侧卧位可使疼痛减轻。查体：巩膜无黄染，全腹无肌紧张、无压痛、肝脾未触及。最可能的诊断为","o":["胃黏膜脱垂","溃疡性结肠炎","血卟啉病","胰腺癌","肠扭转"],"a":0,"e":"上腹部疼痛与体位相关、左侧卧位减轻是胃黏膜脱垂的特征，脱垂的胃黏膜回纳后症状缓解。溃疡性结肠炎以腹泻、黏液脓血便为主；血卟啉病有腹痛和精神症状；胰腺癌疼痛呈持续性并向背部放射；肠扭转多为急性剧烈绞痛，均无左侧卧位缓解特点"},{"q":"年轻男性，发热5天，每天体温维持在39～41℃，24小时内体温波动相差不超过1℃。体检发现腹部玫瑰疹，肝脾肿大。该患者的热型是","o":["间歇热","波状热","回归热","稽留热","弛张热"],"a":3,"e":"体温持续维持在39～41℃高水平达5天，24小时波动不超过1℃，符合稽留热，伴腹部玫瑰疹和肝脾肿大提示伤寒高热期。弛张热24小时波动超过1℃；间歇热体温可降至正常；波状热为布氏杆菌病的热型；回归热为周期性高热与无热期交替，均不符合"},{"q":"患者，女，47岁，胆囊结石取出术后第2天，诉胸痛。床旁血气：pH 7.45，PaCO2 25mmHg，HCO3- 17mEq/L，PaO2 58mmHg。此时患者最可能发生了","o":["呼吸性碱中毒与低氧血症代偿期","呼吸性碱中毒失代偿期","代谢性碱中毒部分代偿期","呼吸性酸中毒与低氧血症代偿期","抽成了静脉血"],"a":0,"e":"pH7.45在正常高限、PaCO2显著降低、HCO3相应下降，提示呼吸性碱中毒处于代偿阶段；PaO258mmHg低于60mmHg为低氧血症，故为呼吸性碱中毒与低氧血症代偿期。呼吸性碱中毒失代偿期pH应大于7.45；代谢性碱中毒HCO3升高；呼吸性酸中毒PaCO2升高，均不符"},{"q":"患者，女，25岁，因“双下肢水肿半个月”入院。查BP 150/70mmHg，尿蛋白（＋＋＋），尿红细胞（＋＋），血WBC降低，血Cr 110μmol/L，Coombs试验阳性，补体降低，抗核抗体阳性，类风湿因子阳性。最可能的诊断是","o":["慢性肾小球肾炎","急性肾小球肾炎","类风湿关节炎","系统性红斑狼疮","IgA肾病"],"a":3,"e":"水肿、蛋白尿、血尿伴白细胞减少、Coombs试验阳性、抗核抗体阳性及补体降低，为多系统受累和自身抗体产生，符合系统性红斑狼疮及狼疮性肾炎。急慢性肾小球肾炎无多种自身抗体；类风湿关节炎以关节病变为主；IgA肾病以血尿为主且无自身抗体，均不符"},{"q":"患者，男，18岁，学校体检心电图发现异常，如下，最可能的诊断是","o":["窦性心动过缓","三度房室传导阻滞，交界区逸搏心律","窦性心律，频发交界区期前收缩","三度房室传导阻滞，室性逸搏心律","二度Ⅱ型房室传导阻滞"],"a":1,"e":"本题原题配有图片，图片未随文档保留，以下解析依文字线索推断：题干涉及图片/信息缺失，无法作答。三度房室传导阻滞时心房激动完全不能下传，阻滞以下潜在起搏点发放激动，若QRS正常、频率40～60次/分则为交界区逸搏心律。窦性心动过缓每个P波后均有QRS；室性逸搏心律QRS宽大畸形、频率20～40次/分；二度Ⅱ型存在间歇下传的P波，均不同\n\n官方题库中缺失图片"},{"q":"患者，男，晨起尿液呈红色，遂就诊。尿常规：尿潜血（＋＋＋），镜检发现尿中出现大量均一性红细胞，关于红细胞来源，错误的是","o":["肾脏","输尿管","膀胱","前列腺","尿道"],"a":0,"e":"均一性红细胞形态一致，提示出血来自肾小球以下的泌尿道，输尿管、膀胱、前列腺和尿道出血均属此类。肾小球来源的血尿因红细胞通过受损基底膜受挤压变形，呈非均一性红细胞并伴蛋白尿和管型，故肾脏不是均一性红细胞的来源"},{"q":"患者，女，43岁，慢性乙型肝炎20年。近期恶心、食欲减退，查体：心肺无异常，脾肋下3cm，双下肢凹陷性水肿。该患者不会出现的情况是","o":["凝血因子缺乏","血红蛋白减少","雌激素增加","醛固酮增加","肾上腺皮质激素减少"],"a":3,"e":"官方答案为【醛固酮增加】，但依据教材，正确答案为【肾上腺皮质激素减少】。肝硬化腹水的形成机制包括继发性醛固酮增多，患者实际会出现醛固酮增加，将其列为不会出现与教材矛盾。肝硬化时肝脏对雌激素和醛固酮等激素灭活减少，凝血因子合成减少并可伴贫血，而肾上腺皮质激素减少并非其表现"},{"q":"患者，女，25岁。近年来多次于情绪激动或生气后出现四肢抽搐，两眼紧闭，每次发作时间较长。抽搐发作时，无舌咬伤及大、小便失禁。该患者最可能的诊断是","o":["晕厥","癫痫小发作","癫痫大发作","癔症性发作","短暂性脑缺血发作"],"a":3,"e":"发作有明显情绪激动诱因，发作形式不固定、持续时间较长，且无舌咬伤和大小便失禁，符合癔症性发作。癫痫大发作有意识丧失、舌咬伤和尿失禁，发作后意识恢复较慢；癫痫小发作以短暂意识障碍为主；晕厥多为短暂意识丧失；短暂性脑缺血发作有局灶神经功能缺损"},{"q":"患者，男，54岁。右肋痛４个月，食欲减退。查体：巩膜轻度黄染，肝肋下1cm，质中等，未触及结节。肝CT扫描见肝有大小不等的斑块放射性缺损区，边缘不整齐。实验室检查：AFP 540μg/L，HBsAg（＋）。该患者最可能的诊断是","o":["乙型肝炎","阿米巴肝脓肿","肝硬化","原发性肝癌","淤胆性肝炎"],"a":3,"e":"AFP高达540μg/L并持续升高，结合HBsAg阳性、肝右叶占位和CT斑块状缺损，符合原发性肝癌，AFP≥400ng/ml持续1个月为重要诊断依据。乙型肝炎和肝硬化AFP仅轻度升高；阿米巴肝脓肿有发热和脓液；淤胆性肝炎以ALP和胆红素升高为主，均无AFP显著增高"},{"q":"患者，男，46岁，长期大量饮酒史，腹胀1个月入院。近2天尿量200ml/d。查体：巩膜黄染，颈部见蜘蛛痣，颈静脉不充盈，腹部膨隆，移动性浊音阳性。该患者少尿的原因首先考虑","o":["心功能不全","慢性肾炎","肝肾综合征","前列腺肥大","急性肾炎"],"a":2,"e":"肝硬化失代偿期出现大量腹水和少尿，但颈静脉不充盈，提示肾血流量减少所致的肾前性少尿，即肝肾综合征。心功能不全致少尿常有颈静脉怒张和肺淤血；急慢性肾炎有血尿、蛋白尿和高血压；前列腺肥大表现为排尿困难和残余尿增多，均不符合"},{"q":"患者，男，神经系统查体发现眼球受压30s后心率减少达15次/min。这提示","o":["迷走神经功能增强","迷走神经功能麻痹","交感神经亢进","深感觉过敏","深反射活跃"],"a":0,"e":"压迫眼球后心率减少达15次/分，超过正常减少10～12次/分的范围，为眼心反射亢进，提示迷走神经功能增强。迷走神经麻痹时压迫眼球无心率减慢反应；交感神经亢进时压迫后心率反而加快；深感觉过敏和深反射活跃属于神经系统其他体征，与眼心反射无关"},{"q":"患者，女，22岁。2个月前开始无明显诱因出现怕热多汗、心悸手抖、烦躁易怒、体重下降。查体脉搏100次/min，双眼凸出、睑裂增大、瞬目减少。最可能的诊断是","o":["眼球筋膜炎","肢端肥大症","破伤风","甲状腺功能亢进","库欣综合征"],"a":3,"e":"怕热多汗、心悸手抖、烦躁易怒、体重下降伴突眼和睑裂增大，是甲状腺激素过多致代谢亢进和交感兴奋的表现，符合甲状腺功能亢进。库欣综合征为向心性肥胖和满月脸；肢端肥大症为手足增大和面容改变；破伤风有牙关紧闭和肌强直；眼球筋膜炎无全身代谢症状"},{"q":"患者，男，35岁。眩晕1天，伴恶心、呕吐，无耳鸣及听力减退，有近期上呼吸道感染史。查体：T 36.5℃，神志清，四肢肌力及腱反射正常。该患者最可能的诊断是","o":["梅尼埃病","多发性硬化","前庭神经元炎","颅内感染性疾病","癫痫"],"a":0,"e":"官方答案为【梅尼埃病】，但依据教材，正确答案为【前庭神经元炎】。前庭神经元炎多在上呼吸道感染后急性起病，眩晕伴恶心呕吐而一般无耳鸣及听力减退，与本例相符；梅尼埃病以发作性眩晕伴耳鸣、听力减退和眼震为特点。多发性硬化有中枢体征；颅内感染伴发热和脑膜刺激征；癫痫为反复发作的脑部异常放电"},{"q":"患者，男，55岁。近两年有夜间阵发性呼吸困难，入院前2小时出现呼吸困难，咳粉红色泡沫痰。患者最可能出现呼吸困难的原因是","o":["急性左心衰竭","心肌梗死","支气管哮喘","气胸","肺炎"],"a":0,"e":"夜间阵发性呼吸困难、端坐呼吸和咳粉红色泡沫痰是急性左心衰竭肺淤血的典型表现，因肺毛细血管压力急剧升高致液体和红细胞渗入肺泡。支气管哮喘以呼气性哮鸣音为主、无粉红泡沫痰；气胸为突发胸痛和呼吸音消失；肺炎有发热和实变体征；心肌梗死以胸痛为主"},{"q":"年轻女性，反复发作咳嗽、胸闷4年，常在春夏之交发作，夜间重，并有鼻痒、喷嚏等症。听诊双肺较多干性啰音，呼气延长。最可能的诊断为","o":["肺气肿","气胸","胸腔积液","支气管哮喘","慢性支气管炎"],"a":3,"e":"反复发作性咳嗽胸闷、有明显季节和夜间规律，伴鼻痒喷嚏等过敏表现，双肺干啰音和呼气延长提示可逆性气流受限，符合支气管哮喘。慢性支气管炎以长期咳痰为主、季节规律不明显；肺气肿为持续性呼吸困难；气胸为突发胸痛；胸腔积液叩诊浊音，均无发作性过敏特点"},{"q":"患者，男，42岁，急性白血病（M5）化疗后缓解，拟行骨髓移植。移植配型时，HLA各位点中抗原相配程度最为重要的是","o":["人类白细胞抗原-D和DR","人类白细胞抗原-B","人类白细胞抗原-A","人类白细胞抗原-C","人类白细胞抗原-DN"],"a":0,"e":"HLA-DR的配合对提高移植物存活率尤为重要，供受者HLA-A、B、D、DR相同者存活率明显更高，故骨髓移植配型以D和DR位点最为关键。HLA-A、B虽参与配型但重要性次于DR；HLA-C和DN与移植排斥关系较弱，均非最关键位点"},{"q":"患者，男，16岁。自幼常有鼻出血，3天前踢球时外伤，右大腿肿胀，活动受限，有家族史。为确诊应做的检查是","o":["毛细血管脆性试验","出血时间","凝血酶凝固时间","部分凝血活酶时间","抗凝血酶Ⅲ活性"],"a":3,"e":"自幼鼻出血、外伤后深部组织肿胀并有家族史，提示血友病等内源性凝血因子缺乏，活化部分凝血活酶时间是内源凝血系统最灵敏和常用的筛选试验，故为确诊首选。毛细血管脆性试验用于血管壁异常；出血时间反映血小板功能；凝血酶凝固时间检测纤维蛋白原；抗凝血酶Ⅲ活性用于易栓症"},{"q":"患者，男，46岁。活动耐力进行性下降5年。近半年来平地步行50m左右即感呼吸急促，并出现双下肢水肿。1周前上呼吸道感染后症状加重，伴夜间阵发性呼吸困难。查体：平卧位，颈静脉怒张，肝颈静脉反流征阳性，双肺可闻及细湿啰音，双下肢凹陷性水肿。目前该患者的心力衰竭类型为","o":["急性右心衰竭","急性左心衰竭","全心衰竭","慢性左心衰竭","慢性右心衰竭"],"a":2,"e":"夜间阵发性呼吸困难和双肺湿啰音提示肺淤血的左心衰竭表现，颈静脉怒张、肝颈静脉反流征阳性和下肢水肿提示体循环淤血的右心衰竭表现，两者并存为全心衰竭。单纯左心衰竭无体循环淤血体征；急性右心衰竭无慢性肺淤血过程；急性心衰起病急骤，均不符"},{"q":"患者，男，32岁，低热、乏力，盗汗1个月余。近日胸闷呼吸困难，X线示胸腔积液，考虑为渗出液。下列描述正确的是","o":["置入试管内不自凝","蛋白定量＜25g/L","葡萄糖定量与血糖相近","细胞计数常＞500×106/L","以淋巴细胞、间皮细胞为主"],"a":3,"e":"渗出液因炎症致血管通透性增加，细胞数常大于500×10⁶/L，符合该患者低热盗汗、结核性胸膜炎的积液特点。渗出液含纤维蛋白原易自凝，不自凝为漏出液；蛋白定量小于25g/L为漏出液；渗出液葡萄糖常低于血糖；结核性积液以淋巴细胞为主，但细胞总数增多是渗出液的通用标准"},{"q":"患者，男，50岁，肝硬化病史10年，以严重腹水3周来诊。肝脾触诊应采用哪种方法","o":["单手触诊法","双手触诊法","滑动触诊法","钩指触诊法","冲击触诊法"],"a":4,"e":"大量腹水时肝脾被液体包围，冲击触诊法以并拢三指快速冲击腹壁，使脏器在液体中浮沉被触及，是腹水患者检查肝脾的方法。单手触诊用于一般腹部触诊；双手触诊适用于无腹水时；滑动触诊用于胃肠道和肿块；钩指触诊多用于儿童肝脾，均不适合大量腹水"},{"q":"患者，男，24岁。1个月前无明显诱因出现咳嗽、乏力、盗汗，伴胸痛，随呼吸或咳嗽加重，查体示气管向右侧移位。该患者最可能的疾患是","o":["自发性气胸","胸膜粘连","结核性胸膜炎并左侧胸腔积液","结核性胸膜炎并右侧胸腔积液","大叶性肺炎"],"a":2,"e":"低热、盗汗、胸痛随呼吸咳嗽加重，提示结核性胸膜炎，气管向右侧移位说明左侧胸腔占位效应，由左侧积液推挤纵隔所致，故为合并左侧胸腔积液。若为右侧积液气管应左移；自发性气胸叩诊鼓音；胸膜粘连气管向患侧移位；大叶性肺炎无气管移位和积液征"},{"q":"患者，男，40岁，饥饿时中上腹部隐痛10年，伴反酸嗳气，在进食和服制酸剂后可缓解。今晨中上腹剧痛后腹痛持续存在。该患者最可能患的基础疾病是","o":["急性胰腺炎","胰腺癌","胃癌","消化性溃疡","急性胆囊炎"],"a":3,"e":"慢性周期性饥饿痛、进食和服制酸剂缓解，是消化性溃疡的典型节律性疼痛，今晨剧痛持续提示可能出现穿孔等并发症，基础疾病仍为消化性溃疡。急性胰腺炎多为暴饮暴食后持续性剧痛；胰腺癌疼痛无节律且伴消瘦；胃癌疼痛节律消失；急性胆囊炎为右上腹痛伴发热"},{"q":"患者，男，65岁，诊断乙肝肝硬化失代偿期，有门静脉高压。其查体腹壁静脉血流方向正确的是","o":["与正常的血流方向相同","与正常的血流方向相反","方向不固定","肚脐以下向上流","肚脐以上向下流"],"a":0,"e":"门静脉高压时腹壁曲张静脉以脐为中心向四周放射，脐以上血流向上、脐以下向下，与正常腹壁静脉血流方向相同。下腔静脉阻塞时脐以下血流改向上；上腔静脉阻塞时上腹壁血流向下，均与正常方向相反，可借此鉴别"},{"q":"患者，男，50岁，患肝硬化5年。肝脏超声为：肝脏缩小，表面不平，内部回声粗糙。近1个月，肝脏增大，肋下可及。应首选复查的化验检查是","o":["GPT","A/G","GOT","AFP","ALP"],"a":3,"e":"肝硬化患者肝脏由缩小转为增大，提示可能恶变为原发性肝癌，AFP是辅助诊断肝癌最常用的标志物，应首选复查。GPT、GOT反映肝细胞损伤；A/G比值反映肝脏合成功能；ALP升高多见于胆汁淤积和骨病，均不能早期提示癌变"},{"q":"患者，男，51岁，曾患急性乙型病毒性肝炎，近期发现皮肤黏膜发黄。该患者首先出现黄染的部位可能是","o":["前额","巩膜","鼻部","手掌","足底"],"a":1,"e":"黄疸时胆红素升高，因巩膜富含弹性蛋白与胆红素亲和力强，黄染首先出现于巩膜、硬腭后部及软腭黏膜，之后才出现皮肤黄染。胡萝卜素增高所致黄染先见于手掌、足底、前额及鼻部，且不累及巩膜和口腔黏膜，可与真性黄疸鉴别"},{"q":"患者，女，52岁。2个月前无明显诱因出现乏力、食欲缺乏、消瘦，半月前开始出现腹胀、腹围增大、尿量减少、尿色黄。该患者最可能的面容是","o":["贫血面容","肝病面容","肾病面容","黏液性水肿面容","二尖瓣面容"],"a":1,"e":"乏力、食欲缺乏、消瘦、腹胀、腹围增大、尿少及尿黄提示肝硬化失代偿期，肝病面容表现为面色晦暗、额部鼻背双颊褐色色素沉着。肾病面容为面色苍白和眼睑水肿；贫血面容唇舌色淡；黏液性水肿面容苍白虚肿；二尖瓣面容为双颊紫红，均不符"},{"q":"患者，男，低热1个月，右侧胸痛3天，胸部X线可见右侧肋膈角少量胸腔积液。关于该患者体征描述正确的是","o":["气管移向左侧","右侧胸廓饱满","右侧叩诊呈过清音","右侧可触及胸膜摩擦感","右侧肺泡呼吸音增强"],"a":3,"e":"低热胸痛、肋膈角少量积液提示纤维蛋白性胸膜炎，纤维蛋白沉着使胸膜粗糙，呼吸时摩擦可在下前侧胸壁触及胸膜摩擦感。少量积液不使气管移位或胸廓饱满；叩诊应为浊音而非过清音；积液区肺泡呼吸音减弱而非增强，均不符合"},{"q":"患者，女，无发热和腰痛，有膀胱刺激征和血尿，可能的诊断是","o":["急性膀胱炎","急性肾盂肾炎","泌尿系结核","膀胱结石","膀胱肿瘤"],"a":0,"e":"膀胱刺激征伴血尿而无发热和腰痛，病变局限于下尿路，符合急性膀胱炎，炎症刺激膀胱三角区和后尿道产生明显尿急尿痛。急性肾盂肾炎有发热和腰痛；泌尿系结核病程长且抗生素无效；膀胱结石伴排尿中断；膀胱肿瘤以无痛性血尿为主，均不符"},{"q":"患者，女，30岁。劳累性呼吸困难2年。查体：心尖部闻及舒张中、晚期隆隆样杂音，胸骨左缘第2肋间舒张期递减型叹气样杂音。最可能诊断为","o":["二尖瓣狭窄合并主动脉瓣器质性关闭不全","二尖瓣狭窄合并肺动脉瓣器质性关闭不全","二尖瓣狭窄合并肺动脉瓣相对性关闭不全","二尖瓣狭窄合并肺动脉瓣相对性狭窄","二尖瓣狭窄合并肺动脉瓣器质性狭窄"],"a":2,"e":"心尖区舒张中晚期隆隆样杂音为二尖瓣狭窄，胸骨左缘第2肋间递减型叹气样杂音为Graham Steell杂音，系二尖瓣狭窄致肺动脉高压、肺动脉扩张引起的相对性肺动脉瓣关闭不全。主动脉瓣器质性关闭不全杂音位于主动脉瓣第二听诊区并向左下传导；肺动脉瓣器质性病变极少见，均不符"},{"q":"患者，女，16岁，胸痛，呼吸困难。查体：气管向左侧移位，语颤右侧减弱，叩之实音。最可能的诊断是","o":["气胸","胸腔积液","肺气肿","支气管扩张","支气管哮喘"],"a":1,"e":"气管向左侧移位说明右侧胸腔占位，右侧语颤减弱、叩诊实音提示右侧胸腔积液，液体阻隔声音传导并使叩诊呈实音。气胸叩诊鼓音；肺气肿为过清音且气管无移位；支气管扩张以固定湿啰音为主；支气管哮喘以干啰音和呼气延长为主，均不符合"},{"q":"患者，女，18岁，发热、咽痛、鼻黏膜出血10天。查体：浅表淋巴结、肝、脾大，胸骨压痛，右下肢皮肤可见3cm×3cm大小肿块，质硬。实验室检查：RBC 3、1×1012/L，Hb 85g/L，WBC 45×109/L，BPC 20×109/L；骨髓增生极度活跃，原始细胞占80%，部分原始细胞胞质中可见Auer小体，原始细胞POX染色弱阳性，PAS染色胞质淡红色，胞质边缘有细小的阳性颗粒，α-NAE染色阳性，能被氟化钠抑制。应诊断为","o":["急性粒细胞白血病","急性早幼粒细胞白血病","急性单核细胞白血病","急性红白血病","急性淋巴细胞白血病"],"a":2,"e":"α-NAE染色阳性且能被氟化钠抑制是单核细胞的特征，结合原始细胞增多、Auer小体及POX弱阳性，符合急性单核细胞白血病。急性粒细胞白血病POX强阳性且NAE不被氟化钠抑制；急性淋巴细胞白血病PAS呈粗颗粒或块状；急性红白血病以幼红细胞增生为主，均不符"},{"q":"患者，女，72岁。4小时前做家务时突然倒地不省人事，家属发现后呼120送入医院。查体意识丧失，唤之不醒，各种生理反射均消失。其意识障碍程度属","o":["嗜睡","意识模糊","昏睡","浅昏迷","深昏迷"],"a":4,"e":"意识完全丧失、呼之不醒且各种生理反射均消失，为深昏迷，因脑干网状上行激活系统严重受损。浅昏迷对疼痛刺激尚有防御反应、深反射存在；昏睡可被强刺激短暂唤醒；嗜睡为病理性睡眠可唤醒；意识模糊为轻度意识障碍伴定向力减退，均不符"},{"q":"患者，女，51岁，下蹲或腹部用力时，出现不自主地流尿。初步考虑是","o":["充盈性尿失禁","急迫性尿失禁","反射性尿失禁","真性尿失禁","压力性尿失禁"],"a":4,"e":"下蹲或腹部用力使腹压骤增时尿液不自主流出，而平时无明显尿失禁，符合压力性尿失禁，因膀胱颈部括约肌功能不全。充盈性尿失禁为尿潴留致被动溢出；急迫性尿失禁伴强烈尿急；反射性尿失禁无尿意；真性尿失禁为持续漏尿，均与腹压诱发不符"},{"q":"某患者体检发现心尖部递减型舒张早期隆隆杂音，胸骨左缘第3肋间可闻递减型舒张期叹气样杂音，血压140/50mmHg。其最可能的诊断为","o":["二尖瓣狭窄合并主动脉瓣关闭不全","二尖瓣狭窄合并肺动脉瓣关闭不全","严重二尖瓣狭窄","二尖瓣狭窄合并主动脉瓣狭窄","主动脉瓣关闭不全"],"a":4,"e":"胸骨左缘第3肋间递减型舒张期叹气样杂音为主动脉瓣关闭不全，脉压增大至90mmHg支持该诊断，心尖区舒张早期隆隆样杂音为Austin Flint杂音，系反流血液冲击二尖瓣所致，并非真正二尖瓣狭窄。二狭的隆隆样杂音在舒张中晚期且左侧卧位明显，本例不符"},{"q":"患者，男，30岁。反复头痛，前额痛为主，午后头痛加重，平卧位时头痛减轻，无呕吐及视物模糊。家族中无类似病史。查体：BP 130/70mmHg，双瞳孔等大等圆，颈软，上颌窦区有压痛。检查眼压不高。可能的诊断是","o":["青光眼","高血压","鼻窦炎","颅内压升高","偏头痛"],"a":2,"e":"前额痛伴上颌窦区压痛，平卧位减轻、午后加重，符合鼻窦炎，因鼻窦引流不畅和体位改变致窦内压力变化。青光眼有眼压升高和视力改变；颅内压升高头痛清晨加重且平卧加重；偏头痛为搏动性痛伴家族史；高血压头痛伴血压明显升高，均无鼻窦压痛"},{"q":"患者，女，30岁，发热1周，左腹股沟区可扪及5cm×4cm×3cm大小肿物，有压痛，有波动感。切开发现其肿物为脓液，黏稠有粪臭。首选的抗菌药物是","o":["青霉素","庆大霉素","红霉素","链霉素","甲硝唑"],"a":1,"e":"腹股沟脓肿破溃后脓液黏稠有粪臭，提示肠道来源的革兰阴性杆菌感染，庆大霉素属氨基糖苷类，对革兰阴性菌有较强抗菌活性，故为首选。青霉素主要针对革兰阳性菌；红霉素为大环内酯类；链霉素耳肾毒性大、多用于结核；甲硝唑针对厌氧菌，均非本例首选"},{"q":"患者，男，22岁，发热、咳嗽、胸痛3天。查体：右下肺呼吸音减弱，语颤减弱，叩诊呈实音。最有可能的疾病是","o":["气胸","胸腔积液","肺脓肿","支气管哮喘","肺气肿"],"a":1,"e":"发热咳嗽胸痛，右下肺呼吸音减弱、语颤减弱、叩诊实音，提示胸腔积液，液体阻隔使语颤和呼吸音减弱、叩诊呈实音。气胸叩诊鼓音；肺脓肿语颤增强并可闻及湿啰音、咳脓痰；支气管哮喘以干啰音和呼气延长为主；肺气肿叩诊过清音，均不符合"},{"q":"患者，男，66岁，因“反复间断呼吸困难10年，加重6小时”收入住院。有冠心病病史9年，平时未规律服药控制。此次急性加重，端坐呼吸，咳粉红色泡沫痰，双肺均可闻及呼吸音，可闻及较多湿啰音及哮鸣音，心率快。入院肌钙蛋白及D-二聚体未见特殊异常，心电图提示窦性心动过速，NT-proBNP 8643ng/ml。该患者考虑","o":["支气管哮喘急性发作","张力性气胸","急性肺水肿","气管异物","大面积肺栓塞"],"a":2,"e":"端坐呼吸、咳粉红色泡沫痰、双肺满布湿啰音和哮鸣音、NT-proBNP显著升高，符合急性左心衰竭所致急性肺水肿，因肺毛细血管楔压急剧升高致液体外渗。支气管哮喘无粉红色泡沫痰且BNP不高；张力性气胸呼吸音消失；气管异物有吸气性呼吸困难；肺栓塞D-二聚体升高，均不符"},{"q":"患者，女，32岁，有尿频、尿急、尿痛症状2天，尿量正常，无发热，伴腰痛，要明确诊断，首选的检查是","o":["尿常规＋镜检","肾功能","泌尿系CT","膀胱镜","静脉肾炎造影"],"a":0,"e":"尿频尿急尿痛伴腰痛，提示尿路感染可能累及上尿路，尿常规加镜检可快速发现白细胞、红细胞和脓尿，是明确诊断的首选。肾功能反映肾小球滤过功能；泌尿系CT和静脉肾盂造影用于结构性病变；膀胱镜为有创检查，均不作为首选"},{"q":"患者，男，22岁。长期食用辛辣刺激性食物，间断腹痛。今日饮用大量酒后出现呕血，后持续性腹痛，不缓解。查体：腹部柔韧，腹肌紧张，全腹压痛。行腹部平片可见膈下游离气体。可能的诊断为","o":["急性胰腺炎","消化性溃疡穿孔","急性肠梗阻","胆道蛔虫症","结核性腹膜炎"],"a":1,"e":"呕血、持续性腹痛不缓解、腹肌紧张和膈下游离气体，提示空腔脏器穿孔，结合溃疡病史为消化性溃疡穿孔，气体逸入腹腔聚集于膈下。急性胰腺炎血淀粉酶升高但无膈下游离气体；急性肠梗阻为阵发性绞痛和气液平；胆道蛔虫为阵发性钻顶样痛；结核性腹膜炎起病缓慢，均不符"},{"q":"患者，女，32岁，进行性膀胱刺激征，经抗生素治疗不见好转，伴右侧腰部胀痛及午后潮热。对诊断有决定性意义的检查是","o":["尿普通细菌培养","尿细胞学检查","膀胱B超","逆行尿路造影","尿沉渣找结核杆菌"],"a":4,"e":"进行性膀胱刺激征、抗生素治疗无效伴午后潮热和腰痛，提示泌尿系结核，尿沉渣找结核杆菌可发现病原，对确诊有决定性意义。尿普通细菌培养多为阴性；尿细胞学用于肿瘤筛查；膀胱B超和逆行尿路造影仅提示形态改变，均不能确诊结核"},{"q":"患者，男，32岁，低热、头痛2天。行腰穿术取得脑脊液后，静置24小时表面出现薄膜状，考虑为","o":["结核性脑膜炎","病毒性脑膜炎","化脓性脑膜炎","新型隐球菌脑炎","流行性乙型脑炎"],"a":0,"e":"脑脊液静置24小时后表面形成薄膜，是结核性脑膜炎的特征，因纤维蛋白析出形成网状薄膜，涂片可找到结核杆菌。化脓性脑膜炎脑脊液呈乳白色浑浊；病毒性脑膜炎和流行性乙型脑炎外观清亮；新型隐球菌脑炎需墨汁染色找荚膜孢子，均无薄膜形成"},{"q":"患者，男，59岁。逐渐消瘦，咳嗽，左胸痛，气短逐渐加重，低热，无咯血，胸透左胸腔中等量积液。该患叩诊最可能出现的是","o":["清音","鼓音","过清音","浊鼓音","实音"],"a":4,"e":"消瘦、低热、胸痛和中等量胸腔积液，叩诊积液区呈实音，因液体完全阻隔含气肺组织的叩诊反响，积液下部尤为明显。清音为正常肺；鼓音见于气胸和肺空洞；过清音见于肺气肿；浊音多见于少量积液或肺实变，中等量积液典型为实音"},{"q":"患者，66岁，既往5年高血压病史。心悸1年，劳力性心累胸闷2个月。查体：心音强弱快慢绝对不齐。常规心电图示心室率，125次/min，等电位线消失，P波不可见，QRS呈正常形态。该患者的心电图诊断是","o":["窦性心律，频发室性期前收缩","心房颤动","心房扑动","阵发性室上性心动过速","阵发性室性心动过速"],"a":1,"e":"心音强弱快慢绝对不齐、心室率快、P波消失且等电位线消失代之以f波、QRS形态正常，符合心房颤动，因心房失去协调收缩、激动紊乱下传。心房扑动可见锯齿状F波；阵发性室上性心动过速心律规整、突发突止；室性心动过速QRS宽大畸形，均不符"},{"q":"患者，女，17岁，以周期性鼻出血2年为主诉来诊。双鼻腔内检查未见异常。血常规：WBC 7.5×109/L，Hb 130g/L，RBC 4.0×1012/L，血小板计数 250×109/L。最可能的诊断是","o":["血小板减少性紫癜","白血病","子宫内膜异位症","再生障碍性贫血","缺铁性贫血"],"a":2,"e":"周期性鼻出血与月经周期相关，鼻腔检查无异常且血小板正常，提示子宫内膜异位症，鼻腔异位的子宫内膜随月经周期脱落出血。血小板减少性紫癜有血小板降低；白血病有白细胞异常和贫血；再生障碍性贫血全血细胞减少；缺铁性贫血有小细胞低色素改变，均无周期性鼻出血"},{"q":"患者，女，22岁。近5天来发烧寒战，头痛，尿呈酱油色。查体：巩膜黄染，心肺未见异常，腹软，无压痛，肝脾未触及。下列哪项检查支持溶血性贫血的诊断","o":["血清非结合胆红素正常","血清结合胆红素增加","尿胆红素阳性","尿胆原增加","血清碱性磷酸酶增加"],"a":3,"e":"溶血性贫血时红细胞破坏致非结合胆红素生成增多，经肠肝循环使尿胆原增加并随尿排出，同时尿胆红素阴性，故尿胆原增加支持诊断。血清非结合胆红素应升高而非正常；结合胆红素增加和尿胆红素阳性多见于肝细胞性或阻塞性黄疸；碱性磷酸酶增加提示胆汁淤积，均不符"},{"q":"患者，男，48岁，10年少量饮酒史。近1个月上腹疼痛，饥饿时加重，呈现疼痛－进食－缓解的规律。如为活动期溃疡，其内镜下的表现是","o":["直径0.5～1.5cm椭圆形凹陷，底部覆以白苔，其上可见出血点或血痂，周围黏膜充血、水肿，呈堤状隆起","溃疡缩小、变浅、白苔边缘光滑变薄，周边水肿，再生上皮明显呈红色栅状，可见黏膜皱襞集中，达溃疡边缘","溃疡面消失被再生上皮覆盖，黏膜皱襞呈放射状集中","黏膜充血、斑片状发红，黏膜水肿、反光增强","黏膜肥厚、水肿，皱襞粗大似脑回状"],"a":0,"e":"活动期消化性溃疡内镜下见圆形或椭圆形凹陷，直径0.5～1.5cm，底部覆白苔、血痂，周围黏膜充血水肿呈堤状隆起，与本项描述一致。B项溃疡缩小变浅、白苔变薄、再生上皮呈红色栅状、皱襞向溃疡集中，为愈合期表现。C项溃疡面消失、被再生上皮覆盖、皱襞放射状集中，属瘢痕期。E项黏膜肥厚、皱襞粗大似脑回状为肥厚性胃炎，D项为浅表性胃炎改变"},{"q":"患者，女，24岁发热、乏力、盗汗，胸痛伴呼吸困难1周，听诊可闻及胸膜摩擦音。该患最有可能的诊断是","o":["大叶性肺炎","大量胸腔积液","渗出性胸膜炎","支气管扩张","慢性支气管炎"],"a":2,"e":"发热、乏力、盗汗提示结核毒性症状，胸痛伴呼吸困难且闻及胸膜摩擦音，为纤维蛋白渗出使胸膜粗糙所致，符合渗出性胸膜炎。大叶性肺炎虽有发热胸痛，但以咳铁锈色痰、肺实变为主。大量胸腔积液时胸痛反减轻，出现叩诊浊音与呼吸音消失。支气管扩张以慢性咳脓痰、反复咯血为特征，慢性支气管炎以长期咳喘为主"},{"q":"患者，男，80岁，慢性阻塞性肺疾病病史20年。关于该患者的叩诊，说法错误的是","o":["叩诊呈过清音","Kronig峡增宽","肺下界下移","肺下界移动度减弱","肝浊音界上移"],"a":4,"e":"慢性阻塞性肺疾病因肺过度充气，叩诊呈过清音，肺上界Kronig峡增宽，肺下界下移，肺下界移动度减弱，均为典型体征。肝浊音界在肺气肿、右侧张力性气胸时应向下移位而非上移，故本项说法错误。肝浊音界上移见于右肺纤维化、右下肺不张、气腹、鼓肠等。Kronig峡变窄或叩浊则见于肺结核肺尖浸润、纤维化"},{"q":"患者，女，23岁。因心悸1个月就诊。查体：血压120/80mmHg，心率85次/min，律不齐。心电图示：窦性心律，可见提前出现的P波，形态与窦性P波不同，P-R间期0.14s，QRS波群形态正常。心悸最可能的原因是","o":["窦性心动过速","心房颤动","窦性心动过缓","室性期前收缩","房性期前收缩"],"a":4,"e":"心电图提前出现异位P′波且形态与窦性P波不同，P-R间期0.14s大于0.12s，QRS形态正常，符合房性期前收缩。窦性心动过速与窦性心动过缓均为窦性节律、P波形态一致，无提前异位P波。室性期前收缩其前无相关P波，QRS宽大畸形。心房颤动P波消失代之以f波、心律绝对不齐，与本例不符"},{"q":"患者，女，50岁。风湿性心脏病病史10年，心慌气短14天。查心电图：P波消失，代之以大小不等、形状各异的f波，频率为400次/min，心室律绝对不规则，心率130次/min，脉率110次/min。应考虑为","o":["室性期前收缩二联律","心房扑动","室上性心动过速","心房颤动","窦性心律不齐"],"a":3,"e":"风湿性心脏病患者P波消失代以大小不等、形状各异的f波，频率约400次/min，心室律绝对不规则，并有脉搏短绌（脉率110少于心率130），符合心房颤动。心房扑动代为规则锯齿状F波，心室律多规则。室上性心动过速心律规整、突发突止。窦性心律不齐P波形态正常、仅轻度不齐；室性期前收缩二联律为成对提前出现的宽大QRS波"},{"q":"患者，女，24岁，反复无诱因心悸，持续时间不等，症状自行恢复；晕厥1次。体格检查示心率170次/min，心律齐，无杂音。该患者最可能的诊断是","o":["心房颤动","心房扑动","阵发性室上性心动过速","窦性心动过速","预激综合征"],"a":2,"e":"反复发作、突发突止的心悸，心率170次/min且心律绝对规整、无杂音，符合阵发性室上性心动过速。窦性心动过速心率多为100～150次/min且渐起渐止，少见如此规整高速。心房颤动心律绝对不齐，心房扑动心室率可规则但可见锯齿状F波。预激综合征以δ波、P-R间期缩短为特征，非本例首要诊断"},{"q":"患者，男，29岁，因午后低热10天，左侧胸痛伴活动后气紧5天入院。胸片示左侧中量胸腔积液。为减轻症状，该患者采取的体位最有可能是","o":["被动体位","强迫坐位","强迫停立位","强迫蹲位","强迫侧卧位"],"a":4,"e":"结核性胸膜炎患者取患侧卧位，可限制患侧胸廓活动以减轻胸痛，并利于健侧代偿呼吸，故为强迫侧卧位。强迫坐位（端坐呼吸）多见于心衰、哮喘，借重力减少回心血量。强迫停立位见于心绞痛发作，强迫蹲位见于发绀型先天性心脏病。被动体位见于意识丧失或极度衰弱、无力自行变换体位者"},{"q":"某风湿性心脏病患者，心电图表现为：P波增宽，呈双峰型，P波时限0.12s，两峰间距0.05s，以Ⅰ、Ⅱ、aVL导联明显，应考虑为","o":["左室肥大","双房肥大","左房肥大","右房肥大","右室肥大"],"a":2,"e":"风湿性心脏病二尖瓣病变时P波增宽达0.12s、呈双峰型、两峰间距0.05s大于0.04s，以Ⅰ、Ⅱ、aVL导联明显，为二尖瓣型P波，符合左房肥大。右房肥大P波尖高、振幅大于等于0.25mV，以Ⅱ、Ⅲ、aVF明显，称肺型P波。双房肥大兼有两者特点；左、右室肥大主要改变在QRS波群，而非P波"},{"q":"患者，男，45岁。车祸伤后出现尿痛，血尿3小时。查体：阴茎和阴囊部出现蝴蝶形血肿。该患者最可能的诊断是","o":["急性膀胱炎","急性前列腺炎","尿道破裂","急性附睾炎","睾丸外伤"],"a":2,"e":"会阴部车祸伤后出现尿痛、血尿，阴茎阴囊出现蝴蝶形血肿，为前尿道破裂的典型表现，血液沿Colles筋膜蔓延所致。急性膀胱炎以膀胱刺激征为主，无外伤及血肿。急性前列腺炎伴会阴胀痛与发热。急性附睾炎、睾丸外伤的肿胀局限于阴囊内容物，无蝴蝶形会阴血肿与排尿异常"},{"q":"患儿，女，14岁，学生，发现脱发1周余。查体：左侧淋巴结肿大，有轻压痛；头皮数个脱发区，有白色鳞屑粘着，头发上可见鳞屑。诊断考虑","o":["石棉状糠疹","头皮银屑病","头癣","头皮脂溢性皮炎","斑秃"],"a":2,"e":"儿童头皮数个脱发区伴白色鳞屑粘着、头发受累，并有局部淋巴结肿痛，符合头癣（白癣）。石棉状糠疹鳞屑呈石棉状堆积但无脱发。头皮银屑病为边界清楚红斑覆厚鳞屑、头发多不受累。头皮脂溢性皮炎鳞屑油腻伴瘙痒、炎症轻微。斑秃为圆形或椭圆形无鳞屑的非瘢痕性脱发，无鳞屑及炎症"},{"q":"患者，女，32岁，进行性膀胱刺激征，经抗生素治疗不见好转，伴右侧腰部胀痛及午后潮热。为了解患者肾功能及形态的病理改变，最有价值的检查是","o":["超声检查","静脉尿路造影","逆行尿路造影","CT","MRI"],"a":1,"e":"进行性膀胱刺激征、抗生素治疗无效伴午后潮热，提示膀胱结核。静脉尿路造影既能显示肾实质显影功能，又能观察肾盂肾盏及输尿管形态改变，对了解肾功能与形态最有价值。超声仅能粗略判断形态、难评估分肾功能。逆行造影不能反映肾功能且感染时禁忌。CT、MRI形态清晰但评价肾功能不如静脉尿路造影直观"},{"q":"患者，男，60岁，食欲缺乏、腹胀，考虑酒精性肝硬化失代偿来诊。下列查体可见，但应除外","o":["蛙状腹","水母头样腹壁静脉","肚脐突出","腹式呼吸增强","肝掌"],"a":3,"e":"酒精性肝硬化失代偿可见腹水（蛙状腹、脐突出）、腹壁静脉曲张呈水母头样及肝掌等。大量腹水使腹壁膨隆、膈肌上抬，腹式呼吸应减弱而非增强，故本项为应除外项。腹式呼吸增强不多见，常为癔症性呼吸，或胸腔疾病（如大量胸腔积液）致胸式呼吸受限时的代偿表现"}];
